questions.push(
{"id":7065,"chapter":7,"q":"What is the speed limit when passing horse riders?","options":["Up to 10 mph","20 mph","30 mph","No limit"],"answer":0,"exp":{"hi":"घुड़सवारों को 10 mph से ज़्यादा नहीं पर पार करें और कम से कम 2 मीटर जगह छोड़ें।","pa":"ਘੋੜਸਵਾਰਾਂ ਨੂੰ 10 mph ਤੋਂ ਵੱਧ ਨਾ ਚਲਾ ਕੇ ਲੰਘੋ ਅਤੇ ਘੱਟੋ-ਘੱਟ 2 ਮੀਟਰ ਜਗ੍ਹਾ ਛੱਡੋ।","ur":"گھڑ سواروں کو 10 mph سے زیادہ رفتار پر نہ گزریں اور کم از کم 2 میٹر جگہ چھوڑیں۔","bn":"ঘোড়সওয়ারদের 10 mph-এর বেশি গতিতে পেরোবেন না এবং অন্তত 2 মিটার জায়গা ছাড়ুন।","te":"గుర్రపు రౌతులను 10 mph కంటే ఎక్కువ వేగంతో దాటవద్దు, కనీసం 2 మీటర్లు వదలండి.","mr":"घोडेस्वारांना 10 mph पेक्षा जास्त वेगाने ओलांडू नका आणि किमान 2 मीटर जागा सोडा.","ml":"കുതിരസവാരിക്കാരെ 10 mph-ൽ കൂടുതൽ വേഗത്തിൽ മറികടക്കരുത്, കുറഞ്ഞത് 2 മീറ്റർ ഇടം വിടുക.","ta":"குதிரை சவாரியாளர்களை 10 mph-க்கு மிகாத வேகத்தில் கடங்கள், குறைந்தது 2 மீட்டர் இடம் விடுங்கள்.","gu":"ઘોડેસવારોને 10 mph થી વધુ ઝડપે પસાર ન થાઓ અને ઓછામાં ઓછી 2 મીટર જગ્યા છોડો.","ne":"घोडचढीहरूलाई 10 mph भन्दा बढी गतिमा पार नगर्नुहोस् र कम्तीमा 2 मिटर ठाउँ छोड्नुहोस्।"},"tr":{"hi":{"q":"घुड़सवारों को पार करते समय speed limit क्या है?","o":["10 mph तक","20 mph","30 mph","कोई सीमा नहीं"]},"pa":{"q":"ਘੋੜਸਵਾਰਾਂ ਨੂੰ ਪਾਰ ਕਰਦੇ ਸਮੇਂ speed limit ਕੀ ਹੈ?","o":["10 mph ਤੱਕ","20 mph","30 mph","ਕੋਈ ਹੱਦ ਨਹੀਂ"]},"ur":{"q":"گھڑ سواروں کو پار کرتے وقت speed limit کیا ہے؟","o":["10 mph تک","20 mph","30 mph","کوئی حد نہیں"]},"bn":{"q":"ঘোড়সওয়ারদের পেরোনোর সময় speed limit কত?","o":["10 mph পর্যন্ত","20 mph","30 mph","কোনো সীমা নেই"]},"te":{"q":"గుర్రపు రౌతులను దాటేటప్పుడు speed limit ఎంత?","o":["10 mph వరకు","20 mph","30 mph","పరిమితి లేదు"]},"mr":{"q":"घोडेस्वारांना ओलांडताना speed limit किती आहे?","o":["10 mph पर्यंत","20 mph","30 mph","मर्यादा नाही"]},"ml":{"q":"കുതിരസവാരിക്കാരെ മറികടക്കുമ്പോൾ speed limit എത്ര?","o":["10 mph വരെ","20 mph","30 mph","പരിധിയില്ല"]},"ta":{"q":"குதிரை சவாரியாளர்களைக் கடக்கும்போது speed limit என்ன?","o":["10 mph வரை","20 mph","30 mph","வரம்பு இல்லை"]},"gu":{"q":"ઘોડેસવારોને પસાર કરતી વખતે speed limit કેટલી?","o":["10 mph સુધી","20 mph","30 mph","કોઈ મર્યાદા નથી"]},"ne":{"q":"घोडचढीहरूलाई पार गर्दा गति सीमा कति हो?","o":["10 mph सम्म","20 mph","30 mph","कुनै सीमा छैन"]}}},
{"id":7066,"chapter":7,"q":"Why must you take extra care with older drivers?","options":["They may be slower to react","They always drive fast","They don't signal","They're rude"],"answer":0,"exp":{"hi":"बुज़ुर्ग ड्राइवरों को प्रतिक्रिया में ज़्यादा समय लग सकता है। धैर्य रखें और दूरी बनाए रखें।","pa":"ਬਜ਼ੁਰਗ ਡਰਾਈਵਰਾਂ ਨੂੰ ਪ੍ਰਤੀਕਿਰਿਆ ਵਿੱਚ ਵੱਧ ਸਮਾਂ ਲੱਗ ਸਕਦਾ ਹੈ। ਸਬਰ ਰੱਖੋ ਅਤੇ ਦੂਰੀ ਬਣਾਈ ਰੱਖੋ।","ur":"بزرگ ڈرائیوروں کو ردِعمل میں زیادہ وقت لگ سکتا ہے۔ صبر کریں اور فاصلہ رکھیں۔","bn":"বয়স্ক চালকদের প্রতিক্রিয়া দিতে বেশি সময় লাগতে পারে। ধৈর্য ধরুন এবং দূরত্ব রাখুন।","te":"వృద్ధ డ్రైవర్లు స్పందించడానికి ఎక్కువ సమయం తీసుకోవచ్చు. ఓపిక పట్టి దూరం పాటించండి.","mr":"वृद्ध चालकांना प्रतिक्रिया द्यायला जास्त वेळ लागू शकतो. संयम ठेवा आणि अंतर राखा.","ml":"പ്രായമായ ഡ്രൈവർമാർക്ക് പ്രതികരിക്കാൻ കൂടുതൽ സമയം വേണ്ടിവന്നേക്കാം. ക്ഷമിച്ച് അകലം പാലിക്കുക.","ta":"முதிய ஓட்டுநர்கள் எதிர்வினையாற்ற அதிக நேரம் எடுக்கலாம். பொறுமையாக இருந்து இடைவெளி விடுங்கள்.","gu":"વૃદ્ધ ડ્રાઇવરોને પ્રતિક્રિયા આપવામાં વધુ સમય લાગી શકે. ધીરજ રાખો અને અંતર જાળવો.","ne":"वृद्ध चालकहरूलाई प्रतिक्रिया दिन बढी समय लाग्न सक्छ। धैर्य राख्नुहोस् र दूरी कायम गर्नुहोस्।"},"tr":{"hi":{"q":"बुज़ुर्ग ड्राइवरों के साथ ज़्यादा सावधानी क्यों बरतें?","o":["उनकी प्रतिक्रिया धीमी हो सकती है","वे हमेशा तेज़ चलाते हैं","वे signal नहीं देते","वे बदतमीज़ होते हैं"]},"pa":{"q":"ਬਜ਼ੁਰਗ ਡਰਾਈਵਰਾਂ ਨਾਲ ਵੱਧ ਸਾਵਧਾਨੀ ਕਿਉਂ ਵਰਤੋ?","o":["ਉਨ੍ਹਾਂ ਦੀ ਪ੍ਰਤੀਕਿਰਿਆ ਹੌਲੀ ਹੋ ਸਕਦੀ ਹੈ","ਉਹ ਹਮੇਸ਼ਾ ਤੇਜ਼ ਚਲਾਉਂਦੇ ਹਨ","ਉਹ signal ਨਹੀਂ ਦਿੰਦੇ","ਉਹ ਬਦਤਮੀਜ਼ ਹੁੰਦੇ ਹਨ"]},"ur":{"q":"بزرگ ڈرائیوروں کے ساتھ اضافی احتیاط کیوں برتنی چاہیے؟","o":["ان کا ردِعمل سست ہو سکتا ہے","وہ ہمیشہ تیز چلاتے ہیں","وہ signal نہیں دیتے","وہ بد تمیز ہوتے ہیں"]},"bn":{"q":"বয়স্ক চালকদের সঙ্গে বাড়তি সতর্কতা দরকার কেন?","o":["তাঁদের প্রতিক্রিয়া ধীর হতে পারে","তাঁরা সবসময় দ্রুত চালান","তাঁরা signal দেন না","তাঁরা রূঢ়"]},"te":{"q":"వృద్ధ డ్రైవర్ల విషయంలో అదనపు జాగ్రత్త ఎందుకు అవసరం?","o":["వారి స్పందన నెమ్మదిగా ఉండవచ్చు","వారు ఎప్పుడూ వేగంగా నడుపుతారు","వారు signal ఇవ్వరు","వారు మొరటుగా ఉంటారు"]},"mr":{"q":"वृद्ध चालकांबाबत जास्त काळजी का घ्यावी?","o":["त्यांची प्रतिक्रिया हळू असू शकते","ते नेहमी वेगाने चालवतात","ते signal देत नाहीत","ते उद्धट असतात"]},"ml":{"q":"പ്രായമായ ഡ്രൈവർമാരോട് കൂടുതൽ ശ്രദ്ധ വേണ്ടത് എന്തുകൊണ്ട്?","o":["അവരുടെ പ്രതികരണം പതുക്കെയായിരിക്കാം","അവർ എപ്പോഴും വേഗത്തിൽ ഓടിക്കുന്നു","അവർ signal നൽകില്ല","അവർ പരുഷരാണ്"]},"ta":{"q":"முதிய ஓட்டுநர்களிடம் ஏன் கூடுதல் கவனம் தேவை?","o":["அவர்களின் எதிர்வினை மெதுவாக இருக்கலாம்","அவர்கள் எப்போதும் வேகமாக ஓட்டுவார்கள்","அவர்கள் signal தர மாட்டார்கள்","அவர்கள் முரடர்கள்"]},"gu":{"q":"વૃદ્ધ ડ્રાઇવરો સાથે વધુ સાવચેતી કેમ રાખવી?","o":["તેમની પ્રતિક્રિયા ધીમી હોઈ શકે","તેઓ હંમેશાં ઝડપથી ચલાવે છે","તેઓ signal આપતા નથી","તેઓ અસભ્ય હોય છે"]},"ne":{"q":"वृद्ध चालकहरूसँग किन थप सावधानी अपनाउनुपर्छ?","o":["उनीहरूको प्रतिक्रिया ढिलो हुन सक्छ","उनीहरू सधैं छिटो चलाउँछन्","उनीहरू संकेत दिँदैनन्","उनीहरू अशिष्ट हुन्छन्"]}}},
{"id":7067,"chapter":7,"q":"You turn into a side road. A pedestrian is already crossing. What should you do?","options":["Sound your horn","Wait for them to cross","Drive around them","Speed up"],"answer":1,"exp":{"hi":"जिस side road में आप मुड़ते हैं वहाँ पार करते पैदल यात्रियों को priority है। इंतज़ार करें।","pa":"ਜਿਸ side road ਵਿੱਚ ਤੁਸੀਂ ਮੁੜਦੇ ਹੋ ਉੱਥੇ ਪਾਰ ਕਰਦੇ ਪੈਦਲ ਯਾਤਰੀਆਂ ਨੂੰ priority ਹੈ। ਉਡੀਕ ਕਰੋ।","ur":"جس side road میں آپ مڑتے ہیں وہاں سڑک پار کرنے والے پیدل لوگوں کو priority ہے۔ انتظار کریں۔","bn":"আপনি যে side road-এ মোড় নেন সেখানে রাস্তা পার হওয়া পথচারীদের priority আছে। অপেক্ষা করুন।","te":"మీరు తిరిగే side road లో దాటుతున్న పాదచారులకు ప్రాధాన్యత ఉంది. వేచి ఉండండి.","mr":"तुम्ही ज्या side road मध्ये वळता तिथे रस्ता ओलांडणाऱ्या पादचाऱ्यांना प्राधान्य असते. थांबा.","ml":"നിങ്ങൾ തിരിയുന്ന side road-ൽ മുറിച്ചുകടക്കുന്ന കാൽനടക്കാർക്ക് മുൻഗണനയുണ്ട്. കാത്തിരിക്കുക.","ta":"நீங்கள் திரும்பும் side road-ல் கடக்கும் பாதசாரிகளுக்கு முன்னுரிமை உண்டு. காத்திருங்கள்.","gu":"તમે જે side road માં વળો ત્યાં ઓળંગતા રાહદારીઓને પ્રાથમિકતા છે. રાહ જુઓ.","ne":"तपाईं मोडिने side road मा काट्दै गरेका पैदल यात्रीहरूलाई प्राथमिकता हुन्छ। पर्खनुहोस्।"},"tr":{"hi":{"q":"आप side road में मुड़ते हैं और कोई पैदल यात्री पहले से सड़क पार कर रहा है। आपको क्या करना चाहिए?","o":["horn बजाएँ","उसके पार होने का इंतज़ार करें","उसके चारों ओर से निकलें","तेज़ करें"]},"pa":{"q":"ਤੁਸੀਂ side road ਵਿੱਚ ਮੁੜਦੇ ਹੋ ਅਤੇ ਕੋਈ ਪੈਦਲ ਯਾਤਰੀ ਪਹਿਲਾਂ ਹੀ ਸੜਕ ਪਾਰ ਕਰ ਰਿਹਾ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["horn ਵਜਾਓ","ਉਸਦੇ ਪਾਰ ਹੋਣ ਦੀ ਉਡੀਕ ਕਰੋ","ਉਸਦੇ ਆਲੇ-ਦੁਆਲਿਓਂ ਲੰਘੋ","ਤੇਜ਼ ਕਰੋ"]},"ur":{"q":"آپ side road میں مڑتے ہیں اور ایک پیدل شخص پہلے سے سڑک پار کر رہا ہے۔ آپ کو کیا کرنا چاہیے؟","o":["horn بجائیں","اس کے پار ہونے کا انتظار کریں","اس کے گرد سے نکل جائیں","رفتار بڑھائیں"]},"bn":{"q":"আপনি একটি side road-এ মোড় নিলেন। একজন পথচারী ইতিমধ্যে রাস্তা পার হচ্ছেন। আপনার কী করা উচিত?","o":["horn বাজান","তাঁর পার হওয়া পর্যন্ত অপেক্ষা করুন","তাঁকে ঘুরে পেরিয়ে যান","গতি বাড়ান"]},"te":{"q":"మీరు ఒక side road లోకి తిరిగారు. ఒక పాదచారి అప్పటికే రోడ్డు దాటుతున్నాడు. మీరు ఏమి చేయాలి?","o":["horn కొట్టండి","అతను దాటే వరకు వేచి ఉండండి","అతని చుట్టూ నడపండి","వేగం పెంచండి"]},"mr":{"q":"तुम्ही side road मध्ये वळता. एक पादचारी आधीच रस्ता ओलांडत आहे. तुम्ही काय केले पाहिजे?","o":["horn वाजवा","त्याने ओलांडेपर्यंत थांबा","त्याच्याभोवती वळसा घालून जा","वेग वाढवा"]},"ml":{"q":"നിങ്ങൾ ഒരു side road-ലേക്ക് തിരിയുന്നു. ഒരു കാൽനടക്കാരൻ ഇതിനകം റോഡ് മുറിച്ചുകടക്കുന്നു. നിങ്ങൾ എന്ത് ചെയ്യണം?","o":["horn അടിക്കുക","അയാൾ മുറിച്ചുകടക്കുന്നതുവരെ കാത്തിരിക്കുക","അയാൾക്ക് ചുറ്റും ഓടിച്ചുപോകുക","വേഗം കൂട്ടുക"]},"ta":{"q":"நீங்கள் side road-க்குள் திரும்புகிறீர்கள். ஒரு பாதசாரி ஏற்கனவே சாலையைக் கடக்கிறார். நீங்கள் என்ன செய்ய வேண்டும்?","o":["horn அடிக்கவும்","அவர் கடக்கும் வரை காத்திருக்கவும்","அவரைச் சுற்றிச் செல்லவும்","வேகத்தை அதிகரிக்கவும்"]},"gu":{"q":"તમે side road માં વળો છો. એક રાહદારી પહેલેથી રસ્તો ઓળંગી રહ્યો છે. તમારે શું કરવું?","o":["horn વગાડો","તે ઓળંગી લે ત્યાં સુધી રાહ જુઓ","તેની આસપાસથી નીકળો","ઝડપ વધારો"]},"ne":{"q":"तपाईं side road मा मोडिनुहुन्छ। एक पैदल यात्री पहिले नै सडक काट्दै छ। तपाईंले के गर्नुपर्छ?","o":["horn बजाउनुहोस्","उसले काट्दासम्म पर्खनुहोस्","उसको वरिपरिबाट जानुहोस्","गति बढाउनुहोस्"]}}},
{"id":7068,"chapter":7,"q":"Why should you be careful near a school at the start or end of the day?","options":["Children may run out and parents may park carelessly","It's quiet","There are no cars","It's a bus route"],"answer":0,"exp":{"hi":"बच्चे और अभिभावक व्यस्त और विचलित होते हैं। धीमे हों।","pa":"ਬੱਚੇ ਅਤੇ ਮਾਪੇ ਰੁੱਝੇ ਅਤੇ ਧਿਆਨ-ਭਟਕੇ ਹੁੰਦੇ ਹਨ। ਹੌਲੀ ਹੋਵੋ।","ur":"بچے اور والدین مصروف اور توجہ بٹے ہوئے ہوتے ہیں۔ رفتار کم کریں۔","bn":"শিশু ও অভিভাবকরা ব্যস্ত ও অন্যমনস্ক থাকেন। গতি কমান।","te":"పిల్లలు, తల్లిదండ్రులు హడావుడిగా, దృష్టి మళ్లి ఉంటారు. వేగం తగ్గించండి.","mr":"मुले आणि पालक व्यग्र आणि विचलित असतात. वेग कमी करा.","ml":"കുട്ടികളും രക്ഷിതാക്കളും തിരക്കിലും ശ്രദ്ധ മാറിയവരുമായിരിക്കും. വേഗം കുറയ്ക്കുക.","ta":"குழந்தைகளும் பெற்றோரும் பரபரப்பாகவும் கவனம் சிதறியும் இருப்பார்கள். வேகத்தைக் குறையுங்கள்.","gu":"બાળકો અને માતાપિતા વ્યસ્ત અને ધ્યાન ભટકેલા હોય છે. ઝડપ ઘટાડો.","ne":"बच्चाहरू र अभिभावकहरू व्यस्त र ध्यान भङ्ग भएका हुन्छन्। गति घटाउनुहोस्।"},"tr":{"hi":{"q":"School के पास दिन की शुरुआत या अंत में सावधान क्यों रहें?","o":["बच्चे दौड़ सकते हैं और अभिभावक लापरवाही से park कर सकते हैं","वहाँ शांति रहती है","वहाँ गाड़ियाँ नहीं होतीं","यह bus route है"]},"pa":{"q":"School ਕੋਲ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਜਾਂ ਅੰਤ ਵਿੱਚ ਸਾਵਧਾਨ ਕਿਉਂ ਰਹੋ?","o":["ਬੱਚੇ ਦੌੜ ਸਕਦੇ ਹਨ ਅਤੇ ਮਾਪੇ ਲਾਪਰਵਾਹੀ ਨਾਲ park ਕਰ ਸਕਦੇ ਹਨ","ਉੱਥੇ ਸ਼ਾਂਤੀ ਰਹਿੰਦੀ ਹੈ","ਉੱਥੇ ਗੱਡੀਆਂ ਨਹੀਂ ਹੁੰਦੀਆਂ","ਇਹ bus route ਹੈ"]},"ur":{"q":"دن کے آغاز یا اختتام پر school کے قریب احتیاط کیوں کرنی چاہیے؟","o":["بچے دوڑ سکتے ہیں اور والدین لاپرواہی سے park کر سکتے ہیں","وہاں خاموشی ہوتی ہے","وہاں گاڑیاں نہیں ہوتیں","یہ bus route ہے"]},"bn":{"q":"দিনের শুরুতে বা শেষে school-এর কাছে সতর্ক থাকা উচিত কেন?","o":["শিশুরা দৌড়ে আসতে পারে এবং অভিভাবকেরা অসাবধানে park করতে পারেন","সেখানে শান্ত","সেখানে গাড়ি নেই","এটি bus route"]},"te":{"q":"రోజు మొదట్లో లేదా చివర్లో school దగ్గర జాగ్రత్తగా ఉండాలి ఎందుకు?","o":["పిల్లలు పరిగెత్తవచ్చు, తల్లిదండ్రులు అజాగ్రత్తగా park చేయవచ్చు","అక్కడ ప్రశాంతంగా ఉంటుంది","అక్కడ కార్లు ఉండవు","ఇది bus route"]},"mr":{"q":"दिवसाच्या सुरुवातीला किंवा शेवटी school जवळ काळजी का घ्यावी?","o":["मुले धावू शकतात आणि पालक निष्काळजीपणे park करू शकतात","तिथे शांतता असते","तिथे गाड्या नसतात","हा bus route आहे"]},"ml":{"q":"ദിവസത്തിന്റെ തുടക്കത്തിലോ അവസാനത്തിലോ school-ന് അടുത്ത് ശ്രദ്ധിക്കേണ്ടത് എന്തുകൊണ്ട്?","o":["കുട്ടികൾ ഓടിവന്നേക്കാം, രക്ഷിതാക്കൾ അശ്രദ്ധമായി park ചെയ്തേക്കാം","അവിടെ ശാന്തമാണ്","അവിടെ വാഹനങ്ങളില്ല","ഇത് bus route ആണ്"]},"ta":{"q":"நாளின் தொடக்கத்திலோ முடிவிலோ school அருகே ஏன் கவனமாக இருக்க வேண்டும்?","o":["குழந்தைகள் ஓடலாம், பெற்றோர் கவனக்குறைவாக park செய்யலாம்","அங்கே அமைதியாக இருக்கும்","அங்கே கார்கள் இல்லை","இது bus route"]},"gu":{"q":"દિવસની શરૂઆતમાં કે અંતે school પાસે સાવચેત કેમ રહેવું?","o":["બાળકો દોડી શકે અને માતાપિતા બેદરકારીથી park કરી શકે","ત્યાં શાંતિ હોય છે","ત્યાં ગાડીઓ નથી હોતી","તે bus route છે"]},"ne":{"q":"दिनको सुरु वा अन्त्यमा विद्यालय नजिक किन सावधान रहनुपर्छ?","o":["बच्चाहरू दौडिन सक्छन् र अभिभावकहरूले लापरबाहीसँग park गर्न सक्छन्","त्यहाँ शान्त हुन्छ","त्यहाँ car हुँदैनन्","त्यो bus route हो"]}}},
{"id":7069,"chapter":7,"q":"What should a pedestrian wear at night to be seen?","options":["Dark clothing","Bright or reflective clothing","Nothing special","A hat"],"answer":1,"exp":{"hi":"Reflective कपड़े रात में ड्राइवरों को पैदल यात्रियों को देखने में मदद करते हैं।","pa":"Reflective ਕੱਪੜੇ ਰਾਤ ਨੂੰ ਡਰਾਈਵਰਾਂ ਨੂੰ ਪੈਦਲ ਯਾਤਰੀਆਂ ਨੂੰ ਵੇਖਣ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਨ।","ur":"reflective کپڑے رات کو ڈرائیوروں کو پیدل لوگوں کو دیکھنے میں مدد دیتے ہیں۔","bn":"reflective পোশাক অন্ধকারে চালকদের পথচারী দেখতে সাহায্য করে।","te":"reflective దుస్తులు చీకటిలో డ్రైవర్లు పాదచారులను చూడటానికి సహాయపడతాయి.","mr":"reflective कपडे अंधारात चालकांना पादचारी पाहण्यास मदत करतात.","ml":"reflective വസ്ത്രം ഇരുട്ടിൽ ഡ്രൈവർമാർക്ക് കാൽനടക്കാരെ കാണാൻ സഹായിക്കുന്നു.","ta":"reflective ஆடை இருட்டில் பாதசாரிகளை ஓட்டுநர்கள் பார்க்க உதவுகிறது.","gu":"reflective કપડાં અંધારામાં ડ્રાઇવરોને રાહદારીઓ જોવામાં મદદ કરે છે.","ne":"reflective लुगाले अँध्यारोमा चालकहरूलाई पैदल यात्री देख्न मद्दत गर्छ।"},"tr":{"hi":{"q":"रात में दिखने के लिए पैदल यात्री को क्या पहनना चाहिए?","o":["गहरे कपड़े","चमकीले या reflective कपड़े","कुछ ख़ास नहीं","टोपी"]},"pa":{"q":"ਰਾਤ ਨੂੰ ਦਿਖਣ ਲਈ ਪੈਦਲ ਯਾਤਰੀ ਨੂੰ ਕੀ ਪਾਉਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਗੂੜ੍ਹੇ ਕੱਪੜੇ","ਚਮਕੀਲੇ ਜਾਂ reflective ਕੱਪੜੇ","ਕੁਝ ਖ਼ਾਸ ਨਹੀਂ","ਟੋਪੀ"]},"ur":{"q":"رات کو نظر آنے کے لیے پیدل شخص کو کیا پہننا چاہیے؟","o":["گہرے کپڑے","چمکدار یا reflective کپڑے","کچھ خاص نہیں","ٹوپی"]},"bn":{"q":"রাতে দেখা যাওয়ার জন্য পথচারীর কী পরা উচিত?","o":["গাঢ় পোশাক","উজ্জ্বল বা reflective পোশাক","বিশেষ কিছু না","টুপি"]},"te":{"q":"రాత్రి కనిపించడానికి పాదచారి ఏమి ధరించాలి?","o":["ముదురు దుస్తులు","ప్రకాశవంతమైన లేదా reflective దుస్తులు","ప్రత్యేకమైనది ఏమీ లేదు","టోపీ"]},"mr":{"q":"रात्री दिसण्यासाठी पादचाऱ्याने काय घालावे?","o":["गडद कपडे","तेजस्वी किंवा reflective कपडे","काही विशेष नाही","टोपी"]},"ml":{"q":"രാത്രി കാണപ്പെടാൻ ഒരു കാൽനടക്കാരൻ എന്ത് ധരിക്കണം?","o":["ഇരുണ്ട വസ്ത്രം","തിളക്കമുള്ളതോ reflective ആയതോ ആയ വസ്ത്രം","പ്രത്യേകിച്ച് ഒന്നുമില്ല","തൊപ്പി"]},"ta":{"q":"இரவில் தெரிவதற்காக பாதசாரி என்ன அணிய வேண்டும்?","o":["கரிய ஆடை","பிரகாசமான அல்லது reflective ஆடை","சிறப்பாக எதுவுமில்லை","தொப்பி"]},"gu":{"q":"રાત્રે દેખાવા માટે રાહદારીએ શું પહેરવું?","o":["ઘેરા કપડાં","તેજસ્વી અથવા reflective કપડાં","કંઈ ખાસ નહીં","ટોપી"]},"ne":{"q":"राति देखिन पैदल यात्रीले के लगाउनुपर्छ?","o":["गाढा लुगा","चम्किलो वा reflective लुगा","केही विशेष होइन","टोपी"]}}},
{"id":7070,"chapter":7,"q":"You see a cyclist at night with no lights or reflectors. What should you do?","options":["Pass closely","Slow down and give plenty of space","Sound your horn","Flash your lights"],"answer":1,"exp":{"hi":"बिना lights वाले cyclists बहुत मुश्किल से दिखते हैं। धीमे हों और ज़्यादा जगह छोड़ें।","pa":"ਬਿਨਾਂ lights ਵਾਲੇ cyclists ਬਹੁਤ ਮੁਸ਼ਕਲ ਨਾਲ ਦਿਖਦੇ ਹਨ। ਹੌਲੀ ਹੋਵੋ ਅਤੇ ਵੱਧ ਜਗ੍ਹਾ ਛੱਡੋ।","ur":"بغیر lights کے سائیکل سوار بہت مشکل سے نظر آتے ہیں۔ رفتار کم کریں اور زیادہ جگہ چھوڑیں۔","bn":"lights ছাড়া সাইকেল আরোহীদের দেখা খুব কঠিন। গতি কমান এবং বাড়তি জায়গা ছাড়ুন।","te":"lights లేని సైకిల్ వారు చాలా కష్టంగా కనిపిస్తారు. వేగం తగ్గించి అదనపు చోటు వదలండి.","mr":"lights नसलेले सायकलस्वार दिसणे खूप कठीण असते. वेग कमी करा आणि जास्त जागा सोडा.","ml":"lights ഇല്ലാത്ത സൈക്കിൾ യാത്രക്കാരെ കാണാൻ വളരെ ബുദ്ധിമുട്ടാണ്. വേഗം കുറച്ച് കൂടുതൽ ഇടം വിടുക.","ta":"lights இல்லாத சைக்கிள் ஓட்டுபவர்கள் பார்ப்பது மிகக் கடினம். வேகத்தைக் குறைத்து கூடுதல் இடம் விடுங்கள்.","gu":"lights વગરના સાઇકલ સવારો ખૂબ મુશ્કેલીથી દેખાય છે. ઝડપ ઘટાડો અને વધુ જગ્યા છોડો.","ne":"बत्ती नभएका साइकलचालकहरू धेरै कठिनाइले देखिन्छन्। गति घटाउनुहोस् र बढी ठाउँ छोड्नुहोस्।"},"tr":{"hi":{"q":"रात में आपको बिना lights या reflectors वाला cyclist दिखता है। आपको क्या करना चाहिए?","o":["पास से निकलें","धीमे हों और ज़्यादा जगह दें","horn बजाएँ","lights झपकाएँ"]},"pa":{"q":"ਰਾਤ ਨੂੰ ਤੁਹਾਨੂੰ ਬਿਨਾਂ lights ਜਾਂ reflectors ਵਾਲਾ cyclist ਦਿਖਦਾ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਨੇੜਿਓਂ ਲੰਘੋ","ਹੌਲੀ ਹੋਵੋ ਅਤੇ ਵੱਧ ਜਗ੍ਹਾ ਦਿਓ","horn ਵਜਾਓ","lights ਝਪਕਾਓ"]},"ur":{"q":"رات کو آپ کو بغیر lights یا reflectors کے سائیکل سوار نظر آتا ہے۔ آپ کو کیا کرنا چاہیے؟","o":["قریب سے گزریں","رفتار کم کریں اور زیادہ جگہ دیں","horn بجائیں","lights جھپکائیں"]},"bn":{"q":"রাতে আপনি lights বা reflectors ছাড়া একজন সাইকেল আরোহীকে দেখলেন। আপনার কী করা উচিত?","o":["কাছ দিয়ে যান","গতি কমান এবং অনেকটা জায়গা দিন","horn বাজান","lights ঝলকান"]},"te":{"q":"రాత్రి lights లేదా reflectors లేని సైకిల్ వ్యక్తి కనిపిస్తున్నాడు. మీరు ఏమి చేయాలి?","o":["దగ్గరగా దాటండి","వేగం తగ్గించి పుష్కలంగా చోటు ఇవ్వండి","horn కొట్టండి","lights మెరిపించండి"]},"mr":{"q":"रात्री तुम्हाला lights किंवा reflectors नसलेला सायकलस्वार दिसतो. तुम्ही काय केले पाहिजे?","o":["जवळून जा","वेग कमी करा आणि भरपूर जागा द्या","horn वाजवा","lights लुकलुकवा"]},"ml":{"q":"രാത്രി lights-ഓ reflectors-ഓ ഇല്ലാത്ത ഒരു സൈക്കിൾ യാത്രക്കാരനെ കാണുന്നു. നിങ്ങൾ എന്ത് ചെയ്യണം?","o":["അടുത്തുകൂടി കടന്നുപോകുക","വേഗം കുറച്ച് ധാരാളം ഇടം നൽകുക","horn അടിക്കുക","lights മിന്നിക്കുക"]},"ta":{"q":"இரவில் lights அல்லது reflectors இல்லாத சைக்கிள் ஓட்டுபவரைப் பார்க்கிறீர்கள். நீங்கள் என்ன செய்ய வேண்டும்?","o":["அருகில் கடக்கவும்","வேகத்தைக் குறைத்து நிறைய இடம் விடவும்","horn அடிக்கவும்","lights-ஐ மின்னவிடவும்"]},"gu":{"q":"રાત્રે તમને lights કે reflectors વગરનો સાઇકલ સવાર દેખાય છે. તમારે શું કરવું?","o":["નજીકથી નીકળો","ઝડપ ઘટાડો અને પૂરતી જગ્યા આપો","horn વગાડો","lights ઝબકાવો"]},"ne":{"q":"राति तपाईंले बत्ती वा reflector नभएको साइकलचालक देख्नुभयो। तपाईंले के गर्नुपर्छ?","o":["नजिकबाट पार गर्नुहोस्","गति घटाउनुहोस् र प्रशस्त ठाउँ दिनुहोस्","horn बजाउनुहोस्","बत्ती चम्काउनुहोस्"]}}},
{"id":7071,"chapter":7,"q":"The lights at a pelican crossing show green for you but a pedestrian is still crossing. What should you do?","options":["Go if you can pass before them","Wait until the crossing is clear","Sound your horn","Edge forward"],"answer":1,"exp":{"hi":"जो अभी crossing पर है उसे रास्ता दें। जब ख़ाली हो तभी चलें।","pa":"ਜੋ ਹਾਲੇ crossing 'ਤੇ ਹੈ ਉਸਨੂੰ ਰਾਹ ਦਿਓ। ਜਦੋਂ ਖ਼ਾਲੀ ਹੋਵੇ ਤਾਂ ਹੀ ਚੱਲੋ।","ur":"جو ابھی crossing پر ہے اسے راستہ دیں۔ صرف تب چلیں جب خالی ہو۔","bn":"যিনি এখনও crossing-এ আছেন তাঁকে পথ দিন। ফাঁকা হলেই শুধু যান।","te":"ఇంకా crossing పై ఉన్నవారికి దారి ఇవ్వండి. ఖాళీగా ఉన్నప్పుడే వెళ్లండి.","mr":"जो अजूनही crossing वर आहे त्याला मार्ग द्या. मोकळे असेल तेव्हाच जा.","ml":"ഇപ്പോഴും crossing-ൽ ഉള്ളവർക്ക് വഴി നൽകുക. ഒഴിഞ്ഞതിന് ശേഷം മാത്രം പോകുക.","ta":"இன்னும் crossing-ல் இருப்பவருக்கு வழி விடுங்கள். காலியானபோது மட்டும் செல்லுங்கள்.","gu":"જે હજી crossing પર છે તેને રસ્તો આપો. ખાલી હોય ત્યારે જ જાઓ.","ne":"जो अझै crossing मा छन् उनलाई बाटो दिनुहोस्। खाली भएपछि मात्र जानुहोस्।"},"tr":{"hi":{"q":"Pelican crossing पर आपके लिए हरी light है पर एक पैदल यात्री अभी पार कर रहा है। आपको क्या करना चाहिए?","o":["उससे पहले निकल सकें तो चल दें","Crossing ख़ाली होने तक इंतज़ार करें","horn बजाएँ","आगे सरकते जाएँ"]},"pa":{"q":"Pelican crossing 'ਤੇ ਤੁਹਾਡੇ ਲਈ ਹਰੀ light ਹੈ ਪਰ ਇੱਕ ਪੈਦਲ ਯਾਤਰੀ ਹਾਲੇ ਪਾਰ ਕਰ ਰਿਹਾ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਉਸ ਤੋਂ ਪਹਿਲਾਂ ਲੰਘ ਸਕੋ ਤਾਂ ਚੱਲ ਪਓ","Crossing ਖ਼ਾਲੀ ਹੋਣ ਤੱਕ ਉਡੀਕ ਕਰੋ","horn ਵਜਾਓ","ਅੱਗੇ ਸਰਕਦੇ ਜਾਓ"]},"ur":{"q":"pelican crossing پر آپ کے لیے سبز light ہے لیکن ایک پیدل شخص ابھی تک سڑک پار کر رہا ہے۔ آپ کو کیا کرنا چاہیے؟","o":["اس سے پہلے گزر سکیں تو چل پڑیں","crossing خالی ہونے تک انتظار کریں","horn بجائیں","آگے سرکتے جائیں"]},"bn":{"q":"pelican crossing-এ আপনার জন্য সবুজ light কিন্তু একজন পথচারী এখনও পার হচ্ছেন। আপনার কী করা উচিত?","o":["তাঁর আগে পেরোতে পারলে যান","crossing ফাঁকা না হওয়া পর্যন্ত অপেক্ষা করুন","horn বাজান","একটু একটু এগিয়ে যান"]},"te":{"q":"pelican crossing వద్ద మీకు ఆకుపచ్చ light ఉంది కానీ ఒక పాదచారి ఇంకా దాటుతున్నాడు. మీరు ఏమి చేయాలి?","o":["అతని ముందే దాటగలిగితే వెళ్లండి","crossing ఖాళీ అయ్యే వరకు వేచి ఉండండి","horn కొట్టండి","కొంచెం కొంచెం ముందుకు జరగండి"]},"mr":{"q":"pelican crossing वर तुमच्यासाठी हिरवा light आहे पण एक पादचारी अजून ओलांडत आहे. तुम्ही काय केले पाहिजे?","o":["त्याच्या आधी जाता आले तर जा","crossing मोकळे होईपर्यंत थांबा","horn वाजवा","थोडे थोडे पुढे सरका"]},"ml":{"q":"pelican crossing-ൽ നിങ്ങൾക്ക് പച്ച light ആണ്, പക്ഷേ ഒരു കാൽനടക്കാരൻ ഇപ്പോഴും മുറിച്ചുകടക്കുന്നു. നിങ്ങൾ എന്ത് ചെയ്യണം?","o":["അയാൾക്ക് മുമ്പ് കടന്നുപോകാൻ കഴിയുമെങ്കിൽ പോകുക","crossing ഒഴിയുന്നതുവരെ കാത്തിരിക്കുക","horn അടിക്കുക","മെല്ലെ മുന്നോട്ട് നീങ്ങിക്കൊണ്ടിരിക്കുക"]},"ta":{"q":"pelican crossing-ல் உங்களுக்குப் பச்சை light, ஆனால் ஒரு பாதசாரி இன்னும் கடந்துகொண்டிருக்கிறார். நீங்கள் என்ன செய்ய வேண்டும்?","o":["அவருக்கு முன் கடக்க முடிந்தால் செல்லவும்","crossing காலியாகும் வரை காத்திருக்கவும்","horn அடிக்கவும்","மெல்ல மெல்ல முன்னேறவும்"]},"gu":{"q":"pelican crossing પર તમારા માટે લીલી light છે પણ એક રાહદારી હજી ઓળંગી રહ્યો છે. તમારે શું કરવું?","o":["તેની પહેલાં નીકળી શકો તો જાઓ","crossing ખાલી થાય ત્યાં સુધી રાહ જુઓ","horn વગાડો","થોડું થોડું આગળ સરકો"]},"ne":{"q":"pelican crossing मा तपाईंका लागि हरियो बत्ती छ तर एक पैदल यात्री अझै काट्दै छ। तपाईंले के गर्नुपर्छ?","o":["उसभन्दा अघि पार गर्न सक्नुहुन्छ भने जानुहोस्","crossing खाली नभएसम्म पर्खनुहोस्","horn बजाउनुहोस्","बिस्तारै अगाडि सर्नुहोस्"]}}},
{"id":8001,"chapter":8,"q":"You’re following a long lorry that’s signalling to turn left. What should you do?","options":["Stay well back, as it may swing out to the right before turning","Overtake it on the left","Stay close behind to get through quickly","Sound your horn"],"answer":0,"exp":{"hi":"लंबी गाड़ी left मुड़ने से पहले दाईं ओर झूल सकती है। बाईं ओर से निकले तो बीच में दब सकते हो।","pa":"ਲੰਮੀ ਗੱਡੀ left ਮੁੜਨ ਤੋਂ ਪਹਿਲਾਂ ਸੱਜੇ ਪਾਸੇ ਝੂਲ ਸਕਦੀ ਹੈ। ਖੱਬੇ ਪਾਸਿਓਂ ਨਿਕਲੇ ਤਾਂ ਵਿਚਕਾਰ ਦੱਬ ਸਕਦੇ ਹੋ।","ur":"لمبی گاڑی left مڑنے سے پہلے دائیں طرف جھول سکتی ہے۔ بائیں طرف سے نکلے تو بیچ میں دب سکتے ہیں۔","bn":"(not translated yet)","te":"పొడవైన వాహనం left తిరిగే ముందు కుడి వైపుకు ఊగవచ్చు. ఎడమ వైపు నుండి దూరితే మధ్యలో నలిగిపోవచ్చు.","mr":"लांब गाडी left वळण्याआधी उजवीकडे झुलू शकते. डावीकडून निघालात तर मध्ये दबले जाऊ शकता.","ml":"നീളമുള്ള വാഹനം ഇടത്തേക്ക് തിരിയുന്നതിന് മുമ്പ് വലത്തേക്ക് ആടാം. ഇടതുവശത്തുകൂടി കടക്കാൻ ശ്രമിച്ചാൽ ഇടയിൽ ഞെരുങ്ങാം.","ta":"நீண்ட வாகனம் இடதுபுறம் திரும்பும் முன் வலதுபுறம் வளையலாம். இடதுபுறம் முந்தினால் இடையில் நசுங்கலாம்.","gu":"લાંબી lorry ડાબે વળતાં પહેલાં જમણી તરફ ફેલાઈ શકે. ઘણા પાછળ રહો અને ડાબી બાજુથી ઓવરટેક ન કરો.","ne":"लामो lorry बायाँ मोड्नु अघि दायाँतिर फैलिन सक्छ। धेरै पछाडि बस्नुहोस् र बायाँबाट overtake नगर्नुहोस्।"},"tr":{"hi":{"q":"आप एक लंबी lorry के पीछे हैं जो बाएँ मुड़ने का signal दे रही है। आपको क्या करना चाहिए?","o":["काफ़ी पीछे रहो, क्योंकि वह मुड़ने से पहले दाईं तरफ़ घूम सकती है","उसे बाईं तरफ़ से overtake करो","जल्दी निकलने के लिए उसके पास-पास चलो","horn बजाओ"]},"pa":{"q":"ਤੁਸੀਂ ਇਕ ਲੰਮੀ lorry ਦੇ ਪਿੱਛੇ ਹੋ ਜੋ ਖੱਬੇ ਮੁੜਨ ਦਾ signal ਦੇ ਰਹੀ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਕਾਫ਼ੀ ਪਿੱਛੇ ਰਹੋ, ਕਿਉਂਕਿ ਉਹ ਮੁੜਨ ਤੋਂ ਪਹਿਲਾਂ ਸੱਜੇ ਪਾਸੇ ਘੁੰਮ ਸਕਦੀ ਹੈ","ਉਸ ਨੂੰ ਖੱਬੇ ਪਾਸਿਓਂ overtake ਕਰੋ","ਜਲਦੀ ਨਿਕਲਣ ਲਈ ਉਸ ਦੇ ਨੇੜੇ-ਨੇੜੇ ਚੱਲੋ","horn ਵਜਾਓ"]},"ur":{"q":"آپ ایک لمبی لاری کے پیچھے ہیں جو بائیں مڑنے کا اشارہ دے رہی ہے۔ آپ کو کیا کرنا چاہیے؟","o":["کافی پیچھے رہیں، کیونکہ وہ مڑنے سے پہلے دائیں طرف جھول سکتی ہے","اسے بائیں طرف سے اوور ٹیک کریں","جلدی نکلنے کے لیے اس کے قریب پیچھے رہیں","ہارن بجائیں"]},"bn":{"q":"আপনি একটি লম্বা লরির পেছনে আছেন যা বাঁয়ে বাঁক নেওয়ার সিগন্যাল দিচ্ছে। আপনার কী করা উচিত?","o":["অনেক পেছনে থাকুন, কারণ বাঁক নেওয়ার আগে এটি ডান দিকে সরে যেতে পারে","বাঁ দিক দিয়ে এটিকে ওভারটেক করুন","তাড়াতাড়ি পার হতে কাছ ঘেঁষে থাকুন","হর্ন দিন"]},"te":{"q":"మీరు ఎడమకు తిరగడానికి సిగ్నల్ ఇస్తున్న పొడవైన లారీ వెనుక ఉన్నారు. మీరు ఏమి చేయాలి?","o":["బాగా వెనుక ఉండండి, ఎందుకంటే అది తిరగడానికి ముందు కుడివైపుకు ఊగవచ్చు","ఎడమవైపు నుంచి ఓవర్‌టేక్ చేయండి","త్వరగా దాటడానికి దగ్గరగా వెనుక ఉండండి","హారన్ మోగించండి"]},"mr":{"q":"तुम्ही डावीकडे वळण्याचा signal देणाऱ्या लांब लॉरीच्या मागे आहात. तुम्ही काय करावे?","o":["चांगले मागे राहा, कारण वळण्यापूर्वी ती उजवीकडे सरकू शकते","डावीकडून ओव्हरटेक करा","लवकर निघण्यासाठी अगदी मागे राहा","हॉर्न वाजवा"]},"ml":{"q":"ഇടത്തേക്ക് തിരിയാൻ signal കാണിക്കുന്ന ഒരു നീളമുള്ള lorry-യെ പിന്തുടരുകയാണ്. എന്ത് ചെയ്യണം?","o":["തിരിയുന്നതിന് മുമ്പ് അത് വലത്തേക്ക് ആടിയേക്കാം, അതിനാൽ നന്നായി പിന്നിൽ നിൽക്കുക","ഇടതുവശത്തുകൂടി ഓവർടേക്ക് ചെയ്യുക","വേഗം കടക്കാൻ അടുത്ത് പിന്തുടരുക","horn അടിക്കുക"]},"ta":{"q":"இடதுபுறம் திரும்ப signal செய்யும் நீண்ட lorry-ஐ பின்தொடர்கிறீர்கள். என்ன செய்ய வேண்டும்?","o":["நன்றாக பின்னால் இருங்கள், திரும்பும் முன் அது வலதுபுறம் வளையலாம்","அதை இடதுபுறம் முந்துங்கள்","சீக்கிரம் கடக்க நெருக்கமாக பின்தொடருங்கள்","horn அடியுங்கள்"]},"gu":{"q":"તમે લાંબી lorry પાછળ છો જે ડાબે વળવાનો signal આપે છે. શું કરવું?","o":["ઘણા પાછળ રહો, કેમ કે તે વળતાં પહેલાં જમણી તરફ ફેલાઈ શકે","ડાબી બાજુથી ઓવરટેક કરો","જલદી નીકળવા નજીક પાછળ ચાલો","horn વગાડો"]},"ne":{"q":"तपाईं लामो lorry को पछाडि हुनुहुन्छ जसले बायाँ मोड्ने signal दिँदैछ। के गर्नुपर्छ?","o":["धेरै पछाडि बस्नुहोस्, किनकि मोड्नु अघि ऊ दायाँतिर फैलिन सक्छ","बायाँबाट overtake गर्नुहोस्","छिटो निस्कन नजिक पछ्याउनुहोस्","horn बजाउनुहोस्"]}}},
{"id":8003,"chapter":8,"q":"Why do trams need extra care?","options":["They only run at night","They can turn into any road","They’re quiet and can’t steer to avoid you","They always go very fast"],"answer":2,"exp":{"hi":"Tram पटरी पर चलती है, मुड़ नहीं सकती, और बहुत शांत होती है। पटरियाँ भी फिसलन वाली होती हैं।","pa":"Tram ਪਟੜੀ ’ਤੇ ਚੱਲਦੀ ਹੈ, ਮੁੜ ਨਹੀਂ ਸਕਦੀ, ਅਤੇ ਬਹੁਤ ਸ਼ਾਂਤ ਹੁੰਦੀ ਹੈ। ਪਟੜੀਆਂ ਵੀ ਤਿਲਕਣ ਵਾਲੀਆਂ ਹੁੰਦੀਆਂ ਹਨ।","ur":"Tram پٹری پر چلتی ہے، مڑ نہیں سکتی، اور بہت خاموش ہوتی ہے۔ پٹریاں بھی پھسلن والی ہوتی ہیں۔","bn":"(not translated yet)","te":"Tram పట్టాలపై వెళ్తుంది, తిరగలేదు, చాలా నిశ్శబ్దంగా ఉంటుంది. పట్టాలు కూడా జారుడుగా ఉంటాయి.","mr":"Tram रुळांवर चालते, वळू शकत नाही, आणि खूप शांत असते. रूळही निसरडे असतात.","ml":"Tram പാളത്തിലൂടെ ഓടുന്നു, തിരിയാൻ കഴിയില്ല, വളരെ നിശ്ശബ്ദവുമാണ്. പാളങ്ങളും വഴുക്കലുള്ളതാണ്.","ta":"Tram தண்டவாளத்தில் ஓடும், திரும்ப முடியாது, மிக அமைதியாகவும் இருக்கும். தண்டவாளங்களும் வழுக்கும்.","gu":"Trams શાંત હોય છે અને steer કરી શકતી નથી, તેમજ ઊભી રહેવા લાંબું અંતર જોઈએ. પાટા પર ઊભા ન રહો.","ne":"Trams शान्त हुन्छन् र steer गर्न सक्दैनन्, साथै रोकिन लामो दूरी चाहिन्छ। पटरीमा नरोकिनुहोस्।"},"tr":{"hi":{"q":"trams के आसपास अतिरिक्त सावधानी क्यों ज़रूरी है?","o":["वे सिर्फ़ रात में चलती हैं","वे किसी भी सड़क में मुड़ सकती हैं","वे शांत होती हैं और आपसे बचने के लिए मुड़ नहीं सकतीं","वे हमेशा बहुत तेज़ चलती हैं"]},"pa":{"q":"trams ਦੇ ਆਲੇ-ਦੁਆਲੇ ਵਾਧੂ ਸਾਵਧਾਨੀ ਕਿਉਂ ਜ਼ਰੂਰੀ ਹੈ?","o":["ਉਹ ਸਿਰਫ਼ ਰਾਤ ਨੂੰ ਚੱਲਦੀਆਂ ਹਨ","ਉਹ ਕਿਸੇ ਵੀ ਸੜਕ ਵਿੱਚ ਮੁੜ ਸਕਦੀਆਂ ਹਨ","ਉਹ ਸ਼ਾਂਤ ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਤੁਹਾਡੇ ਤੋਂ ਬਚਣ ਲਈ ਮੁੜ ਨਹੀਂ ਸਕਦੀਆਂ","ਉਹ ਹਮੇਸ਼ਾ ਬਹੁਤ ਤੇਜ਼ ਚੱਲਦੀਆਂ ਹਨ"]},"ur":{"q":"ٹراموں کے ساتھ اضافی احتیاط کی ضرورت کیوں ہے؟","o":["وہ صرف رات کو چلتی ہیں","وہ کسی بھی سڑک پر مڑ سکتی ہیں","وہ خاموش ہوتی ہیں اور آپ سے بچنے کے لیے رخ نہیں موڑ سکتیں","وہ ہمیشہ بہت تیز چلتی ہیں"]},"bn":{"q":"ট্রামের ক্ষেত্রে বাড়তি সতর্কতা দরকার কেন?","o":["এগুলো শুধু রাতে চলে","এগুলো যেকোনো রাস্তায় বাঁক নিতে পারে","এগুলো নিঃশব্দ এবং আপনাকে এড়াতে স্টিয়ার করতে পারে না","এগুলো সবসময় খুব জোরে চলে"]},"te":{"q":"ట్రామ్‌ల దగ్గర అదనపు జాగ్రత్త ఎందుకు అవసరం?","o":["అవి రాత్రి మాత్రమే నడుస్తాయి","అవి ఏ రోడ్డులోకైనా తిరగగలవు","అవి నిశ్శబ్దంగా ఉంటాయి, మిమ్మల్ని తప్పించుకోవడానికి స్టీరింగ్ చేయలేవు","అవి ఎల్లప్పుడూ చాలా వేగంగా వెళ్తాయి"]},"mr":{"q":"ट्रामजवळ जास्त काळजी का घ्यावी लागते?","o":["त्या फक्त रात्री धावतात","त्या कोणत्याही रस्त्यावर वळू शकतात","त्या शांत असतात आणि तुम्हाला चुकवण्यासाठी वळू शकत नाहीत","त्या नेहमी खूप वेगाने जातात"]},"ml":{"q":"trams-ന് അടുത്ത് കൂടുതൽ ശ്രദ്ധ വേണ്ടത് എന്തുകൊണ്ട്?","o":["അവ രാത്രി മാത്രം ഓടുന്നു","അവയ്ക്ക് ഏത് റോഡിലേക്കും തിരിയാം","അവ നിശ്ശബ്ദമാണ്, നിങ്ങളെ ഒഴിവാക്കാൻ steer ചെയ്യാനും കഴിയില്ല","അവ എപ്പോഴും വളരെ വേഗത്തിൽ പോകുന്നു"]},"ta":{"q":"trams-க்கு ஏன் கூடுதல் கவனம் தேவை?","o":["அவை இரவில் மட்டும் ஓடும்","அவை எந்த சாலைக்கும் திரும்பலாம்","அவை அமைதியானவை, உங்களைத் தவிர்க்க திரும்ப முடியாது","அவை எப்போதும் மிக வேகமாக செல்லும்"]},"gu":{"q":"trams પાસે વધારાની કાળજી કેમ જરૂરી છે?","o":["તે ફક્ત રાત્રે ચાલે છે","તે કોઈ પણ રોડમાં વળી શકે","તે શાંત હોય છે અને તમને બચાવવા steer કરી શકતી નથી","તે હંમેશા ખૂબ ઝડપી હોય છે"]},"ne":{"q":"trams को नजिक किन थप सावधानी चाहिन्छ?","o":["तिनी राति मात्र चल्छन्","तिनी जुनसुकै सडकमा मोडिन सक्छन्","तिनी शान्त हुन्छन् र तपाईंलाई जोगाउन steer गर्न सक्दैनन्","तिनी सधैं धेरै छिटो हुन्छन्"]}}},
{"id":8004,"chapter":8,"q":"What’s the maximum speed of a powered mobility scooter or wheelchair on the road?","options":["4 mph","12 mph","15 mph","8 mph"],"answer":3,"exp":{"hi":"सड़क पर 8 mph, pavement पर 4 mph। बहुत धीमे होते हैं, धैर्य रखो।","pa":"ਸੜਕ ’ਤੇ 8 mph, pavement ’ਤੇ 4 mph। ਬਹੁਤ ਹੌਲੀ ਹੁੰਦੇ ਹਨ, ਸਬਰ ਰੱਖੋ।","ur":"سڑک پر 8 mph، pavement پر 4 mph۔ بہت آہستہ ہوتے ہیں، صبر رکھیں۔","bn":"(not translated yet)","te":"రోడ్డుపై 8 mph, pavement పై 4 mph. చాలా నెమ్మదిగా ఉంటాయి, ఓపిక పట్టండి.","mr":"रस्त्यावर 8 mph, pavement वर 4 mph. खूप हळू असतात, संयम ठेवा.","ml":"റോഡിൽ 8 mph, pavement-ൽ 4 mph. വളരെ പതുക്കെയാണ്, ക്ഷമിക്കുക.","ta":"சாலையில் 8 mph, pavement-இல் 4 mph. மிக மெதுவானவை, பொறுமையாக இருங்கள்.","gu":"Powered વ્હીલચેર કે mobility scooter ની રોડ પર મહત્તમ ઝડપ 8 mph (footpath પર 4 mph) હોય છે.","ne":"Powered व्हीलचेयर वा mobility scooter को सडकमा अधिकतम गति 8 mph (footpath मा 4 mph) हुन्छ।"},"tr":{"hi":{"q":"सड़क पर powered mobility scooter या wheelchair की अधिकतम speed कितनी होती है?","o":["4 mph","12 mph","15 mph","8 mph"]},"pa":{"q":"ਸੜਕ 'ਤੇ powered mobility scooter ਜਾਂ wheelchair ਦੀ ਵੱਧ ਤੋਂ ਵੱਧ speed ਕਿੰਨੀ ਹੁੰਦੀ ਹੈ?","o":["4 mph","12 mph","15 mph","8 mph"]},"ur":{"q":"سڑک پر پاور سے چلنے والے موبیلٹی اسکوٹر یا وہیل چیئر کی زیادہ سے زیادہ رفتار کیا ہے؟","o":["4 mph","12 mph","15 mph","8 mph"]},"bn":{"q":"রাস্তায় পাওয়ার-চালিত মোবিলিটি স্কুটার বা হুইলচেয়ারের সর্বোচ্চ গতি কত?","o":["৪ mph","১২ mph","১৫ mph","৮ mph"]},"te":{"q":"రోడ్డుపై పవర్డ్ మొబిలిటీ స్కూటర్ లేదా వీల్‌చైర్ గరిష్ట వేగం ఎంత?","o":["4 mph","12 mph","15 mph","8 mph"]},"mr":{"q":"रस्त्यावर powered mobility scooter किंवा व्हीलचेअरचा कमाल वेग किती?","o":["४ mph","१२ mph","१५ mph","८ mph"]},"ml":{"q":"റോഡിൽ powered mobility scooter അല്ലെങ്കിൽ wheelchair-ന്റെ പരമാവധി വേഗത എത്രയാണ്?","o":["4 mph","12 mph","15 mph","8 mph"]},"ta":{"q":"சாலையில் மின்சார mobility scooter அல்லது சக்கர நாற்காலியின் அதிகபட்ச வேகம் என்ன?","o":["4 mph","12 mph","15 mph","8 mph"]},"gu":{"q":"રોડ પર powered mobility scooter કે વ્હીલચેરની મહત્તમ ઝડપ કેટલી હોય?","o":["4 mph","12 mph","15 mph","8 mph"]},"ne":{"q":"सडकमा powered mobility scooter वा व्हीलचेयरको अधिकतम गति कति हो?","o":["4 mph","12 mph","15 mph","8 mph"]}}},
{"id":8005,"chapter":8,"q":"You can’t see the mirrors of the lorry in front. What does this mean?","options":["The driver probably can’t see you","You’re at a safe distance","The lorry is about to stop","The driver has seen you"],"answer":0,"exp":{"hi":"Mirrors नहीं दिख रहे = आप उसके blind spot में हो। पीछे हटो ताकि mirrors दिखें।","pa":"Mirrors ਨਹੀਂ ਦਿਸ ਰਹੇ = ਤੁਸੀਂ ਉਸ ਦੇ blind spot ਵਿੱਚ ਹੋ। ਪਿੱਛੇ ਹਟੋ ਤਾਂ ਜੋ mirrors ਦਿਸਣ।","ur":"Mirrors نظر نہیں آ رہے = آپ اس کے blind spot میں ہیں۔ پیچھے ہٹیں تاکہ mirrors نظر آئیں۔","bn":"(not translated yet)","te":"Mirrors కనిపించడం లేదు = మీరు దాని blind spot లో ఉన్నారు. Mirrors కనిపించేలా వెనక్కి జరగండి.","mr":"Mirrors दिसत नाहीत = तुम्ही त्याच्या blind spot मध्ये आहात. मागे व्हा म्हणजे mirrors दिसतील.","ml":"Mirrors കാണുന്നില്ല = നിങ്ങൾ അതിന്റെ blind spot-ലാണ്. പിന്നോട്ട് മാറി mirrors കാണുന്ന സ്ഥാനത്ത് നിൽക്കുക.","ta":"Mirrors தெரியவில்லை = நீங்கள் அவர் blind spot-இல் உள்ளீர்கள். Mirrors தெரியும்படி பின்னால் செல்லுங்கள்.","gu":"જો તમે lorry ના mirror જોઈ શકતા નથી તો ડ્રાઇવર પણ તમને જોઈ શકતો નથી. વધુ પાછળ જાઓ.","ne":"Lorry का mirror देख्न सक्नुहुन्न भने चालकले पनि तपाईंलाई देख्न सक्दैन। थप पछाडि जानुहोस्।"},"tr":{"hi":{"q":"आपको सामने वाली lorry के mirrors नहीं दिख रहे। इसका क्या मतलब है?","o":["ड्राइवर शायद आपको नहीं देख पा रहा","आप सुरक्षित दूरी पर हैं","lorry रुकने वाली है","ड्राइवर ने आपको देख लिया है"]},"pa":{"q":"ਤੁਹਾਨੂੰ ਸਾਹਮਣੇ ਵਾਲੀ lorry ਦੇ mirrors ਨਹੀਂ ਦਿਖ ਰਹੇ। ਇਸ ਦਾ ਕੀ ਮਤਲਬ ਹੈ?","o":["ਡਰਾਈਵਰ ਸ਼ਾਇਦ ਤੁਹਾਨੂੰ ਨਹੀਂ ਦੇਖ ਪਾ ਰਿਹਾ","ਤੁਸੀਂ ਸੁਰੱਖਿਅਤ ਦੂਰੀ 'ਤੇ ਹੋ","lorry ਰੁਕਣ ਵਾਲੀ ਹੈ","ਡਰਾਈਵਰ ਨੇ ਤੁਹਾਨੂੰ ਦੇਖ ਲਿਆ ਹੈ"]},"ur":{"q":"آپ آگے والی لاری کے آئینے نہیں دیکھ سکتے۔ اس کا کیا مطلب ہے؟","o":["ڈرائیور غالباً آپ کو نہیں دیکھ سکتا","آپ محفوظ فاصلے پر ہیں","لاری رکنے والی ہے","ڈرائیور نے آپ کو دیکھ لیا ہے"]},"bn":{"q":"আপনি সামনের লরির আয়না দেখতে পাচ্ছেন না। এর অর্থ কী?","o":["চালক সম্ভবত আপনাকে দেখতে পাচ্ছেন না","আপনি নিরাপদ দূরত্বে আছেন","লরিটি থামতে যাচ্ছে","চালক আপনাকে দেখেছেন"]},"te":{"q":"ముందున్న లారీ మిర్రర్లు మీకు కనిపించడం లేదు. దీని అర్థం ఏమిటి?","o":["డ్రైవర్‌కు మీరు బహుశా కనిపించరు","మీరు సురక్షిత దూరంలో ఉన్నారు","లారీ ఆగబోతోంది","డ్రైవర్ మిమ్మల్ని చూశాడు"]},"mr":{"q":"तुम्हाला पुढच्या लॉरीचे mirrors दिसत नाहीत. याचा अर्थ काय?","o":["चालकाला कदाचित तुम्ही दिसत नाही","तुम्ही सुरक्षित अंतरावर आहात","लॉरी थांबणार आहे","चालकाने तुम्हाला पाहिले आहे"]},"ml":{"q":"മുന്നിലെ lorry-യുടെ mirrors നിങ്ങൾക്ക് കാണാൻ കഴിയുന്നില്ല. ഇതിന്റെ അർത്ഥം എന്താണ്?","o":["ഡ്രൈവർക്ക് നിങ്ങളെ കാണാൻ കഴിയാൻ സാധ്യതയില്ല","നിങ്ങൾ സുരക്ഷിതമായ അകലത്തിലാണ്","lorry നിൽക്കാൻ പോകുന്നു","ഡ്രൈവർ നിങ്ങളെ കണ്ടിരിക്കുന്നു"]},"ta":{"q":"முன்னால் உள்ள lorry-இன் mirrors உங்களுக்கு தெரியவில்லை. இதன் அர்த்தம் என்ன?","o":["ஓட்டுநர் உங்களைப் பார்க்க முடியாமல் இருக்கலாம்","நீங்கள் பாதுகாப்பான தூரத்தில் உள்ளீர்கள்","lorry நிற்கப் போகிறது","ஓட்டுநர் உங்களைப் பார்த்துவிட்டார்"]},"gu":{"q":"તમને આગળની lorry ના mirrors દેખાતા નથી. તેનો અર્થ શું છે?","o":["ડ્રાઇવર કદાચ તમને જોઈ શકતો નથી","તમે સલામત અંતરે છો","lorry ઊભી રહેવાની છે","ડ્રાઇવરે તમને જોયા છે"]},"ne":{"q":"तपाईंले अगाडिको lorry का mirrors देख्न सक्नुहुन्न। यसको अर्थ के हो?","o":["चालकले सायद तपाईंलाई देख्न सक्दैन","तपाईं सुरक्षित दूरीमा हुनुहुन्छ","lorry रोकिन लागेको छ","चालकले तपाईंलाई देखेको छ"]}}},
{"id":8006,"chapter":8,"q":"A bus at a bus stop signals to pull out. What should you do?","options":["Overtake it quickly","Give way if it’s safe to do so","Speed up to pass it","Sound your horn"],"answer":1,"exp":{"hi":"Highway Code कहता है, सुरक्षित हो तो bus को निकलने दो, ख़ासकर built-up areas में।","pa":"Highway Code ਕਹਿੰਦਾ ਹੈ, ਸੁਰੱਖਿਅਤ ਹੋਵੇ ਤਾਂ bus ਨੂੰ ਨਿਕਲਣ ਦਿਓ, ਖ਼ਾਸ ਕਰਕੇ built-up areas ਵਿੱਚ।","ur":"Highway Code کہتا ہے، محفوظ ہو تو bus کو نکلنے دیں، خاص طور پر built-up areas میں۔","bn":"(not translated yet)","te":"Highway Code ప్రకారం, సురక్షితమైతే bus ను వెళ్ళనివ్వండి, ముఖ్యంగా built-up areas లో.","mr":"Highway Code सांगतो, सुरक्षित असेल तर bus ला निघू द्या, विशेषतः built-up areas मध्ये.","ml":"Highway Code പറയുന്നു, സുരക്ഷിതമെങ്കിൽ bus-ന് പുറത്തേക്ക് വരാൻ അനുവദിക്കുക, പ്രത്യേകിച്ച് built-up areas-ൽ.","ta":"Highway Code: பாதுகாப்பாக இருந்தால் பேருந்து புறப்பட வழி விடுங்கள், குறிப்பாக built-up பகுதிகளில்.","gu":"બસ stop પરથી નીકળવાનો signal આપે તો, સલામત અને સરળ હોય તો તેને રસ્તો આપો.","ne":"बसले stop बाट निस्कने signal दिए, सुरक्षित र सजिलो भए बाटो दिनुहोस्।"},"tr":{"hi":{"q":"बस स्टॉप पर खड़ी बस निकलने का signal देती है। आपको क्या करना चाहिए?","o":["जल्दी से उसे overtake करो","अगर सुरक्षित हो तो उसे रास्ता दो","उसे पार करने के लिए speed बढ़ाओ","horn बजाओ"]},"pa":{"q":"ਬੱਸ ਸਟਾਪ 'ਤੇ ਖੜ੍ਹੀ ਬੱਸ ਨਿਕਲਣ ਦਾ signal ਦਿੰਦੀ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਜਲਦੀ ਨਾਲ ਉਸ ਨੂੰ overtake ਕਰੋ","ਜੇ ਸੁਰੱਖਿਅਤ ਹੋਵੇ ਤਾਂ ਉਸ ਨੂੰ ਰਾਹ ਦਿਓ","ਉਸ ਨੂੰ ਪਾਰ ਕਰਨ ਲਈ speed ਵਧਾਓ","horn ਵਜਾਓ"]},"ur":{"q":"بس اسٹاپ پر کھڑی بس باہر نکلنے کا اشارہ دیتی ہے۔ آپ کو کیا کرنا چاہیے؟","o":["اسے تیزی سے اوور ٹیک کریں","اگر محفوظ ہو تو راستہ دیں","اسے پار کرنے کے لیے رفتار بڑھائیں","ہارن بجائیں"]},"bn":{"q":"বাস স্টপের একটি বাস বেরোনোর সিগন্যাল দিল। আপনার কী করা উচিত?","o":["দ্রুত ওভারটেক করুন","নিরাপদ হলে পথ ছেড়ে দিন","পার হতে গতি বাড়ান","হর্ন দিন"]},"te":{"q":"బస్ స్టాప్ వద్ద ఉన్న బస్సు బయటకు రావడానికి సిగ్నల్ ఇచ్చింది. మీరు ఏమి చేయాలి?","o":["దాన్ని త్వరగా ఓవర్‌టేక్ చేయండి","సురక్షితమైతే దారి ఇవ్వండి","దాటడానికి వేగం పెంచండి","హారన్ మోగించండి"]},"mr":{"q":"बस थांब्यावरील बस बाहेर पडण्याचा signal देते. तुम्ही काय करावे?","o":["तिला लवकर ओव्हरटेक करा","सुरक्षित असेल तर वाट द्या","ती पार करण्यासाठी वेग वाढवा","हॉर्न वाजवा"]},"ml":{"q":"bus stop-ലെ ഒരു ബസ് പുറത്തേക്ക് നീങ്ങാൻ signal കാണിക്കുന്നു. എന്ത് ചെയ്യണം?","o":["വേഗം ഓവർടേക്ക് ചെയ്യുക","സുരക്ഷിതമാണെങ്കിൽ വഴി നൽകുക","കടന്നുപോകാൻ വേഗത കൂട്ടുക","horn അടിക്കുക"]},"ta":{"q":"பேருந்து நிறுத்தத்தில் உள்ள பேருந்து வெளியே புறப்பட signal செய்கிறது. என்ன செய்ய வேண்டும்?","o":["அதை வேகமாக முந்துங்கள்","பாதுகாப்பாக இருந்தால் வழி விடுங்கள்","கடக்க வேகத்தை கூட்டுங்கள்","horn அடியுங்கள்"]},"gu":{"q":"bus stop પર ઊભેલી બસ નીકળવાનો signal આપે છે. શું કરવું?","o":["ઝડપથી ઓવરટેક કરો","સલામત હોય તો રસ્તો આપો","પસાર થવા ઝડપ વધારો","horn વગાડો"]},"ne":{"q":"bus stop मा रहेको बसले निस्कने signal दिन्छ। के गर्नुपर्छ?","o":["छिटो overtake गर्नुहोस्","सुरक्षित भए बाटो दिनुहोस्","नाघ्न गति बढाउनुहोस्","horn बजाउनुहोस्"]}}},
{"id":8007,"chapter":8,"q":"Why does overtaking a long vehicle need extra care?","options":["It’s illegal on single carriageways","Long vehicles can’t see behind","It takes longer to pass and you need more clear road","Long vehicles always speed up"],"answer":2,"exp":{"hi":"लंबी गाड़ी के बगल में ज़्यादा देर रहना पड़ता है, इसलिए आगे बहुत ज़्यादा साफ़ सड़क चाहिए।","pa":"ਲੰਮੀ ਗੱਡੀ ਦੇ ਨਾਲ ਵੱਧ ਦੇਰ ਰਹਿਣਾ ਪੈਂਦਾ ਹੈ, ਇਸ ਲਈ ਅੱਗੇ ਬਹੁਤ ਜ਼ਿਆਦਾ ਸਾਫ਼ ਸੜਕ ਚਾਹੀਦੀ ਹੈ।","ur":"لمبی گاڑی کے ساتھ زیادہ دیر رہنا پڑتا ہے، اس لیے آگے بہت زیادہ صاف سڑک چاہیے۔","bn":"(not translated yet)","te":"పొడవైన వాహనం పక్కన ఎక్కువసేపు ఉండాలి, కాబట్టి ముందు చాలా ఎక్కువ ఖాళీ రోడ్డు కావాలి.","mr":"लांब गाडीच्या बाजूने जास्त वेळ राहावे लागते, म्हणून पुढे खूप जास्त मोकळा रस्ता हवा.","ml":"നീളമുള്ള വാഹനത്തിന്റെ അടുത്ത് കൂടുതൽ നേരം നിൽക്കേണ്ടി വരും, അതിനാൽ മുന്നിൽ വളരെ കൂടുതൽ ഒഴിഞ്ഞ റോഡ് വേണം.","ta":"நீண்ட வாகனத்தின் அருகே அதிக நேரம் இருக்க வேண்டியிருக்கும், எனவே முன்னால் மிக அதிக தெளிவான சாலை தேவை.","gu":"લાંબા વાહનને ઓવરટેક કરવા વધુ સમય અને ખુલ્લો રોડ જોઈએ. ખાતરી ન હોય તો રાહ જુઓ.","ne":"लामो सवारीलाई overtake गर्न बढी समय र खुला सडक चाहिन्छ। पक्का छैन भने पर्खनुहोस्।"},"tr":{"hi":{"q":"लंबे वाहन को overtake करते समय अतिरिक्त सावधानी क्यों ज़रूरी है?","o":["single carriageway पर यह ग़ैरक़ानूनी है","लंबे वाहन पीछे नहीं देख सकते","इसे पार करने में ज़्यादा समय लगता है और आपको ज़्यादा ख़ाली सड़क चाहिए","लंबे वाहन हमेशा speed बढ़ा देते हैं"]},"pa":{"q":"ਲੰਮੇ ਵਾਹਨ ਨੂੰ overtake ਕਰਦੇ ਸਮੇਂ ਵਾਧੂ ਸਾਵਧਾਨੀ ਕਿਉਂ ਜ਼ਰੂਰੀ ਹੈ?","o":["single carriageway 'ਤੇ ਇਹ ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਹੈ","ਲੰਮੇ ਵਾਹਨ ਪਿੱਛੇ ਨਹੀਂ ਦੇਖ ਸਕਦੇ","ਇਸ ਨੂੰ ਪਾਰ ਕਰਨ ਵਿੱਚ ਵੱਧ ਸਮਾਂ ਲੱਗਦਾ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਵੱਧ ਖ਼ਾਲੀ ਸੜਕ ਚਾਹੀਦੀ ਹੈ","ਲੰਮੇ ਵਾਹਨ ਹਮੇਸ਼ਾ speed ਵਧਾ ਦਿੰਦੇ ਹਨ"]},"ur":{"q":"لمبی گاڑی کو اوور ٹیک کرنے میں اضافی احتیاط کیوں چاہیے؟","o":["سنگل کیریج ویز پر یہ غیر قانونی ہے","لمبی گاڑیاں پیچھے نہیں دیکھ سکتیں","اسے پار کرنے میں زیادہ وقت لگتا ہے اور آپ کو زیادہ صاف سڑک چاہیے","لمبی گاڑیاں ہمیشہ رفتار بڑھا لیتی ہیں"]},"bn":{"q":"লম্বা যানকে ওভারটেক করতে বাড়তি সতর্কতা দরকার কেন?","o":["একক ক্যারেজওয়েতে এটি বেআইনি","লম্বা যান পেছনে দেখতে পায় না","পার হতে বেশি সময় লাগে এবং আপনার আরও ফাঁকা রাস্তা দরকার","লম্বা যান সবসময় গতি বাড়ায়"]},"te":{"q":"పొడవైన వాహనాన్ని ఓవర్‌టేక్ చేయడానికి అదనపు జాగ్రత్త ఎందుకు అవసరం?","o":["సింగిల్ క్యారేజ్‌వేలపై ఇది చట్టవిరుద్ధం","పొడవైన వాహనాలు వెనుక చూడలేవు","దాటడానికి ఎక్కువ సమయం పడుతుంది, ఎక్కువ ఖాళీ రోడ్డు కావాలి","పొడవైన వాహనాలు ఎల్లప్పుడూ వేగం పెంచుతాయి"]},"mr":{"q":"लांब वाहनाला ओव्हरटेक करताना जास्त काळजी का घ्यावी लागते?","o":["एकेरी रस्त्यावर ते बेकायदेशीर आहे","लांब वाहनांना मागचे दिसत नाही","पार करायला जास्त वेळ लागतो आणि जास्त मोकळा रस्ता लागतो","लांब वाहने नेहमी वेग वाढवतात"]},"ml":{"q":"നീളമുള്ള വാഹനത്തെ ഓവർടേക്ക് ചെയ്യാൻ കൂടുതൽ ശ്രദ്ധ വേണ്ടത് എന്തുകൊണ്ട്?","o":["single carriageways-ൽ അത് നിയമവിരുദ്ധമാണ്","നീളമുള്ള വാഹനങ്ങൾക്ക് പിന്നിൽ കാണാൻ കഴിയില്ല","കടക്കാൻ കൂടുതൽ സമയമെടുക്കും, കൂടുതൽ ഒഴിഞ്ഞ റോഡ് വേണം","നീളമുള്ള വാഹനങ്ങൾ എപ്പോഴും വേഗത കൂട്ടും"]},"ta":{"q":"நீண்ட வாகனத்தை முந்துவதற்கு ஏன் கூடுதல் கவனம் தேவை?","o":["single carriageway-இல் சட்டவிரோதம்","நீண்ட வாகனங்களால் பின்னால் பார்க்க முடியாது","கடக்க அதிக நேரம் ஆகும், அதிக தெளிவான சாலை தேவை","நீண்ட வாகனங்கள் எப்போதும் வேகமெடுக்கும்"]},"gu":{"q":"લાંબા વાહનને ઓવરટેક કરવામાં વધારાની કાળજી કેમ?","o":["single carriageway પર તે ગેરકાયદેસર છે","લાંબા વાહનો પાછળ જોઈ શકતા નથી","પસાર થવામાં વધુ સમય લાગે અને વધુ ખુલ્લો રોડ જોઈએ","લાંબા વાહનો હંમેશા ઝડપ વધારે છે"]},"ne":{"q":"लामो सवारीलाई overtake गर्दा थप सावधानी किन चाहिन्छ?","o":["single carriageway मा यो गैरकानूनी छ","लामा सवारीले पछाडि देख्न सक्दैनन्","नाघ्न बढी समय लाग्छ र बढी खुला सडक चाहिन्छ","लामा सवारीले सधैं गति बढाउँछन्"]}}},
{"id":8010,"chapter":8,"q":"A long vehicle approaching a roundabout is in the left lane but signalling right. Why?","options":["It’s turning left","It needs extra room to make the turn","The driver has made a mistake","It’s about to stop"],"answer":1,"exp":{"hi":"लंबी गाड़ियों को मुड़ने के लिए ज़्यादा जगह चाहिए, इसलिए वो अलग lane ले सकती हैं। उनके बगल में मत चलो।","pa":"ਲੰਮੀਆਂ ਗੱਡੀਆਂ ਨੂੰ ਮੁੜਨ ਲਈ ਵੱਧ ਥਾਂ ਚਾਹੀਦੀ ਹੈ, ਇਸ ਲਈ ਉਹ ਵੱਖਰੀ lane ਲੈ ਸਕਦੀਆਂ ਹਨ। ਉਨ੍ਹਾਂ ਦੇ ਨਾਲ-ਨਾਲ ਨਾ ਚੱਲੋ।","ur":"لمبی گاڑیوں کو مڑنے کے لیے زیادہ جگہ چاہیے، اس لیے وہ الگ lane لے سکتی ہیں۔ ان کے ساتھ ساتھ نہ چلیں۔","bn":"(not translated yet)","te":"పొడవైన వాహనాలకు తిరగడానికి ఎక్కువ స్థలం కావాలి, కాబట్టి వేరే lane తీసుకోవచ్చు. వాటి పక్కపక్కనే వెళ్ళకండి.","mr":"लांब गाड्यांना वळण्यासाठी जास्त जागा लागते, म्हणून त्या वेगळी lane घेऊ शकतात. त्यांच्या बाजूने चालू नका.","ml":"നീളമുള്ള വാഹനങ്ങൾക്ക് തിരിയാൻ കൂടുതൽ സ്ഥലം വേണം, അതിനാൽ വേറെ lane എടുക്കാം. അവയുടെ വശത്തുകൂടി ഓടിക്കരുത്.","ta":"நீண்ட வாகனங்களுக்கு திரும்ப அதிக இடம் தேவை, அதனால் வேறு lane எடுக்கலாம். அவற்றின் பக்கத்தில் செல்லாதீர்கள்.","gu":"લાંબા વાહનને roundabout પર વળવા વધુ જગ્યા જોઈએ, તેથી ડાબી lane માં હોવા છતાં જમણે signal. તેમને જગ્યા આપો.","ne":"लामो सवारीलाई roundabout मा मोड्न बढी ठाउँ चाहिन्छ, त्यसैले बायाँ lane मा भए पनि दायाँ signal। उनीहरूलाई ठाउँ दिनुहोस्।"},"tr":{"hi":{"q":"roundabout के पास पहुँचता एक लंबा वाहन बाईं lane में है लेकिन दाएँ का signal दे रहा है। ऐसा क्यों?","o":["वह बाएँ मुड़ रहा है","उसे मुड़ने के लिए अतिरिक्त जगह चाहिए","ड्राइवर से ग़लती हो गई है","वह रुकने वाला है"]},"pa":{"q":"roundabout ਦੇ ਨੇੜੇ ਪਹੁੰਚਦਾ ਇਕ ਲੰਮਾ ਵਾਹਨ ਖੱਬੀ lane ਵਿੱਚ ਹੈ ਪਰ ਸੱਜੇ ਦਾ signal ਦੇ ਰਿਹਾ ਹੈ। ਅਜਿਹਾ ਕਿਉਂ?","o":["ਉਹ ਖੱਬੇ ਮੁੜ ਰਿਹਾ ਹੈ","ਉਸ ਨੂੰ ਮੁੜਨ ਲਈ ਵਾਧੂ ਥਾਂ ਚਾਹੀਦੀ ਹੈ","ਡਰਾਈਵਰ ਤੋਂ ਗ਼ਲਤੀ ਹੋ ਗਈ ਹੈ","ਉਹ ਰੁਕਣ ਵਾਲਾ ਹੈ"]},"ur":{"q":"راؤنڈ اباؤٹ کے قریب پہنچتی ایک لمبی گاڑی بائیں لین میں ہے لیکن دائیں مڑنے کا اشارہ دے رہی ہے۔ کیوں؟","o":["وہ بائیں مڑ رہی ہے","اسے مڑنے کے لیے اضافی جگہ چاہیے","ڈرائیور سے غلطی ہوئی ہے","وہ رکنے والی ہے"]},"bn":{"q":"রাউন্ডঅ্যাবাউটের কাছে আসা একটি লম্বা যান বাঁ লেনে আছে কিন্তু ডানে সিগন্যাল দিচ্ছে। কেন?","o":["এটি বাঁয়ে ঘুরছে","বাঁক নিতে এর বাড়তি জায়গা দরকার","চালক ভুল করেছেন","এটি থামতে যাচ্ছে"]},"te":{"q":"రౌండ్‌అబౌట్ దగ్గరకు వస్తున్న పొడవైన వాహనం ఎడమ లేన్‌లో ఉంది కానీ కుడి సిగ్నల్ ఇస్తోంది. ఎందుకు?","o":["అది ఎడమకు తిరుగుతోంది","తిరగడానికి దానికి అదనపు చోటు కావాలి","డ్రైవర్ పొరపాటు చేశాడు","అది ఆగబోతోంది"]},"mr":{"q":"roundabout जवळ येणारे लांब वाहन डाव्या लेनमध्ये आहे पण उजवीकडचा signal देत आहे. का?","o":["ते डावीकडे वळत आहे","वळण घेण्यासाठी त्याला अतिरिक्त जागा हवी आहे","चालकाने चूक केली आहे","ते थांबणार आहे"]},"ml":{"q":"roundabout-ലേക്ക് അടുക്കുന്ന ഒരു നീളമുള്ള വാഹനം ഇടത് lane-ലാണ്, പക്ഷേ വലത്തേക്ക് signal കാണിക്കുന്നു. എന്തുകൊണ്ട്?","o":["അത് ഇടത്തേക്ക് തിരിയുന്നു","തിരിയാൻ അതിന് അധിക സ്ഥലം ആവശ്യമാണ്","ഡ്രൈവർക്ക് തെറ്റ് പറ്റി","അത് നിൽക്കാൻ പോകുന്നു"]},"ta":{"q":"roundabout-ஐ நெருங்கும் நீண்ட வாகனம் இடது lane-இல் இருக்கிறது ஆனால் வலதுபுற signal காட்டுகிறது. ஏன்?","o":["அது இடதுபுறம் திரும்புகிறது","திரும்ப அதற்கு கூடுதல் இடம் தேவை","ஓட்டுநர் தவறு செய்துவிட்டார்","அது நிற்கப் போகிறது"]},"gu":{"q":"roundabout નજીક પહોંચતું લાંબું વાહન ડાબી lane માં છે પણ જમણો signal આપે છે. કેમ?","o":["તે ડાબે વળે છે","તેને વળવા વધારાની જગ્યા જોઈએ","ડ્રાઇવરે ભૂલ કરી છે","તે ઊભું રહેવાનું છે"]},"ne":{"q":"roundabout नजिक आउँदै गरेको लामो सवारी बायाँ lane मा छ तर दायाँ signal दिँदैछ। किन?","o":["ऊ बायाँ मोडिँदैछ","उसलाई मोड्न थप ठाउँ चाहिन्छ","चालकले गल्ती गरेको छ","ऊ रोकिन लागेको छ"]}}},
{"id":8011,"chapter":8,"q":"Near tram tracks, what must you not do?","options":["Look out for trams","Give way to trams","Drive in a lane or route reserved only for trams","Cross the tracks at a junction"],"answer":2,"exp":{"hi":"सिर्फ़ tram के लिए बने रास्ते में गाड़ी चलाना मना है। Tracks पार करते वक़्त सीधे और सावधानी से।","pa":"ਸਿਰਫ਼ tram ਲਈ ਬਣੇ ਰਾਹ ਵਿੱਚ ਗੱਡੀ ਚਲਾਉਣਾ ਮਨ੍ਹਾ ਹੈ। Tracks ਪਾਰ ਕਰਦੇ ਵੇਲੇ ਸਿੱਧੇ ਅਤੇ ਸਾਵਧਾਨੀ ਨਾਲ।","ur":"صرف tram کے لیے بنے راستے میں گاڑی چلانا منع ہے۔ Tracks پار کرتے وقت سیدھا اور احتیاط سے۔","bn":"(not translated yet)","te":"Tram కోసం మాత్రమే ఉన్న దారిలో వాహనం నడపడం నిషేధం. Tracks దాటేటప్పుడు నేరుగా, జాగ్రత్తగా.","mr":"फक्त tram साठी असलेल्या मार्गात गाडी चालवणे मना आहे. Tracks ओलांडताना सरळ आणि काळजीपूर्वक.","ml":"Tram-ന് മാത്രമുള്ള പാതയിൽ വാഹനം ഓടിക്കുന്നത് പാടില്ല. Tracks മുറിച്ചുകടക്കുമ്പോൾ നേരെയും ശ്രദ്ധയോടെയും.","ta":"Tram-க்கு மட்டும் உள்ள பாதையில் ஓட்டுவது தடை. தண்டவாளங்களை கடக்கும்போது நேராகவும் கவனமாகவும் கடக்கவும்.","gu":"ફક્ત trams માટે અનામત lane કે માર્ગમાં ચલાવવું નહીં. Trams ને હંમેશા રસ્તો આપો.","ne":"Trams का लागि मात्र आरक्षित lane वा मार्गमा नचलाउनुहोस्। Trams लाई सधैं बाटो दिनुहोस्।"},"tr":{"hi":{"q":"tram की पटरियों के पास आपको क्या नहीं करना चाहिए?","o":["trams पर नज़र रखना","trams को रास्ता देना","सिर्फ़ trams के लिए आरक्षित lane या रास्ते में गाड़ी चलाना","junction पर पटरियाँ पार करना"]},"pa":{"q":"tram ਦੀਆਂ ਪਟੜੀਆਂ ਦੇ ਨੇੜੇ ਤੁਹਾਨੂੰ ਕੀ ਨਹੀਂ ਕਰਨਾ ਚਾਹੀਦਾ?","o":["trams 'ਤੇ ਨਜ਼ਰ ਰੱਖਣਾ","trams ਨੂੰ ਰਾਹ ਦੇਣਾ","ਸਿਰਫ਼ trams ਲਈ ਰਾਖਵੀਂ lane ਜਾਂ ਰਾਹ ਵਿੱਚ ਗੱਡੀ ਚਲਾਉਣਾ","junction 'ਤੇ ਪਟੜੀਆਂ ਪਾਰ ਕਰਨਾ"]},"ur":{"q":"ٹرام کی پٹریوں کے قریب آپ کو کیا نہیں کرنا چاہیے؟","o":["ٹراموں پر نظر رکھنا","ٹراموں کو راستہ دینا","صرف ٹراموں کے لیے مخصوص لین یا راستے میں گاڑی چلانا","جنکشن پر پٹریاں پار کرنا"]},"bn":{"q":"ট্রামের লাইনের কাছে আপনার কী করা উচিত নয়?","o":["ট্রামের দিকে নজর রাখা","ট্রামকে পথ ছেড়ে দেওয়া","শুধু ট্রামের জন্য সংরক্ষিত লেন বা পথে গাড়ি চালানো","জংশনে লাইন পার হওয়া"]},"te":{"q":"ట్రామ్ పట్టాల దగ్గర మీరు ఏమి చేయకూడదు?","o":["ట్రామ్‌ల కోసం చూడడం","ట్రామ్‌లకు దారి ఇవ్వడం","ట్రామ్‌లకు మాత్రమే రిజర్వ్ చేసిన లేన్ లేదా మార్గంలో నడపడం","జంక్షన్ వద్ద పట్టాలు దాటడం"]},"mr":{"q":"ट्राम रुळांजवळ तुम्ही काय करू नये?","o":["ट्रामवर लक्ष ठेवणे","ट्रामला वाट देणे","फक्त ट्रामसाठी राखीव लेन किंवा मार्गावर गाडी चालवणे","चौकात रूळ ओलांडणे"]},"ml":{"q":"tram tracks-ന് അടുത്ത് എന്ത് ചെയ്യരുത്?","o":["trams-നെ ശ്രദ്ധിക്കുക","trams-ന് വഴി നൽകുക","trams-ന് മാത്രം സംവരണം ചെയ്ത lane അല്ലെങ്കിൽ പാതയിൽ ഓടിക്കുക","junction-ൽ tracks മുറിച്ചുകടക്കുക"]},"ta":{"q":"tram தண்டவாளங்கள் அருகே என்ன செய்யக்கூடாது?","o":["trams-ஐ கவனிப்பது","trams-க்கு வழி விடுவது","trams-க்கு மட்டும் ஒதுக்கப்பட்ட lane அல்லது பாதையில் ஓட்டுவது","junction-இல் தண்டவாளங்களை கடப்பது"]},"gu":{"q":"tram પાટા પાસે તમારે શું ન કરવું?","o":["trams પર નજર રાખવી","trams ને રસ્તો આપવો","ફક્ત trams માટે અનામત lane કે માર્ગમાં ચલાવવું","junction પર પાટા ઓળંગવા"]},"ne":{"q":"tram पटरी नजिक तपाईंले के गर्नु हुँदैन?","o":["trams मा नजर राख्नु","trams लाई बाटो दिनु","trams का लागि मात्र आरक्षित lane वा मार्गमा चलाउनु","junction मा पटरी पार गर्नु"]}}},
{"id":8013,"chapter":8,"q":"You’re following a vehicle spreading salt or grit on the road. What should you do?","options":["Keep well back to avoid grit hitting your car","Overtake it quickly","Drive close behind it","Sound your horn"],"answer":0,"exp":{"hi":"Gritter की बजरी गाड़ी को नुकसान पहुँचा सकती है। दूर रहो और धैर्य रखो।","pa":"Gritter ਦੀ ਬਜਰੀ ਗੱਡੀ ਨੂੰ ਨੁਕਸਾਨ ਪਹੁੰਚਾ ਸਕਦੀ ਹੈ। ਦੂਰ ਰਹੋ ਅਤੇ ਸਬਰ ਰੱਖੋ।","ur":"Gritter کی بجری گاڑی کو نقصان پہنچا سکتی ہے۔ دور رہیں اور صبر رکھیں۔","bn":"(not translated yet)","te":"Gritter కంకర మీ వాహనాన్ని పాడుచేయవచ్చు. దూరంగా ఉండి ఓపిక పట్టండి.","mr":"Gritter ची खडी गाडीचे नुकसान करू शकते. दूर राहा आणि संयम ठेवा.","ml":"Gritter-ന്റെ grit വാഹനത്തിന് കേടുവരുത്താം. അകലം പാലിക്കുക, ക്ഷമിക്കുക.","ta":"Gritter-இன் கற்கள் உங்கள் வாகனத்தை சேதப்படுத்தலாம். தூரம் வையுங்கள், பொறுமையாக இருங்கள்.","gu":"Grit ફેલાવતા વાહન પાછળ દૂર રહો જેથી પથ્થર તમારી કારને ન લાગે. ઓવરટેક કરતાં સાવચેતી.","ne":"Grit छर्ने सवारीको पछाडि टाढा बस्नुहोस् ताकि ढुङ्गा तपाईंको कारमा नलागोस्। Overtake गर्दा सावधानी।"},"tr":{"hi":{"q":"आप सड़क पर नमक या grit बिखेरते वाहन के पीछे हैं। आपको क्या करना चाहिए?","o":["grit आपकी कार पर न लगे इसलिए काफ़ी पीछे रहो","जल्दी से उसे overtake करो","उसके ठीक पीछे चलो","horn बजाओ"]},"pa":{"q":"ਤੁਸੀਂ ਸੜਕ 'ਤੇ ਲੂਣ ਜਾਂ grit ਖਿਲਾਰਦੇ ਵਾਹਨ ਦੇ ਪਿੱਛੇ ਹੋ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["grit ਤੁਹਾਡੀ ਕਾਰ 'ਤੇ ਨਾ ਵੱਜੇ ਇਸ ਲਈ ਕਾਫ਼ੀ ਪਿੱਛੇ ਰਹੋ","ਜਲਦੀ ਨਾਲ ਉਸ ਨੂੰ overtake ਕਰੋ","ਉਸ ਦੇ ਠੀਕ ਪਿੱਛੇ ਚੱਲੋ","horn ਵਜਾਓ"]},"ur":{"q":"آپ نمک یا بجری چھڑکنے والی گاڑی کے پیچھے ہیں۔ آپ کو کیا کرنا چاہیے؟","o":["کافی پیچھے رہیں تاکہ بجری آپ کی گاڑی پر نہ لگے","اسے تیزی سے اوور ٹیک کریں","اس کے قریب پیچھے چلیں","ہارن بجائیں"]},"bn":{"q":"আপনি রাস্তায় লবণ বা নুড়ি ছড়ানো একটি যানের পেছনে আছেন। আপনার কী করা উচিত?","o":["অনেক পেছনে থাকুন যাতে নুড়ি আপনার গাড়িতে না লাগে","দ্রুত ওভারটেক করুন","এর কাছ ঘেঁষে চলুন","হর্ন দিন"]},"te":{"q":"మీరు రోడ్డుపై ఉప్పు లేదా గ్రిట్ చల్లుతున్న వాహనం వెనుక ఉన్నారు. మీరు ఏమి చేయాలి?","o":["గ్రిట్ మీ కారుకు తగలకుండా బాగా వెనుక ఉండండి","త్వరగా ఓవర్‌టేక్ చేయండి","దాని వెనుకే దగ్గరగా నడపండి","హారన్ మోగించండి"]},"mr":{"q":"तुम्ही रस्त्यावर मीठ किंवा खडी पसरवणाऱ्या वाहनाच्या मागे आहात. तुम्ही काय करावे?","o":["तुमच्या कारला खडी लागू नये म्हणून चांगले मागे राहा","त्याला लवकर ओव्हरटेक करा","अगदी मागे चालवा","हॉर्न वाजवा"]},"ml":{"q":"റോഡിൽ ഉപ്പോ grit-ഓ വിതറുന്ന ഒരു വാഹനത്തെ പിന്തുടരുകയാണ്. എന്ത് ചെയ്യണം?","o":["grit നിങ്ങളുടെ കാറിൽ തട്ടാതിരിക്കാൻ നന്നായി പിന്നിൽ നിൽക്കുക","വേഗം ഓവർടേക്ക് ചെയ്യുക","അതിന്റെ തൊട്ടുപിന്നിൽ ഓടിക്കുക","horn അടിക്കുക"]},"ta":{"q":"சாலையில் உப்பு அல்லது சரளை தூவும் வாகனத்தை பின்தொடர்கிறீர்கள். என்ன செய்ய வேண்டும்?","o":["கற்கள் உங்கள் காரில் படாமல் இருக்க நன்றாக பின்னால் இருங்கள்","அதை வேகமாக முந்துங்கள்","அதற்கு நெருக்கமாக ஓட்டுங்கள்","horn அடியுங்கள்"]},"gu":{"q":"તમે મીઠું કે grit ફેલાવતા વાહન પાછળ ચાલો છો. શું કરવું?","o":["grit તમારી કારને ન લાગે તે માટે ઘણા પાછળ રહો","ઝડપથી ઓવરટેક કરો","તેની નજીક પાછળ ચલાવો","horn વગાડો"]},"ne":{"q":"तपाईं नुन वा grit छर्दै गरेको सवारीको पछाडि हुनुहुन्छ। के गर्नुपर्छ?","o":["grit तपाईंको कारमा नलागोस् भनी धेरै पछाडि बस्नुहोस्","छिटो overtake गर्नुहोस्","उसको नजिक पछ्याउनुहोस्","horn बजाउनुहोस्"]}}},
{"id":8014,"chapter":8,"q":"A powered wheelchair on a dual carriageway is showing a flashing amber light. What does this tell you?","options":["It’s broken down","It’s a slow-moving vehicle","It’s an emergency vehicle","It’s about to turn right"],"answer":1,"exp":{"hi":"तेज़ dual carriageway पर धीमी गाड़ियाँ amber light लगाती हैं। जल्दी पहचानो और speed कम करो।","pa":"ਤੇਜ਼ dual carriageway ’ਤੇ ਹੌਲੀ ਗੱਡੀਆਂ amber light ਲਾਉਂਦੀਆਂ ਹਨ। ਜਲਦੀ ਪਛਾਣੋ ਅਤੇ speed ਘਟਾਓ।","ur":"تیز dual carriageway پر سست گاڑیاں amber light لگاتی ہیں۔ جلدی پہچانیں اور speed کم کریں۔","bn":"(not translated yet)","te":"వేగవంతమైన dual carriageway పై నెమ్మది వాహనాలు amber light వాడతాయి. త్వరగా గుర్తించి speed తగ్గించండి.","mr":"वेगवान dual carriageway वर हळू गाड्या amber light लावतात. लवकर ओळखा आणि speed कमी करा.","ml":"വേഗതയുള്ള dual carriageway-ൽ പതുക്കെ നീങ്ങുന്ന വാഹനങ്ങൾ amber light വയ്ക്കും. വേഗം തിരിച്ചറിഞ്ഞ് speed കുറയ്ക്കുക.","ta":"வேகமான dual carriageway-இல் மெதுவான வாகனங்கள் amber light போடும். சீக்கிரம் கண்டறிந்து வேகத்தை குறையுங்கள்.","gu":"Amber ઝબકતી લાઈટ = ધીમું ચાલતું વાહન. Powered વ્હીલચેર dual carriageway પર amber બતાવે.","ne":"Amber झिमझिम बत्ती = ढिलो चल्ने सवारी। Powered व्हीलचेयरले dual carriageway मा amber देखाउँछ।"},"tr":{"hi":{"q":"dual carriageway पर एक powered wheelchair चमकती amber बत्ती दिखा रही है। यह आपको क्या बताता है?","o":["वह ख़राब हो गई है","वह धीमा चलने वाला वाहन है","वह आपातकालीन वाहन है","वह दाएँ मुड़ने वाली है"]},"pa":{"q":"dual carriageway 'ਤੇ ਇਕ powered wheelchair ਝਪਕਦੀ amber ਬੱਤੀ ਦਿਖਾ ਰਹੀ ਹੈ। ਇਹ ਤੁਹਾਨੂੰ ਕੀ ਦੱਸਦਾ ਹੈ?","o":["ਉਹ ਖ਼ਰਾਬ ਹੋ ਗਈ ਹੈ","ਉਹ ਹੌਲੀ ਚੱਲਣ ਵਾਲਾ ਵਾਹਨ ਹੈ","ਉਹ ਐਮਰਜੈਂਸੀ ਵਾਹਨ ਹੈ","ਉਹ ਸੱਜੇ ਮੁੜਨ ਵਾਲੀ ਹੈ"]},"ur":{"q":"ڈبل کیریج وے پر ایک پاور وہیل چیئر ٹمٹماتی امبر بتی دکھا رہی ہے۔ یہ آپ کو کیا بتاتا ہے؟","o":["یہ خراب ہو گئی ہے","یہ آہستہ چلنے والی گاڑی ہے","یہ ہنگامی گاڑی ہے","یہ دائیں مڑنے والی ہے"]},"bn":{"q":"ডুয়াল ক্যারেজওয়েতে একটি পাওয়ার হুইলচেয়ার জ্বলনিভুনি অ্যাম্বার আলো দেখাচ্ছে। এটি আপনাকে কী বলে?","o":["এটি বিকল হয়েছে","এটি একটি ধীর গতির যান","এটি একটি জরুরি যান","এটি ডানে বাঁক নিতে যাচ্ছে"]},"te":{"q":"డ్యూయల్ క్యారేజ్‌వేపై పవర్డ్ వీల్‌చైర్ మెరిసే అంబర్ లైట్ చూపుతోంది. ఇది మీకు ఏమి చెబుతుంది?","o":["అది చెడిపోయింది","ఇది నెమ్మదిగా కదిలే వాహనం","ఇది అత్యవసర వాహనం","ఇది కుడికి తిరగబోతోంది"]},"mr":{"q":"dual carriageway वर powered व्हीलचेअर चमकणारा अंबर दिवा दाखवत आहे. यावरून तुम्हाला काय कळते?","o":["ती बिघडली आहे","हे हळू चालणारे वाहन आहे","हे आपत्कालीन वाहन आहे","ती उजवीकडे वळणार आहे"]},"ml":{"q":"dual carriageway-ലെ ഒരു powered wheelchair മിന്നുന്ന amber light കാണിക്കുന്നു. ഇത് നിങ്ങളോട് എന്താണ് പറയുന്നത്?","o":["അത് കേടായി","അത് പതുക്കെ നീങ്ങുന്ന വാഹനമാണ്","അത് ഒരു അടിയന്തര വാഹനമാണ്","അത് വലത്തേക്ക് തിരിയാൻ പോകുന്നു"]},"ta":{"q":"dual carriageway-இல் மின்சார சக்கர நாற்காலி மின்னும் amber விளக்கை காட்டுகிறது. இது உங்களுக்கு என்ன சொல்கிறது?","o":["அது பழுதாகியுள்ளது","அது மெதுவாக செல்லும் வாகனம்","அது அவசர வாகனம்","அது வலதுபுறம் திரும்பப் போகிறது"]},"gu":{"q":"dual carriageway પર powered વ્હીલચેર ઝબકતી amber લાઈટ બતાવે છે. તે શું દર્શાવે છે?","o":["તે બગડી ગઈ છે","તે ધીમું ચાલતું વાહન છે","તે ઇમર્જન્સી વાહન છે","તે જમણે વળવાની છે"]},"ne":{"q":"dual carriageway मा powered व्हीलचेयरले झिमझिम amber बत्ती देखाउँछ। यसले के जनाउँछ?","o":["यो बिग्रिएको छ","यो ढिलो चल्ने सवारी हो","यो आपतकालीन सवारी हो","यो दायाँ मोडिन लागेको छ"]}}},
{"id":8015,"chapter":8,"q":"You’re waiting to turn right out of a junction. An approaching bus is signalling left. What should you do?","options":["Flash your lights at the driver","Sound your horn and go","Wait until you’re sure the bus is actually turning","Pull out straight away"],"answer":2,"exp":{"hi":"Signal गलती से हो सकता है। जब bus मुड़ना शुरू करे तभी निकलो।","pa":"Signal ਗਲਤੀ ਨਾਲ ਹੋ ਸਕਦਾ ਹੈ। ਜਦੋਂ bus ਮੁੜਨਾ ਸ਼ੁਰੂ ਕਰੇ ਤਦੇ ਨਿਕਲੋ।","ur":"Signal غلطی سے ہو سکتا ہے۔ جب bus مڑنا شروع کرے تبھی نکلیں۔","bn":"(not translated yet)","te":"Signal పొరపాటున ఉండవచ్చు. Bus తిరగడం మొదలుపెట్టినప్పుడే బయలుదేరండి.","mr":"Signal चुकून चालू असू शकतो. Bus वळायला लागली तेव्हाच निघा.","ml":"Signal അബദ്ധത്തിൽ ഇട്ടതാകാം. Bus തിരിയാൻ തുടങ്ങുമ്പോൾ മാത്രം പുറത്തേക്ക് കയറുക.","ta":"Signal தவறுதலாக இருக்கலாம். பேருந்து திரும்பத் தொடங்கும்போது மட்டும் வெளியே செல்லுங்கள்.","gu":"બસ ડાબો signal આપે તો પણ ખાતરી ન થાય ત્યાં સુધી નીકળશો નહીં. Signal ભૂલથી પણ હોઈ શકે.","ne":"बसले बायाँ signal दिए पनि पक्का नभएसम्म नजानुहोस्। Signal गल्तीले पनि बल्न सक्छ।"},"tr":{"hi":{"q":"आप junction से दाएँ मुड़ने का इंतज़ार कर रहे हैं। आती हुई बस बाएँ का signal दे रही है। आपको क्या करना चाहिए?","o":["ड्राइवर पर lights चमकाओ","horn बजाओ और निकल जाओ","पक्का होने तक इंतज़ार करो कि बस सच में मुड़ रही है","तुरंत निकल जाओ"]},"pa":{"q":"ਤੁਸੀਂ junction ਤੋਂ ਸੱਜੇ ਮੁੜਨ ਦਾ ਇੰਤਜ਼ਾਰ ਕਰ ਰਹੇ ਹੋ। ਆ ਰਹੀ ਬੱਸ ਖੱਬੇ ਦਾ signal ਦੇ ਰਹੀ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਡਰਾਈਵਰ 'ਤੇ lights ਚਮਕਾਓ","horn ਵਜਾਓ ਅਤੇ ਨਿਕਲ ਜਾਓ","ਪੱਕਾ ਹੋਣ ਤੱਕ ਇੰਤਜ਼ਾਰ ਕਰੋ ਕਿ ਬੱਸ ਸੱਚਮੁੱਚ ਮੁੜ ਰਹੀ ਹੈ","ਤੁਰੰਤ ਨਿਕਲ ਜਾਓ"]},"ur":{"q":"آپ جنکشن سے دائیں مڑنے کا انتظار کر رہے ہیں۔ آتی ہوئی بس بائیں مڑنے کا اشارہ دے رہی ہے۔ آپ کو کیا کرنا چاہیے؟","o":["ڈرائیور پر بتیاں چمکائیں","ہارن بجائیں اور نکل جائیں","اس وقت تک انتظار کریں جب تک یقین نہ ہو جائے کہ بس واقعی مڑ رہی ہے","فوراً نکل جائیں"]},"bn":{"q":"আপনি জংশন থেকে ডানে বাঁক নেওয়ার অপেক্ষায় আছেন। আসন্ন একটি বাস বাঁয়ে সিগন্যাল দিচ্ছে। আপনার কী করা উচিত?","o":["চালকের দিকে আলো জ্বালিয়ে-নিভিয়ে ইশারা দিন","হর্ন দিয়ে এগিয়ে যান","নিশ্চিত না হওয়া পর্যন্ত অপেক্ষা করুন যে বাসটি সত্যিই বাঁক নিচ্ছে","সঙ্গে সঙ্গে বেরিয়ে যান"]},"te":{"q":"మీరు జంక్షన్ నుంచి కుడికి తిరగడానికి వేచి ఉన్నారు. వస్తున్న బస్సు ఎడమ సిగ్నల్ ఇస్తోంది. మీరు ఏమి చేయాలి?","o":["డ్రైవర్‌కు లైట్లు మెరిపించండి","హారన్ మోగించి వెళ్ళండి","బస్సు నిజంగా తిరుగుతోందని నిర్ధారించుకునే వరకు వేచి ఉండండి","వెంటనే బయటకు వెళ్ళండి"]},"mr":{"q":"तुम्ही चौकातून उजवीकडे वळण्यासाठी थांबला आहात. येणारी बस डावीकडचा signal देत आहे. तुम्ही काय करावे?","o":["चालकावर दिवे चमकवा","हॉर्न वाजवा आणि जा","बस खरोखर वळत आहे याची खात्री होईपर्यंत थांबा","लगेच बाहेर पडा"]},"ml":{"q":"ഒരു junction-ൽനിന്ന് വലത്തേക്ക് തിരിയാൻ കാത്തിരിക്കുകയാണ്. അടുത്തെത്തുന്ന ഒരു ബസ് ഇടത്തേക്ക് signal കാണിക്കുന്നു. എന്ത് ചെയ്യണം?","o":["ഡ്രൈവർക്ക് നേരെ lights മിന്നിക്കുക","horn അടിച്ച് പോകുക","ബസ് ശരിക്കും തിരിയുന്നുണ്ടെന്ന് ഉറപ്പാകുന്നതുവരെ കാത്തിരിക്കുക","ഉടൻ പുറത്തേക്ക് കയറുക"]},"ta":{"q":"junction-இலிருந்து வலதுபுறம் திரும்ப காத்திருக்கிறீர்கள். நெருங்கி வரும் பேருந்து இடதுபுற signal காட்டுகிறது. என்ன செய்ய வேண்டும்?","o":["ஓட்டுநருக்கு lights மின்னச் செய்யுங்கள்","horn அடித்து செல்லுங்கள்","பேருந்து உண்மையில் திரும்புகிறது என்று உறுதியாகும் வரை காத்திருங்கள்","உடனே வெளியே செல்லுங்கள்"]},"gu":{"q":"તમે junction પરથી જમણે વળવા રાહ જુઓ છો. આવતી બસ ડાબો signal આપે છે. શું કરવું?","o":["ડ્રાઇવર સામે લાઈટ ઝબકાવો","horn વગાડી જાઓ","બસ ખરેખર વળે છે તેની ખાતરી થાય ત્યાં સુધી રાહ જુઓ","તરત નીકળો"]},"ne":{"q":"तपाईं junction बाट दायाँ मोड्न पर्खँदै हुनुहुन्छ। आउँदै गरेको बसले बायाँ signal दिँदैछ। के गर्नुपर्छ?","o":["चालकलाई बत्ती झिमझिम गर्नुहोस्","horn बजाएर जानुहोस्","बस साँच्चै मोडिँदैछ भन्ने पक्का नभएसम्म पर्खनुहोस्","तुरुन्तै निस्कनुहोस्"]}}},
{"id":8016,"chapter":8,"q":"Why do motorcyclists often ride near the centre of their lane?","options":["To stop you overtaking","Because they’re lost","To avoid the kerb only","To see better and be seen"],"answer":3,"exp":{"hi":"बीच में रहने से वो आगे ज़्यादा देख पाते हैं और दूसरों को दिखते हैं।","pa":"ਵਿਚਕਾਰ ਰਹਿਣ ਨਾਲ ਉਹ ਅੱਗੇ ਵੱਧ ਦੇਖ ਸਕਦੇ ਹਨ ਅਤੇ ਦੂਜਿਆਂ ਨੂੰ ਦਿਸਦੇ ਹਨ।","ur":"درمیان میں رہنے سے وہ آگے زیادہ دیکھ سکتے ہیں اور دوسروں کو نظر آتے ہیں۔","bn":"(not translated yet)","te":"మధ్యలో ఉంటే వారు ముందుకు ఎక్కువ చూడగలరు, ఇతరులకు కనిపిస్తారు.","mr":"मध्ये राहिल्याने त्यांना पुढचे जास्त दिसते आणि इतरांना ते दिसतात.","ml":"നടുവിൽ ഓടിച്ചാൽ അവർക്ക് മുന്നിൽ കൂടുതൽ കാണാം, മറ്റുള്ളവർക്ക് അവരെയും കാണാം.","ta":"நடுவில் இருந்தால் அவர்கள் முன்னால் அதிகம் பார்க்கலாம், மற்றவர்களுக்கும் தெரிவார்கள்.","gu":"મોટરસાઇકલ સવારો lane ની વચ્ચે ચલાવે જેથી વધુ દેખાય અને પોતે પણ સારી રીતે જોઈ શકે.","ne":"मोटरसाइकल सवार lane को बीचमा चलाउँछन् ताकि बढी देखियोस् र आफूले पनि राम्ररी देख्न सकून्।"},"tr":{"hi":{"q":"मोटरसाइकिल सवार अक्सर अपनी lane के बीच के पास क्यों चलते हैं?","o":["आपको overtake करने से रोकने के लिए","क्योंकि वे रास्ता भटक गए हैं","सिर्फ़ kerb से बचने के लिए","बेहतर देखने और दिखाई देने के लिए"]},"pa":{"q":"ਮੋਟਰਸਾਈਕਲ ਸਵਾਰ ਅਕਸਰ ਆਪਣੀ lane ਦੇ ਵਿਚਕਾਰ ਦੇ ਨੇੜੇ ਕਿਉਂ ਚੱਲਦੇ ਹਨ?","o":["ਤੁਹਾਨੂੰ overtake ਕਰਨ ਤੋਂ ਰੋਕਣ ਲਈ","ਕਿਉਂਕਿ ਉਹ ਰਾਹ ਭੁੱਲ ਗਏ ਹਨ","ਸਿਰਫ਼ kerb ਤੋਂ ਬਚਣ ਲਈ","ਬਿਹਤਰ ਦੇਖਣ ਅਤੇ ਦਿਖਾਈ ਦੇਣ ਲਈ"]},"ur":{"q":"موٹر سائیکل سوار اکثر اپنی لین کے بیچ کے قریب کیوں چلتے ہیں؟","o":["آپ کو اوور ٹیک کرنے سے روکنے کے لیے","کیونکہ وہ راستہ بھول گئے ہیں","صرف کنارے سے بچنے کے لیے","بہتر دیکھنے اور زیادہ نظر آنے کے لیے"]},"bn":{"q":"মোটরসাইকেল আরোহীরা প্রায়ই নিজের লেনের মাঝখানের কাছে চলেন কেন?","o":["আপনাকে ওভারটেক করা ঠেকাতে","কারণ তারা পথ হারিয়েছে","শুধু কার্ব এড়াতে","ভালো দেখতে এবং বেশি দৃশ্যমান হতে"]},"te":{"q":"మోటార్‌సైకిల్ వారు తరచుగా తమ లేన్ మధ్యకు దగ్గరగా ఎందుకు నడుపుతారు?","o":["మీరు ఓవర్‌టేక్ చేయకుండా ఆపడానికి","వారు దారి తప్పినందున","కేవలం కర్బ్ తప్పించడానికి","బాగా చూడడానికి, కనిపించడానికి"]},"mr":{"q":"मोटरसायकलस्वार अनेकदा त्यांच्या लेनच्या मध्यभागाजवळ का चालवतात?","o":["तुम्ही ओव्हरटेक करू नये म्हणून","कारण ते हरवले आहेत","फक्त कर्ब टाळण्यासाठी","जास्त चांगले पाहण्यासाठी आणि दिसण्यासाठी"]},"ml":{"q":"മോട്ടോർസൈക്കിൾ യാത്രക്കാർ പലപ്പോഴും lane-ന്റെ നടുവിനടുത്ത് ഓടിക്കുന്നത് എന്തുകൊണ്ട്?","o":["നിങ്ങൾ ഓവർടേക്ക് ചെയ്യുന്നത് തടയാൻ","വഴി തെറ്റിയതിനാൽ","kerb ഒഴിവാക്കാൻ മാത്രം","കൂടുതൽ നന്നായി കാണാനും കാണപ്പെടാനും"]},"ta":{"q":"மோட்டார் சைக்கிள் ஓட்டுநர்கள் ஏன் பெரும்பாலும் lane-இன் நடுவே அருகில் ஓட்டுகிறார்கள்?","o":["நீங்கள் முந்துவதைத் தடுக்க","அவர்கள் வழி தவறியதால்","kerb-ஐ தவிர்க்க மட்டும்","நன்றாகப் பார்க்கவும் தெரியவும்"]},"gu":{"q":"મોટરસાઇકલ સવારો ઘણીવાર lane ની વચ્ચે કેમ ચલાવે છે?","o":["તમને ઓવરટેક કરતાં રોકવા","કારણ કે તે ખોવાયા છે","ફક્ત kerb થી બચવા","વધુ સારી રીતે જોવા અને દેખાવા"]},"ne":{"q":"मोटरसाइकल सवार प्राय: lane को बीचमा किन चलाउँछन्?","o":["तपाईंलाई overtake गर्न नदिन","किनभने तिनी हराएका छन्","kerb बाट बच्न मात्र","राम्रोसँग देख्न र देखिन"]}}},
{"id":8017,"chapter":8,"q":"Why should cyclists and motorcyclists take care crossing tram tracks?","options":["Wheels can slip or get stuck; cross at a right angle","Tracks are electric","Trams go backwards","It’s not allowed"],"answer":0,"exp":{"hi":"पटरी में पहिया फँस या फिसल सकता है। सीधे कोण पर पार करना सुरक्षित है।","pa":"ਪਟੜੀ ਵਿੱਚ ਪਹੀਆ ਫਸ ਜਾਂ ਤਿਲਕ ਸਕਦਾ ਹੈ। ਸਿੱਧੇ ਕੋਣ ’ਤੇ ਪਾਰ ਕਰਨਾ ਸੁਰੱਖਿਅਤ ਹੈ।","ur":"پٹری میں پہیہ پھنس یا پھسل سکتا ہے۔ سیدھے زاویے پر پار کرنا محفوظ ہے۔","bn":"(not translated yet)","te":"పట్టాలో చక్రం ఇరుక్కోవచ్చు లేదా జారవచ్చు. నేరుగా కోణంలో దాటడం సురక్షితం.","mr":"रुळात चाक अडकू किंवा घसरू शकते. काटकोनात ओलांडणे सुरक्षित आहे.","ml":"പാളത്തിൽ wheel കുടുങ്ങുകയോ തെന്നുകയോ ചെയ്യാം. വലത്കോണിൽ മുറിച്ചുകടക്കുന്നതാണ് സുരക്ഷിതം.","ta":"தண்டவாளத்தில் சக்கரம் சிக்கலாம் அல்லது வழுக்கலாம். செங்குத்து கோணத்தில் கடப்பது பாதுகாப்பானது.","gu":"Tram પાટા લપસણા અને પૈડાં ફસાવી શકે. કાટકોણે (90°) ઓળંગો.","ne":"Tram पटरी चिप्लो हुन्छ र पाङ्ग्रा अड्काउन सक्छ। समकोणमा (90°) पार गर्नुहोस्।"},"tr":{"hi":{"q":"साइकिल सवारों और मोटरसाइकिल सवारों को tram की पटरियाँ पार करते समय सावधान क्यों रहना चाहिए?","o":["पहिये फिसल सकते हैं या फँस सकते हैं; समकोण पर पार करो","पटरियों में बिजली होती है","trams पीछे की ओर जाती हैं","यह अनुमत नहीं है"]},"pa":{"q":"ਸਾਈਕਲ ਸਵਾਰਾਂ ਅਤੇ ਮੋਟਰਸਾਈਕਲ ਸਵਾਰਾਂ ਨੂੰ tram ਦੀਆਂ ਪਟੜੀਆਂ ਪਾਰ ਕਰਦੇ ਸਮੇਂ ਸਾਵਧਾਨ ਕਿਉਂ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਪਹੀਏ ਤਿਲਕ ਸਕਦੇ ਹਨ ਜਾਂ ਫਸ ਸਕਦੇ ਹਨ; ਸਮਕੋਣ 'ਤੇ ਪਾਰ ਕਰੋ","ਪਟੜੀਆਂ ਵਿੱਚ ਬਿਜਲੀ ਹੁੰਦੀ ਹੈ","trams ਪਿੱਛੇ ਵੱਲ ਜਾਂਦੀਆਂ ਹਨ","ਇਹ ਮਨਜ਼ੂਰ ਨਹੀਂ ਹੈ"]},"ur":{"q":"سائیکل سواروں اور موٹر سائیکل سواروں کو ٹرام کی پٹریاں پار کرتے وقت احتیاط کیوں کرنی چاہیے؟","o":["پہیے پھسل سکتے ہیں یا پھنس سکتے ہیں؛ انہیں زاویہ قائمہ (سیدھے) پر پار کریں","پٹریاں بجلی کی ہوتی ہیں","ٹرامیں الٹی چلتی ہیں","ایسا کرنے کی اجازت نہیں"]},"bn":{"q":"সাইকেল ও মোটরসাইকেল আরোহীদের ট্রামলাইন পার হওয়ার সময় সতর্ক হওয়া উচিত কেন?","o":["চাকা পিছলে যেতে বা আটকে যেতে পারে; সমকোণে পার হন","লাইনগুলো বৈদ্যুতিক","ট্রাম পিছনে চলে","এটি অনুমোদিত নয়"]},"te":{"q":"సైకిలిస్టులు, మోటార్‌సైకిల్ వారు ట్రామ్ పట్టాలు దాటేటప్పుడు ఎందుకు జాగ్రత్త తీసుకోవాలి?","o":["చక్రాలు జారవచ్చు లేదా ఇరుక్కోవచ్చు; లంబ కోణంలో దాటండి","పట్టాలు విద్యుత్తుతో ఉంటాయి","ట్రామ్‌లు వెనక్కి వెళ్తాయి","ఇది అనుమతించబడదు"]},"mr":{"q":"सायकलस्वार आणि मोटरसायकलस्वारांनी ट्राम रूळ ओलांडताना काळजी का घ्यावी?","o":["चाके घसरू किंवा अडकू शकतात; काटकोनात ओलांडा","रूळ विजेचे असतात","ट्राम उलट जातात","ते परवानगीप्राप्त नाही"]},"ml":{"q":"സൈക്കിൾ, മോട്ടോർസൈക്കിൾ യാത്രക്കാർ tram tracks മുറിച്ചുകടക്കുമ്പോൾ ശ്രദ്ധിക്കേണ്ടത് എന്തുകൊണ്ട്?","o":["wheels തെന്നുകയോ കുടുങ്ങുകയോ ചെയ്യാം; വലത്കോണിൽ മുറിച്ചുകടക്കുക","tracks വൈദ്യുതിയുള്ളതാണ്","trams പിന്നോട്ട് പോകും","അത് അനുവദനീയമല്ല"]},"ta":{"q":"cyclists மற்றும் மோட்டார் சைக்கிள் ஓட்டுநர்கள் tram தண்டவாளங்களை கடக்கும்போது ஏன் கவனமாக இருக்க வேண்டும்?","o":["சக்கரங்கள் வழுக்கலாம் அல்லது சிக்கலாம்; செங்குத்து கோணத்தில் கடக்கவும்","தண்டவாளங்கள் மின்சாரம் உள்ளவை","trams பின்னோக்கி செல்லும்","அனுமதி இல்லை"]},"gu":{"q":"cyclists અને મોટરસાઇકલ સવારોએ tram પાટા ઓળંગતા કાળજી કેમ રાખવી?","o":["પૈડાં લપસી શકે કે ફસાઈ શકે; કાટકોણે ઓળંગો","પાટા વીજળીવાળા છે","trams પાછળ જાય છે","તેની મંજૂરી નથી"]},"ne":{"q":"cyclists र मोटरसाइकल सवारले tram पटरी काट्दा किन सावधानी अपनाउने?","o":["पाङ्ग्रा चिप्लन वा अड्किन सक्छन्; समकोणमा पार गर्नुहोस्","पटरीमा बिजुली हुन्छ","trams पछाडि जान्छन्","यसको अनुमति छैन"]}}},
{"id":8019,"chapter":8,"q":"An abnormal load with a police escort is coming towards you on a narrow road. What should you do?","options":["Sound your horn","Flash your lights","Be ready to stop and follow the escort’s directions","Keep going"],"answer":2,"exp":{"hi":"बड़े loads को पूरी सड़क चाहिए। Escort के निर्देश मानो।","pa":"ਵੱਡੇ loads ਨੂੰ ਪੂਰੀ ਸੜਕ ਚਾਹੀਦੀ ਹੈ। Escort ਦੇ ਨਿਰਦੇਸ਼ ਮੰਨੋ।","ur":"بڑے loads کو پوری سڑک چاہیے۔ Escort کی ہدایات مانیں۔","bn":"(not translated yet)","te":"పెద్ద loads కు రోడ్డు మొత్తం కావాలి. Escort సూచనలు పాటించండి.","mr":"मोठ्या loads ना संपूर्ण रस्ता हवा असतो. Escort च्या सूचना पाळा.","ml":"വലിയ loads-ന് റോഡ് മുഴുവൻ വേണം. അകമ്പടിക്കാരുടെ നിർദ്ദേശങ്ങൾ പാലിക്കുക.","ta":"பெரிய சுமைகளுக்கு முழு சாலையும் தேவை. Escort-இன் அறிவுறுத்தல்களைப் பின்பற்றுங்கள்.","gu":"Abnormal load અને escort આવે તો ઊભા રહેવા તૈયાર રહો અને escort ની સૂચના પાળો.","ne":"Abnormal load र escort आउँदा रोकिन तयार रहनुहोस् र escort को निर्देशन पालना गर्नुहोस्।"},"tr":{"hi":{"q":"पुलिस escort वाला असामान्य माल (abnormal load) संकरी सड़क पर आपकी तरफ़ आ रहा है। आपको क्या करना चाहिए?","o":["horn बजाओ","lights चमकाओ","रुकने को तैयार रहो और escort के निर्देशों का पालन करो","चलते रहो"]},"pa":{"q":"ਪੁਲਿਸ escort ਵਾਲਾ ਅਸਾਧਾਰਨ ਮਾਲ (abnormal load) ਭੀੜੀ ਸੜਕ 'ਤੇ ਤੁਹਾਡੇ ਵੱਲ ਆ ਰਿਹਾ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["horn ਵਜਾਓ","lights ਚਮਕਾਓ","ਰੁਕਣ ਲਈ ਤਿਆਰ ਰਹੋ ਅਤੇ escort ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ","ਚੱਲਦੇ ਰਹੋ"]},"ur":{"q":"پولیس ایسکارٹ کے ساتھ ایک غیر معمولی بوجھ والی گاڑی تنگ سڑک پر آپ کی طرف آ رہی ہے۔ آپ کو کیا کرنا چاہیے؟","o":["ہارن بجائیں","بتیاں چمکائیں","رکنے کے لیے تیار رہیں اور ایسکارٹ کی ہدایات پر عمل کریں","چلتے رہیں"]},"bn":{"q":"পুলিশ এসকর্টসহ একটি অস্বাভাবিক বোঝাই যান সরু রাস্তায় আপনার দিকে আসছে। আপনার কী করা উচিত?","o":["হর্ন দিন","আলো জ্বালিয়ে-নিভিয়ে ইশারা দিন","থামতে প্রস্তুত থাকুন এবং এসকর্টের নির্দেশ মেনে চলুন","চলতে থাকুন"]},"te":{"q":"పోలీస్ ఎస్కార్ట్‌తో ఉన్న అసాధారణ లోడ్ ఇరుకైన రోడ్డుపై మీ వైపు వస్తోంది. మీరు ఏమి చేయాలి?","o":["హారన్ మోగించండి","లైట్లు మెరిపించండి","ఆగడానికి సిద్ధంగా ఉండి ఎస్కార్ట్ ఆదేశాలు పాటించండి","కొనసాగండి"]},"mr":{"q":"पोलीस एस्कॉर्टसह एक अवाढव्य माल (abnormal load) अरुंद रस्त्यावर तुमच्याकडे येत आहे. तुम्ही काय करावे?","o":["हॉर्न वाजवा","दिवे चमकवा","थांबायला तयार राहा आणि एस्कॉर्टच्या सूचना पाळा","चालू ठेवा"]},"ml":{"q":"പോലീസ് അകമ്പടിയോടെ ഒരു abnormal load ഇടുങ്ങിയ റോഡിൽ നിങ്ങൾക്ക് നേരെ വരുന്നു. എന്ത് ചെയ്യണം?","o":["horn അടിക്കുക","lights മിന്നിക്കുക","നിർത്താൻ തയ്യാറായി അകമ്പടിക്കാരുടെ നിർദ്ദേശങ്ങൾ പാലിക്കുക","തുടരുക"]},"ta":{"q":"போலீஸ் பாதுகாப்புடன் ஒரு அசாதாரண சுமை குறுகிய சாலையில் உங்களை நோக்கி வருகிறது. என்ன செய்ய வேண்டும்?","o":["horn அடியுங்கள்","lights மின்னச் செய்யுங்கள்","நிற்க தயாராகி escort-இன் வழிகாட்டுதலை பின்பற்றுங்கள்","தொடர்ந்து செல்லுங்கள்"]},"gu":{"q":"સાંકડા રોડ પર પોલીસ escort સાથે abnormal load તમારી તરફ આવે છે. શું કરવું?","o":["horn વગાડો","લાઈટ ઝબકાવો","ઊભા રહેવા તૈયાર રહો અને escort ની સૂચના પાળો","ચાલુ રાખો"]},"ne":{"q":"साँघुरो सडकमा प्रहरी escort सहितको abnormal load तपाईंतिर आउँदैछ। के गर्नुपर्छ?","o":["horn बजाउनुहोस्","बत्ती झिमझिम गर्नुहोस्","रोकिन तयार रहनुहोस् र escort को निर्देशन पालना गर्नुहोस्","चलिरहनुहोस्"]}}},
{"id":8020,"chapter":8,"q":"You hear a beeping sound and see a lorry reversing. What should you do?","options":["Drive past quickly","Sound your horn","Flash your lights","Stop and wait; the driver may not see you"],"answer":3,"exp":{"hi":"Reverse करती lorry के पीछे बड़ा blind spot होता है। रुककर इंतज़ार करो।","pa":"Reverse ਹੁੰਦੀ lorry ਦੇ ਪਿੱਛੇ ਵੱਡਾ blind spot ਹੁੰਦਾ ਹੈ। ਰੁਕ ਕੇ ਉਡੀਕ ਕਰੋ।","ur":"Reverse ہوتی lorry کے پیچھے بڑا blind spot ہوتا ہے۔ رک کر انتظار کریں۔","bn":"(not translated yet)","te":"Reverse అవుతున్న lorry వెనుక పెద్ద blind spot ఉంటుంది. ఆగి ఎదురుచూడండి.","mr":"Reverse करणाऱ्या lorry च्या मागे मोठा blind spot असतो. थांबून वाट पाहा.","ml":"Reverse ചെയ്യുന്ന lorry-യുടെ പിന്നിൽ വലിയ blind spot ഉണ്ട്. നിർത്തി കാത്തിരിക്കുക.","ta":"பின்னோக்கி செல்லும் lorry-இன் பின்னால் பெரிய blind spot உண்டு. நின்று காத்திருங்கள்.","gu":"Reverse કરતી lorry ના ડ્રાઇવરને તમે ન દેખાતા હો. ઊભા રહીને રાહ જુઓ.","ne":"Reverse गर्दै गरेको lorry का चालकले तपाईंलाई नदेख्न सक्छ। रोकिएर पर्खनुहोस्।"},"tr":{"hi":{"q":"आपको बीप की आवाज़ सुनाई देती है और एक lorry reverse करती दिखती है। आपको क्या करना चाहिए?","o":["जल्दी से निकल जाओ","horn बजाओ","lights चमकाओ","रुक जाओ और इंतज़ार करो; ड्राइवर आपको नहीं देख पा रहा हो सकता है"]},"pa":{"q":"ਤੁਹਾਨੂੰ ਬੀਪ ਦੀ ਆਵਾਜ਼ ਸੁਣਾਈ ਦਿੰਦੀ ਹੈ ਅਤੇ ਇਕ lorry reverse ਕਰਦੀ ਦਿਸਦੀ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਜਲਦੀ ਨਾਲ ਨਿਕਲ ਜਾਓ","horn ਵਜਾਓ","lights ਚਮਕਾਓ","ਰੁਕ ਜਾਓ ਅਤੇ ਇੰਤਜ਼ਾਰ ਕਰੋ; ਡਰਾਈਵਰ ਤੁਹਾਨੂੰ ਨਹੀਂ ਦੇਖ ਪਾ ਰਿਹਾ ਹੋ ਸਕਦਾ ਹੈ"]},"ur":{"q":"آپ بیپ کی آواز سنتے ہیں اور ایک لاری کو ریورس کرتے دیکھتے ہیں۔ آپ کو کیا کرنا چاہیے؟","o":["تیزی سے گزر جائیں","ہارن بجائیں","بتیاں چمکائیں","رک کر انتظار کریں؛ ڈرائیور آپ کو نہیں دیکھ سکتا"]},"bn":{"q":"আপনি বিপ শব্দ শুনছেন এবং একটি লরিকে রিভার্স করতে দেখছেন। আপনার কী করা উচিত?","o":["দ্রুত পার হয়ে যান","হর্ন দিন","আলো জ্বালিয়ে-নিভিয়ে ইশারা দিন","থামুন ও অপেক্ষা করুন; চালক আপনাকে দেখতে নাও পেতে পারেন"]},"te":{"q":"మీకు బీప్ శబ్దం వినిపిస్తోంది, లారీ రివర్స్ చేస్తున్నట్లు కనిపిస్తోంది. మీరు ఏమి చేయాలి?","o":["త్వరగా దాటి వెళ్ళండి","హారన్ మోగించండి","లైట్లు మెరిపించండి","ఆగి వేచి ఉండండి; డ్రైవర్‌కు మీరు కనిపించకపోవచ్చు"]},"mr":{"q":"तुम्हाला बीपचा आवाज येतो आणि लॉरी रिव्हर्स होताना दिसते. तुम्ही काय करावे?","o":["लवकर पुढे जा","हॉर्न वाजवा","दिवे चमकवा","थांबा आणि वाट पाहा; चालकाला तुम्ही दिसत नसाल"]},"ml":{"q":"ബീപ്പ് ശബ്ദം കേൾക്കുകയും ഒരു lorry reverse ചെയ്യുന്നത് കാണുകയും ചെയ്യുന്നു. എന്ത് ചെയ്യണം?","o":["വേഗം കടന്നുപോകുക","horn അടിക്കുക","lights മിന്നിക്കുക","നിർത്തി കാത്തിരിക്കുക; ഡ്രൈവർക്ക് നിങ്ങളെ കാണാൻ കഴിഞ്ഞേക്കില്ല"]},"ta":{"q":"beep சத்தம் கேட்கிறது, ஒரு lorry பின்னோக்கி செல்வதைப் பார்க்கிறீர்கள். என்ன செய்ய வேண்டும்?","o":["வேகமாக கடந்து செல்லுங்கள்","horn அடியுங்கள்","lights மின்னச் செய்யுங்கள்","நின்று காத்திருங்கள்; ஓட்டுநர் உங்களைப் பார்க்காமல் இருக்கலாம்"]},"gu":{"q":"તમને beeping સંભળાય છે અને lorry reverse કરતી દેખાય છે. શું કરવું?","o":["ઝડપથી પસાર થાઓ","horn વગાડો","લાઈટ ઝબકાવો","ઊભા રહી રાહ જુઓ; ડ્રાઇવર તમને ન જોતો હોય"]},"ne":{"q":"तपाईंले बिप-बिप आवाज सुन्नुभयो र lorry reverse गर्दै गरेको देख्नुभयो। के गर्नुपर्छ?","o":["छिटो नाघ्नुहोस्","horn बजाउनुहोस्","बत्ती झिमझिम गर्नुहोस्","रोकिएर पर्खनुहोस्; चालकले तपाईंलाई नदेखेको हुन सक्छ"]}}},
{"id":8021,"chapter":8,"q":"Why might a large lorry not use the right-hand lane on a motorway with three or more lanes?","options":["Lorries over 7.5 tonnes aren’t allowed in it","It’s too narrow","It’s for buses","It’s for emergencies"],"answer":0,"exp":{"hi":"7.5 tonne से भारी goods vehicles (और towing वाली गाड़ियाँ) सबसे दाईं lane में नहीं जा सकतीं (कुछ ख़ास हालात छोड़कर)।","pa":"7.5 tonne ਤੋਂ ਭਾਰੀ goods vehicles (ਅਤੇ towing ਵਾਲੀਆਂ ਗੱਡੀਆਂ) ਸਭ ਤੋਂ ਸੱਜੀ lane ਵਿੱਚ ਨਹੀਂ ਜਾ ਸਕਦੀਆਂ (ਕੁਝ ਖ਼ਾਸ ਹਾਲਾਤ ਛੱਡ ਕੇ)।","ur":"7.5 tonne سے بھاری goods vehicles (اور towing والی گاڑیاں) سب سے دائیں lane میں نہیں جا سکتیں (کچھ خاص حالات چھوڑ کر)۔","bn":"(not translated yet)","te":"7.5 tonne కన్నా బరువైన goods vehicles (towing వాహనాలు కూడా) అత్యంత కుడి lane లోకి వెళ్ళకూడదు (కొన్ని ప్రత్యేక సందర్భాలు తప్ప).","mr":"7.5 tonne पेक्षा जड goods vehicles (आणि towing करणाऱ्या गाड्या) सर्वात उजव्या lane मध्ये जाऊ शकत नाहीत (काही विशेष परिस्थिती वगळता).","ml":"7.5 tonne-ൽ കൂടുതലുള്ള goods vehicles-നും (towing ചെയ്യുന്ന വാഹനങ്ങൾക്കും) ഏറ്റവും വലത് lane-ൽ പോകാൻ പാടില്ല (ചില പ്രത്യേക സാഹചര്യങ്ങൾ ഒഴികെ).","ta":"7.5 டன்னுக்கு மேற்பட்ட goods வாகனங்கள் (மற்றும் இழுக்கும் வாகனங்கள்) வலது முனையில் உள்ள lane-இல் செல்ல முடியாது (சில சிறப்பு சூழ்நிலைகளைத் தவிர).","gu":"7.5 ટનથી ભારે lorries ને ત્રણ કે વધુ lanes વાળા motorway પર જમણી lane નો ઉપયોગ કરવાની મનાઈ છે.","ne":"7.5 टनभन्दा भारी lorries लाई तीन वा बढी lane भएको मोटरवेमा दायाँ lane प्रयोग गर्न मनाही छ।"},"tr":{"hi":{"q":"तीन या ज़्यादा lanes वाले मोटरवे पर बड़ी lorry दाईं तरफ़ वाली lane का इस्तेमाल क्यों नहीं कर सकती?","o":["7.5 टन से भारी lorries को इसमें अनुमति नहीं है","यह बहुत संकरी है","यह बसों के लिए है","यह आपात स्थिति के लिए है"]},"pa":{"q":"ਤਿੰਨ ਜਾਂ ਵੱਧ lanes ਵਾਲੇ ਮੋਟਰਵੇ 'ਤੇ ਵੱਡੀ lorry ਸੱਜੇ ਪਾਸੇ ਵਾਲੀ lane ਕਿਉਂ ਨਹੀਂ ਵਰਤ ਸਕਦੀ?","o":["7.5 ਟਨ ਤੋਂ ਭਾਰੀਆਂ lorries ਨੂੰ ਇਸ ਵਿੱਚ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ","ਇਹ ਬਹੁਤ ਭੀੜੀ ਹੈ","ਇਹ ਬੱਸਾਂ ਲਈ ਹੈ","ਇਹ ਐਮਰਜੈਂਸੀ ਲਈ ਹੈ"]},"ur":{"q":"تین یا زیادہ لینوں والی موٹروے پر بڑی لاری دائیں لین کیوں استعمال نہیں کر سکتی؟","o":["7.5 ٹن سے زیادہ کی لاریوں کو اس میں اجازت نہیں","یہ بہت تنگ ہے","یہ بسوں کے لیے ہے","یہ ہنگامی حالات کے لیے ہے"]},"bn":{"q":"তিন বা তার বেশি লেনের মোটরওয়েতে একটি বড় লরি ডান দিকের লেন ব্যবহার করে না কেন?","o":["৭.৫ টনের বেশি লরির জন্য এতে অনুমতি নেই","এটি খুব সরু","এটি বাসের জন্য","এটি জরুরি অবস্থার জন্য"]},"te":{"q":"మూడు లేదా అంతకంటే ఎక్కువ లేన్లు ఉన్న మోటార్‌వేపై పెద్ద లారీ కుడి వైపు లేన్‌ను ఎందుకు వాడకపోవచ్చు?","o":["7.5 టన్నుల కంటే బరువైన లారీలకు అందులో అనుమతి లేదు","ఇది చాలా ఇరుకుగా ఉంది","ఇది బస్సుల కోసం","ఇది అత్యవసరాల కోసం"]},"mr":{"q":"तीन किंवा अधिक लेन असलेल्या मोटरवेवर मोठी लॉरी उजवी लेन का वापरू शकत नाही?","o":["७.५ टनांपेक्षा जड लॉरींना त्यात परवानगी नाही","ती खूप अरुंद आहे","ती बससाठी आहे","ती आणीबाणीसाठी आहे"]},"ml":{"q":"മൂന്നോ അതിലധികമോ lanes ഉള്ള മോട്ടോർവേയിൽ ഒരു വലിയ lorry വലത് lane ഉപയോഗിക്കാത്തത് എന്തുകൊണ്ടായിരിക്കാം?","o":["7.5 ടണ്ണിന് മുകളിലുള്ള lorries-ന് അതിൽ അനുവാദമില്ല","അത് വളരെ ഇടുങ്ങിയതാണ്","അത് ബസുകൾക്കുള്ളതാണ്","അത് അടിയന്തര ഉപയോഗത്തിനാണ്"]},"ta":{"q":"மூன்று அல்லது அதற்கு மேற்பட்ட lanes உள்ள மோட்டார்வேயில் பெரிய lorry ஏன் வலது lane-ஐ பயன்படுத்தாமல் இருக்கலாம்?","o":["7.5 டன்னுக்கு மேற்பட்ட lorry-கள் அதில் அனுமதிக்கப்படாது","அது மிகவும் குறுகியது","அது பேருந்துகளுக்கு","அது அவசரத்திற்கு"]},"gu":{"q":"ત્રણ કે વધુ lanes વાળા motorway પર મોટી lorry જમણી lane કેમ ન વાપરે?","o":["7.5 ટનથી ભારે lorries ને તેમાં મંજૂરી નથી","તે ખૂબ સાંકડી છે","તે બસો માટે છે","તે ઇમર્જન્સી માટે છે"]},"ne":{"q":"तीन वा बढी lane भएको मोटरवेमा ठूलो lorry ले दायाँ lane किन प्रयोग गर्दैन?","o":["7.5 टनभन्दा भारी lorries लाई त्यसमा अनुमति छैन","यो धेरै साँघुरो छ","यो बसका लागि हो","यो आपतकालका लागि हो"]}}},
{"id":8022,"chapter":8,"q":"Why might a lorry take a long time to overtake another lorry on a motorway?","options":["The road is too narrow","Both may be speed-limited to similar speeds","Lorries can’t accelerate","It’s against the rules"],"answer":1,"exp":{"hi":"बड़ी lorries में speed limiter होते हैं, इसलिए दोनों की speed लगभग बराबर होती है। धैर्य रखो।","pa":"ਵੱਡੀਆਂ lorries ਵਿੱਚ speed limiter ਹੁੰਦੇ ਹਨ, ਇਸ ਲਈ ਦੋਵਾਂ ਦੀ speed ਲਗਭਗ ਬਰਾਬਰ ਹੁੰਦੀ ਹੈ। ਸਬਰ ਰੱਖੋ।","ur":"بڑی lorries میں speed limiter ہوتے ہیں، اس لیے دونوں کی speed تقریباً برابر ہوتی ہے۔ صبر رکھیں۔","bn":"(not translated yet)","te":"పెద్ద lorries లో speed limiters ఉంటాయి, కాబట్టి రెండింటి speed దాదాపు సమానం. ఓపిక పట్టండి.","mr":"मोठ्या lorries मध्ये speed limiter असतात, म्हणून दोघांचा speed जवळपास सारखा असतो. संयम ठेवा.","ml":"വലിയ lorries-ൽ speed limiter ഉണ്ട്, അതിനാൽ രണ്ടിന്റെയും speed ഏതാണ്ട് തുല്യമാണ്. ക്ഷമിക്കുക.","ta":"பெரிய lorry-களில் speed limiter இருப்பதால் இரண்டும் ஏறக்குறைய ஒரே வேகத்தில் செல்லும். பொறுமை.","gu":"Lorries ઘણીવાર સમાન ઝડપ (limiter) સુધી જ ચાલે, એટલે ઓવરટેક કરવામાં લાંબો સમય લાગે. ધીરજ રાખો.","ne":"Lorries प्राय: उस्तै गति (limiter) सम्म मात्र चल्छन्, त्यसैले overtake गर्न लामो समय लाग्छ। धैर्य राख्नुहोस्।"},"tr":{"hi":{"q":"मोटरवे पर एक lorry को दूसरी lorry को overtake करने में लंबा समय क्यों लग सकता है?","o":["सड़क बहुत संकरी है","दोनों की speed एक जैसी सीमित हो सकती है","lorries accelerate नहीं कर सकतीं","यह नियमों के ख़िलाफ़ है"]},"pa":{"q":"ਮੋਟਰਵੇ 'ਤੇ ਇਕ lorry ਨੂੰ ਦੂਜੀ lorry ਨੂੰ overtake ਕਰਨ ਵਿੱਚ ਲੰਮਾ ਸਮਾਂ ਕਿਉਂ ਲੱਗ ਸਕਦਾ ਹੈ?","o":["ਸੜਕ ਬਹੁਤ ਭੀੜੀ ਹੈ","ਦੋਵਾਂ ਦੀ speed ਇੱਕੋ ਜਿਹੀ ਸੀਮਤ ਹੋ ਸਕਦੀ ਹੈ","lorries accelerate ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ","ਇਹ ਨਿਯਮਾਂ ਦੇ ਖ਼ਿਲਾਫ਼ ਹੈ"]},"ur":{"q":"موٹروے پر ایک لاری دوسری لاری کو اوور ٹیک کرنے میں بہت وقت کیوں لے سکتی ہے؟","o":["سڑک بہت تنگ ہے","دونوں کی رفتار تقریباً ایک جیسی حد میں بندھی ہو سکتی ہے","لاریاں رفتار نہیں بڑھا سکتیں","یہ قواعد کے خلاف ہے"]},"bn":{"q":"মোটরওয়েতে একটি লরি অন্য লরিকে ওভারটেক করতে কেন অনেক সময় নিতে পারে?","o":["রাস্তা খুব সরু","দুটিরই গতি কাছাকাছি সীমায় বাঁধা থাকতে পারে","লরি গতি বাড়াতে পারে না","এটি নিয়মের বিরুদ্ধে"]},"te":{"q":"మోటార్‌వేపై ఒక లారీ మరో లారీని ఓవర్‌టేక్ చేయడానికి ఎక్కువ సమయం ఎందుకు పట్టవచ్చు?","o":["రోడ్డు చాలా ఇరుకుగా ఉంది","రెండింటికీ ఒకే విధమైన వేగ పరిమితి ఉండవచ్చు","లారీలు వేగం పెంచలేవు","ఇది నియమాలకు విరుద్ధం"]},"mr":{"q":"मोटरवेवर एका लॉरीला दुसऱ्या लॉरीला ओव्हरटेक करायला खूप वेळ का लागू शकतो?","o":["रस्ता खूप अरुंद आहे","दोघांचाही वेग सारख्याच मर्यादेपर्यंत बंधित असू शकतो","लॉरी वेग वाढवू शकत नाहीत","ते नियमांविरुद्ध आहे"]},"ml":{"q":"മോട്ടോർവേയിൽ ഒരു lorry മറ്റൊരു lorry-യെ ഓവർടേക്ക് ചെയ്യാൻ കൂടുതൽ സമയമെടുക്കുന്നത് എന്തുകൊണ്ടായിരിക്കാം?","o":["റോഡ് വളരെ ഇടുങ്ങിയതാണ്","രണ്ടിനും ഏതാണ്ട് ഒരേ വേഗതാ പരിധിയാകാം","lorries-ന് accelerate ചെയ്യാൻ കഴിയില്ല","അത് നിയമത്തിന് എതിരാണ്"]},"ta":{"q":"மோட்டார்வேயில் ஒரு lorry மற்றொரு lorry-ஐ முந்த ஏன் நீண்ட நேரம் ஆகலாம்?","o":["சாலை மிகவும் குறுகியது","இரண்டுக்கும் வேக வரம்பு கட்டுப்பாடு இருந்து ஒரே வேகத்தில் இருக்கலாம்","lorry-களால் வேகமெடுக்க முடியாது","விதிகளுக்கு எதிரானது"]},"gu":{"q":"motorway પર એક lorry બીજી lorry ને ઓવરટેક કરવામાં લાંબો સમય કેમ લે?","o":["રોડ ખૂબ સાંકડો છે","બંને સમાન ઝડપ સુધી limited હોઈ શકે","lorries accelerate કરી શકતી નથી","તે નિયમ વિરુદ્ધ છે"]},"ne":{"q":"मोटरवेमा एउटा lorry ले अर्को lorry लाई नाघ्न किन लामो समय लिन सक्छ?","o":["सडक धेरै साँघुरो छ","दुवै उस्तै गतिमा limited हुन सक्छन्","lorries accelerate गर्न सक्दैनन्","यो नियम विरुद्ध हो"]}}},
{"id":8023,"chapter":8,"q":"Why is it dangerous for a cyclist to be on the left of a lorry at a junction?","options":["The cyclist has priority","Lorries always go straight","The lorry may turn left and the driver may not see them","Lorries can’t turn left"],"answer":2,"exp":{"hi":"Lorry के बाईं ओर बड़ा blind spot होता है। Driver के तौर पर cyclists का ख़ास ध्यान रखो।","pa":"Lorry ਦੇ ਖੱਬੇ ਪਾਸੇ ਵੱਡਾ blind spot ਹੁੰਦਾ ਹੈ। Driver ਵਜੋਂ cyclists ਦਾ ਖ਼ਾਸ ਧਿਆਨ ਰੱਖੋ।","ur":"Lorry کے بائیں طرف بڑا blind spot ہوتا ہے۔ Driver کے طور پر cyclists کا خاص دھیان رکھیں۔","bn":"(not translated yet)","te":"Lorry ఎడమ వైపు పెద్ద blind spot ఉంటుంది. Driver గా cyclists ను ప్రత్యేకంగా గమనించండి.","mr":"Lorry च्या डाव्या बाजूला मोठा blind spot असतो. Driver म्हणून cyclists कडे विशेष लक्ष द्या.","ml":"Lorry-യുടെ ഇടതുവശത്ത് വലിയ blind spot ഉണ്ട്. ഡ്രൈവർ എന്ന നിലയിൽ cyclists-നെ പ്രത്യേകം ശ്രദ്ധിക്കുക.","ta":"Lorry-இன் இடதுபுறம் பெரிய blind spot உண்டு. ஓட்டுநராக cyclists-ஐ குறிப்பாக கவனியுங்கள்.","gu":"Lorry ની ડાબી બાજુનો cyclist ડ્રાઇવરને દેખાતો નથી અને lorry ડાબે વળે તો અકસ્માત થાય. ત્યાં ન રહો.","ne":"Lorry को बायाँतिरको cyclist चालकले देख्दैन र lorry बायाँ मोडिए दुर्घटना हुन्छ। त्यहाँ नबस्नुहोस्।"},"tr":{"hi":{"q":"junction पर lorry के बाईं तरफ़ साइकिल सवार का होना ख़तरनाक क्यों है?","o":["साइकिल सवार को प्राथमिकता होती है","lorries हमेशा सीधे जाती हैं","lorry बाएँ मुड़ सकती है और ड्राइवर उसे देख न पाए","lorries बाएँ नहीं मुड़ सकतीं"]},"pa":{"q":"junction 'ਤੇ lorry ਦੇ ਖੱਬੇ ਪਾਸੇ ਸਾਈਕਲ ਸਵਾਰ ਦਾ ਹੋਣਾ ਖ਼ਤਰਨਾਕ ਕਿਉਂ ਹੈ?","o":["ਸਾਈਕਲ ਸਵਾਰ ਨੂੰ ਪਹਿਲ ਹੁੰਦੀ ਹੈ","lorries ਹਮੇਸ਼ਾ ਸਿੱਧੀਆਂ ਜਾਂਦੀਆਂ ਹਨ","lorry ਖੱਬੇ ਮੁੜ ਸਕਦੀ ਹੈ ਅਤੇ ਡਰਾਈਵਰ ਉਸ ਨੂੰ ਨਾ ਦੇਖ ਸਕੇ","lorries ਖੱਬੇ ਨਹੀਂ ਮੁੜ ਸਕਦੀਆਂ"]},"ur":{"q":"جنکشن پر سائیکل سوار کا لاری کے بائیں طرف ہونا خطرناک کیوں ہے؟","o":["سائیکل سوار کو ترجیح حاصل ہے","لاریاں ہمیشہ سیدھی جاتی ہیں","لاری بائیں مڑ سکتی ہے اور ڈرائیور انہیں نہ دیکھ سکے","لاریاں بائیں نہیں مڑ سکتیں"]},"bn":{"q":"জংশনে লরির বাঁ পাশে সাইকেল আরোহীর থাকা বিপজ্জনক কেন?","o":["সাইকেল আরোহীর অগ্রাধিকার আছে","লরি সবসময় সোজা যায়","লরি বাঁয়ে বাঁক নিতে পারে এবং চালক তাদের নাও দেখতে পারেন","লরি বাঁয়ে বাঁক নিতে পারে না"]},"te":{"q":"జంక్షన్ వద్ద లారీ ఎడమవైపు సైకిలిస్ట్ ఉండడం ఎందుకు ప్రమాదకరం?","o":["సైకిలిస్ట్‌కు ప్రాధాన్యత ఉంటుంది","లారీలు ఎల్లప్పుడూ నేరుగా వెళ్తాయి","లారీ ఎడమకు తిరగవచ్చు, డ్రైవర్ వారిని చూడకపోవచ్చు","లారీలు ఎడమకు తిరగలేవు"]},"mr":{"q":"चौकात सायकलस्वाराने लॉरीच्या डावीकडे असणे धोकादायक का आहे?","o":["सायकलस्वाराला प्राधान्य असते","लॉरी नेहमी सरळ जातात","लॉरी डावीकडे वळू शकते आणि चालकाला ते दिसणार नाहीत","लॉरी डावीकडे वळू शकत नाहीत"]},"ml":{"q":"ഒരു junction-ൽ lorry-യുടെ ഇടതുവശത്ത് സൈക്കിൾ യാത്രക്കാരൻ നിൽക്കുന്നത് അപകടകരമാകുന്നത് എന്തുകൊണ്ട്?","o":["സൈക്കിൾ യാത്രക്കാരന് മുൻഗണനയുണ്ട്","lorries എപ്പോഴും നേരെ പോകും","lorry ഇടത്തേക്ക് തിരിഞ്ഞേക്കാം, ഡ്രൈവർക്ക് അവരെ കാണാൻ കഴിഞ്ഞേക്കില്ല","lorries-ന് ഇടത്തേക്ക് തിരിയാൻ കഴിയില്ല"]},"ta":{"q":"junction-இல் ஒரு cyclist lorry-இன் இடதுபுறம் இருப்பது ஏன் ஆபத்து?","o":["cyclist-க்கு முன்னுரிமை உண்டு","lorry-கள் எப்போதும் நேராக செல்லும்","lorry இடதுபுறம் திரும்பலாம், ஓட்டுநர் அவரைப் பார்க்காமல் இருக்கலாம்","lorry-களால் இடதுபுறம் திரும்ப முடியாது"]},"gu":{"q":"junction પર lorry ની ડાબી બાજુએ cyclist હોવું જોખમી કેમ?","o":["cyclist ને priority છે","lorries હંમેશા સીધી જાય છે","lorry ડાબે વળી શકે અને ડ્રાઇવર તેમને ન જુએ","lorries ડાબે વળી શકતી નથી"]},"ne":{"q":"junction मा lorry को बायाँ पट्टि cyclist हुनु किन खतरनाक हो?","o":["cyclist लाई priority छ","lorries सधैं सिधा जान्छन्","lorry बायाँ मोडिन सक्छ र चालकले उसलाई नदेख्न सक्छ","lorries बायाँ मोड्न सक्दैनन्"]}}},
{"id":8024,"chapter":8,"q":"Why should you take care when overtaking a car towing a caravan?","options":["It will speed up","It can’t see you","It’s always slow","It’s long and may sway, especially in wind"],"answer":3,"exp":{"hi":"Caravan लंबा होता है और हवा में झूल सकता है। ज़्यादा जगह और समय रखो।","pa":"Caravan ਲੰਮਾ ਹੁੰਦਾ ਹੈ ਅਤੇ ਹਵਾ ਵਿੱਚ ਝੂਲ ਸਕਦਾ ਹੈ। ਵੱਧ ਥਾਂ ਅਤੇ ਸਮਾਂ ਰੱਖੋ।","ur":"Caravan لمبا ہوتا ہے اور ہوا میں جھول سکتا ہے۔ زیادہ جگہ اور وقت رکھیں۔","bn":"(not translated yet)","te":"Caravan పొడవుగా ఉంటుంది, గాలిలో ఊగవచ్చు. ఎక్కువ స్థలం, సమయం ఉంచండి.","mr":"Caravan लांब असते आणि वाऱ्यात झुलू शकते. जास्त जागा आणि वेळ ठेवा.","ml":"Caravan നീളമുള്ളതാണ്, കാറ്റിൽ ആടാം. കൂടുതൽ സ്ഥലവും സമയവും വയ്ക്കുക.","ta":"Caravan நீளமானது, காற்றில் அசையலாம். அதிக இடமும் நேரமும் வையுங்கள்.","gu":"Caravan વાળી કાર લાંબી હોય અને પવનમાં કે ઓવરટેક સમયે ડોલી શકે. વધારાની જગ્યા રાખો.","ne":"Caravan भएको कार लामो हुन्छ र हावा वा overtake बेला डुल्न सक्छ। थप ठाउँ राख्नुहोस्।"},"tr":{"hi":{"q":"caravan खींचती कार को overtake करते समय आपको सावधान क्यों रहना चाहिए?","o":["वह speed बढ़ा लेगी","वह आपको नहीं देख सकती","वह हमेशा धीमी होती है","वह लंबी होती है और डगमगा सकती है, ख़ासकर हवा में"]},"pa":{"q":"caravan ਖਿੱਚਦੀ ਕਾਰ ਨੂੰ overtake ਕਰਦੇ ਸਮੇਂ ਤੁਹਾਨੂੰ ਸਾਵਧਾਨ ਕਿਉਂ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਉਹ speed ਵਧਾ ਲਵੇਗੀ","ਉਹ ਤੁਹਾਨੂੰ ਨਹੀਂ ਦੇਖ ਸਕਦੀ","ਉਹ ਹਮੇਸ਼ਾ ਹੌਲੀ ਹੁੰਦੀ ਹੈ","ਉਹ ਲੰਮੀ ਹੁੰਦੀ ਹੈ ਅਤੇ ਡਗਮਗਾ ਸਕਦੀ ਹੈ, ਖ਼ਾਸ ਕਰਕੇ ਹਵਾ ਵਿੱਚ"]},"ur":{"q":"کیراوان کھینچنے والی کار کو اوور ٹیک کرتے وقت آپ کو احتیاط کیوں کرنی چاہیے؟","o":["وہ رفتار بڑھا لے گی","وہ آپ کو نہیں دیکھ سکتی","وہ ہمیشہ آہستہ ہوتی ہے","وہ لمبی ہوتی ہے اور جھول سکتی ہے، خاص طور پر ہوا میں"]},"bn":{"q":"ক্যারাভান টানা গাড়িকে ওভারটেক করার সময় সতর্ক থাকা উচিত কেন?","o":["এটি গতি বাড়াবে","এটি আপনাকে দেখতে পায় না","এটি সবসময় ধীর","এটি লম্বা এবং দুলতে পারে, বিশেষ করে বাতাসে"]},"te":{"q":"కారవాన్ లాగే కారును ఓవర్‌టేక్ చేసేటప్పుడు మీరు ఎందుకు జాగ్రత్తగా ఉండాలి?","o":["అది వేగం పెంచుతుంది","అది మిమ్మల్ని చూడలేదు","అది ఎల్లప్పుడూ నెమ్మదిగా ఉంటుంది","అది పొడవుగా ఉంటుంది, ముఖ్యంగా గాలిలో ఊగవచ్చు"]},"mr":{"q":"कारवान ओढणाऱ्या कारला ओव्हरटेक करताना काळजी का घ्यावी?","o":["ती वेग वाढवेल","तिला तुम्ही दिसत नाही","ती नेहमी हळू असते","ती लांब असते आणि विशेषतः वाऱ्यात डोलू शकते"]},"ml":{"q":"caravan വലിക്കുന്ന കാറിനെ ഓവർടേക്ക് ചെയ്യുമ്പോൾ ശ്രദ്ധിക്കേണ്ടത് എന്തുകൊണ്ട്?","o":["അത് വേഗത കൂട്ടും","അതിന് നിങ്ങളെ കാണാൻ കഴിയില്ല","അത് എപ്പോഴും പതുക്കെയാണ്","അത് നീളമുള്ളതാണ്, പ്രത്യേകിച്ച് കാറ്റിൽ ആടാം"]},"ta":{"q":"caravan இழுக்கும் காரை முந்தும்போது ஏன் கவனமாக இருக்க வேண்டும்?","o":["அது வேகமெடுக்கும்","அதற்கு உங்களை பார்க்க முடியாது","அது எப்போதும் மெதுவாக இருக்கும்","அது நீளமானது, குறிப்பாக காற்றில் அசையலாம்"]},"gu":{"q":"caravan ખેંચતી કારને ઓવરટેક કરતાં કાળજી કેમ રાખવી?","o":["તે ઝડપ વધારશે","તે તમને જોઈ શકતી નથી","તે હંમેશા ધીમી હોય છે","તે લાંબી હોય છે અને ખાસ કરીને પવનમાં ડોલી શકે"]},"ne":{"q":"caravan तान्दै गरेको कारलाई overtake गर्दा किन सावधानी अपनाउने?","o":["यसले गति बढाउँछ","यसले तपाईंलाई देख्न सक्दैन","यो सधैं ढिलो हुन्छ","यो लामो हुन्छ र हावामा विशेष गरी डुल्न सक्छ"]}}},
{"id":8025,"chapter":8,"q":"An emergency vehicle has just passed you. What should you be ready for?","options":["More emergency vehicles following","Speeding up behind it","The road being clear","Nothing"],"answer":0,"exp":{"hi":"अक्सर एक के पीछे और emergency vehicles आते हैं। Mirror देखते रहो।","pa":"ਅਕਸਰ ਇੱਕ ਦੇ ਪਿੱਛੇ ਹੋਰ emergency vehicles ਆਉਂਦੇ ਹਨ। Mirror ਦੇਖਦੇ ਰਹੋ।","ur":"اکثر ایک کے پیچھے اور emergency vehicles آتے ہیں۔ Mirror دیکھتے رہیں۔","bn":"(not translated yet)","te":"తరచుగా ఒకదాని వెనుక మరిన్ని emergency vehicles వస్తాయి. Mirror చూస్తూ ఉండండి.","mr":"अनेकदा एकाच्या मागे आणखी emergency vehicles येतात. Mirror पाहत राहा.","ml":"പലപ്പോഴും ഒന്നിന്റെ പിന്നാലെ കൂടുതൽ emergency വാഹനങ്ങൾ വരും. Mirror നോക്കിക്കൊണ്ടിരിക്കുക.","ta":"பெரும்பாலும் ஒன்றின் பின் மேலும் அவசர வாகனங்கள் வரும். Mirror-ஐ பார்த்துக்கொண்டே இருங்கள்.","gu":"એક ઇમર્જન્સી વાહન પસાર થાય પછી બીજા આવી શકે. તૈયાર રહો અને રસ્તો ખાલી રાખો.","ne":"एउटा आपतकालीन सवारी नाघेपछि अर्को आउन सक्छ। तयार रहनुहोस् र बाटो खाली राख्नुहोस्।"},"tr":{"hi":{"q":"एक आपातकालीन वाहन अभी आपके पास से निकला है। आपको किस बात के लिए तैयार रहना चाहिए?","o":["पीछे और आपातकालीन वाहन आ सकते हैं","उसके पीछे speed बढ़ाना","सड़क का साफ़ होना","कुछ नहीं"]},"pa":{"q":"ਇਕ ਐਮਰਜੈਂਸੀ ਵਾਹਨ ਹੁਣੇ ਤੁਹਾਡੇ ਕੋਲੋਂ ਲੰਘਿਆ ਹੈ। ਤੁਹਾਨੂੰ ਕਿਸ ਗੱਲ ਲਈ ਤਿਆਰ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਪਿੱਛੇ ਹੋਰ ਐਮਰਜੈਂਸੀ ਵਾਹਨ ਆ ਸਕਦੇ ਹਨ","ਉਸ ਦੇ ਪਿੱਛੇ speed ਵਧਾਉਣਾ","ਸੜਕ ਦਾ ਸਾਫ਼ ਹੋਣਾ","ਕੁਝ ਨਹੀਂ"]},"ur":{"q":"ایک ہنگامی گاڑی ابھی آپ کے پاس سے گزری ہے۔ آپ کو کس بات کے لیے تیار رہنا چاہیے؟","o":["اس کے پیچھے مزید ہنگامی گاڑیاں آ رہی ہوں","اس کے پیچھے رفتار بڑھانا","سڑک کا صاف ہونا","کسی بات کے لیے نہیں"]},"bn":{"q":"একটি জরুরি যান এইমাত্র আপনাকে পেরিয়ে গেল। আপনার কীসের জন্য প্রস্তুত থাকা উচিত?","o":["আরও জরুরি যান আসছে","এর পেছনে গতি বাড়ানো","রাস্তা পরিষ্কার থাকা","কিছুর জন্য নয়"]},"te":{"q":"ఒక అత్యవసర వాహనం ఇప్పుడే మిమ్మల్ని దాటి వెళ్లింది. మీరు దేనికి సిద్ధంగా ఉండాలి?","o":["వెనుక మరిన్ని అత్యవసర వాహనాలు వస్తుండడం","దాని వెనుక వేగం పెంచడం","రోడ్డు ఖాళీగా ఉండడం","ఏమీ లేదు"]},"mr":{"q":"एक आपत्कालीन वाहन नुकतेच तुमच्या बाजूने गेले आहे. तुम्ही कशासाठी तयार असावे?","o":["आणखी आपत्कालीन वाहने मागून येणे","त्याच्या मागे वेगाने जाणे","रस्ता मोकळा असणे","काहीच नाही"]},"ml":{"q":"ഒരു അടിയന്തര വാഹനം നിങ്ങളെ കടന്നുപോയി. എന്തിന് തയ്യാറായിരിക്കണം?","o":["പിന്നാലെ കൂടുതൽ അടിയന്തര വാഹനങ്ങൾ വരുന്നത്","അതിന്റെ പിന്നാലെ വേഗത കൂട്ടുന്നത്","റോഡ് ഒഴിഞ്ഞിരിക്കുന്നത്","ഒന്നിനും ഇല്ല"]},"ta":{"q":"ஒரு அவசர வாகனம் உங்களை கடந்து சென்றது. எதற்குத் தயாராக இருக்க வேண்டும்?","o":["மேலும் அவசர வாகனங்கள் பின்தொடர்வது","அதன் பின்னால் வேகமெடுப்பது","சாலை தெளிவாக இருப்பது","எதுவும் இல்லை"]},"gu":{"q":"ઇમર્જન્સી વાહન હમણાં જ તમને પસાર કરી ગયું. શાના માટે તૈયાર રહેવું?","o":["તેની પાછળ વધુ ઇમર્જન્સી વાહનો આવી શકે","તેની પાછળ ઝડપ વધારવાની","રોડ ખાલી હોવાની","કંઈ નહીં"]},"ne":{"q":"आपतकालीन सवारीले भर्खरै तपाईंलाई नाघ्यो। केका लागि तयार रहने?","o":["उसको पछाडि थप आपतकालीन सवारी आउन सक्छन्","उसको पछाडि गति बढाउने","सडक खाली हुने","केही होइन"]}}},
{"id":8027,"chapter":8,"q":"Why should you stop well back behind a large vehicle at traffic lights?","options":["To let pedestrians cross","It’s the law","So you can see the lights and the driver can see you","To save fuel"],"answer":2,"exp":{"hi":"पास रुकोगे तो lights नहीं दिखेंगी और आप driver के blind spot में होगे।","pa":"ਨੇੜੇ ਰੁਕੋਗੇ ਤਾਂ lights ਨਹੀਂ ਦਿਸਣਗੀਆਂ ਅਤੇ ਤੁਸੀਂ driver ਦੇ blind spot ਵਿੱਚ ਹੋਵੋਗੇ।","ur":"قریب رکیں گے تو lights نظر نہیں آئیں گی اور آپ driver کے blind spot میں ہوں گے۔","bn":"(not translated yet)","te":"దగ్గరగా ఆగితే lights కనిపించవు, మీరు driver blind spot లో ఉంటారు.","mr":"जवळ थांबलात तर lights दिसणार नाहीत आणि तुम्ही driver च्या blind spot मध्ये असाल.","ml":"അടുത്ത് നിന്നാൽ lights കാണില്ല, നിങ്ങൾ ഡ്രൈവറുടെ blind spot-ലും ആകും.","ta":"நெருக்கமாக நின்றால் lights தெரியாது, நீங்கள் ஓட்டுநரின் blind spot-இல் இருப்பீர்கள்.","gu":"મોટા વાહન પાછળ ઘણા પાછળ ઊભા રહો જેથી લાઈટ દેખાય અને ડ્રાઇવર તમને જોઈ શકે.","ne":"ठूलो सवारीको पछाडि धेरै पछाडि रोकिनुहोस् ताकि बत्ती देखियोस् र चालकले तपाईंलाई देख्न सकोस्।"},"tr":{"hi":{"q":"ट्रैफ़िक लाइट पर आपको बड़े वाहन के काफ़ी पीछे क्यों रुकना चाहिए?","o":["पैदल यात्रियों को पार करने देने के लिए","यह क़ानून है","ताकि आप lights देख सकें और ड्राइवर आपको देख सके","ईंधन बचाने के लिए"]},"pa":{"q":"ਟ੍ਰੈਫ਼ਿਕ ਲਾਈਟ 'ਤੇ ਤੁਹਾਨੂੰ ਵੱਡੇ ਵਾਹਨ ਦੇ ਕਾਫ਼ੀ ਪਿੱਛੇ ਕਿਉਂ ਰੁਕਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਪੈਦਲ ਯਾਤਰੀਆਂ ਨੂੰ ਪਾਰ ਕਰਨ ਦੇਣ ਲਈ","ਇਹ ਕਾਨੂੰਨ ਹੈ","ਤਾਂ ਜੋ ਤੁਸੀਂ lights ਦੇਖ ਸਕੋ ਅਤੇ ਡਰਾਈਵਰ ਤੁਹਾਨੂੰ ਦੇਖ ਸਕੇ","ਤੇਲ ਬਚਾਉਣ ਲਈ"]},"ur":{"q":"ٹریفک لائٹس پر بڑی گاڑی کے پیچھے آپ کو کافی فاصلے پر کیوں رکنا چاہیے؟","o":["پیدل چلنے والوں کو پار کرنے دینے کے لیے","یہ قانون ہے","تاکہ آپ بتیاں دیکھ سکیں اور ڈرائیور آپ کو دیکھ سکے","ایندھن بچانے کے لیے"]},"bn":{"q":"ট্রাফিক লাইটে বড় যানের অনেক পেছনে থামা উচিত কেন?","o":["পথচারীদের পার হতে দেওয়ার জন্য","এটি আইন","যাতে আপনি আলো দেখতে পান এবং চালক আপনাকে দেখতে পান","জ্বালানি বাঁচাতে"]},"te":{"q":"ట్రాఫిక్ లైట్ల వద్ద పెద్ద వాహనం వెనుక బాగా దూరంగా ఎందుకు ఆగాలి?","o":["పాదచారులను దాటనివ్వడానికి","ఇది చట్టం","మీకు లైట్లు కనిపించడానికి, డ్రైవర్‌కు మీరు కనిపించడానికి","ఇంధనం ఆదా చేయడానికి"]},"mr":{"q":"ट्रॅफिक लाइटला मोठ्या वाहनामागे चांगले मागे का थांबावे?","o":["पादचाऱ्यांना ओलांडू देण्यासाठी","हा कायदा आहे","म्हणजे तुम्हाला दिवे दिसतील आणि चालकाला तुम्ही दिसाल","इंधन वाचवण्यासाठी"]},"ml":{"q":"traffic lights-ൽ വലിയ വാഹനത്തിന് നന്നായി പിന്നിൽ നിൽക്കേണ്ടത് എന്തുകൊണ്ട്?","o":["കാൽനടക്കാർക്ക് കടക്കാൻ","അത് നിയമമാണ്","lights കാണാൻ കഴിയാനും ഡ്രൈവർക്ക് നിങ്ങളെ കാണാൻ കഴിയാനും","ഇന്ധനം ലാഭിക്കാൻ"]},"ta":{"q":"traffic lights-இல் பெரிய வாகனத்தின் பின்னால் ஏன் நன்றாக தள்ளி நிற்க வேண்டும்?","o":["பாதசாரிகள் கடக்க விட","சட்டப்படி தேவை","lights உங்களுக்கு தெரியவும் ஓட்டுநர் உங்களைப் பார்க்கவும்","எரிபொருள் சேமிக்க"]},"gu":{"q":"traffic lights પર મોટા વાહન પાછળ ઘણા પાછળ કેમ ઊભા રહેવું?","o":["રાહદારીઓને ક્રોસ કરવા દેવા","તે કાયદો છે","જેથી તમે લાઈટ જોઈ શકો અને ડ્રાઇવર તમને જોઈ શકે","બળતણ બચાવવા"]},"ne":{"q":"traffic lights मा ठूलो सवारीको पछाडि धेरै पछाडि किन रोकिने?","o":["पैदल यात्रीलाई बाटो काट्न दिन","यो कानुन हो","ताकि तपाईंले बत्ती देख्न सक्नुहोस् र चालकले तपाईंलाई देख्न सकोस्","इन्धन बचाउन"]}}},
{"id":8029,"chapter":8,"q":"What may happen as you overtake a large vehicle at speed?","options":["Air turbulence can push your car, so hold the steering firmly","Your car will speed up","Your brakes will lock","Nothing"],"answer":0,"exp":{"hi":"बड़ी गाड़ी के आसपास हवा का दबाव car को खिसका सकता है। Steering कसकर पकड़ो।","pa":"ਵੱਡੀ ਗੱਡੀ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਹਵਾ ਦਾ ਦਬਾਅ car ਨੂੰ ਖਿਸਕਾ ਸਕਦਾ ਹੈ। Steering ਘੁੱਟ ਕੇ ਫੜੋ।","ur":"بڑی گاڑی کے ارد گرد ہوا کا دباؤ car کو کھسکا سکتا ہے۔ Steering مضبوطی سے پکڑیں۔","bn":"(not translated yet)","te":"పెద్ద వాహనం చుట్టూ గాలి ఒత్తిడి car ను పక్కకు నెట్టవచ్చు. Steering గట్టిగా పట్టుకోండి.","mr":"मोठ्या गाडीभोवतीचा हवेचा दाब car ला ढकलू शकतो. Steering घट्ट धरा.","ml":"വലിയ വാഹനത്തിന് ചുറ്റുമുള്ള വായുമർദ്ദം car-നെ തള്ളിമാറ്റാം. Steering ഉറപ്പായി പിടിക്കുക.","ta":"பெரிய வாகனத்தின் அருகே காற்றழுத்தம் உங்கள் காரை நகர்த்தலாம். Steering-ஐ உறுதியாகப் பிடியுங்கள்.","gu":"મોટા વાહનને ઓવરટેક કરતાં હવાની ખળભળ તમારી કારને ધકેલી શકે. Steering મજબૂત પકડો.","ne":"ठूलो सवारीलाई overtake गर्दा हावाको अशान्तिले तपाईंको कारलाई धकेल्न सक्छ। Steering दह्रोसँग समात्नुहोस्।"},"tr":{"hi":{"q":"तेज़ speed पर बड़े वाहन को overtake करते समय क्या हो सकता है?","o":["हवा की हलचल आपकी कार को धकेल सकती है, इसलिए steering मज़बूती से पकड़ो","आपकी कार की speed बढ़ जाएगी","आपके brakes जाम हो जाएँगे","कुछ नहीं"]},"pa":{"q":"ਤੇਜ਼ speed 'ਤੇ ਵੱਡੇ ਵਾਹਨ ਨੂੰ overtake ਕਰਦੇ ਸਮੇਂ ਕੀ ਹੋ ਸਕਦਾ ਹੈ?","o":["ਹਵਾ ਦੀ ਹਲਚਲ ਤੁਹਾਡੀ ਕਾਰ ਨੂੰ ਧੱਕ ਸਕਦੀ ਹੈ, ਇਸ ਲਈ steering ਮਜ਼ਬੂਤੀ ਨਾਲ ਫੜੋ","ਤੁਹਾਡੀ ਕਾਰ ਦੀ speed ਵਧ ਜਾਵੇਗੀ","ਤੁਹਾਡੇ brakes ਜਾਮ ਹੋ ਜਾਣਗੇ","ਕੁਝ ਨਹੀਂ"]},"ur":{"q":"بڑی گاڑی کو تیز رفتار پر اوور ٹیک کرتے وقت کیا ہو سکتا ہے؟","o":["ہوا کا بھنور آپ کی کار کو دھکیل سکتا ہے، اس لیے اسٹیئرنگ مضبوطی سے پکڑیں","آپ کی کار تیز ہو جائے گی","آپ کی بریکیں جام ہو جائیں گی","کچھ نہیں"]},"bn":{"q":"বড় যানকে দ্রুত গতিতে ওভারটেক করার সময় কী ঘটতে পারে?","o":["বাতাসের ঘূর্ণি আপনার গাড়িকে ঠেলে দিতে পারে, তাই স্টিয়ারিং শক্ত করে ধরুন","আপনার গাড়ি গতি বাড়াবে","আপনার ব্রেক লক হয়ে যাবে","কিছুই না"]},"te":{"q":"పెద్ద వాహనాన్ని ఎక్కువ వేగంతో ఓవర్‌టేక్ చేసేటప్పుడు ఏమి జరగవచ్చు?","o":["గాలి అల్లకల్లోలం మీ కారును నెట్టవచ్చు, కాబట్టి స్టీరింగ్‌ను గట్టిగా పట్టుకోండి","మీ కారు వేగం పెరుగుతుంది","మీ బ్రేక్‌లు లాక్ అవుతాయి","ఏమీ జరగదు"]},"mr":{"q":"मोठ्या वाहनाला वेगाने ओव्हरटेक करताना काय होऊ शकते?","o":["हवेच्या झोताने तुमची कार ढकलली जाऊ शकते, म्हणून स्टीअरिंग घट्ट धरा","तुमची कार वेग वाढवेल","तुमचे ब्रेक लॉक होतील","काहीच नाही"]},"ml":{"q":"വലിയ വാഹനത്തെ വേഗത്തിൽ ഓവർടേക്ക് ചെയ്യുമ്പോൾ എന്ത് സംഭവിക്കാം?","o":["വായുവിന്റെ ഇളക്കം നിങ്ങളുടെ കാറിനെ തള്ളാം, അതിനാൽ steering ഉറപ്പായി പിടിക്കുക","നിങ്ങളുടെ കാർ വേഗത കൂട്ടും","നിങ്ങളുടെ brakes ലോക്ക് ആകും","ഒന്നും സംഭവിക്കില്ല"]},"ta":{"q":"வேகத்தில் பெரிய வாகனத்தை முந்தும்போது என்ன நடக்கலாம்?","o":["காற்றுச் சுழற்சி உங்கள் காரை தள்ளலாம், steering-ஐ உறுதியாகப் பிடியுங்கள்","உங்கள் கார் வேகமெடுக்கும்","உங்கள் brakes lock ஆகும்","எதுவும் இல்லை"]},"gu":{"q":"મોટા વાહનને ઝડપે ઓવરટેક કરતાં શું થઈ શકે?","o":["હવાની ખળભળ તમારી કારને ધકેલી શકે, એટલે steering મજબૂત પકડો","તમારી કાર ઝડપી થશે","તમારા brakes લૉક થશે","કંઈ નહીં"]},"ne":{"q":"ठूलो सवारीलाई छिटो overtake गर्दा के हुन सक्छ?","o":["हावाको अशान्तिले तपाईंको कारलाई धकेल्न सक्छ, त्यसैले steering दह्रोसँग समात्नुहोस्","तपाईंको कार छिटो हुनेछ","तपाईंका brakes लक हुनेछन्","केही पनि होइन"]}}},
{"id":9001,"chapter":9,"q":"Why is coasting downhill with the clutch pressed down dangerous?","options":["You have less control of the car","It uses more fuel","It wears out the tyres faster","It makes the engine overheat"],"answer":0,"exp":{"hi":"Clutch दबाने से engine braking ख़त्म, गाड़ी तेज़ होती जाती है और steer या accelerate करना मुश्किल।","pa":"Clutch ਦਬਾਉਣ ਨਾਲ engine braking ਖ਼ਤਮ, ਗੱਡੀ ਤੇਜ਼ ਹੁੰਦੀ ਜਾਂਦੀ ਹੈ ਅਤੇ steer ਜਾਂ accelerate ਕਰਨਾ ਔਖਾ।","ur":"Clutch دبانے سے engine braking ختم، گاڑی تیز ہوتی جاتی ہے اور steer یا accelerate کرنا مشکل۔","bn":"(not translated yet)","te":"Clutch నొక్కితే engine braking పోతుంది, వాహనం వేగం పెరుగుతూనే ఉంటుంది, steer లేదా accelerate చేయడం కష్టం.","mr":"Clutch दाबल्याने engine braking संपते, गाडी वेगाने जाते आणि steer किंवा accelerate करणे कठीण होते.","ml":"Clutch അമർത്തിയാൽ engine braking ഇല്ലാതാകും, കാർ വേഗം കൂടിക്കൊണ്ടിരിക്കും, steer ചെയ്യാനും accelerate ചെയ്യാനും ബുദ്ധിമുട്ടാകും.","ta":"Clutch அழுத்தினால் engine braking போய்விடும், கார் வேகம் கூடிக்கொண்டே போகும், steer அல்லது accelerate செய்வது கடினம்.","gu":"Clutch દબાવીને coasting કરવાથી એંજિન braking મળતું નથી અને કાર પર નિયંત્રણ ઘટે. હંમેશા gear માં રહો.","ne":"Clutch थिचेर coasting गर्दा इन्जिन braking पाइँदैन र कारमाथिको नियन्त्रण घट्छ। सधैं gear मा रहनुहोस्।"},"tr":{"hi":{"q":"clutch दबाकर ढलान पर उतरना (coasting) ख़तरनाक क्यों है?","o":["कार पर आपका नियंत्रण कम हो जाता है","इससे ज़्यादा ईंधन लगता है","इससे टायर जल्दी घिसते हैं","इससे इंजन ज़्यादा गर्म हो जाता है"]},"pa":{"q":"clutch ਦਬਾ ਕੇ ਢਲਾਣ ਤੋਂ ਉਤਰਨਾ (coasting) ਖ਼ਤਰਨਾਕ ਕਿਉਂ ਹੈ?","o":["ਕਾਰ 'ਤੇ ਤੁਹਾਡਾ ਕਾਬੂ ਘੱਟ ਜਾਂਦਾ ਹੈ","ਇਸ ਵਿੱਚ ਵੱਧ ਤੇਲ ਲੱਗਦਾ ਹੈ","ਇਸ ਨਾਲ ਟਾਇਰ ਜਲਦੀ ਘਿਸਦੇ ਹਨ","ਇਸ ਨਾਲ ਇੰਜਣ ਵੱਧ ਗਰਮ ਹੋ ਜਾਂਦਾ ਹੈ"]},"ur":{"q":"کلچ دبا کر ڈھلان سے نیچے اترنا (کوسٹنگ) خطرناک کیوں ہے؟","o":["گاڑی پر آپ کا قابو کم ہوتا ہے","اس سے زیادہ ایندھن خرچ ہوتا ہے","اس سے ٹائر زیادہ تیزی سے گھستے ہیں","اس سے انجن زیادہ گرم ہو جاتا ہے"]},"bn":{"q":"ক্লাচ চেপে ঢাল বেয়ে নামা (কোস্টিং) বিপজ্জনক কেন?","o":["গাড়ির ওপর আপনার নিয়ন্ত্রণ কমে যায়","এতে বেশি জ্বালানি লাগে","এতে টায়ার দ্রুত ক্ষয় হয়","এতে ইঞ্জিন অতিরিক্ত গরম হয়"]},"te":{"q":"క్లచ్ నొక్కి ఉంచి కిందికి కోస్టింగ్ చేయడం ఎందుకు ప్రమాదకరం?","o":["కారుపై మీ నియంత్రణ తగ్గుతుంది","ఇది ఎక్కువ ఇంధనం వాడుతుంది","ఇది టైర్లను త్వరగా అరిగిస్తుంది","ఇది ఇంజిన్ వేడెక్కేలా చేస్తుంది"]},"mr":{"q":"क्लच दाबून उतारावर coasting करणे धोकादायक का आहे?","o":["तुमचे गाडीवरील नियंत्रण कमी होते","त्यात जास्त इंधन लागते","त्यामुळे टायर लवकर झिजतात","त्यामुळे इंजिन जास्त तापते"]},"ml":{"q":"clutch അമർത്തി താഴേക്ക് coasting ചെയ്യുന്നത് അപകടകരമായത് എന്തുകൊണ്ട്?","o":["കാറിന്മേലുള്ള നിയന്ത്രണം കുറയും","കൂടുതൽ ഇന്ധനം ചെലവാകും","tyres വേഗം തേയും","എൻജിൻ അമിതമായി ചൂടാകും"]},"ta":{"q":"clutch-ஐ அழுத்திய நிலையில் கீழ்நோக்கி coasting செய்வது ஏன் ஆபத்தானது?","o":["காரின் மீது உங்கள் கட்டுப்பாடு குறையும்","அதிக எரிபொருள் செலவாகும்","டயர்கள் வேகமாக தேயும்","engine அதிக வெப்பமடையும்"]},"gu":{"q":"clutch દબાવીને ઢાળ ઉતરવું (coasting) જોખમી કેમ છે?","o":["કાર પર નિયંત્રણ ઓછું રહે","તે વધુ બળતણ વાપરે છે","તે tyres ને ઝડપથી ઘસે છે","તે એંજિનને વધુ ગરમ કરે છે"]},"ne":{"q":"clutch थिचेर ओरालो झर्नु (coasting) किन खतरनाक छ?","o":["कारमाथिको नियन्त्रण कम हुन्छ","यसले बढी इन्धन खर्च गर्छ","यसले tyres लाई छिटो खियाउँछ","यसले इन्जिन बढी तताउँछ"]}}},
{"id":9002,"chapter":9,"q":"When should you use fog lights?","options":["Whenever you’re on a motorway","When visibility is seriously reduced, generally to less than 100 metres","Whenever it’s raining","At night on unlit roads"],"answer":1,"exp":{"hi":"सिर्फ़ जब दिखना बहुत कम हो, आम तौर पर 100 m से कम। सुधरते ही बंद करो।","pa":"ਸਿਰਫ਼ ਜਦੋਂ ਦਿਸਣਾ ਬਹੁਤ ਘੱਟ ਹੋਵੇ, ਆਮ ਤੌਰ ’ਤੇ 100 m ਤੋਂ ਘੱਟ। ਸੁਧਰਦੇ ਹੀ ਬੰਦ ਕਰੋ।","ur":"صرف جب دیکھنا بہت کم ہو، عام طور پر 100 m سے کم۔ بہتر ہوتے ہی بند کریں۔","bn":"(not translated yet)","te":"చూపు చాలా తక్కువగా ఉన్నప్పుడు మాత్రమే, సాధారణంగా 100 m కన్నా తక్కువ. మెరుగుపడగానే ఆపేయండి.","mr":"फक्त जेव्हा दिसणे खूप कमी असेल, साधारणपणे 100 m पेक्षा कमी. सुधारताच बंद करा.","ml":"Visibility വളരെ കുറയുമ്പോൾ മാത്രം, സാധാരണ 100 m-ൽ താഴെ. മെച്ചപ്പെട്ടാലുടൻ ഓഫ് ചെയ്യുക.","ta":"பார்வைத்திறன் மிகக் குறைந்தால் மட்டும், பொதுவாக 100 m-க்கு குறைவு. மேம்பட்டவுடன் அணைக்கவும்.","gu":"Fog lights ફક્ત ત્યારે જ્યારે દૃશ્યતા ગંભીર રીતે ઘટી હોય (સામાન્ય રીતે 100 મીટરથી ઓછું). વરસાદમાં નહીં.","ne":"Fog lights केवल दृश्यता गम्भीर रूपमा घट्दा मात्र (सामान्यतया 100 मिटरभन्दा कम)। वर्षामा होइन।"},"tr":{"hi":{"q":"आपको fog lights कब इस्तेमाल करनी चाहिए?","o":["जब भी आप मोटरवे पर हों","जब दृश्यता बहुत कम हो जाए, आम तौर पर 100 मीटर से कम","जब भी बारिश हो","रात में बिना रोशनी वाली सड़कों पर"]},"pa":{"q":"ਤੁਹਾਨੂੰ fog lights ਕਦੋਂ ਵਰਤਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?","o":["ਜਦੋਂ ਵੀ ਤੁਸੀਂ ਮੋਟਰਵੇ 'ਤੇ ਹੋਵੋ","ਜਦੋਂ ਦਿੱਖ ਬਹੁਤ ਘੱਟ ਹੋ ਜਾਵੇ, ਆਮ ਤੌਰ 'ਤੇ 100 ਮੀਟਰ ਤੋਂ ਘੱਟ","ਜਦੋਂ ਵੀ ਮੀਂਹ ਪਵੇ","ਰਾਤ ਨੂੰ ਬਿਨਾਂ ਰੋਸ਼ਨੀ ਵਾਲੀਆਂ ਸੜਕਾਂ 'ਤੇ"]},"ur":{"q":"آپ کو فوگ لائٹس کب استعمال کرنی چاہئیں؟","o":["جب بھی آپ موٹروے پر ہوں","جب نظر آنے کی صلاحیت بہت کم ہو جائے، عام طور پر 100 میٹر سے کم","جب بھی بارش ہو","رات کو بغیر روشنی والی سڑکوں پر"]},"bn":{"q":"আপনি কখন ফগ লাইট ব্যবহার করবেন?","o":["মোটরওয়েতে থাকলেই","যখন দৃশ্যমানতা গুরুতরভাবে কমে যায়, সাধারণত ১০০ মিটারের কম","বৃষ্টি হলেই","আলোহীন রাস্তায় রাতে"]},"te":{"q":"మీరు ఫాగ్ లైట్లను ఎప్పుడు వాడాలి?","o":["మోటార్‌వేపై ఉన్నప్పుడల్లా","దృశ్యమానత తీవ్రంగా తగ్గినప్పుడు, సాధారణంగా 100 మీటర్ల కంటే తక్కువ ఉన్నప్పుడు","వర్షం పడినప్పుడల్లా","వెలుతురు లేని రోడ్లపై రాత్రి"]},"mr":{"q":"तुम्ही fog lights केव्हा वापरावेत?","o":["मोटरवेवर असताना नेहमी","दृश्यमानता गंभीरपणे कमी असताना, साधारणपणे १०० मीटरपेक्षा कमी","पाऊस पडत असताना नेहमी","रात्री दिवे नसलेल्या रस्त्यांवर"]},"ml":{"q":"fog lights എപ്പോഴാണ് ഉപയോഗിക്കേണ്ടത്?","o":["മോട്ടോർവേയിൽ ആയിരിക്കുമ്പോഴെല്ലാം","visibility ഗുരുതരമായി കുറയുമ്പോൾ, സാധാരണയായി 100 മീറ്ററിൽ താഴെ","മഴ പെയ്യുമ്പോഴെല്ലാം","വെളിച്ചമില്ലാത്ത റോഡുകളിൽ രാത്രി"]},"ta":{"q":"fog lights-ஐ எப்போது பயன்படுத்த வேண்டும்?","o":["மோட்டார்வேயில் இருக்கும்போதெல்லாம்","பார்வைத்திறன் கடுமையாக குறையும்போது, பொதுவாக 100 மீட்டருக்கு குறைவாக","மழை பெய்யும்போதெல்லாம்","விளக்கு இல்லாத சாலைகளில் இரவில்"]},"gu":{"q":"fog lights ક્યારે વાપરવી?","o":["motorway પર હોઈએ ત્યારે હંમેશા","જ્યારે દૃશ્યતા ગંભીર રીતે ઘટી હોય, સામાન્ય રીતે 100 મીટરથી ઓછી","જ્યારે વરસાદ હોય ત્યારે","લાઈટ વગરના રોડ પર રાત્રે"]},"ne":{"q":"fog lights कहिले प्रयोग गर्ने?","o":["मोटरवेमा हुँदा जहिले पनि","दृश्यता गम्भीर रूपमा घटेको बेला, सामान्यतया 100 मिटरभन्दा कम","वर्षा हुँदा जहिले पनि","राति उज्यालो नभएको सडकमा"]}}},
{"id":9003,"chapter":9,"q":"Why should you switch off your fog lights when visibility improves?","options":["They overheat","It’s required only at night","They can dazzle others and hide your brake lights","They use too much fuel"],"answer":2,"exp":{"hi":"तेज़ rear fog light पीछे वालों को चौंधियाती है और brake light को छुपा देती है।","pa":"ਤੇਜ਼ rear fog light ਪਿੱਛੇ ਵਾਲਿਆਂ ਨੂੰ ਚੁੰਧਿਆਉਂਦੀ ਹੈ ਅਤੇ brake light ਨੂੰ ਲੁਕਾ ਦਿੰਦੀ ਹੈ।","ur":"تیز rear fog light پیچھے والوں کو چندھیاتی ہے اور brake light کو چھپا دیتی ہے۔","bn":"(not translated yet)","te":"ప్రకాశవంతమైన rear fog light వెనుకవారి కళ్ళు చెదిరేలా చేస్తుంది, brake light ను దాచేస్తుంది.","mr":"तेजस्वी rear fog light मागच्यांचे डोळे दिपवते आणि brake light झाकते.","ml":"തെളിഞ്ഞ rear fog light പിന്നിലുള്ളവരുടെ കണ്ണ് മഞ്ഞളിപ്പിക്കും, brake light മറയ്ക്കുകയും ചെയ്യും.","ta":"பிரகாசமான rear fog light பின்னால் உள்ளவர்களுக்கு கண் கூசி brake light-ஐ மறைக்கும்.","gu":"સુધરેલી દૃશ્યતામાં fog lights બીજાને અંજાવે અને તમારી brake lights છુપાવી શકે. તરત બંધ કરો.","ne":"सुधारिएको दृश्यतामा fog lights ले अरूलाई चिलाउँछ र तपाईंका brake lights लुकाउन सक्छ। तुरुन्त बन्द गर्नुहोस्।"},"tr":{"hi":{"q":"दृश्यता सुधरने पर आपको fog lights बंद क्यों कर देनी चाहिए?","o":["वे ज़्यादा गर्म हो जाती हैं","यह सिर्फ़ रात में ज़रूरी है","वे दूसरों की आँखें चौंधिया सकती हैं और आपकी brake lights छिपा सकती हैं","वे बहुत ज़्यादा ईंधन इस्तेमाल करती हैं"]},"pa":{"q":"ਦਿੱਖ ਸੁਧਰਨ 'ਤੇ ਤੁਹਾਨੂੰ fog lights ਬੰਦ ਕਿਉਂ ਕਰ ਦੇਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?","o":["ਉਹ ਵੱਧ ਗਰਮ ਹੋ ਜਾਂਦੀਆਂ ਹਨ","ਇਹ ਸਿਰਫ਼ ਰਾਤ ਨੂੰ ਜ਼ਰੂਰੀ ਹੈ","ਉਹ ਦੂਜਿਆਂ ਦੀਆਂ ਅੱਖਾਂ ਚੌਂਧਿਆ ਸਕਦੀਆਂ ਹਨ ਅਤੇ ਤੁਹਾਡੀਆਂ brake lights ਲੁਕਾ ਸਕਦੀਆਂ ਹਨ","ਉਹ ਬਹੁਤ ਜ਼ਿਆਦਾ ਤੇਲ ਵਰਤਦੀਆਂ ਹਨ"]},"ur":{"q":"جب نظر آنے کی صلاحیت بہتر ہو جائے تو آپ کو فوگ لائٹس بند کیوں کرنی چاہئیں؟","o":["وہ زیادہ گرم ہو جاتی ہیں","یہ صرف رات کے لیے ضروری ہے","وہ دوسروں کی آنکھیں چندھیا سکتی ہیں اور آپ کی بریک لائٹس چھپا دیتی ہیں","وہ بہت زیادہ ایندھن خرچ کرتی ہیں"]},"bn":{"q":"দৃশ্যমানতা ভালো হলে ফগ লাইট বন্ধ করা উচিত কেন?","o":["এগুলো অতিরিক্ত গরম হয়","এটি শুধু রাতে প্রয়োজন","এগুলো অন্যদের চোখ ধাঁধাতে পারে এবং আপনার ব্রেক লাইট ঢেকে দেয়","এগুলো অনেক বেশি জ্বালানি ব্যবহার করে"]},"te":{"q":"దృశ్యమానత మెరుగుపడినప్పుడు ఫాగ్ లైట్లను ఎందుకు ఆపేయాలి?","o":["అవి వేడెక్కుతాయి","ఇది రాత్రి మాత్రమే అవసరం","అవి ఇతరుల కళ్లు చెదరగొట్టవచ్చు, మీ బ్రేక్ లైట్లను దాచవచ్చు","అవి ఎక్కువ ఇంధనం వాడతాయి"]},"mr":{"q":"दृश्यमानता सुधारल्यावर तुम्ही fog lights का बंद करावेत?","o":["ते जास्त तापतात","ते फक्त रात्री आवश्यक आहे","ते इतरांचे डोळे दिपवू शकतात आणि तुमचे ब्रेक लाइट झाकतात","ते खूप इंधन वापरतात"]},"ml":{"q":"visibility മെച്ചപ്പെടുമ്പോൾ fog lights ഓഫ് ചെയ്യേണ്ടത് എന്തുകൊണ്ട്?","o":["അവ അമിതമായി ചൂടാകും","രാത്രിയിൽ മാത്രം നിർബന്ധം","അവ മറ്റുള്ളവരുടെ കണ്ണ് മഞ്ഞളിപ്പിക്കുകയും നിങ്ങളുടെ brake lights മറയ്ക്കുകയും ചെയ്യും","അവ വളരെയധികം ഇന്ധനം ഉപയോഗിക്കും"]},"ta":{"q":"பார்வைத்திறன் மேம்படும்போது fog lights-ஐ ஏன் அணைக்க வேண்டும்?","o":["அவை அதிக வெப்பமடையும்","இரவில் மட்டும் தேவை","அவை மற்றவர்களுக்கு கண் கூசி உங்கள் brake lights-ஐ மறைக்கலாம்","அவை அதிக எரிபொருள் பயன்படுத்தும்"]},"gu":{"q":"દૃશ્યતા સુધરે ત્યારે fog lights કેમ બંધ કરવી?","o":["તે વધુ ગરમ થાય છે","ફક્ત રાત્રે જરૂરી છે","તે બીજાને અંજાવી શકે અને તમારી brake lights છુપાવી શકે","તે ખૂબ બળતણ વાપરે છે"]},"ne":{"q":"दृश्यता सुध्रिँदा fog lights किन बन्द गर्ने?","o":["तिनी बढी तात्छन्","राति मात्र आवश्यक छ","तिनले अरूलाई चिलाउन सक्छन् र तपाईंका brake lights लुकाउन सक्छन्","तिनले धेरै इन्धन खर्च गर्छन्"]}}},
{"id":9004,"chapter":9,"q":"The rear of your car skids to the right. Which way should you steer?","options":["To the left","Keep the wheel straight and brake hard","Pull the handbrake on","To the right"],"answer":3,"exp":{"hi":"जिस तरफ़ पिछला हिस्सा फिसले, उसी तरफ़ steer करो। ज़ोर का brake या handbrake skid बढ़ाता है।","pa":"ਜਿਸ ਪਾਸੇ ਪਿਛਲਾ ਹਿੱਸਾ ਤਿਲਕੇ, ਉਸੇ ਪਾਸੇ steer ਕਰੋ। ਜ਼ੋਰ ਦੀ brake ਜਾਂ handbrake skid ਵਧਾਉਂਦੀ ਹੈ।","ur":"جس طرف پچھلا حصہ پھسلے، اسی طرف steer کریں۔ زور کی brake یا handbrake skid بڑھاتی ہے۔","bn":"(not translated yet)","te":"వెనుక భాగం ఏ వైపుకు జారుతోందో అదే వైపుకు steer చేయండి. గట్టి brake లేదా handbrake skid ను పెంచుతాయి.","mr":"मागचा भाग ज्या बाजूला घसरतो त्याच बाजूला steer करा. जोरात brake किंवा handbrake skid वाढवतो.","ml":"പിൻഭാഗം തെന്നുന്ന ദിശയിലേക്ക് തന്നെ steer ചെയ്യുക. ശക്തമായ brake അല്ലെങ്കിൽ handbrake skid കൂട്ടും.","ta":"பின்பகுதி எந்தப் பக்கம் வழுக்குகிறதோ அதே பக்கம் steer செய்யுங்கள். கடுமையான brake அல்லது handbrake skid-ஐ அதிகரிக்கும்.","gu":"Skid જે તરફ થાય તે તરફ steer કરો (જમણી તરફ skid થાય તો જમણી તરફ). Brake ન મારો, ધીમે ધીમે ઝડપ ઘટાડો.","ne":"Skid जता हुन्छ त्यतै steer गर्नुहोस् (दायाँतिर skid भए दायाँतिर)। Brake नलगाउनुहोस्, बिस्तारै गति घटाउनुहोस्।"},"tr":{"hi":{"q":"आपकी कार का पिछला हिस्सा दाईं तरफ़ फिसल जाता है। आपको किस तरफ़ steer करना चाहिए?","o":["बाईं तरफ़","steering सीधा रखो और ज़ोर से brake लगाओ","handbrake खींचो","दाईं तरफ़"]},"pa":{"q":"ਤੁਹਾਡੀ ਕਾਰ ਦਾ ਪਿਛਲਾ ਹਿੱਸਾ ਸੱਜੇ ਪਾਸੇ ਤਿਲਕ ਜਾਂਦਾ ਹੈ। ਤੁਹਾਨੂੰ ਕਿਸ ਪਾਸੇ steer ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਖੱਬੇ ਪਾਸੇ","steering ਸਿੱਧਾ ਰੱਖੋ ਅਤੇ ਜ਼ੋਰ ਨਾਲ brake ਲਾਓ","handbrake ਖਿੱਚੋ","ਸੱਜੇ ਪਾਸੇ"]},"ur":{"q":"آپ کی کار کا پچھلا حصہ دائیں طرف پھسلتا ہے۔ آپ کو کس طرف اسٹیئر کرنا چاہیے؟","o":["بائیں طرف","پہیہ سیدھا رکھیں اور زور سے بریک لگائیں","ہینڈ بریک کھینچ لیں","دائیں طرف"]},"bn":{"q":"আপনার গাড়ির পেছনটা ডান দিকে পিছলে গেল। আপনি কোন দিকে স্টিয়ার করবেন?","o":["বাঁ দিকে","চাকা সোজা রাখুন এবং জোরে ব্রেক করুন","হ্যান্ডব্রেক টানুন","ডান দিকে"]},"te":{"q":"మీ కారు వెనుక భాగం కుడివైపు జారింది. మీరు ఏ వైపు స్టీర్ చేయాలి?","o":["ఎడమ వైపు","స్టీరింగ్ నేరుగా ఉంచి గట్టిగా బ్రేక్ వేయండి","హ్యాండ్‌బ్రేక్ లాగండి","కుడి వైపు"]},"mr":{"q":"तुमच्या कारचा मागचा भाग उजवीकडे घसरतो. तुम्ही कोणत्या दिशेने स्टीअर करावे?","o":["डावीकडे","स्टीअरिंग सरळ ठेवा आणि जोरात ब्रेक लावा","हँडब्रेक ओढा","उजवीकडे"]},"ml":{"q":"നിങ്ങളുടെ കാറിന്റെ പിൻഭാഗം വലത്തേക്ക് skid ചെയ്യുന്നു. ഏത് ദിശയിൽ steer ചെയ്യണം?","o":["ഇടത്തേക്ക്","steering നേരെ വച്ച് ശക്തമായി brake ചെയ്യുക","handbrake വലിക്കുക","വലത്തേക്ക്"]},"ta":{"q":"உங்கள் காரின் பின்பகுதி வலதுபுறம் skid ஆகிறது. எந்த திசையில் steer செய்ய வேண்டும்?","o":["இடதுபுறம்","steering-ஐ நேராக வைத்து கடுமையாக brake போடுங்கள்","handbrake-ஐ இழுங்கள்","வலதுபுறம்"]},"gu":{"q":"તમારી કારનો પાછળનો ભાગ જમણી તરફ skid થાય છે. કઈ તરફ steer કરવું?","o":["ડાબી તરફ","steering સીધું રાખી જોરથી brake મારો","handbrake ખેંચો","જમણી તરફ"]},"ne":{"q":"तपाईंको कारको पछाडिको भाग दायाँतिर skid हुन्छ। कुन तर्फ steer गर्ने?","o":["बायाँतिर","steering सिधा राखेर जोडले brake लगाउने","handbrake तान्ने","दायाँतिर"]}}},
{"id":9005,"chapter":9,"q":"You’re driving down a long, steep hill. How can you stop your brakes overheating?","options":["Select a lower gear","Select neutral","Press the clutch down","Switch the engine off"],"answer":0,"exp":{"hi":"Low gear में engine braking मदद करती है और brakes पर कम ज़ोर पड़ता है। Neutral या clutch = coasting।","pa":"Low gear ਵਿੱਚ engine braking ਮਦਦ ਕਰਦੀ ਹੈ ਅਤੇ brakes ’ਤੇ ਘੱਟ ਜ਼ੋਰ ਪੈਂਦਾ ਹੈ। Neutral ਜਾਂ clutch = coasting।","ur":"Low gear میں engine braking مدد کرتی ہے اور brakes پر کم زور پڑتا ہے۔ Neutral یا clutch = coasting۔","bn":"(not translated yet)","te":"Low gear లో engine braking సహాయపడుతుంది, brakes పై తక్కువ భారం. Neutral లేదా clutch = coasting.","mr":"Low gear मध्ये engine braking मदत करते आणि brakes वर कमी ताण येतो. Neutral किंवा clutch = coasting.","ml":"Low gear-ൽ engine braking സഹായിക്കും, brakes-ന് ഭാരം കുറയും. Neutral അല്ലെങ്കിൽ clutch = coasting.","ta":"குறைந்த gear-இல் engine braking உதவும், brakes மீது சுமை குறையும். Neutral அல்லது clutch = coasting.","gu":"લાંબા ઢાળ પર નીચો gear પસંદ કરો જેથી એંજિન braking મળે અને brakes વધુ ગરમ ન થાય.","ne":"लामो ओरालोमा होचो gear छान्नुहोस् ताकि इन्जिन braking मिलोस् र brakes बढी नतातून्।"},"tr":{"hi":{"q":"आप लंबी, तीखी ढलान पर उतर रहे हैं। आप अपने brakes को ज़्यादा गर्म होने से कैसे बचा सकते हैं?","o":["नीचे का gear चुनो","neutral चुनो","clutch दबाकर रखो","इंजन बंद कर दो"]},"pa":{"q":"ਤੁਸੀਂ ਲੰਮੀ, ਤਿੱਖੀ ਢਲਾਣ 'ਤੇ ਉਤਰ ਰਹੇ ਹੋ। ਤੁਸੀਂ ਆਪਣੇ brakes ਨੂੰ ਵੱਧ ਗਰਮ ਹੋਣ ਤੋਂ ਕਿਵੇਂ ਬਚਾ ਸਕਦੇ ਹੋ?","o":["ਨੀਵਾਂ gear ਚੁਣੋ","neutral ਚੁਣੋ","clutch ਦਬਾ ਕੇ ਰੱਖੋ","ਇੰਜਣ ਬੰਦ ਕਰ ਦਿਓ"]},"ur":{"q":"آپ ایک لمبی، کھڑی ڈھلان سے نیچے جا رہے ہیں۔ آپ اپنی بریکوں کو زیادہ گرم ہونے سے کیسے روک سکتے ہیں؟","o":["نچلا گیئر لگائیں","نیوٹرل لگائیں","کلچ دبا دیں","انجن بند کر دیں"]},"bn":{"q":"আপনি একটি লম্বা, খাড়া ঢাল বেয়ে নামছেন। আপনার ব্রেক অতিরিক্ত গরম হওয়া কীভাবে ঠেকাবেন?","o":["নিচু গিয়ার বেছে নিন","নিউট্রাল বেছে নিন","ক্লাচ চেপে ধরুন","ইঞ্জিন বন্ধ করুন"]},"te":{"q":"మీరు పొడవైన, నిటారైన కొండపై నుంచి దిగుతున్నారు. మీ బ్రేక్‌లు వేడెక్కకుండా ఎలా ఆపవచ్చు?","o":["తక్కువ గేర్ ఎంచుకోండి","న్యూట్రల్ ఎంచుకోండి","క్లచ్ నొక్కి ఉంచండి","ఇంజిన్ ఆపేయండి"]},"mr":{"q":"तुम्ही लांब, तीव्र उतारावरून जात आहात. तुमचे ब्रेक जास्त तापू नयेत म्हणून काय करावे?","o":["कमी गिअर निवडा","neutral निवडा","क्लच दाबा","इंजिन बंद करा"]},"ml":{"q":"നീളമുള്ള കുത്തനെയുള്ള ഇറക്കത്തിലൂടെ ഓടിക്കുകയാണ്. brakes അമിതമായി ചൂടാകുന്നത് എങ്ങനെ തടയാം?","o":["താഴ്ന്ന gear തിരഞ്ഞെടുക്കുക","neutral തിരഞ്ഞെടുക്കുക","clutch താഴേക്ക് അമർത്തുക","എൻജിൻ ഓഫ് ചെയ്യുക"]},"ta":{"q":"நீண்ட செங்குத்தான மலையில் கீழே ஓட்டுகிறீர்கள். brakes அதிக வெப்பமடையாமல் தடுக்க எப்படி?","o":["குறைந்த gear-ஐ தேர்ந்தெடுங்கள்","neutral-ஐ தேர்ந்தெடுங்கள்","clutch-ஐ அழுத்தி வையுங்கள்","engine-ஐ அணைத்துவிடுங்கள்"]},"gu":{"q":"તમે લાંબા, ઊભા ઢાળ પરથી ઉતરી રહ્યા છો. brakes ને વધુ ગરમ થતાં કેવી રીતે રોકશો?","o":["નીચો gear પસંદ કરો","neutral પસંદ કરો","clutch દબાવી રાખો","એંજિન બંધ કરો"]},"ne":{"q":"तपाईं लामो, ठाडो ओरालो झर्दै हुनुहुन्छ। brakes बढी तात्नबाट कसरी रोक्ने?","o":["होचो gear छान्नुहोस्","neutral छान्नुहोस्","clutch थिचिराख्नुहोस्","इन्जिन बन्द गर्नुहोस्"]}}},
{"id":9006,"chapter":9,"q":"After driving through deep water, what should you do?","options":["Check your tyre pressures","Test your brakes gently","Speed up to dry the engine","Stop and wait for an hour"],"answer":1,"exp":{"hi":"गीले brakes ठीक से काम नहीं करते। सुरक्षित जगह पर हल्का brake लगाकर test करो।","pa":"ਗਿੱਲੇ brakes ਠੀਕ ਕੰਮ ਨਹੀਂ ਕਰਦੇ। ਸੁਰੱਖਿਅਤ ਥਾਂ ’ਤੇ ਹਲਕੀ brake ਲਾ ਕੇ test ਕਰੋ।","ur":"گیلے brakes ٹھیک کام نہیں کرتے۔ محفوظ جگہ پر ہلکی brake لگا کر test کریں۔","bn":"(not translated yet)","te":"తడి brakes సరిగ్గా పనిచేయవు. సురక్షిత చోట తేలికగా brake వేసి test చేయండి.","mr":"ओले brakes नीट काम करत नाहीत. सुरक्षित जागी हलका brake लावून test करा.","ml":"നനഞ്ഞ brakes ശരിയായി പ്രവർത്തിക്കില്ല. സുരക്ഷിതമായ സ്ഥലത്ത് പതുക്കെ brake ചെയ്ത് പരീക്ഷിക്കുക.","ta":"ஈர brakes சரியாக வேலை செய்யாது. பாதுகாப்பான இடத்தில் மெதுவாக brake போட்டு சோதியுங்கள்.","gu":"પાણીમાંથી નીકળ્યા પછી brakes ધીમેથી ચકાસો. ભીના brakes નબળા હોય છે; થોડા દબાવો જેથી સુકાય.","ne":"पानीबाट निस्केपछि brakes बिस्तारै परीक्षण गर्नुहोस्। भिजेका brakes कमजोर हुन्छन्; थोरै थिचेर सुकाउनुहोस्।"},"tr":{"hi":{"q":"गहरे पानी से गुज़रने के बाद आपको क्या करना चाहिए?","o":["टायरों का pressure जाँचो","अपने brakes को धीरे से परखो","इंजन सुखाने के लिए speed बढ़ाओ","रुककर एक घंटा इंतज़ार करो"]},"pa":{"q":"ਡੂੰਘੇ ਪਾਣੀ ਵਿੱਚੋਂ ਲੰਘਣ ਤੋਂ ਬਾਅਦ ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਟਾਇਰਾਂ ਦਾ pressure ਜਾਂਚੋ","ਆਪਣੇ brakes ਨੂੰ ਹੌਲੀ ਜਿਹੇ ਪਰਖੋ","ਇੰਜਣ ਸੁਕਾਉਣ ਲਈ speed ਵਧਾਓ","ਰੁਕ ਕੇ ਇਕ ਘੰਟਾ ਇੰਤਜ਼ਾਰ ਕਰੋ"]},"ur":{"q":"گہرے پانی سے گزرنے کے بعد آپ کو کیا کرنا چاہیے؟","o":["اپنے ٹائروں کا پریشر چیک کریں","اپنی بریکیں آہستگی سے آزما کر دیکھیں","انجن خشک کرنے کے لیے رفتار بڑھائیں","رک جائیں اور ایک گھنٹہ انتظار کریں"]},"bn":{"q":"গভীর পানি পার হওয়ার পর আপনার কী করা উচিত?","o":["টায়ারের চাপ পরীক্ষা করুন","আলতো করে ব্রেক পরীক্ষা করুন","ইঞ্জিন শুকাতে গতি বাড়ান","থামুন এবং এক ঘণ্টা অপেক্ষা করুন"]},"te":{"q":"లోతైన నీటిలో నడిపిన తర్వాత మీరు ఏమి చేయాలి?","o":["టైర్ ప్రెజర్లు తనిఖీ చేయండి","మీ బ్రేక్‌లను మెల్లగా పరీక్షించండి","ఇంజిన్ ఆరడానికి వేగం పెంచండి","ఆగి ఒక గంట వేచి ఉండండి"]},"mr":{"q":"खोल पाण्यातून गेल्यावर तुम्ही काय करावे?","o":["टायरचा दाब तपासा","ब्रेक हळूच तपासून पाहा","इंजिन सुकवण्यासाठी वेग वाढवा","थांबा आणि एक तास वाट पाहा"]},"ml":{"q":"ആഴമുള്ള വെള്ളത്തിലൂടെ ഓടിച്ച ശേഷം എന്ത് ചെയ്യണം?","o":["tyre pressures പരിശോധിക്കുക","brakes പതുക്കെ പരീക്ഷിക്കുക","എൻജിൻ ഉണക്കാൻ വേഗത കൂട്ടുക","നിർത്തി ഒരു മണിക്കൂർ കാത്തിരിക്കുക"]},"ta":{"q":"ஆழமான நீரில் ஓட்டிய பிறகு என்ன செய்ய வேண்டும்?","o":["டயர் pressure-ஐ சரிபாருங்கள்","brakes-ஐ மெதுவாக சோதியுங்கள்","engine-ஐ உலர்த்த வேகமாக ஓட்டுங்கள்","நின்று ஒரு மணி நேரம் காத்திருங்கள்"]},"gu":{"q":"ઊંડા પાણીમાંથી પસાર થયા પછી શું કરવું?","o":["tyre pressure તપાસો","brakes ધીમેથી ચકાસો","એંજિન સૂકવવા ઝડપ વધારો","ઊભા રહી એક કલાક રાહ જુઓ"]},"ne":{"q":"गहिरो पानी पार गरेपछि के गर्नुपर्छ?","o":["tyre pressure जाँच्नुहोस्","brakes बिस्तारै परीक्षण गर्नुहोस्","इन्जिन सुकाउन गति बढाउनुहोस्","रोकिएर एक घण्टा पर्खनुहोस्"]}}},
{"id":9007,"chapter":9,"q":"How should you drive through a flood?","options":["In neutral","At your normal speed","Slowly in first gear, keeping engine speed high by slipping the clutch","Fast, in a high gear"],"answer":2,"exp":{"hi":"धीरे first gear में, engine की speed ऊँची रखो ताकि exhaust में पानी न घुसे। पहले देख लो पानी कितना गहरा है।","pa":"ਹੌਲੀ first gear ਵਿੱਚ, engine ਦੀ speed ਉੱਚੀ ਰੱਖੋ ਤਾਂ ਜੋ exhaust ਵਿੱਚ ਪਾਣੀ ਨਾ ਵੜੇ। ਪਹਿਲਾਂ ਦੇਖ ਲਓ ਪਾਣੀ ਕਿੰਨਾ ਡੂੰਘਾ ਹੈ।","ur":"آہستہ first gear میں، engine کی speed اونچی رکھیں تاکہ exhaust میں پانی نہ جائے۔ پہلے دیکھ لیں پانی کتنا گہرا ہے۔","bn":"(not translated yet)","te":"నెమ్మదిగా first gear లో, exhaust లోకి నీరు రాకుండా engine speed ఎక్కువగా ఉంచండి. ముందుగా నీరు ఎంత లోతుందో చూడండి.","mr":"हळू first gear मध्ये, engine चा speed जास्त ठेवा म्हणजे exhaust मध्ये पाणी शिरणार नाही. आधी पाणी किती खोल आहे ते पाहा.","ml":"പതുക്കെ first gear-ൽ, exhaust-ൽ വെള്ളം കയറാതിരിക്കാൻ engine വേഗത ഉയർന്നു വയ്ക്കുക. ആദ്യം വെള്ളത്തിന്റെ ആഴം നോക്കുക.","ta":"மெதுவாக முதல் gear-இல், engine வேகத்தை உயர்வாக வைத்து exhaust-இல் நீர் புகாமல் பாருங்கள். முதலில் நீரின் ஆழத்தை பாருங்கள்.","gu":"પૂરના પાણીમાં ધીમેથી પહેલા gear માં, clutch સરકાવીને એંજિન ગતિ ઊંચી રાખો જેથી exhaust માં પાણી ન ભરાય.","ne":"बाढीको पानीमा बिस्तारै पहिलो gear मा, clutch चिप्लाएर इन्जिन गति उच्च राख्नुहोस् ताकि exhaust मा पानी नपसोस्।"},"tr":{"hi":{"q":"बाढ़ के पानी में से आपको कैसे चलाना चाहिए?","o":["neutral में","अपनी सामान्य speed पर","first gear में धीरे-धीरे, clutch को थोड़ा खिसकाकर इंजन की speed ऊँची रखते हुए","तेज़, ऊँचे gear में"]},"pa":{"q":"ਹੜ੍ਹ ਦੇ ਪਾਣੀ ਵਿੱਚੋਂ ਤੁਹਾਨੂੰ ਕਿਵੇਂ ਚਲਾਉਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["neutral ਵਿੱਚ","ਆਪਣੀ ਆਮ speed 'ਤੇ","first gear ਵਿੱਚ ਹੌਲੀ-ਹੌਲੀ, clutch ਨੂੰ ਥੋੜ੍ਹਾ ਖਿਸਕਾ ਕੇ ਇੰਜਣ ਦੀ speed ਉੱਚੀ ਰੱਖਦੇ ਹੋਏ","ਤੇਜ਼, ਉੱਚੇ gear ਵਿੱਚ"]},"ur":{"q":"سیلابی پانی سے گزرتے وقت آپ کو گاڑی کیسے چلانی چاہیے؟","o":["نیوٹرل میں","اپنی معمول کی رفتار سے","آہستہ، پہلے گیئر میں، کلچ کو پھسلاتے ہوئے انجن کی رفتار اونچی رکھ کر","تیز، اونچے گیئر میں"]},"bn":{"q":"বন্যার পানি দিয়ে আপনি কীভাবে চালাবেন?","o":["নিউট্রালে","স্বাভাবিক গতিতে","ধীরে, প্রথম গিয়ারে, ক্লাচ পিছলিয়ে ইঞ্জিনের গতি উঁচু রেখে","জোরে, উঁচু গিয়ারে"]},"te":{"q":"వరద నీటి గుండా మీరు ఎలా నడపాలి?","o":["న్యూట్రల్‌లో","మీ సాధారణ వేగంతో","మొదటి గేర్‌లో నెమ్మదిగా, క్లచ్ కొద్దిగా జారవిడుస్తూ ఇంజిన్ వేగాన్ని ఎక్కువగా ఉంచుతూ","ఎత్తైన గేర్‌లో వేగంగా"]},"mr":{"q":"तुम्ही पुराच्या पाण्यातून कसे चालवावे?","o":["neutral मध्ये","नेहमीच्या वेगाने","पहिल्या गिअरमध्ये हळू, क्लच slip करून इंजिनचा वेग जास्त ठेवत","वेगाने, वरच्या गिअरमध्ये"]},"ml":{"q":"വെള്ളപ്പൊക്കത്തിലൂടെ എങ്ങനെ ഓടിക്കണം?","o":["neutral-ൽ","സാധാരണ വേഗത്തിൽ","first gear-ൽ പതുക്കെ, clutch slip ചെയ്ത് എൻജിൻ വേഗത ഉയർന്ന നിലയിൽ നിലനിർത്തി","ഉയർന്ന gear-ൽ വേഗത്തിൽ"]},"ta":{"q":"வெள்ளம் நிறைந்த இடத்தில் எப்படி ஓட்ட வேண்டும்?","o":["neutral-இல்","வழக்கமான வேகத்தில்","மெதுவாக முதல் gear-இல், clutch-ஐ சறுக்கவிட்டு engine வேகத்தை உயர்வாக வைத்து","வேகமாக, உயர்ந்த gear-இல்"]},"gu":{"q":"પૂરના પાણીમાંથી કેવી રીતે ચલાવવું?","o":["neutral માં","સામાન્ય ઝડપે","ધીમેથી પહેલા gear માં, clutch સરકાવીને એંજિન ગતિ ઊંચી રાખીને","ઝડપથી, ઊંચા gear માં"]},"ne":{"q":"बाढीको पानीबाट कसरी चलाउने?","o":["neutral मा","सामान्य गतिमा","बिस्तारै पहिलो gear मा, clutch चिप्लाएर इन्जिन गति उच्च राख्दै","छिटो, माथिल्लो gear मा"]}}},
{"id":9008,"chapter":9,"q":"When should you dip your headlights at night?","options":["Never","Only in towns","Only when parked","When meeting oncoming traffic or following another vehicle"],"answer":3,"exp":{"hi":"Main beam दूसरों की आँखें चौंधिया देता है। सामने से गाड़ी आए या आप किसी के पीछे हो तो dip करो।","pa":"Main beam ਦੂਜਿਆਂ ਦੀਆਂ ਅੱਖਾਂ ਚੁੰਧਿਆ ਦਿੰਦਾ ਹੈ। ਸਾਹਮਣਿਓਂ ਗੱਡੀ ਆਵੇ ਜਾਂ ਤੁਸੀਂ ਕਿਸੇ ਦੇ ਪਿੱਛੇ ਹੋਵੋ ਤਾਂ dip ਕਰੋ।","ur":"Main beam دوسروں کی آنکھیں چندھیا دیتا ہے۔ سامنے سے گاڑی آئے یا آپ کسی کے پیچھے ہوں تو dip کریں۔","bn":"(not translated yet)","te":"Main beam ఇతరుల కళ్ళు చెదిరేలా చేస్తుంది. ఎదురుగా వాహనం వస్తే లేదా మీరు ఎవరి వెనుకైనా ఉంటే dip చేయండి.","mr":"Main beam इतरांचे डोळे दिपवतो. समोरून गाडी आली किंवा तुम्ही कोणाच्या मागे असाल तर dip करा.","ml":"Main beam മറ്റുള്ളവരുടെ കണ്ണ് മഞ്ഞളിപ്പിക്കും. എതിരെ വാഹനം വരുമ്പോഴോ നിങ്ങൾ ഒരാളുടെ പിന്നിലാകുമ്പോഴോ dip ചെയ്യുക.","ta":"Main beam மற்றவர்கள் கண்ணைக் கூசும். எதிரே வாகனம் வந்தால் அல்லது நீங்கள் ஒருவரை பின்தொடர்ந்தால் dip செய்யுங்கள்.","gu":"સામેના વાહનને મળતાં કે બીજા વાહન પાછળ ચાલતાં headlights dip કરો જેથી બીજા અંજાઈ ન જાય.","ne":"आउँदै गरेको सवारी भेट्दा वा अर्को सवारीको पछाडि चल्दा headlights dip गर्नुहोस् ताकि अरू चिलाऊन् नपरून्।"},"tr":{"hi":{"q":"रात में आपको headlights को dip कब करना चाहिए?","o":["कभी नहीं","सिर्फ़ शहरों में","सिर्फ़ park होने पर","जब सामने से ट्रैफ़िक आ रहा हो या आप किसी दूसरे वाहन के पीछे चल रहे हों"]},"pa":{"q":"ਰਾਤ ਨੂੰ ਤੁਹਾਨੂੰ headlights ਨੂੰ dip ਕਦੋਂ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਕਦੇ ਨਹੀਂ","ਸਿਰਫ਼ ਸ਼ਹਿਰਾਂ ਵਿੱਚ","ਸਿਰਫ਼ park ਹੋਣ 'ਤੇ","ਜਦੋਂ ਸਾਹਮਣਿਓਂ ਟ੍ਰੈਫ਼ਿਕ ਆ ਰਿਹਾ ਹੋਵੇ ਜਾਂ ਤੁਸੀਂ ਕਿਸੇ ਦੂਜੇ ਵਾਹਨ ਦੇ ਪਿੱਛੇ ਚੱਲ ਰਹੇ ਹੋਵੋ"]},"ur":{"q":"رات کو آپ کو اپنی ہیڈ لائٹس ڈپ کب کرنی چاہئیں؟","o":["کبھی نہیں","صرف قصبوں میں","صرف پارک ہونے پر","جب سامنے سے ٹریفک آ رہی ہو یا آپ کسی اور گاڑی کے پیچھے چل رہے ہوں"]},"bn":{"q":"রাতে আপনি কখন হেডলাইট ডিপ করবেন?","o":["কখনো নয়","শুধু শহরে","শুধু পার্ক করা অবস্থায়","যখন বিপরীত দিক থেকে ট্রাফিক আসছে বা অন্য যানকে অনুসরণ করছেন"]},"te":{"q":"రాత్రి మీరు హెడ్‌లైట్లను ఎప్పుడు డిప్ చేయాలి?","o":["ఎప్పుడూ కాదు","పట్టణాల్లో మాత్రమే","పార్క్ చేసినప్పుడు మాత్రమే","ఎదురు ట్రాఫిక్‌ను కలిసినప్పుడు లేదా మరో వాహనం వెనుక వెళ్తున్నప్పుడు"]},"mr":{"q":"रात्री तुम्ही हेडलाइट केव्हा dip करावेत?","o":["कधीच नाही","फक्त शहरांत","फक्त पार्क केलेले असताना","समोरून वाहतूक येत असताना किंवा दुसऱ्या वाहनाच्या मागे चालताना"]},"ml":{"q":"രാത്രിയിൽ headlights എപ്പോഴാണ് dip ചെയ്യേണ്ടത്?","o":["ഒരിക്കലും വേണ്ട","പട്ടണങ്ങളിൽ മാത്രം","park ചെയ്തിരിക്കുമ്പോൾ മാത്രം","എതിരെ traffic വരുമ്പോഴോ മറ്റൊരു വാഹനത്തെ പിന്തുടരുമ്പോഴോ"]},"ta":{"q":"இரவில் headlights-ஐ எப்போது dip செய்ய வேண்டும்?","o":["ஒருபோதும் இல்லை","நகரங்களில் மட்டும்","park செய்திருக்கும்போது மட்டும்","எதிரே வரும் traffic-ஐ சந்திக்கும்போது அல்லது மற்றொரு வாகனத்தை பின்தொடரும்போது"]},"gu":{"q":"રાત્રે headlights ક્યારે dip કરવી?","o":["ક્યારેય નહીં","ફક્ત શહેરોમાં","ફક્ત park કરેલા હો ત્યારે","સામેથી આવતા traffic ને મળતાં કે બીજા વાહનની પાછળ ચાલતાં"]},"ne":{"q":"राति headlights कहिले dip गर्ने?","o":["कहिल्यै होइन","सहरमा मात्र","park गरिएको बेला मात्र","आउँदै गरेको traffic भेट्दा वा अर्को सवारीको पछाडि चल्दा"]}}},
{"id":9009,"chapter":9,"q":"At night in a built-up area with street lights, which lights should you use?","options":["Dipped headlights","Main beam","No lights","Rear fog lights"],"answer":0,"exp":{"hi":"शहर में रात को dipped headlights ताकि आप दिख सको और दूसरे चौंधिया न जाएँ।","pa":"ਸ਼ਹਿਰ ਵਿੱਚ ਰਾਤ ਨੂੰ dipped headlights ਤਾਂ ਜੋ ਤੁਸੀਂ ਦਿਸੋ ਅਤੇ ਦੂਜੇ ਚੁੰਧਿਆ ਨਾ ਜਾਣ।","ur":"شہر میں رات کو dipped headlights تاکہ آپ نظر آئیں اور دوسرے چندھیا نہ جائیں۔","bn":"(not translated yet)","te":"పట్టణంలో రాత్రి dipped headlights, మీరు కనిపించేలా, ఇతరుల కళ్ళు చెదరకుండా.","mr":"शहरात रात्री dipped headlights म्हणजे तुम्ही दिसाल आणि इतरांचे डोळे दिपणार नाहीत.","ml":"നഗരത്തിൽ രാത്രിയിൽ dipped headlights, നിങ്ങളെ കാണാനും മറ്റുള്ളവരുടെ കണ്ണ് മഞ്ഞളിക്കാതിരിക്കാനും.","ta":"நகரத்தில் இரவில் dipped headlights, நீங்கள் தெரியவும் மற்றவர்களுக்கு கூசாமல் இருக்கவும்.","gu":"Street lights વાળા built-up વિસ્તારમાં dipped headlights વાપરો. Main beam અને fog lights ન જોઈએ.","ne":"Street lights भएको built-up क्षेत्रमा dipped headlights प्रयोग गर्नुहोस्। Main beam र fog lights नचाहिने।"},"tr":{"hi":{"q":"रात में street lights वाले built-up क्षेत्र में आपको कौन सी lights इस्तेमाल करनी चाहिए?","o":["Dipped headlights","Main beam","कोई lights नहीं","Rear fog lights"]},"pa":{"q":"ਰਾਤ ਨੂੰ street lights ਵਾਲੇ built-up ਖੇਤਰ ਵਿੱਚ ਤੁਹਾਨੂੰ ਕਿਹੜੀਆਂ lights ਵਰਤਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?","o":["Dipped headlights","Main beam","ਕੋਈ lights ਨਹੀਂ","Rear fog lights"]},"ur":{"q":"رات کو اسٹریٹ لائٹ والے آبادی کے علاقے میں آپ کو کون سی بتیاں استعمال کرنی چاہئیں؟","o":["ڈپڈ ہیڈ لائٹس","مین بیم","کوئی بتی نہیں","پچھلی فوگ لائٹس"]},"bn":{"q":"রাতে রাস্তার বাতিযুক্ত জনবসতি এলাকায় আপনি কোন আলো ব্যবহার করবেন?","o":["ডিপড হেডলাইট","মেইন বিম","কোনো আলো নয়","পেছনের ফগ লাইট"]},"te":{"q":"వీధి దీపాలు ఉన్న జనావాస ప్రాంతంలో రాత్రి మీరు ఏ లైట్లు వాడాలి?","o":["డిప్డ్ హెడ్‌లైట్లు","మెయిన్ బీమ్","లైట్లు వద్దు","వెనుక ఫాగ్ లైట్లు"]},"mr":{"q":"रस्त्यावर दिवे असलेल्या वस्तीच्या भागात रात्री तुम्ही कोणते दिवे वापरावेत?","o":["Dipped headlights","Main beam","कोणतेही दिवे नाही","मागचे fog lights"]},"ml":{"q":"street lights ഉള്ള built-up പ്രദേശത്ത് രാത്രിയിൽ ഏത് lights ഉപയോഗിക്കണം?","o":["dipped headlights","main beam","lights വേണ്ട","rear fog lights"]},"ta":{"q":"தெருவிளக்குகள் உள்ள built-up பகுதியில் இரவில் எந்த விளக்குகளை பயன்படுத்த வேண்டும்?","o":["dipped headlights","main beam","விளக்குகள் வேண்டாம்","பின் fog lights"]},"gu":{"q":"રાત્રે street lights વાળા built-up વિસ્તારમાં કઈ લાઈટો વાપરવી?","o":["dipped headlights","main beam","કોઈ લાઈટ નહીં","rear fog lights"]},"ne":{"q":"राति street lights भएको built-up क्षेत्रमा कुन बत्ती प्रयोग गर्ने?","o":["dipped headlights","main beam","कुनै बत्ती होइन","rear fog lights"]}}},
{"id":9010,"chapter":9,"q":"Why is overtaking at night more dangerous?","options":["It’s illegal after dark","It’s harder to judge speed and distance","Roads are always busier","Your lights are dimmer"],"answer":1,"exp":{"hi":"अँधेरे में सामने वाली गाड़ी की speed और दूरी का अंदाज़ा मुश्किल है, और मोड़ या ढलान छुपे होते हैं।","pa":"ਹਨੇਰੇ ਵਿੱਚ ਸਾਹਮਣੇ ਵਾਲੀ ਗੱਡੀ ਦੀ speed ਅਤੇ ਦੂਰੀ ਦਾ ਅੰਦਾਜ਼ਾ ਔਖਾ ਹੈ, ਅਤੇ ਮੋੜ ਜਾਂ ਢਲਾਨਾਂ ਲੁਕੀਆਂ ਹੁੰਦੀਆਂ ਹਨ।","ur":"اندھیرے میں سامنے والی گاڑی کی speed اور فاصلے کا اندازہ مشکل ہے، اور موڑ یا ڈھلانیں چھپی ہوتی ہیں۔","bn":"(not translated yet)","te":"చీకటిలో ఎదురు వాహనం speed, దూరం అంచనా వేయడం కష్టం, మలుపులు లేదా వాలులు దాగి ఉంటాయి.","mr":"अंधारात पुढच्या गाडीचा speed आणि अंतर यांचा अंदाज घेणे कठीण असते, आणि वळणे किंवा उतार लपलेले असतात.","ml":"ഇരുട്ടിൽ മുന്നിലെ വാഹനത്തിന്റെ speed-ഉം ദൂരവും കണക്കാക്കാൻ ബുദ്ധിമുട്ടാണ്, വളവുകളും ഇറക്കങ്ങളും മറഞ്ഞിരിക്കും.","ta":"இருட்டில் முன் வாகனத்தின் வேகத்தையும் தூரத்தையும் மதிப்பிடுவது கடினம், வளைவுகளும் சரிவுகளும் மறைந்திருக்கலாம்.","gu":"રાત્રે ઝડપ અને અંતરનો અંદાજ કઠિન છે, એટલે ઓવરટેક વધુ જોખમી. ખાતરી ન હોય તો રાહ જુઓ.","ne":"राति गति र दूरीको अनुमान गाह्रो हुन्छ, त्यसैले overtake बढी खतरनाक। पक्का छैन भने पर्खनुहोस्।"},"tr":{"hi":{"q":"रात में overtake करना ज़्यादा ख़तरनाक क्यों है?","o":["अंधेरा होने के बाद यह ग़ैरक़ानूनी है","speed और दूरी का अंदाज़ा लगाना मुश्किल होता है","सड़कें हमेशा ज़्यादा व्यस्त होती हैं","आपकी lights मद्धम हो जाती हैं"]},"pa":{"q":"ਰਾਤ ਨੂੰ overtake ਕਰਨਾ ਵੱਧ ਖ਼ਤਰਨਾਕ ਕਿਉਂ ਹੈ?","o":["ਹਨੇਰੇ ਤੋਂ ਬਾਅਦ ਇਹ ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਹੈ","speed ਅਤੇ ਦੂਰੀ ਦਾ ਅੰਦਾਜ਼ਾ ਲਾਉਣਾ ਔਖਾ ਹੁੰਦਾ ਹੈ","ਸੜਕਾਂ ਹਮੇਸ਼ਾ ਵੱਧ ਰੁੱਝੀਆਂ ਹੁੰਦੀਆਂ ਹਨ","ਤੁਹਾਡੀਆਂ lights ਮੱਧਮ ਹੋ ਜਾਂਦੀਆਂ ਹਨ"]},"ur":{"q":"رات کو اوور ٹیک کرنا زیادہ خطرناک کیوں ہے؟","o":["اندھیرے کے بعد یہ غیر قانونی ہے","رفتار اور فاصلے کا اندازہ لگانا مشکل ہوتا ہے","سڑکیں ہمیشہ زیادہ مصروف ہوتی ہیں","آپ کی بتیاں مدھم ہوتی ہیں"]},"bn":{"q":"রাতে ওভারটেক করা বেশি বিপজ্জনক কেন?","o":["অন্ধকারের পর এটি বেআইনি","গতি ও দূরত্ব আন্দাজ করা কঠিন","রাস্তা সবসময় বেশি ব্যস্ত","আপনার আলো ম্লান"]},"te":{"q":"రాత్రి ఓవర్‌టేక్ చేయడం ఎందుకు ఎక్కువ ప్రమాదకరం?","o":["చీకటి పడిన తర్వాత ఇది చట్టవిరుద్ధం","వేగం, దూరాన్ని అంచనా వేయడం కష్టం","రోడ్లు ఎల్లప్పుడూ ఎక్కువ రద్దీగా ఉంటాయి","మీ లైట్లు మసకగా ఉంటాయి"]},"mr":{"q":"रात्री ओव्हरटेक करणे जास्त धोकादायक का आहे?","o":["अंधारानंतर ते बेकायदेशीर आहे","वेग आणि अंतराचा अंदाज घेणे कठीण असते","रस्ते नेहमी जास्त गर्दीचे असतात","तुमचे दिवे अंधुक असतात"]},"ml":{"q":"രാത്രിയിൽ ഓവർടേക്ക് ചെയ്യുന്നത് കൂടുതൽ അപകടകരമായത് എന്തുകൊണ്ട്?","o":["ഇരുട്ടിനുശേഷം അത് നിയമവിരുദ്ധമാണ്","വേഗതയും ദൂരവും കണക്കാക്കാൻ കൂടുതൽ ബുദ്ധിമുട്ടാണ്","റോഡുകൾ എപ്പോഴും കൂടുതൽ തിരക്കുള്ളതാണ്","നിങ്ങളുടെ lights മങ്ങിയതാണ്"]},"ta":{"q":"இரவில் முந்துவது ஏன் கூடுதல் ஆபத்தானது?","o":["இருட்டிய பிறகு சட்டவிரோதம்","வேகத்தையும் தூரத்தையும் மதிப்பிடுவது கடினம்","சாலைகள் எப்போதும் அதிக நெரிசலாக இருக்கும்","உங்கள் விளக்குகள் மங்கலாக இருக்கும்"]},"gu":{"q":"રાત્રે ઓવરટેક કરવું વધુ જોખમી કેમ છે?","o":["અંધારા પછી તે ગેરકાયદેસર છે","ઝડપ અને અંતરનો અંદાજ લગાવવો કઠિન છે","રોડ હંમેશા વધુ વ્યસ્ત હોય છે","તમારી લાઈટો ઝાંખી હોય છે"]},"ne":{"q":"राति overtake गर्नु किन बढी खतरनाक छ?","o":["अँध्यारो भएपछि यो गैरकानूनी छ","गति र दूरीको अनुमान गर्न गाह्रो हुन्छ","सडक सधैं बढी व्यस्त हुन्छ","तपाईंका बत्ती मधुरा हुन्छन्"]}}},
{"id":9011,"chapter":9,"q":"What is engine braking?","options":["Pressing the clutch to slow down","Switching off the engine","Slowing the car by easing off the accelerator while in gear","Using the handbrake while moving"],"answer":2,"exp":{"hi":"Gear में accelerator छोड़ने पर engine गाड़ी को धीमा करता है। Low gear में ये और ज़्यादा असर करता है।","pa":"Gear ਵਿੱਚ accelerator ਛੱਡਣ ’ਤੇ engine ਗੱਡੀ ਨੂੰ ਹੌਲੀ ਕਰਦਾ ਹੈ। Low gear ਵਿੱਚ ਇਹ ਹੋਰ ਵੱਧ ਅਸਰ ਕਰਦਾ ਹੈ।","ur":"Gear میں accelerator چھوڑنے پر engine گاڑی کو آہستہ کرتا ہے۔ Low gear میں یہ اور زیادہ اثر کرتا ہے۔","bn":"(not translated yet)","te":"Gear లో ఉండి accelerator వదిలితే engine వాహనాన్ని నెమ్మదిస్తుంది. Low gear లో ఇది ఇంకా ఎక్కువ ప్రభావం చూపుతుంది.","mr":"Gear मध्ये accelerator सोडल्यावर engine गाडी हळू करतो. Low gear मध्ये हे अजून जास्त परिणामकारक.","ml":"Gear-ൽ ഇരിക്കെ accelerator അയച്ചാൽ engine വാഹനം പതുക്കെയാക്കുന്നു. Low gear-ൽ ഇത് കൂടുതൽ ഫലപ്രദം.","ta":"Gear-இல் accelerator-ஐ விட்டால் engine காரை மெதுவாக்கும். குறைந்த gear-இல் இது இன்னும் அதிகம்.","gu":"Engine braking = gear માં રહી accelerator છોડીને કારને ધીમી કરવી. Clutch દબાવીને નહીં.","ne":"Engine braking = gear मा रहेर accelerator छोडेर कारलाई ढिलो पार्नु। Clutch थिचेर होइन।"},"tr":{"hi":{"q":"engine braking क्या है?","o":["धीमे होने के लिए clutch दबाना","इंजन बंद कर देना","gear में रहते हुए accelerator से पैर हटाकर कार को धीमा करना","चलते समय handbrake इस्तेमाल करना"]},"pa":{"q":"engine braking ਕੀ ਹੈ?","o":["ਹੌਲੀ ਹੋਣ ਲਈ clutch ਦਬਾਉਣਾ","ਇੰਜਣ ਬੰਦ ਕਰ ਦੇਣਾ","gear ਵਿੱਚ ਰਹਿੰਦੇ ਹੋਏ accelerator ਤੋਂ ਪੈਰ ਹਟਾ ਕੇ ਕਾਰ ਨੂੰ ਹੌਲੀ ਕਰਨਾ","ਚੱਲਦੇ ਸਮੇਂ handbrake ਵਰਤਣਾ"]},"ur":{"q":"انجن بریکنگ کیا ہے؟","o":["رفتار کم کرنے کے لیے کلچ دبانا","انجن بند کر دینا","گیئر میں رہتے ہوئے ایکسیلریٹر چھوڑ کر گاڑی کی رفتار کم کرنا","چلتے ہوئے ہینڈ بریک استعمال کرنا"]},"bn":{"q":"ইঞ্জিন ব্রেকিং কী?","o":["গতি কমাতে ক্লাচ চাপা","ইঞ্জিন বন্ধ করে দেওয়া","গিয়ারে থেকে অ্যাক্সিলারেটর ছেড়ে গাড়ির গতি কমানো","চলার সময় হ্যান্ডব্রেক ব্যবহার করা"]},"te":{"q":"ఇంజిన్ బ్రేకింగ్ అంటే ఏమిటి?","o":["వేగం తగ్గించడానికి క్లచ్ నొక్కడం","ఇంజిన్ ఆపేయడం","గేర్‌లో ఉండగా యాక్సిలరేటర్ నుంచి కాలు తీసి కారు వేగం తగ్గించడం","కదులుతూ హ్యాండ్‌బ్రేక్ వాడడం"]},"mr":{"q":"engine braking म्हणजे काय?","o":["वेग कमी करण्यासाठी क्लच दाबणे","इंजिन बंद करणे","गिअरमध्ये असताना अ‍ॅक्सिलरेटर सोडून कारचा वेग कमी करणे","चालताना हँडब्रेक वापरणे"]},"ml":{"q":"എന്താണ് engine braking?","o":["വേഗത കുറയ്ക്കാൻ clutch അമർത്തുന്നത്","എൻജിൻ ഓഫ് ചെയ്യുന്നത്","gear-ൽ ഇരിക്കെ accelerator അയച്ച് വാഹനം പതുക്കെയാക്കുന്നത്","ഓടുമ്പോൾ handbrake ഉപയോഗിക്കുന്നത്"]},"ta":{"q":"engine braking என்றால் என்ன?","o":["வேகத்தை குறைக்க clutch-ஐ அழுத்துவது","engine-ஐ அணைப்பது","gear-இல் இருக்கும்போது accelerator-ஐ தளர்த்தி காரின் வேகத்தை குறைப்பது","ஓடும்போது handbrake பயன்படுத்துவது"]},"gu":{"q":"engine braking એટલે શું?","o":["ધીમા પડવા clutch દબાવવું","એંજિન બંધ કરવું","gear માં રહી accelerator ઢીલું કરી કારને ધીમી કરવી","ચાલતા handbrake વાપરવું"]},"ne":{"q":"engine braking भनेको के हो?","o":["ढिलो हुन clutch थिच्नु","इन्जिन बन्द गर्नु","gear मा रहेर accelerator सुस्तरी कारलाई ढिलो पार्नु","चलिरहँदा handbrake प्रयोग गर्नु"]}}},
{"id":9012,"chapter":9,"q":"What’s the main cause of skidding?","options":["Worn tyres only","Bad weather alone","Poor road design","The driver: going too fast, or harsh braking, accelerating or steering"],"answer":3,"exp":{"hi":"मौसम और tyres का असर होता है, पर ज़्यादातर skid driver की speed और अचानक हरकतों से होता है।","pa":"ਮੌਸਮ ਅਤੇ tyres ਦਾ ਅਸਰ ਹੁੰਦਾ ਹੈ, ਪਰ ਜ਼ਿਆਦਾਤਰ skid driver ਦੀ speed ਅਤੇ ਅਚਾਨਕ ਹਰਕਤਾਂ ਨਾਲ ਹੁੰਦਾ ਹੈ।","ur":"موسم اور tyres کا اثر ہوتا ہے، مگر زیادہ تر skid driver کی speed اور اچانک حرکتوں سے ہوتا ہے۔","bn":"(not translated yet)","te":"వాతావరణం, tyres ప్రభావం ఉంటుంది, కానీ చాలా skids driver speed, అకస్మాత్తు కదలికల వల్లే జరుగుతాయి.","mr":"हवामान आणि tyres चा परिणाम असतो, पण बहुतेक skid driver च्या speed आणि अचानक हालचालींमुळे होतो.","ml":"കാലാവസ്ഥയും tyres-ഉം സ്വാധീനിക്കും, പക്ഷേ മിക്ക skid-കളും ഡ്രൈവറുടെ speed-ഉം പെട്ടെന്നുള്ള പ്രവൃത്തികളും കാരണമാണ്.","ta":"வானிலையும் டயர்களும் பாதிக்கும், ஆனால் பெரும்பாலான skid-கள் ஓட்டுநரின் வேகம் மற்றும் திடீர் செயல்களால் வரும்.","gu":"Skidding સામાન્ય રીતે ડ્રાઇવરના કારણે: વધુ ઝડપ, કઠોર braking, accelerating કે steering.","ne":"Skidding प्राय: चालकका कारण: धेरै गति, कडा braking, accelerating वा steering।"},"tr":{"hi":{"q":"skidding (फिसलने) का मुख्य कारण क्या है?","o":["सिर्फ़ घिसे हुए टायर","सिर्फ़ ख़राब मौसम","सड़क की ख़राब बनावट","ड्राइवर: बहुत तेज़ चलाना, या ज़ोर से brake लगाना, accelerate करना या steering घुमाना"]},"pa":{"q":"skidding (ਤਿਲਕਣ) ਦਾ ਮੁੱਖ ਕਾਰਨ ਕੀ ਹੈ?","o":["ਸਿਰਫ਼ ਘਿਸੇ ਹੋਏ ਟਾਇਰ","ਸਿਰਫ਼ ਖ਼ਰਾਬ ਮੌਸਮ","ਸੜਕ ਦੀ ਖ਼ਰਾਬ ਬਣਤਰ","ਡਰਾਈਵਰ: ਬਹੁਤ ਤੇਜ਼ ਚਲਾਉਣਾ, ਜਾਂ ਜ਼ੋਰ ਨਾਲ brake ਲਾਉਣਾ, accelerate ਕਰਨਾ ਜਾਂ steering ਘੁਮਾਉਣਾ"]},"ur":{"q":"پھسلنے (اسکڈنگ) کی بنیادی وجہ کیا ہے؟","o":["صرف گھسے ہوئے ٹائر","صرف خراب موسم","سڑک کا خراب ڈیزائن","ڈرائیور: بہت تیز چلانا، یا سخت بریک لگانا، رفتار بڑھانا یا اسٹیئر کرنا"]},"bn":{"q":"পিছলে যাওয়ার (স্কিডিংয়ের) প্রধান কারণ কী?","o":["শুধু ক্ষয়ে যাওয়া টায়ার","শুধু খারাপ আবহাওয়া","রাস্তার খারাপ নকশা","চালক: খুব জোরে চালানো, বা জোরে ব্রেক করা, গতি বাড়ানো বা স্টিয়ার করা"]},"te":{"q":"జారడానికి (skidding) ప్రధాన కారణం ఏమిటి?","o":["అరిగిన టైర్లు మాత్రమే","చెడు వాతావరణం మాత్రమే","రోడ్డు రూపకల్పన లోపం","డ్రైవర్: చాలా వేగంగా నడపడం, లేదా కఠినంగా బ్రేక్ వేయడం, వేగం పెంచడం లేదా స్టీర్ చేయడం"]},"mr":{"q":"घसरण्याचे (skidding) मुख्य कारण काय?","o":["फक्त झिजलेले टायर","फक्त खराब हवामान","रस्त्याची खराब रचना","चालक: खूप वेगाने चालवणे, किंवा जोरात ब्रेक, अ‍ॅक्सिलरेट किंवा स्टीअर करणे"]},"ml":{"q":"skid ചെയ്യുന്നതിന്റെ പ്രധാന കാരണം എന്താണ്?","o":["തേഞ്ഞ tyres മാത്രം","മോശം കാലാവസ്ഥ മാത്രം","മോശം റോഡ് രൂപകൽപ്പന","ഡ്രൈവർ: അമിതവേഗം, അല്ലെങ്കിൽ പരുക്കനായ braking, accelerating, steering"]},"ta":{"q":"skidding-க்கு முக்கிய காரணம் என்ன?","o":["தேய்ந்த டயர்கள் மட்டும்","மோசமான வானிலை மட்டும்","மோசமான சாலை வடிவமைப்பு","ஓட்டுநரே: அதிக வேகம், அல்லது கடுமையான braking, வேகமெடுத்தல் அல்லது steering"]},"gu":{"q":"skidding નું મુખ્ય કારણ શું છે?","o":["ફક્ત ઘસાયેલા tyres","ફક્ત ખરાબ હવામાન","ખરાબ રોડ રચના","ડ્રાઇવર: વધુ ઝડપ, અથવા કઠોર braking, accelerating કે steering"]},"ne":{"q":"skidding को मुख्य कारण के हो?","o":["खिइएका tyres मात्र","खराब मौसम मात्र","खराब सडक डिजाइन","चालक: धेरै गति, वा कडा braking, accelerating वा steering"]}}},
{"id":9013,"chapter":9,"q":"How should you brake on an icy road?","options":["Gently","Hard and quickly","By pumping the pedal hard","With the handbrake"],"answer":0,"exp":{"hi":"Ice पर हल्का और धीरे brake। ज़ोर से brake करने पर wheels lock और skid।","pa":"Ice ’ਤੇ ਹਲਕੀ ਅਤੇ ਹੌਲੀ brake। ਜ਼ੋਰ ਨਾਲ brake ਕਰਨ ’ਤੇ wheels lock ਅਤੇ skid।","ur":"Ice پر ہلکی اور آہستہ brake۔ زور سے brake کرنے پر wheels lock اور skid۔","bn":"(not translated yet)","te":"Ice పై తేలికగా, నెమ్మదిగా brake. గట్టిగా brake వేస్తే wheels lock అయి skid.","mr":"Ice वर हलका आणि हळू brake. जोरात brake केल्यास wheels lock होतात आणि skid.","ml":"Ice-ൽ പതുക്കെ, മൃദുവായി brake ചെയ്യുക. ശക്തമായി ചെയ്താൽ wheels ലോക്ക് ആയി skid ചെയ്യും.","ta":"பனிக்கட்டியில் மென்மையாகவும் மெதுவாகவும் brake போடுங்கள். கடுமையாக போட்டால் wheels lock ஆகி skid ஏற்படும்.","gu":"બરફ પર હળવેથી brake મારો. જોરથી મારશો તો પૈડાં લૉક થઈ skid થાય.","ne":"बरफमा बिस्तारै brake लगाउनुहोस्। जोडले लगाए पाङ्ग्रा लक भएर skid हुन्छ।"},"tr":{"hi":{"q":"बर्फ़ीली सड़क पर आपको brake कैसे लगाना चाहिए?","o":["धीरे से","ज़ोर से और जल्दी","pedal को ज़ोर से बार-बार दबाकर","handbrake से"]},"pa":{"q":"ਬਰਫ਼ੀਲੀ ਸੜਕ 'ਤੇ ਤੁਹਾਨੂੰ brake ਕਿਵੇਂ ਲਾਉਣੀ ਚਾਹੀਦੀ ਹੈ?","o":["ਹੌਲੀ ਜਿਹੇ","ਜ਼ੋਰ ਨਾਲ ਅਤੇ ਜਲਦੀ","pedal ਨੂੰ ਜ਼ੋਰ ਨਾਲ ਵਾਰ-ਵਾਰ ਦਬਾ ਕੇ","handbrake ਨਾਲ"]},"ur":{"q":"برفیلی سڑک پر آپ کو بریک کیسے لگانی چاہیے؟","o":["آہستگی سے","زور سے اور جلدی","پیڈل کو زور زور سے دبا کر","ہینڈ بریک سے"]},"bn":{"q":"বরফে ঢাকা রাস্তায় আপনি কীভাবে ব্রেক করবেন?","o":["আস্তে","জোরে ও দ্রুত","প্যাডেল জোরে পাম্প করে","হ্যান্ডব্রেক দিয়ে"]},"te":{"q":"మంచు రోడ్డుపై మీరు ఎలా బ్రేక్ వేయాలి?","o":["మెల్లగా","గట్టిగా, త్వరగా","పెడల్‌ను గట్టిగా పదేపదే పంపింగ్ చేస్తూ","హ్యాండ్‌బ్రేక్‌తో"]},"mr":{"q":"बर्फाळ रस्त्यावर तुम्ही ब्रेक कसा लावावा?","o":["हळुवारपणे","जोरात आणि पटकन","पेडल जोरात पंप करून","हँडब्रेकने"]},"ml":{"q":"മഞ്ഞുമൂടിയ റോഡിൽ എങ്ങനെ brake ചെയ്യണം?","o":["പതുക്കെ","ശക്തമായും വേഗത്തിലും","pedal ശക്തമായി ആവർത്തിച്ച് അമർത്തി","handbrake ഉപയോഗിച്ച്"]},"ta":{"q":"பனிக்கட்டி சாலையில் எப்படி brake போட வேண்டும்?","o":["மென்மையாக","கடுமையாகவும் வேகமாகவும்","pedal-ஐ கடுமையாக pump செய்து","handbrake மூலம்"]},"gu":{"q":"બરફીલા રોડ પર brake કેવી રીતે મારવો?","o":["હળવેથી","જોરથી અને ઝડપથી","pedal જોરથી pump કરીને","handbrake થી"]},"ne":{"q":"बरफ भएको सडकमा brake कसरी लगाउने?","o":["बिस्तारै","जोडले र छिटो","pedal जोडले pump गरेर","handbrake ले"]}}},
{"id":9014,"chapter":9,"q":"You’re parking facing uphill on a road with a kerb on your left. Which way should you turn your front wheels?","options":["It doesn’t matter","Away from the kerb","Towards the kerb","Straight ahead"],"answer":1,"exp":{"hi":"Wheels kerb से दूर (right) घुमाओ, ताकि गाड़ी पीछे लुढ़के तो wheel kerb से अटक जाए। Handbrake और gear भी लगाओ।","pa":"Wheels kerb ਤੋਂ ਦੂਰ (ਸੱਜੇ) ਘੁਮਾਓ, ਤਾਂ ਜੋ ਗੱਡੀ ਪਿੱਛੇ ਰੁੜ੍ਹੇ ਤਾਂ wheel kerb ਨਾਲ ਅਟਕ ਜਾਵੇ। Handbrake ਅਤੇ gear ਵੀ ਲਾਓ।","ur":"Wheels kerb سے دور (دائیں) گھمائیں، تاکہ گاڑی پیچھے لڑھکے تو wheel kerb سے اٹک جائے۔ Handbrake اور gear بھی لگائیں۔","bn":"(not translated yet)","te":"Wheels ను kerb కు దూరంగా (కుడికి) తిప్పండి, వాహనం వెనక్కి దొర్లితే wheel kerb కు తగిలి ఆగుతుంది. Handbrake, gear కూడా వేయండి.","mr":"Wheels kerb पासून दूर (right) वळवा, म्हणजे गाडी मागे गडगडली तर wheel kerb ला अडेल. Handbrake आणि gear सुद्धा लावा.","ml":"Wheels kerb-ൽനിന്ന് അകലേക്ക് (വലത്തേക്ക്) തിരിക്കുക, കാർ പിന്നോട്ട് ഉരുണ്ടാൽ wheel kerb-ൽ തടഞ്ഞുനിൽക്കാൻ. Handbrake-ഉം gear-ഉം ഇടുക.","ta":"Wheels-ஐ kerb-இலிருந்து விலகி (வலதுபுறம்) திருப்புங்கள், கார் பின்னோக்கி உருண்டால் சக்கரம் kerb-இல் சிக்கும். Handbrake மற்றும் gear-உம் போடுங்கள்.","gu":"ચઢાણ તરફ મોઢું અને kerb ડાબે હોય તો આગળના પૈડાં kerb થી દૂર (જમણે) વાળો, અને handbrake લગાવો.","ne":"उकालो तर्फ मुख र kerb बायाँ भए अगाडिका पाङ्ग्रा kerb बाट टाढा (दायाँ) घुमाउनुहोस्, र handbrake लगाउनुहोस्।"},"tr":{"hi":{"q":"आप ऊपर की ओर मुँह करके park कर रहे हैं और आपकी बाईं तरफ़ kerb है। आपको अगले पहिये किस तरफ़ घुमाने चाहिए?","o":["कोई फ़र्क़ नहीं पड़ता","kerb से दूर","kerb की ओर","सीधे"]},"pa":{"q":"ਤੁਸੀਂ ਉੱਪਰ ਵੱਲ ਮੂੰਹ ਕਰਕੇ park ਕਰ ਰਹੇ ਹੋ ਅਤੇ ਤੁਹਾਡੇ ਖੱਬੇ ਪਾਸੇ kerb ਹੈ। ਤੁਹਾਨੂੰ ਅਗਲੇ ਪਹੀਏ ਕਿਸ ਪਾਸੇ ਘੁਮਾਉਣੇ ਚਾਹੀਦੇ ਹਨ?","o":["ਕੋਈ ਫ਼ਰਕ ਨਹੀਂ ਪੈਂਦਾ","kerb ਤੋਂ ਦੂਰ","kerb ਵੱਲ","ਸਿੱਧੇ"]},"ur":{"q":"آپ بائیں طرف کنارے (کرب) والی سڑک پر چڑھائی کی طرف منہ کر کے پارک کر رہے ہیں۔ آپ کو اگلے پہیے کس طرف موڑنے چاہئیں؟","o":["کوئی فرق نہیں پڑتا","کنارے سے دور","کنارے کی طرف","سیدھے آگے"]},"bn":{"q":"আপনি বাঁ দিকে কার্বযুক্ত রাস্তায় চড়াইয়ের দিকে মুখ করে পার্ক করছেন। সামনের চাকা কোন দিকে ঘোরাবেন?","o":["কোনো পার্থক্য নেই","কার্ব থেকে দূরে","কার্বের দিকে","সোজা সামনে"]},"te":{"q":"మీరు కర్బ్ ఎడమవైపు ఉన్న రోడ్డుపై ఎత్తుకు ముఖం పెట్టి పార్క్ చేస్తున్నారు. మీ ముందు చక్రాలను ఏ వైపు తిప్పాలి?","o":["తేడా లేదు","కర్బ్ నుంచి దూరంగా","కర్బ్ వైపు","నేరుగా ముందుకు"]},"mr":{"q":"तुम्ही डावीकडे कर्ब असलेल्या रस्त्यावर चढाकडे तोंड करून पार्क करत आहात. पुढची चाके कोणत्या दिशेने वळवावीत?","o":["काही फरक पडत नाही","कर्बपासून दूर","कर्बच्या दिशेने","सरळ पुढे"]},"ml":{"q":"ഇടതുവശത്ത് kerb ഉള്ള റോഡിൽ കയറ്റത്തിന് അഭിമുഖമായി park ചെയ്യുകയാണ്. മുൻ wheels ഏത് ദിശയിലേക്ക് തിരിക്കണം?","o":["പ്രശ്നമില്ല","kerb-ൽനിന്ന് അകലേക്ക്","kerb-ന് നേരെ","നേരെ മുന്നോട്ട്"]},"ta":{"q":"இடதுபுறம் kerb உள்ள சாலையில் மேல்நோக்கி எதிர்கொண்டு park செய்கிறீர்கள். முன் சக்கரங்களை எந்த திசையில் திருப்ப வேண்டும்?","o":["பரவாயில்லை","kerb-இலிருந்து விலகி","kerb நோக்கி","நேராக"]},"gu":{"q":"તમે ચઢાણ તરફ મોઢું રાખી park કરો છો અને ડાબી બાજુ kerb છે. આગળના પૈડાં કઈ તરફ વાળવા?","o":["કોઈ ફરક નથી","kerb થી દૂર","kerb તરફ","સીધા આગળ"]},"ne":{"q":"तपाईं उकालो तर्फ मुख फर्काएर park गर्दै हुनुहुन्छ र बायाँ तर्फ kerb छ। अगाडिका पाङ्ग्रा कता घुमाउने?","o":["फरक पर्दैन","kerb बाट टाढा","kerb तिर","सिधा अगाडि"]}}},
{"id":9015,"chapter":9,"q":"What should you do when driving over speed humps?","options":["Swerve around them","Brake hard on top of each hump","Slow down to a safe speed","Speed up between humps"],"answer":2,"exp":{"hi":"Humps speed कम करने के लिए हैं। पूरे हिस्से में धीरे चलो, अक्सर वहाँ pedestrians और बच्चे होते हैं।","pa":"Humps speed ਘਟਾਉਣ ਲਈ ਹਨ। ਪੂਰੇ ਹਿੱਸੇ ਵਿੱਚ ਹੌਲੀ ਚੱਲੋ, ਅਕਸਰ ਉੱਥੇ pedestrians ਅਤੇ ਬੱਚੇ ਹੁੰਦੇ ਹਨ।","ur":"Humps speed کم کرنے کے لیے ہیں۔ پورے حصے میں آہستہ چلیں، اکثر وہاں pedestrians اور بچے ہوتے ہیں۔","bn":"(not translated yet)","te":"Humps speed తగ్గించడానికే. ఆ ప్రాంతం మొత్తం నెమ్మదిగా వెళ్ళండి, అక్కడ తరచుగా pedestrians, పిల్లలు ఉంటారు.","mr":"Humps speed कमी करण्यासाठी आहेत. संपूर्ण भागात हळू चला, तिथे अनेकदा pedestrians आणि मुले असतात.","ml":"Humps വേഗത കുറയ്ക്കാനാണ്. മുഴുവൻ ഭാഗത്തും പതുക്കെ ഓടിക്കുക, അവിടെ പലപ്പോഴും pedestrians-ഉം കുട്ടികളും ഉണ്ടാകും.","ta":"Humps வேகத்தை குறைக்கவே. முழுப் பகுதியிலும் மெதுவாக செல்லுங்கள், பெரும்பாலும் அங்கே பாதசாரிகளும் குழந்தைகளும் இருப்பார்கள்.","gu":"Speed humps પર સલામત ઝડપે ધીમા પડો. દરેક hump પર જોરથી brake ન મારો.","ne":"Speed humps मा सुरक्षित गतिमा ढिलो हुनुहोस्। हरेक hump माथि जोडले brake नलगाउनुहोस्।"},"tr":{"hi":{"q":"speed humps पर से गुज़रते समय आपको क्या करना चाहिए?","o":["उनके बगल से घूमकर निकलो","हर hump के ऊपर ज़ोर से brake लगाओ","सुरक्षित speed तक धीमे हो जाओ","humps के बीच में speed बढ़ाओ"]},"pa":{"q":"speed humps ਉੱਤੋਂ ਲੰਘਦੇ ਸਮੇਂ ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਉਨ੍ਹਾਂ ਦੇ ਕੋਲੋਂ ਘੁੰਮ ਕੇ ਨਿਕਲੋ","ਹਰ hump ਦੇ ਉੱਪਰ ਜ਼ੋਰ ਨਾਲ brake ਲਾਓ","ਸੁਰੱਖਿਅਤ speed ਤੱਕ ਹੌਲੀ ਹੋ ਜਾਓ","humps ਵਿਚਕਾਰ speed ਵਧਾਓ"]},"ur":{"q":"اسپیڈ بریکرز (ہمپس) پر سے گزرتے وقت آپ کو کیا کرنا چاہیے؟","o":["ان کے گرد مڑ کر نکلیں","ہر ہمپ کے اوپر زور سے بریک لگائیں","محفوظ رفتار تک آہستہ کریں","ہمپس کے درمیان رفتار بڑھائیں"]},"bn":{"q":"স্পিড হাম্পের ওপর দিয়ে যাওয়ার সময় আপনার কী করা উচিত?","o":["এড়িয়ে ঘুরে যান","প্রতিটি হাম্পের ওপরে জোরে ব্রেক করুন","নিরাপদ গতিতে কমিয়ে নিন","হাম্পগুলোর মাঝে গতি বাড়ান"]},"te":{"q":"స్పీడ్ హంప్స్ మీదుగా నడుపుతున్నప్పుడు మీరు ఏమి చేయాలి?","o":["వాటి చుట్టూ తప్పించుకోండి","ప్రతి హంప్ పైన గట్టిగా బ్రేక్ వేయండి","సురక్షిత వేగానికి తగ్గించండి","హంప్‌ల మధ్య వేగం పెంచండి"]},"mr":{"q":"speed humps वरून जाताना तुम्ही काय करावे?","o":["त्यांच्या बाजूने वळसा घ्या","प्रत्येक humpच्या माथ्यावर जोरात ब्रेक लावा","सुरक्षित वेगापर्यंत वेग कमी करा","humps च्या मधल्या भागात वेग वाढवा"]},"ml":{"q":"speed humps-ന് മുകളിലൂടെ ഓടിക്കുമ്പോൾ എന്ത് ചെയ്യണം?","o":["അവയെ വെട്ടിച്ചൊഴിഞ്ഞ് പോകുക","ഓരോ hump-ന്റെയും മുകളിൽ ശക്തമായി brake ചെയ്യുക","സുരക്ഷിത വേഗതയിലേക്ക് കുറയ്ക്കുക","humps-ക്കിടയിൽ വേഗത കൂട്ടുക"]},"ta":{"q":"speed humps மேல் ஓட்டும்போது என்ன செய்ய வேண்டும்?","o":["அவற்றைச் சுற்றி வளையுங்கள்","ஒவ்வொரு hump மேலும் கடுமையாக brake போடுங்கள்","பாதுகாப்பான வேகத்திற்கு குறையுங்கள்","humps இடையே வேகமெடுங்கள்"]},"gu":{"q":"speed humps ઉપર ચલાવતાં શું કરવું?","o":["તેમની આસપાસ વળાંક લો","દરેક hump ઉપર જોરથી brake મારો","સલામત ઝડપે ધીમા પડો","humps વચ્ચે ઝડપ વધારો"]},"ne":{"q":"speed humps माथि चलाउँदा के गर्ने?","o":["तिनको वरिपरि घुम्नुहोस्","हरेक hump माथि जोडले brake लगाउनुहोस्","सुरक्षित गतिमा ढिलो हुनुहोस्","humps बीचमा गति बढाउनुहोस्"]}}},
{"id":9016,"chapter":9,"q":"How should you approach a bend?","options":["Brake hard in the middle of the bend","Accelerate before the bend","Coast through the bend","Slow down before the bend, not in it"],"answer":3,"exp":{"hi":"मोड़ से पहले speed कम करो, मोड़ में हल्का accelerator। मोड़ के बीच brake करने से control खो सकते हो।","pa":"ਮੋੜ ਤੋਂ ਪਹਿਲਾਂ speed ਘਟਾਓ, ਮੋੜ ਵਿੱਚ ਹਲਕਾ accelerator। ਮੋੜ ਦੇ ਵਿਚਕਾਰ brake ਕਰਨ ਨਾਲ control ਗੁਆ ਸਕਦੇ ਹੋ।","ur":"موڑ سے پہلے speed کم کریں، موڑ میں ہلکا accelerator۔ موڑ کے درمیان brake کرنے سے control کھو سکتے ہیں۔","bn":"(not translated yet)","te":"మలుపుకు ముందే speed తగ్గించండి, మలుపులో తేలికపాటి accelerator. మలుపు మధ్యలో brake వేస్తే control కోల్పోవచ్చు.","mr":"वळणापूर्वी speed कमी करा, वळणात हलका accelerator. वळणाच्या मध्ये brake केल्याने control जाऊ शकतो.","ml":"വളവിന് മുമ്പ് speed കുറയ്ക്കുക, വളവിനുള്ളിൽ ലഘുവായ accelerator. വളവിന്റെ നടുവിൽ brake ചെയ്താൽ control നഷ്ടപ്പെടാം.","ta":"வளைவுக்கு முன் வேகத்தை குறையுங்கள், வளைவுக்குள் மெல்லிய accelerator. வளைவின் நடுவில் brake போட்டால் control இழக்கலாம்.","gu":"વળાંક પહેલાં ધીમા પડો, વળાંકમાં નહીં. વળાંકમાં brake મારવાથી skid થઈ શકે.","ne":"मोड अघि ढिलो हुनुहोस्, मोडमा होइन। मोडमा brake लगाउँदा skid हुन सक्छ।"},"tr":{"hi":{"q":"आपको मोड़ के पास कैसे पहुँचना चाहिए?","o":["मोड़ के बीच में ज़ोर से brake लगाओ","मोड़ से पहले speed बढ़ाओ","मोड़ में coasting करो","मोड़ से पहले धीमे हो जाओ, मोड़ के अंदर नहीं"]},"pa":{"q":"ਤੁਹਾਨੂੰ ਮੋੜ ਦੇ ਨੇੜੇ ਕਿਵੇਂ ਪਹੁੰਚਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਮੋੜ ਦੇ ਵਿਚਕਾਰ ਜ਼ੋਰ ਨਾਲ brake ਲਾਓ","ਮੋੜ ਤੋਂ ਪਹਿਲਾਂ speed ਵਧਾਓ","ਮੋੜ ਵਿੱਚ coasting ਕਰੋ","ਮੋੜ ਤੋਂ ਪਹਿਲਾਂ ਹੌਲੀ ਹੋ ਜਾਓ, ਮੋੜ ਦੇ ਅੰਦਰ ਨਹੀਂ"]},"ur":{"q":"آپ کو موڑ کے قریب کیسے پہنچنا چاہیے؟","o":["موڑ کے بیچ میں زور سے بریک لگائیں","موڑ سے پہلے رفتار بڑھائیں","موڑ میں کوسٹ کر کے گزریں","موڑ سے پہلے رفتار کم کریں، موڑ کے اندر نہیں"]},"bn":{"q":"আপনার বাঁকের কাছে কীভাবে পৌঁছানো উচিত?","o":["বাঁকের মাঝখানে জোরে ব্রেক করুন","বাঁকের আগে গতি বাড়ান","বাঁকের মধ্যে কোস্ট করুন","বাঁকের আগে গতি কমান, বাঁকের মধ্যে নয়"]},"te":{"q":"మలుపు దగ్గరకు మీరు ఎలా చేరాలి?","o":["మలుపు మధ్యలో గట్టిగా బ్రేక్ వేయండి","మలుపు ముందు వేగం పెంచండి","మలుపులో కోస్టింగ్ చేయండి","మలుపుకు ముందే వేగం తగ్గించండి, మలుపులో కాదు"]},"mr":{"q":"तुम्ही वळणाजवळ कसे जावे?","o":["वळणाच्या मध्यभागी जोरात ब्रेक लावा","वळणापूर्वी वेग वाढवा","वळणातून coasting करा","वळणात नव्हे तर वळणापूर्वी वेग कमी करा"]},"ml":{"q":"ഒരു വളവിലേക്ക് എങ്ങനെ അടുക്കണം?","o":["വളവിന്റെ നടുവിൽ ശക്തമായി brake ചെയ്യുക","വളവിന് മുമ്പ് accelerate ചെയ്യുക","വളവിലൂടെ coasting ചെയ്യുക","വളവിനുള്ളിലല്ല, വളവിന് മുമ്പ് വേഗത കുറയ്ക്കുക"]},"ta":{"q":"வளைவை எப்படி அணுக வேண்டும்?","o":["வளைவின் நடுவில் கடுமையாக brake போடுங்கள்","வளைவுக்கு முன் வேகமெடுங்கள்","வளைவு முழுவதும் coasting செய்யுங்கள்","வளைவுக்கு முன் வேகத்தை குறையுங்கள், வளைவுக்குள் அல்ல"]},"gu":{"q":"વળાંક પાસે કેવી રીતે પહોંચવું?","o":["વળાંકની વચ્ચે જોરથી brake મારો","વળાંક પહેલાં accelerate કરો","વળાંકમાંથી coasting કરો","વળાંક પહેલાં ધીમા પડો, વળાંકમાં નહીં"]},"ne":{"q":"मोडमा कसरी पुग्ने?","o":["मोडको बीचमा जोडले brake लगाउनुहोस्","मोड अघि accelerate गर्नुहोस्","मोडमा coasting गर्नुहोस्","मोड अघि ढिलो हुनुहोस्, मोडमा होइन"]}}},
{"id":9017,"chapter":9,"q":"Where are you most likely to be affected by a sudden crosswind?","options":["On exposed roads, bridges and gaps between buildings","In tunnels","In town centres","In car parks"],"answer":0,"exp":{"hi":"खुले रास्ते, पुल और इमारतों के बीच के ख़ाली हिस्सों में हवा अचानक गाड़ी को खिसका सकती है।","pa":"ਖੁੱਲ੍ਹੇ ਰਾਹ, ਪੁਲ ਅਤੇ ਇਮਾਰਤਾਂ ਵਿਚਕਾਰ ਦੇ ਖ਼ਾਲੀ ਹਿੱਸਿਆਂ ਵਿੱਚ ਹਵਾ ਅਚਾਨਕ ਗੱਡੀ ਨੂੰ ਖਿਸਕਾ ਸਕਦੀ ਹੈ।","ur":"کھلی جگہیں، پل اور عمارتوں کے درمیان خالی حصوں میں ہوا اچانک گاڑی کو کھسکا سکتی ہے۔","bn":"(not translated yet)","te":"బహిరంగ ప్రదేశాలు, వంతెనలు, భవనాల మధ్య ఖాళీల్లో గాలి అకస్మాత్తుగా వాహనాన్ని పక్కకు నెట్టవచ్చు.","mr":"मोकळे रस्ते, पूल आणि इमारतींमधील मोकळ्या भागात वारा अचानक गाडीला हलवू शकतो.","ml":"തുറന്ന വഴികൾ, പാലങ്ങൾ, കെട്ടിടങ്ങൾക്കിടയിലെ ഒഴിഞ്ഞ ഭാഗങ്ങൾ എന്നിവിടങ്ങളിൽ കാറ്റ് പെട്ടെന്ന് വാഹനത്തെ തള്ളാം.","ta":"திறந்த பாதைகள், பாலங்கள், கட்டடங்களுக்கு இடையிலான காலி இடங்களில் காற்று திடீரென காரை நகர்த்தலாம்.","gu":"ખુલ્લા રોડ, પુલ અને ઇમારતો વચ્ચેના ગાબડાંમાં અચાનક crosswind આવી શકે. Steering મજબૂત પકડો.","ne":"खुला सडक, पुल र भवनहरूबीचको खाली ठाउँमा अचानक crosswind आउन सक्छ। Steering दह्रोसँग समात्नुहोस्।"},"tr":{"hi":{"q":"अचानक आने वाली आड़ी हवा (crosswind) का सबसे ज़्यादा असर आप पर कहाँ पड़ सकता है?","o":["खुली सड़कों, पुलों और इमारतों के बीच की ख़ाली जगहों पर","सुरंगों में","शहर के केंद्रों में","car parks में"]},"pa":{"q":"ਅਚਾਨਕ ਆਉਣ ਵਾਲੀ ਆਡੀ ਹਵਾ (crosswind) ਦਾ ਸਭ ਤੋਂ ਵੱਧ ਅਸਰ ਤੁਹਾਡੇ 'ਤੇ ਕਿੱਥੇ ਪੈ ਸਕਦਾ ਹੈ?","o":["ਖੁੱਲ੍ਹੀਆਂ ਸੜਕਾਂ, ਪੁਲਾਂ ਅਤੇ ਇਮਾਰਤਾਂ ਵਿਚਕਾਰਲੀਆਂ ਖ਼ਾਲੀ ਥਾਵਾਂ 'ਤੇ","ਸੁਰੰਗਾਂ ਵਿੱਚ","ਸ਼ਹਿਰ ਦੇ ਕੇਂਦਰਾਂ ਵਿੱਚ","car parks ਵਿੱਚ"]},"ur":{"q":"اچانک پہلو سے آنے والی ہوا سے آپ کے متاثر ہونے کا سب سے زیادہ امکان کہاں ہے؟","o":["کھلی سڑکوں، پلوں اور عمارتوں کے درمیان خالی جگہوں پر","سرنگوں میں","شہر کے مراکز میں","کار پارکوں میں"]},"bn":{"q":"হঠাৎ পাশের বাতাসে আপনি কোথায় সবচেয়ে বেশি প্রভাবিত হতে পারেন?","o":["খোলা রাস্তা, সেতু এবং ভবনের মাঝের ফাঁকে","সুড়ঙ্গে","শহরের কেন্দ্রে","কার পার্কে"]},"te":{"q":"ఆకస్మిక పక్క గాలి (crosswind) వల్ల మీరు ఎక్కడ ఎక్కువగా ప్రభావితం కావచ్చు?","o":["బహిరంగ రోడ్లు, వంతెనలు, భవనాల మధ్య ఖాళీల్లో","సొరంగాల్లో","పట్టణ కేంద్రాల్లో","కార్ పార్క్‌లలో"]},"mr":{"q":"अचानक आडव्या वाऱ्याचा सर्वाधिक परिणाम तुमच्यावर कुठे होण्याची शक्यता असते?","o":["मोकळे रस्ते, पूल आणि इमारतींमधील मोकळ्या जागा","बोगद्यांमध्ये","शहराच्या मध्यवर्ती भागात","कार पार्कमध्ये"]},"ml":{"q":"പെട്ടെന്നുള്ള crosswind നിങ്ങളെ ബാധിക്കാൻ ഏറ്റവും സാധ്യതയുള്ളത് എവിടെ?","o":["തുറന്ന റോഡുകളിൽ, പാലങ്ങളിൽ, കെട്ടിടങ്ങൾക്കിടയിലെ വിടവുകളിൽ","tunnels-ൽ","പട്ടണ കേന്ദ്രങ്ങളിൽ","car parks-ൽ"]},"ta":{"q":"திடீர் பக்கவாட்டு காற்றால் நீங்கள் எங்கு அதிகம் பாதிக்கப்படலாம்?","o":["திறந்த சாலைகள், பாலங்கள், கட்டடங்களுக்கு இடையிலான இடைவெளிகளில்","சுரங்கங்களில்","நகர மையங்களில்","car park-களில்"]},"gu":{"q":"અચાનક crosswind થી તમે સૌથી વધુ ક્યાં અસરગ્રસ્ત થાઓ?","o":["ખુલ્લા રોડ, પુલો અને ઇમારતો વચ્ચેના ગાબડાં પર","tunnels માં","શહેરના કેન્દ્રમાં","car parks માં"]},"ne":{"q":"अचानक crosswind ले तपाईंलाई सबैभन्दा बढी कहाँ प्रभाव पार्छ?","o":["खुला सडक, पुल र भवनहरूबीचको खाली ठाउँमा","सुरुङमा","सहरको केन्द्रमा","car parks मा"]}}},
{"id":9018,"chapter":9,"q":"Why might you change to a lower gear before overtaking?","options":["To brake more easily","To get better acceleration","To save fuel","To reduce noise"],"answer":1,"exp":{"hi":"Low gear में गाड़ी जल्दी speed पकड़ती है, overtake जल्दी और सुरक्षित होता है।","pa":"Low gear ਵਿੱਚ ਗੱਡੀ ਜਲਦੀ speed ਫੜਦੀ ਹੈ, overtake ਜਲਦੀ ਅਤੇ ਸੁਰੱਖਿਅਤ ਹੁੰਦਾ ਹੈ।","ur":"Low gear میں گاڑی جلدی speed پکڑتی ہے، overtake جلدی اور محفوظ ہوتا ہے۔","bn":"(not translated yet)","te":"Low gear లో వాహనం త్వరగా speed అందుకుంటుంది, overtake త్వరగా, సురక్షితంగా జరుగుతుంది.","mr":"Low gear मध्ये गाडी लवकर speed पकडते, overtake जलद आणि सुरक्षित होतो.","ml":"Low gear-ൽ കാർ വേഗം speed പിടിക്കും, ഓവർടേക്ക് വേഗത്തിലും സുരക്ഷിതമായും ആകും.","ta":"குறைந்த gear-இல் கார் விரைவாக வேகம் பிடிக்கும், முந்துவது விரைவாகவும் பாதுகாப்பாகவும் இருக்கும்.","gu":"ઓવરટેક પહેલાં નીચા gear માં બદલવાથી વધુ સારી acceleration મળે અને ઝડપથી પસાર થવાય.","ne":"Overtake गर्नु अघि होचो gear मा बदल्दा राम्रो acceleration मिल्छ र छिटो नाघिन्छ।"},"tr":{"hi":{"q":"overtake करने से पहले आप नीचे के gear में क्यों बदल सकते हैं?","o":["आसानी से brake लगाने के लिए","बेहतर acceleration पाने के लिए","ईंधन बचाने के लिए","शोर कम करने के लिए"]},"pa":{"q":"overtake ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਸੀਂ ਨੀਵੇਂ gear ਵਿੱਚ ਕਿਉਂ ਬਦਲ ਸਕਦੇ ਹੋ?","o":["ਆਸਾਨੀ ਨਾਲ brake ਲਾਉਣ ਲਈ","ਬਿਹਤਰ acceleration ਪਾਉਣ ਲਈ","ਤੇਲ ਬਚਾਉਣ ਲਈ","ਸ਼ੋਰ ਘਟਾਉਣ ਲਈ"]},"ur":{"q":"اوور ٹیک کرنے سے پہلے آپ نچلے گیئر میں کیوں جا سکتے ہیں؟","o":["بریک آسانی سے لگانے کے لیے","بہتر رفتار بڑھانے (ایکسیلریشن) کے لیے","ایندھن بچانے کے لیے","شور کم کرنے کے لیے"]},"bn":{"q":"ওভারটেক করার আগে আপনি নিচু গিয়ারে কেন যেতে পারেন?","o":["সহজে ব্রেক করতে","ভালো অ্যাক্সিলারেশন পেতে","জ্বালানি বাঁচাতে","শব্দ কমাতে"]},"te":{"q":"ఓవర్‌టేక్ చేసే ముందు మీరు తక్కువ గేర్‌కు ఎందుకు మారవచ్చు?","o":["సులభంగా బ్రేక్ వేయడానికి","మెరుగైన వేగవృద్ధి (acceleration) కోసం","ఇంధనం ఆదా చేయడానికి","శబ్దం తగ్గించడానికి"]},"mr":{"q":"ओव्हरटेक करण्यापूर्वी तुम्ही कमी गिअरमध्ये का जाऊ शकता?","o":["ब्रेक सहज लावण्यासाठी","चांगले अ‍ॅक्सिलरेशन मिळवण्यासाठी","इंधन वाचवण्यासाठी","आवाज कमी करण्यासाठी"]},"ml":{"q":"ഓവർടേക്ക് ചെയ്യുന്നതിന് മുമ്പ് താഴ്ന്ന gear-ലേക്ക് മാറുന്നത് എന്തുകൊണ്ട്?","o":["എളുപ്പത്തിൽ brake ചെയ്യാൻ","മെച്ചപ്പെട്ട acceleration കിട്ടാൻ","ഇന്ധനം ലാഭിക്കാൻ","ശബ്ദം കുറയ്ക്കാൻ"]},"ta":{"q":"முந்துவதற்கு முன் ஏன் குறைந்த gear-க்கு மாறலாம்?","o":["எளிதாக brake போட","சிறந்த வேகமெடுத்தலுக்கு","எரிபொருள் சேமிக்க","சத்தத்தை குறைக்க"]},"gu":{"q":"ઓવરટેક કરતાં પહેલાં નીચા gear માં કેમ બદલવું?","o":["વધુ સરળતાથી brake મારવા","વધુ સારી acceleration મેળવવા","બળતણ બચાવવા","અવાજ ઘટાડવા"]},"ne":{"q":"overtake गर्नु अघि होचो gear मा किन बदल्ने?","o":["सजिलै brake लगाउन","राम्रो acceleration पाउन","इन्धन बचाउन","आवाज घटाउन"]}}},
{"id":9019,"chapter":9,"q":"When driving in fog, why shouldn’t you use main beam?","options":["It’s illegal at all times","It dazzles pedestrians only","The light reflects back off the fog and makes it harder to see","It uses too much power"],"answer":2,"exp":{"hi":"Fog में main beam की रोशनी वापस आँखों पर आती है। Dipped headlights इस्तेमाल करो, और 100 m से कम visibility में fog lights।","pa":"Fog ਵਿੱਚ main beam ਦੀ ਰੋਸ਼ਨੀ ਵਾਪਸ ਅੱਖਾਂ ’ਤੇ ਆਉਂਦੀ ਹੈ। Dipped headlights ਵਰਤੋ, ਅਤੇ 100 m ਤੋਂ ਘੱਟ visibility ਵਿੱਚ fog lights।","ur":"Fog میں main beam کی روشنی واپس آنکھوں پر آتی ہے۔ Dipped headlights استعمال کریں، اور 100 m سے کم visibility میں fog lights۔","bn":"(not translated yet)","te":"Fog లో main beam వెలుతురు తిరిగి కళ్ళలోకి వస్తుంది. Dipped headlights వాడండి, 100 m కన్నా తక్కువ visibility లో fog lights.","mr":"Fog मध्ये main beam चा प्रकाश परत डोळ्यांवर येतो. Dipped headlights वापरा, आणि 100 m पेक्षा कमी visibility मध्ये fog lights.","ml":"Fog-ൽ main beam-ന്റെ വെളിച്ചം തിരിച്ച് കണ്ണിൽ വരും. Dipped headlights ഉപയോഗിക്കുക, 100 m-ൽ താഴെ visibility-യിൽ fog lights.","ta":"மூடுபனியில் main beam ஒளி திரும்பி கண்ணில் படும். Dipped headlights பயன்படுத்துங்கள், 100 m-க்கு குறைவான பார்வையில் fog lights.","gu":"ધુમ્મસમાં main beam નો પ્રકાશ ધુમ્મસના કણોથી પાછો ઉછળે અને દૃશ્ય બગાડે. Dipped વાપરો.","ne":"कुहिरोमा main beam को उज्यालो कुहिरोका कणबाट फर्केर दृश्य बिगार्छ। Dipped प्रयोग गर्नुहोस्।"},"tr":{"hi":{"q":"कोहरे में गाड़ी चलाते समय आपको main beam क्यों इस्तेमाल नहीं करनी चाहिए?","o":["यह हर समय ग़ैरक़ानूनी है","यह सिर्फ़ पैदल यात्रियों की आँखें चौंधियाती है","रोशनी कोहरे से टकराकर वापस आती है और देखना मुश्किल बना देती है","यह बहुत ज़्यादा बिजली इस्तेमाल करती है"]},"pa":{"q":"ਧੁੰਦ ਵਿੱਚ ਗੱਡੀ ਚਲਾਉਂਦੇ ਸਮੇਂ ਤੁਹਾਨੂੰ main beam ਕਿਉਂ ਨਹੀਂ ਵਰਤਣੀ ਚਾਹੀਦੀ?","o":["ਇਹ ਹਰ ਸਮੇਂ ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਹੈ","ਇਹ ਸਿਰਫ਼ ਪੈਦਲ ਯਾਤਰੀਆਂ ਦੀਆਂ ਅੱਖਾਂ ਚੌਂਧਿਆਉਂਦੀ ਹੈ","ਰੌਸ਼ਨੀ ਧੁੰਦ ਨਾਲ ਟਕਰਾ ਕੇ ਵਾਪਸ ਆਉਂਦੀ ਹੈ ਅਤੇ ਦੇਖਣਾ ਔਖਾ ਬਣਾ ਦਿੰਦੀ ਹੈ","ਇਹ ਬਹੁਤ ਜ਼ਿਆਦਾ ਬਿਜਲੀ ਵਰਤਦੀ ਹੈ"]},"ur":{"q":"دھند میں گاڑی چلاتے ہوئے آپ کو مین بیم کیوں استعمال نہیں کرنی چاہیے؟","o":["یہ ہر وقت غیر قانونی ہے","یہ صرف پیدل چلنے والوں کی آنکھیں چندھیاتی ہے","روشنی دھند سے واپس منعکس ہوتی ہے اور دیکھنا مشکل کر دیتی ہے","یہ بہت زیادہ بجلی خرچ کرتی ہے"]},"bn":{"q":"কুয়াশায় চালানোর সময় মেইন বিম ব্যবহার করা উচিত নয় কেন?","o":["এটি সবসময় বেআইনি","এটি শুধু পথচারীদের চোখ ধাঁধায়","আলো কুয়াশা থেকে প্রতিফলিত হয়ে ফিরে আসে এবং দেখা কঠিন করে","এটি অনেক বেশি বিদ্যুৎ নেয়"]},"te":{"q":"పొగమంచులో నడుపుతున్నప్పుడు మెయిన్ బీమ్ ఎందుకు వాడకూడదు?","o":["ఇది ఎల్లప్పుడూ చట్టవిరుద్ధం","ఇది పాదచారుల కళ్లను మాత్రమే చెదరగొడుతుంది","వెలుతురు పొగమంచు నుంచి తిరిగి ప్రతిబింబించి చూడడం కష్టతరం చేస్తుంది","ఇది చాలా ఎక్కువ శక్తి వాడుతుంది"]},"mr":{"q":"धुक्यात गाडी चालवताना main beam का वापरू नये?","o":["ते नेहमी बेकायदेशीर आहे","ते फक्त पादचाऱ्यांचे डोळे दिपवते","प्रकाश धुक्यावरून परत परावर्तित होतो आणि पाहणे कठीण होते","ते खूप ऊर्जा वापरते"]},"ml":{"q":"fog-ൽ ഓടിക്കുമ്പോൾ main beam ഉപയോഗിക്കരുത് എന്തുകൊണ്ട്?","o":["അത് എപ്പോഴും നിയമവിരുദ്ധമാണ്","അത് കാൽനടക്കാരെ മാത്രം മഞ്ഞളിപ്പിക്കും","വെളിച്ചം fog-ൽ തട്ടി തിരിച്ചുവരും, കാണാൻ കൂടുതൽ ബുദ്ധിമുട്ടാകും","അത് വളരെ കൂടുതൽ വൈദ്യുതി ഉപയോഗിക്കും"]},"ta":{"q":"மூடுபனியில் ஓட்டும்போது main beam-ஐ ஏன் பயன்படுத்தக்கூடாது?","o":["எப்போதும் சட்டவிரோதம்","பாதசாரிகளுக்கு மட்டும் கூசும்","ஒளி பனியில் பட்டு திரும்பி பார்ப்பதை கடினமாக்கும்","அதிக மின்சாரம் செலவாகும்"]},"gu":{"q":"ધુમ્મસમાં main beam કેમ ન વાપરવી?","o":["તે બધા સમયે ગેરકાયદેસર છે","તે ફક્ત રાહદારીઓને અંજાવે છે","પ્રકાશ ધુમ્મસમાંથી પાછો ઉછળે છે અને જોવું વધુ કઠિન બને","તે ખૂબ power વાપરે છે"]},"ne":{"q":"कुहिरोमा main beam किन प्रयोग नगर्ने?","o":["यो सधैं गैरकानूनी हो","यसले पैदल यात्रीलाई मात्र चिलाउँछ","प्रकाश कुहिरोबाट फर्किन्छ र देख्न गाह्रो बनाउँछ","यसले धेरै power खर्च गर्छ"]}}},
{"id":9020,"chapter":9,"q":"A front tyre bursts while you’re driving. What should you do?","options":["Brake hard immediately","Steer sharply to the verge","Accelerate to keep control","Hold the steering wheel firmly and let the car slow down gradually"],"answer":3,"exp":{"hi":"Steering कसकर पकड़ो, गाड़ी सीधी रखो और धीरे-धीरे रुकने दो। ज़ोर का brake गाड़ी घुमा सकता है।","pa":"Steering ਘੁੱਟ ਕੇ ਫੜੋ, ਗੱਡੀ ਸਿੱਧੀ ਰੱਖੋ ਅਤੇ ਹੌਲੀ-ਹੌਲੀ ਰੁਕਣ ਦਿਓ। ਜ਼ੋਰ ਦੀ brake ਗੱਡੀ ਘੁਮਾ ਸਕਦੀ ਹੈ।","ur":"Steering مضبوطی سے پکڑیں، گاڑی سیدھی رکھیں اور آہستہ آہستہ رکنے دیں۔ زور کی brake گاڑی گھما سکتی ہے۔","bn":"(not translated yet)","te":"Steering గట్టిగా పట్టుకుని, వాహనాన్ని నేరుగా ఉంచి, నెమ్మదిగా ఆగనివ్వండి. గట్టి brake వాహనాన్ని తిప్పేయవచ్చు.","mr":"Steering घट्ट धरा, गाडी सरळ ठेवा आणि हळूहळू थांबू द्या. जोरात brake केल्याने गाडी वळू शकते.","ml":"Steering ഉറപ്പായി പിടിക്കുക, കാർ നേരെ വച്ച് പതുക്കെ നിൽക്കാൻ അനുവദിക്കുക. ശക്തമായ brake കാറിനെ തിരിക്കാം.","ta":"Steering-ஐ உறுதியாகப் பிடித்து, காரை நேராக வைத்து மெதுவாக நிற்க விடுங்கள். கடுமையான brake காரை திருப்பிவிடலாம்.","gu":"Tyre ફાટે તો steering મજબૂત પકડો, ધીમે ધીમે ઝડપ ઘટવા દો. જોરથી brake કે steer ન કરો.","ne":"Tyre फुटे steering दह्रोसँग समात्नुहोस्, बिस्तारै गति घट्न दिनुहोस्। जोडले brake वा steer नगर्नुहोस्।"},"tr":{"hi":{"q":"गाड़ी चलाते समय आगे का एक टायर फट जाता है। आपको क्या करना चाहिए?","o":["तुरंत ज़ोर से brake लगाओ","तेज़ी से किनारे की ओर steer करो","नियंत्रण बनाए रखने के लिए accelerate करो","steering wheel को मज़बूती से पकड़ो और कार को धीरे-धीरे धीमा होने दो"]},"pa":{"q":"ਗੱਡੀ ਚਲਾਉਂਦੇ ਸਮੇਂ ਅੱਗੇ ਦਾ ਇਕ ਟਾਇਰ ਫਟ ਜਾਂਦਾ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਤੁਰੰਤ ਜ਼ੋਰ ਨਾਲ brake ਲਾਓ","ਤੇਜ਼ੀ ਨਾਲ ਕਿਨਾਰੇ ਵੱਲ steer ਕਰੋ","ਕਾਬੂ ਬਣਾਈ ਰੱਖਣ ਲਈ accelerate ਕਰੋ","steering wheel ਨੂੰ ਮਜ਼ਬੂਤੀ ਨਾਲ ਫੜੋ ਅਤੇ ਕਾਰ ਨੂੰ ਹੌਲੀ-ਹੌਲੀ ਹੌਲੀ ਹੋਣ ਦਿਓ"]},"ur":{"q":"گاڑی چلاتے ہوئے آپ کا اگلا ٹائر پھٹ جاتا ہے۔ آپ کو کیا کرنا چاہیے؟","o":["فوراً زور سے بریک لگائیں","تیزی سے کچے کنارے کی طرف موڑیں","قابو برقرار رکھنے کے لیے رفتار بڑھائیں","اسٹیئرنگ وہیل کو مضبوطی سے پکڑیں اور گاڑی کو آہستہ آہستہ رکنے دیں"]},"bn":{"q":"চালানোর সময় আপনার সামনের একটি টায়ার ফেটে গেল। আপনার কী করা উচিত?","o":["সঙ্গে সঙ্গে জোরে ব্রেক করুন","তীব্রভাবে পাশের ঘাসে স্টিয়ার করুন","নিয়ন্ত্রণ রাখতে গতি বাড়ান","স্টিয়ারিং হুইল শক্ত করে ধরুন এবং গাড়িকে ধীরে ধীরে থামতে দিন"]},"te":{"q":"నడుపుతుండగా ముందు టైర్ పేలింది. మీరు ఏమి చేయాలి?","o":["వెంటనే గట్టిగా బ్రేక్ వేయండి","అంచు వైపు తీవ్రంగా స్టీర్ చేయండి","నియంత్రణ కోసం వేగం పెంచండి","స్టీరింగ్ వీల్‌ను గట్టిగా పట్టుకుని కారు క్రమంగా నెమ్మదించనివ్వండి"]},"mr":{"q":"गाडी चालवताना पुढचा टायर फुटतो. तुम्ही काय करावे?","o":["लगेच जोरात ब्रेक लावा","कडेच्या गवताकडे जोरात स्टीअर करा","नियंत्रण राखण्यासाठी अ‍ॅक्सिलरेट करा","स्टीअरिंग व्हील घट्ट धरा आणि गाडीचा वेग हळूहळू कमी होऊ द्या"]},"ml":{"q":"ഓടിക്കുമ്പോൾ ഒരു മുൻ tyre പൊട്ടി. എന്ത് ചെയ്യണം?","o":["ഉടൻ ശക്തമായി brake ചെയ്യുക","verge-ലേക്ക് ശക്തമായി steer ചെയ്യുക","നിയന്ത്രണം നിലനിർത്താൻ accelerate ചെയ്യുക","steering wheel ഉറപ്പായി പിടിച്ച് കാർ പതുക്കെ വേഗത കുറയാൻ അനുവദിക്കുക"]},"ta":{"q":"ஓட்டும்போது முன் டயர் வெடிக்கிறது. என்ன செய்ய வேண்டும்?","o":["உடனே கடுமையாக brake போடுங்கள்","verge நோக்கி கூர்மையாக steer செய்யுங்கள்","control-ஐ தக்கவைக்க வேகமெடுங்கள்","steering wheel-ஐ உறுதியாகப் பிடித்து கார் படிப்படியாக மெதுவாக விடுங்கள்"]},"gu":{"q":"ચલાવતાં આગળનું tyre ફાટે છે. શું કરવું?","o":["તરત જોરથી brake મારો","verge તરફ જોરથી steer કરો","નિયંત્રણ માટે accelerate કરો","steering મજબૂત પકડો અને કારને ધીમે ધીમે ધીમી પડવા દો"]},"ne":{"q":"गाडी चलाउँदा अगाडिको tyre फुट्छ। के गर्नुपर्छ?","o":["तुरुन्तै जोडले brake लगाउनुहोस्","verge तिर जोडले steer गर्नुहोस्","नियन्त्रण राख्न accelerate गर्नुहोस्","steering दह्रोसँग समात्नुहोस् र कारलाई बिस्तारै ढिलो हुन दिनुहोस्"]}}},
{"id":9021,"chapter":9,"q":"It starts to rain after a long dry spell. Why might the road be slippery?","options":["Oil and dust on the surface mix with the water","It won’t be slippery","The rain is colder","Tyres get softer"],"answer":0,"exp":{"hi":"सूखे में जमा oil और धूल पानी के साथ मिलकर सड़क को बहुत फिसलन वाला बना देते हैं।","pa":"ਸੋਕੇ ਵਿੱਚ ਜਮ੍ਹਾ oil ਅਤੇ ਧੂੜ ਪਾਣੀ ਨਾਲ ਮਿਲ ਕੇ ਸੜਕ ਨੂੰ ਬਹੁਤ ਤਿਲਕਣ ਵਾਲਾ ਬਣਾ ਦਿੰਦੇ ਹਨ।","ur":"خشک موسم میں جمع oil اور دھول پانی سے مل کر سڑک کو بہت پھسلن والا بنا دیتے ہیں۔","bn":"(not translated yet)","te":"ఎండలో పేరుకున్న oil, దుమ్ము నీటితో కలిసి రోడ్డును చాలా జారుడుగా చేస్తాయి.","mr":"कोरड्या काळात साचलेले oil आणि धूळ पाण्यात मिसळून रस्ता खूप निसरडा करतात.","ml":"ഉണങ്ങിയ കാലത്ത് അടിഞ്ഞ എണ്ണയും പൊടിയും വെള്ളവുമായി കലർന്ന് റോഡിനെ വളരെ വഴുക്കലുള്ളതാക്കും.","ta":"வறட்சியில் சேர்ந்த எண்ணெயும் தூசியும் நீருடன் கலந்து சாலையை மிகவும் வழுக்கச் செய்யும்.","gu":"લાંબા સૂકા સમય પછી પહેલો વરસાદ તેલ અને ધૂળને પાણી સાથે ભેળવે અને રોડ ખૂબ લપસણો બને.","ne":"लामो सुक्खा समयपछिको पहिलो वर्षाले तेल र धुलोलाई पानीसँग मिसाउँछ र सडक धेरै चिप्लो हुन्छ।"},"tr":{"hi":{"q":"लंबे सूखे दौर के बाद बारिश शुरू होती है। सड़क फिसलन भरी क्यों हो सकती है?","o":["सतह पर तेल और धूल पानी के साथ मिल जाते हैं","वह फिसलन भरी नहीं होगी","बारिश ज़्यादा ठंडी होती है","टायर ज़्यादा नरम हो जाते हैं"]},"pa":{"q":"ਲੰਮੇ ਸੋਕੇ ਤੋਂ ਬਾਅਦ ਮੀਂਹ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ। ਸੜਕ ਤਿਲਕਣ ਵਾਲੀ ਕਿਉਂ ਹੋ ਸਕਦੀ ਹੈ?","o":["ਸਤ੍ਹਾ 'ਤੇ ਤੇਲ ਅਤੇ ਧੂੜ ਪਾਣੀ ਨਾਲ ਮਿਲ ਜਾਂਦੇ ਹਨ","ਉਹ ਤਿਲਕਣ ਵਾਲੀ ਨਹੀਂ ਹੋਵੇਗੀ","ਮੀਂਹ ਵੱਧ ਠੰਢਾ ਹੁੰਦਾ ਹੈ","ਟਾਇਰ ਵੱਧ ਨਰਮ ਹੋ ਜਾਂਦੇ ਹਨ"]},"ur":{"q":"طویل خشک موسم کے بعد بارش شروع ہو جاتی ہے۔ سڑک پھسلواں کیوں ہو سکتی ہے؟","o":["سطح پر موجود تیل اور دھول پانی کے ساتھ مل جاتے ہیں","یہ پھسلواں نہیں ہوگی","بارش زیادہ ٹھنڈی ہوتی ہے","ٹائر نرم ہو جاتے ہیں"]},"bn":{"q":"দীর্ঘ শুকনো সময়ের পর বৃষ্টি শুরু হল। রাস্তা পিচ্ছিল হতে পারে কেন?","o":["পৃষ্ঠের তেল ও ধুলা পানির সঙ্গে মিশে যায়","এটি পিচ্ছিল হবে না","বৃষ্টি বেশি ঠান্ডা","টায়ার নরম হয়"]},"te":{"q":"చాలా కాలం పొడి వాతావరణం తర్వాత వర్షం మొదలైంది. రోడ్డు ఎందుకు జారుడుగా ఉండవచ్చు?","o":["ఉపరితలంపై ఉన్న నూనె, దుమ్ము నీటితో కలుస్తాయి","అది జారుడుగా ఉండదు","వర్షం ఎక్కువ చల్లగా ఉంటుంది","టైర్లు మెత్తబడతాయి"]},"mr":{"q":"बऱ्याच काळाच्या कोरड्या हवामानानंतर पाऊस सुरू होतो. रस्ता निसरडा का असू शकतो?","o":["पृष्ठभागावरील तेल आणि धूळ पाण्यात मिसळते","तो निसरडा होणार नाही","पाऊस जास्त थंड असतो","टायर मऊ होतात"]},"ml":{"q":"ദീർഘകാലം ഉണങ്ങിയ ശേഷം മഴ തുടങ്ങുന്നു. റോഡ് വഴുക്കലുള്ളതാകുന്നത് എന്തുകൊണ്ട്?","o":["പ്രതലത്തിലെ എണ്ണയും പൊടിയും വെള്ളവുമായി കലരുന്നു","വഴുക്കലുണ്ടാകില്ല","മഴ കൂടുതൽ തണുത്തതാണ്","tyres മൃദുവാകുന്നു"]},"ta":{"q":"நீண்ட வறட்சிக்குப் பிறகு மழை தொடங்குகிறது. சாலை ஏன் வழுக்கலாக இருக்கலாம்?","o":["மேற்பரப்பில் உள்ள எண்ணெயும் தூசியும் நீருடன் கலக்கும்","வழுக்காது","மழை அதிக குளிர்ச்சியாக இருக்கும்","டயர்கள் மென்மையாகும்"]},"gu":{"q":"લાંબા સૂકા સમય પછી વરસાદ શરૂ થાય છે. રોડ લપસણો કેમ હોઈ શકે?","o":["સપાટી પરનું તેલ અને ધૂળ પાણી સાથે ભળે છે","તે લપસણો નહીં હોય","વરસાદ વધુ ઠંડો છે","tyres નરમ થાય છે"]},"ne":{"q":"लामो सुक्खा समयपछि वर्षा सुरु हुन्छ। सडक किन चिप्लो हुन सक्छ?","o":["सतहको तेल र धुलो पानीसँग मिसिन्छ","चिप्लो हुँदैन","वर्षा बढी चिसो हुन्छ","tyres नरम हुन्छन्"]}}},
{"id":9022,"chapter":9,"q":"Your windows are misting up while you drive. What should you do?","options":["Drive faster","Use the demister and air conditioning until they’re clear","Wipe them with your hand while driving","Ignore it"],"answer":1,"exp":{"hi":"Demister और AC से काँच साफ़ करो। साफ़ न दिखे तो सुरक्षित जगह रुककर साफ़ करो।","pa":"Demister ਅਤੇ AC ਨਾਲ ਸ਼ੀਸ਼ੇ ਸਾਫ਼ ਕਰੋ। ਸਾਫ਼ ਨਾ ਦਿਸੇ ਤਾਂ ਸੁਰੱਖਿਅਤ ਥਾਂ ਰੁਕ ਕੇ ਸਾਫ਼ ਕਰੋ।","ur":"Demister اور AC سے شیشے صاف کریں۔ صاف نظر نہ آئے تو محفوظ جگہ رک کر صاف کریں۔","bn":"(not translated yet)","te":"Demister, AC తో అద్దాలు శుభ్రం చేయండి. స్పష్టంగా కనిపించకపోతే సురక్షితంగా ఆగి శుభ్రం చేయండి.","mr":"Demister आणि AC ने काच साफ करा. स्पष्ट दिसत नसेल तर सुरक्षित जागी थांबून साफ करा.","ml":"Demister-ഉം AC-യും ഉപയോഗിച്ച് ചില്ല് വൃത്തിയാക്കുക. വ്യക്തമായി കാണുന്നില്ലെങ്കിൽ സുരക്ഷിതമായി നിർത്തി തുടയ്ക്കുക.","ta":"Demister மற்றும் AC மூலம் கண்ணாடியை தெளிவாக்குங்கள். தெரியவில்லை என்றால் பாதுகாப்பாக நின்று சுத்தம் செய்யுங்கள்.","gu":"બારીઓ ધુમ્મસ વાળી થાય તો demister અને A/C વાપરો જ્યાં સુધી સાફ ન થાય. હાથથી લૂછશો નહીં.","ne":"झ्यालमा बाफ लागे सफा नभएसम्म demister र A/C प्रयोग गर्नुहोस्। हातले नपुछ्नुहोस्।"},"tr":{"hi":{"q":"गाड़ी चलाते समय आपकी खिड़कियों पर भाप जम रही है। आपको क्या करना चाहिए?","o":["तेज़ चलाओ","जब तक साफ़ न हो जाएँ, demister और air conditioning इस्तेमाल करो","चलते-चलते हाथ से पोंछो","अनदेखा करो"]},"pa":{"q":"ਗੱਡੀ ਚਲਾਉਂਦੇ ਸਮੇਂ ਤੁਹਾਡੀਆਂ ਖਿੜਕੀਆਂ 'ਤੇ ਭਾਫ਼ ਜੰਮ ਰਹੀ ਹੈ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਤੇਜ਼ ਚਲਾਓ","ਜਦ ਤੱਕ ਸਾਫ਼ ਨਾ ਹੋ ਜਾਣ, demister ਅਤੇ air conditioning ਵਰਤੋ","ਚੱਲਦੇ-ਚੱਲਦੇ ਹੱਥ ਨਾਲ ਪੂੰਝੋ","ਅਣਡਿੱਠਾ ਕਰੋ"]},"ur":{"q":"گاڑی چلاتے ہوئے آپ کی کھڑکیاں دھندلا رہی ہیں۔ آپ کو کیا کرنا چاہیے؟","o":["تیز چلائیں","ڈی مسٹر اور ایئر کنڈیشننگ اس وقت تک استعمال کریں جب تک وہ صاف نہ ہو جائیں","چلاتے ہوئے ہاتھ سے صاف کریں","نظر انداز کریں"]},"bn":{"q":"চালানোর সময় আপনার জানালা ঝাপসা হয়ে যাচ্ছে। আপনার কী করা উচিত?","o":["জোরে চালান","পরিষ্কার না হওয়া পর্যন্ত ডিমিস্টার ও এয়ার কন্ডিশনিং ব্যবহার করুন","চালাতে চালাতে হাত দিয়ে মুছুন","উপেক্ষা করুন"]},"te":{"q":"నడుపుతుండగా మీ కిటికీలు ఆవిరి పట్టుతున్నాయి. మీరు ఏమి చేయాలి?","o":["వేగంగా నడపండి","స్పష్టమయ్యే వరకు డెమిస్టర్, ఎయిర్ కండిషనింగ్ వాడండి","నడుపుతూ చేత్తో తుడవండి","పట్టించుకోకండి"]},"mr":{"q":"गाडी चालवताना तुमच्या खिडक्यांवर धुके (mist) जमत आहे. तुम्ही काय करावे?","o":["वेगाने चालवा","स्वच्छ होईपर्यंत demister आणि एअर कंडिशनिंग वापरा","चालवताना हाताने पुसा","दुर्लक्ष करा"]},"ml":{"q":"ഓടിക്കുമ്പോൾ ജനലുകളിൽ പൊടിമഞ്ഞ് (mist) പിടിക്കുന്നു. എന്ത് ചെയ്യണം?","o":["വേഗത്തിൽ ഓടിക്കുക","വ്യക്തമാകുന്നതുവരെ demister-ഉം air conditioning-ഉം ഉപയോഗിക്കുക","ഓടിക്കുമ്പോൾ കൈ കൊണ്ട് തുടയ്ക്കുക","അവഗണിക്കുക"]},"ta":{"q":"ஓட்டும்போது உங்கள் ஜன்னல்கள் மூடுபனியாகின்றன. என்ன செய்ய வேண்டும்?","o":["வேகமாக ஓட்டுங்கள்","தெளிவாகும் வரை demister மற்றும் air conditioning பயன்படுத்துங்கள்","ஓட்டும்போது கையால் துடையுங்கள்","புறக்கணியுங்கள்"]},"gu":{"q":"ચલાવતાં તમારી બારીઓ ધુમ્મસ વાળી થઈ રહી છે. શું કરવું?","o":["ઝડપથી ચલાવો","સાફ ન થાય ત્યાં સુધી demister અને air conditioning વાપરો","ચલાવતાં હાથથી લૂછો","અવગણો"]},"ne":{"q":"गाडी चलाउँदा तपाईंका झ्यालमा बाफ लाग्दैछ। के गर्नुपर्छ?","o":["छिटो चलाउनुहोस्","सफा नहुन्जेल demister र air conditioning प्रयोग गर्नुहोस्","चलाउँदै हातले पुछ्नुहोस्","बेवास्ता गर्नुहोस्"]}}},
{"id":9023,"chapter":9,"q":"When moving off uphill, how can you stop the car rolling back?","options":["Use neutral","Rev the engine hard","Hold it on the parking brake until you have enough power","Press the clutch fully down"],"answer":2,"exp":{"hi":"Parking brake से गाड़ी पकड़े रखो, फिर accelerator और clutch से power आने पर धीरे-धीरे छोड़ो।","pa":"Parking brake ਨਾਲ ਗੱਡੀ ਫੜੀ ਰੱਖੋ, ਫਿਰ accelerator ਅਤੇ clutch ਨਾਲ power ਆਉਣ ’ਤੇ ਹੌਲੀ-ਹੌਲੀ ਛੱਡੋ।","ur":"Parking brake سے گاڑی پکڑے رکھیں، پھر accelerator اور clutch سے power آنے پر آہستہ آہستہ چھوڑیں۔","bn":"(not translated yet)","te":"Parking brake తో వాహనాన్ని పట్టి ఉంచండి, accelerator, clutch తో power వచ్చాక నెమ్మదిగా వదలండి.","mr":"Parking brake ने गाडी धरून ठेवा, मग accelerator आणि clutch ने power आली की हळूहळू सोडा.","ml":"Parking brake കൊണ്ട് കാർ പിടിച്ചുനിർത്തുക, accelerator-ഉം clutch-ഉം കൊണ്ട് power വരുമ്പോൾ പതുക്കെ വിടുക.","ta":"Parking brake-ல் காரை பிடித்து வைத்து, accelerator மற்றும் clutch மூலம் சக்தி வந்தவுடன் மெதுவாக விடுங்கள்.","gu":"ચઢાણ પર શરૂ કરતાં parking brake પર કાર રાખી પૂરતી શક્તિ મળે ત્યારે છોડો જેથી પાછળ ન સરકે.","ne":"उकालोमा सुरु गर्दा कारलाई parking brake मा राखेर पर्याप्त शक्ति आएपछि छोड्नुहोस् ताकि पछाडि नसरोस्।"},"tr":{"hi":{"q":"चढ़ाई पर चलना शुरू करते समय आप कार को पीछे लुढ़कने से कैसे रोक सकते हैं?","o":["neutral इस्तेमाल करो","इंजन को ज़ोर से rev करो","पर्याप्त शक्ति आने तक उसे parking brake पर रोके रखो","clutch पूरा दबा दो"]},"pa":{"q":"ਚੜ੍ਹਾਈ 'ਤੇ ਤੁਰਨਾ ਸ਼ੁਰੂ ਕਰਦੇ ਸਮੇਂ ਤੁਸੀਂ ਕਾਰ ਨੂੰ ਪਿੱਛੇ ਰੁੜ੍ਹਨ ਤੋਂ ਕਿਵੇਂ ਰੋਕ ਸਕਦੇ ਹੋ?","o":["neutral ਵਰਤੋ","ਇੰਜਣ ਨੂੰ ਜ਼ੋਰ ਨਾਲ rev ਕਰੋ","ਲੋੜੀਂਦੀ ਸ਼ਕਤੀ ਆਉਣ ਤੱਕ ਉਸ ਨੂੰ parking brake 'ਤੇ ਰੋਕੀ ਰੱਖੋ","clutch ਪੂਰਾ ਦਬਾ ਦਿਓ"]},"ur":{"q":"چڑھائی پر چلتے وقت آپ گاڑی کو پیچھے لڑھکنے سے کیسے روک سکتے ہیں؟","o":["نیوٹرل استعمال کریں","انجن کو زور سے ریس دیں","جب تک کافی طاقت نہ ہو اسے پارکنگ بریک پر روکے رکھیں","کلچ کو پورا دبا دیں"]},"bn":{"q":"চড়াইয়ে রওনা দেওয়ার সময় আপনি গাড়িকে পিছনে গড়িয়ে যাওয়া থেকে কীভাবে ঠেকাবেন?","o":["নিউট্রাল ব্যবহার করুন","ইঞ্জিনে জোরে রেস দিন","যথেষ্ট শক্তি না পাওয়া পর্যন্ত এটি পার্কিং ব্রেকে ধরে রাখুন","ক্লাচ পুরোপুরি চেপে ধরুন"]},"te":{"q":"ఎత్తు వైపు బయలుదేరేటప్పుడు కారు వెనక్కి జారకుండా ఎలా ఆపవచ్చు?","o":["న్యూట్రల్ వాడండి","ఇంజిన్‌ను గట్టిగా రేవ్ చేయండి","తగినంత శక్తి వచ్చే వరకు పార్కింగ్ బ్రేక్‌పై పట్టి ఉంచండి","క్లచ్ పూర్తిగా నొక్కండి"]},"mr":{"q":"चढावर गाडी सुरू करताना ती मागे गडगडू नये म्हणून काय करावे?","o":["neutral वापरा","इंजिन जोरात रेव्ह करा","पुरेशी शक्ती येईपर्यंत गाडी parking brake वर धरून ठेवा","क्लच पूर्ण दाबा"]},"ml":{"q":"കയറ്റത്തിൽ വാഹനം എടുക്കുമ്പോൾ പിന്നോട്ട് ഉരുളാതിരിക്കാൻ എന്ത് ചെയ്യാം?","o":["neutral ഉപയോഗിക്കുക","എൻജിൻ ശക്തമായി rev ചെയ്യുക","മതിയായ power കിട്ടുന്നതുവരെ parking brake-ൽ പിടിച്ചുനിർത്തുക","clutch പൂർണ്ണമായി അമർത്തുക"]},"ta":{"q":"மேல்நோக்கி புறப்படும்போது கார் பின்னோக்கி உருளாமல் தடுக்க எப்படி?","o":["neutral பயன்படுத்துங்கள்","engine-ஐ கடுமையாக rev செய்யுங்கள்","போதிய சக்தி வரும் வரை parking brake-இல் பிடித்து வையுங்கள்","clutch-ஐ முழுவதும் அழுத்துங்கள்"]},"gu":{"q":"ચઢાણ પર શરૂ કરતાં કાર પાછળ સરકતી કેવી રીતે રોકશો?","o":["neutral વાપરો","એંજિન જોરથી rev કરો","પૂરતી શક્તિ ન મળે ત્યાં સુધી parking brake પર રાખો","clutch પૂરેપૂરી દબાવો"]},"ne":{"q":"उकालोमा सुरु गर्दा कार पछाडि सर्नबाट कसरी रोक्ने?","o":["neutral प्रयोग गर्नुहोस्","इन्जिन जोडले rev गर्नुहोस्","पर्याप्त शक्ति नआएसम्म parking brake मा राख्नुहोस्","clutch पूरै थिच्नुहोस्"]}}},
{"id":9024,"chapter":9,"q":"You’re parking facing downhill next to a kerb. Which way should you turn your front wheels?","options":["Away from the kerb","Straight ahead","It doesn’t matter","Towards the kerb"],"answer":3,"exp":{"hi":"Kerb की ओर घुमाने से गाड़ी लुढ़के तो wheel kerb से अटक जाएगा। Parking brake भी लगाओ।","pa":"Kerb ਵੱਲ ਘੁਮਾਉਣ ਨਾਲ ਗੱਡੀ ਰੁੜ੍ਹੇ ਤਾਂ wheel kerb ਨਾਲ ਅਟਕ ਜਾਵੇਗਾ। Parking brake ਵੀ ਲਾਓ।","ur":"Kerb کی طرف گھمانے سے گاڑی لڑھکے تو wheel kerb سے اٹک جائے گا۔ Parking brake بھی لگائیں۔","bn":"(not translated yet)","te":"Kerb వైపుకు తిప్పితే వాహనం దొర్లినప్పుడు wheel kerb కు తగిలి ఆగుతుంది. Parking brake కూడా వేయండి.","mr":"Kerb च्या दिशेने वळवल्यास गाडी गडगडली तर wheel kerb ला अडेल. Parking brake सुद्धा लावा.","ml":"Kerb-ന് നേരെ തിരിച്ചാൽ കാർ ഉരുണ്ടാൽ wheel kerb-ൽ തടയും. Parking brake-ഉം ഇടുക.","ta":"Kerb நோக்கி திருப்பினால் கார் உருண்டால் சக்கரம் kerb-இல் சிக்கும். Parking brake-ஐயும் போடுங்கள்.","gu":"ઢાળ તરફ મોઢું અને kerb બાજુએ હોય તો આગળના પૈડાં kerb તરફ વાળો, અને handbrake લગાવો.","ne":"ओरालो तर्फ मुख र kerb छेउमा भए अगाडिका पाङ्ग्रा kerb तिर घुमाउनुहोस्, र handbrake लगाउनुहोस्।"},"tr":{"hi":{"q":"आप kerb के पास नीचे की ओर मुँह करके park कर रहे हैं। आपको अगले पहिये किस तरफ़ घुमाने चाहिए?","o":["kerb से दूर","सीधे","कोई फ़र्क़ नहीं पड़ता","kerb की ओर"]},"pa":{"q":"ਤੁਸੀਂ kerb ਕੋਲ ਹੇਠਾਂ ਵੱਲ ਮੂੰਹ ਕਰਕੇ park ਕਰ ਰਹੇ ਹੋ। ਤੁਹਾਨੂੰ ਅਗਲੇ ਪਹੀਏ ਕਿਸ ਪਾਸੇ ਘੁਮਾਉਣੇ ਚਾਹੀਦੇ ਹਨ?","o":["kerb ਤੋਂ ਦੂਰ","ਸਿੱਧੇ","ਕੋਈ ਫ਼ਰਕ ਨਹੀਂ ਪੈਂਦਾ","kerb ਵੱਲ"]},"ur":{"q":"آپ کنارے کے پاس ڈھلان کی طرف منہ کر کے پارک کر رہے ہیں۔ آپ کو اگلے پہیے کس طرف موڑنے چاہئیں؟","o":["کنارے سے دور","سیدھے آگے","کوئی فرق نہیں پڑتا","کنارے کی طرف"]},"bn":{"q":"আপনি কার্বের পাশে ঢালের দিকে মুখ করে পার্ক করছেন। সামনের চাকা কোন দিকে ঘোরাবেন?","o":["কার্ব থেকে দূরে","সোজা সামনে","কোনো পার্থক্য নেই","কার্বের দিকে"]},"te":{"q":"మీరు కర్బ్ పక్కన కిందికి ముఖం పెట్టి పార్క్ చేస్తున్నారు. మీ ముందు చక్రాలను ఏ వైపు తిప్పాలి?","o":["కర్బ్ నుంచి దూరంగా","నేరుగా ముందుకు","తేడా లేదు","కర్బ్ వైపు"]},"mr":{"q":"तुम्ही कर्बजवळ उताराकडे तोंड करून पार्क करत आहात. पुढची चाके कोणत्या दिशेने वळवावीत?","o":["कर्बपासून दूर","सरळ पुढे","काही फरक पडत नाही","कर्बच्या दिशेने"]},"ml":{"q":"kerb-ന് അടുത്ത് ഇറക്കത്തിന് അഭിമുഖമായി park ചെയ്യുകയാണ്. മുൻ wheels ഏത് ദിശയിലേക്ക് തിരിക്കണം?","o":["kerb-ൽനിന്ന് അകലേക്ക്","നേരെ മുന്നോട്ട്","പ്രശ്നമില്ല","kerb-ന് നേരെ"]},"ta":{"q":"kerb அருகே கீழ்நோக்கி எதிர்கொண்டு park செய்கிறீர்கள். முன் சக்கரங்களை எந்த திசையில் திருப்ப வேண்டும்?","o":["kerb-இலிருந்து விலகி","நேராக","பரவாயில்லை","kerb நோக்கி"]},"gu":{"q":"તમે kerb પાસે ઢાળ તરફ મોઢું રાખી park કરો છો. આગળના પૈડાં કઈ તરફ વાળવા?","o":["kerb થી દૂર","સીધા આગળ","કોઈ ફરક નથી","kerb તરફ"]},"ne":{"q":"तपाईं kerb नजिक ओरालो तर्फ मुख फर्काएर park गर्दै हुनुहुन्छ। अगाडिका पाङ्ग्रा कता घुमाउने?","o":["kerb बाट टाढा","सिधा अगाडि","फरक पर्दैन","kerb तिर"]}}},
{"id":9025,"chapter":9,"q":"When should you use main beam headlights?","options":["On unlit roads when no one is ahead or coming towards you","In towns at night","In fog","When following another car"],"answer":0,"exp":{"hi":"Main beam तभी जब सामने या आगे कोई न हो, वरना दूसरे चौंधिया जाएँगे।","pa":"Main beam ਤਦੇ ਜਦੋਂ ਸਾਹਮਣੇ ਜਾਂ ਅੱਗੇ ਕੋਈ ਨਾ ਹੋਵੇ, ਨਹੀਂ ਤਾਂ ਦੂਜੇ ਚੁੰਧਿਆ ਜਾਣਗੇ।","ur":"Main beam تبھی جب سامنے یا آگے کوئی نہ ہو، ورنہ دوسرے چندھیا جائیں گے۔","bn":"(not translated yet)","te":"ఎదురుగా లేదా ముందు ఎవరూ లేనప్పుడే main beam, లేకపోతే ఇతరుల కళ్ళు చెదురుతాయి.","mr":"Main beam तेव्हाच जेव्हा पुढे किंवा समोर कोणी नसेल, नाहीतर इतरांचे डोळे दिपतील.","ml":"മുന്നിലോ എതിരെയോ ആരുമില്ലെങ്കിൽ മാത്രം main beam, അല്ലെങ്കിൽ മറ്റുള്ളവരുടെ കണ്ണ് മഞ്ഞളിക്കും.","ta":"முன்னால் அல்லது எதிரே யாரும் இல்லாதபோது மட்டும் main beam, இல்லையெனில் மற்றவர்களுக்கு கண் கூசும்.","gu":"Main beam ફક્ત લાઈટ વગરના રોડ પર જ્યારે આગળ કે સામે કોઈ વાહન ન હોય ત્યારે વાપરો.","ne":"Main beam केवल उज्यालो नभएको सडकमा अगाडि वा सामुन्ने कुनै सवारी नहुँदा प्रयोग गर्नुहोस्।"},"tr":{"hi":{"q":"आपको main beam headlights कब इस्तेमाल करनी चाहिए?","o":["बिना रोशनी वाली सड़कों पर, जब आगे या सामने कोई न हो","रात में शहरों में","कोहरे में","जब किसी दूसरी कार के पीछे चल रहे हों"]},"pa":{"q":"ਤੁਹਾਨੂੰ main beam headlights ਕਦੋਂ ਵਰਤਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?","o":["ਬਿਨਾਂ ਰੋਸ਼ਨੀ ਵਾਲੀਆਂ ਸੜਕਾਂ 'ਤੇ, ਜਦੋਂ ਅੱਗੇ ਜਾਂ ਸਾਹਮਣੇ ਕੋਈ ਨਾ ਹੋਵੇ","ਰਾਤ ਨੂੰ ਸ਼ਹਿਰਾਂ ਵਿੱਚ","ਧੁੰਦ ਵਿੱਚ","ਜਦੋਂ ਕਿਸੇ ਦੂਜੀ ਕਾਰ ਦੇ ਪਿੱਛੇ ਚੱਲ ਰਹੇ ਹੋਵੋ"]},"ur":{"q":"آپ کو مین بیم ہیڈ لائٹس کب استعمال کرنی چاہئیں؟","o":["بغیر روشنی والی سڑکوں پر جب آگے یا سامنے سے کوئی نہ آ رہا ہو","رات کو قصبوں میں","دھند میں","جب کسی دوسری کار کے پیچھے چل رہے ہوں"]},"bn":{"q":"আপনি কখন মেইন বিম হেডলাইট ব্যবহার করবেন?","o":["আলোহীন রাস্তায় যখন সামনে বা বিপরীত দিক থেকে কেউ আসছে না","রাতে শহরে","কুয়াশায়","যখন অন্য গাড়িকে অনুসরণ করছেন"]},"te":{"q":"మెయిన్ బీమ్ హెడ్‌లైట్లను మీరు ఎప్పుడు వాడాలి?","o":["వెలుతురు లేని రోడ్లపై, ఎవరూ ముందు లేదా ఎదురుగా లేనప్పుడు","రాత్రి పట్టణాల్లో","పొగమంచులో","మరో కారు వెనుక వెళ్తున్నప్పుడు"]},"mr":{"q":"तुम्ही main beam हेडलाइट केव्हा वापरावेत?","o":["पुढे किंवा समोरून कोणी नसताना दिवे नसलेल्या रस्त्यांवर","रात्री शहरांत","धुक्यात","दुसऱ्या कारच्या मागे चालताना"]},"ml":{"q":"main beam headlights എപ്പോഴാണ് ഉപയോഗിക്കേണ്ടത്?","o":["മുന്നിലോ എതിരെയോ ആരുമില്ലാത്ത, വെളിച്ചമില്ലാത്ത റോഡുകളിൽ","രാത്രി പട്ടണങ്ങളിൽ","fog-ൽ","മറ്റൊരു കാറിനെ പിന്തുടരുമ്പോൾ"]},"ta":{"q":"main beam headlights-ஐ எப்போது பயன்படுத்த வேண்டும்?","o":["முன்னால் அல்லது எதிரே யாரும் இல்லாத, விளக்கு இல்லாத சாலைகளில்","இரவில் நகரங்களில்","மூடுபனியில்","மற்றொரு காரை பின்தொடரும்போது"]},"gu":{"q":"main beam headlights ક્યારે વાપરવી?","o":["લાઈટ વગરના રોડ પર, જ્યારે આગળ કે સામે કોઈ ન હોય","રાત્રે શહેરોમાં","ધુમ્મસમાં","બીજી કારની પાછળ ચાલતાં"]},"ne":{"q":"main beam headlights कहिले प्रयोग गर्ने?","o":["उज्यालो नभएको सडकमा, अगाडि वा सामुन्ने कोही नहुँदा","राति सहरमा","कुहिरोमा","अर्को कारको पछाडि चल्दा"]}}},
{"id":9026,"chapter":9,"q":"Headlights from a vehicle behind are dazzling you in your mirror. What can help?","options":["Speed up","Use the anti-dazzle setting on your interior mirror","Brake suddenly","Switch on your rear fog light"],"answer":1,"exp":{"hi":"अंदर वाले mirror की anti-dazzle setting से चमक कम हो जाती है।","pa":"ਅੰਦਰਲੇ mirror ਦੀ anti-dazzle setting ਨਾਲ ਚਮਕ ਘਟ ਜਾਂਦੀ ਹੈ।","ur":"اندر والے mirror کی anti-dazzle setting سے چمک کم ہو جاتی ہے۔","bn":"(not translated yet)","te":"లోపలి mirror anti-dazzle setting తో మెరుపు తగ్గుతుంది.","mr":"आतील mirror ची anti-dazzle setting चकाकी कमी करते.","ml":"ഉൾവശത്തെ mirror-ലെ anti-dazzle setting വെളിച്ചം കുറയ്ക്കും.","ta":"உள் mirror-இன் anti-dazzle அமைப்பு கூசலை குறைக்கும்.","gu":"પાછળની લાઈટ અંજાવે તો interior mirror ની anti-dazzle સેટિંગ વાપરો.","ne":"पछाडिको बत्तीले चिलाए interior mirror को anti-dazzle सेटिङ प्रयोग गर्नुहोस्।"},"tr":{"hi":{"q":"पीछे वाले वाहन की headlights आपके mirror में आपकी आँखें चौंधिया रही हैं। क्या मदद कर सकता है?","o":["speed बढ़ाओ","अपने अंदर वाले mirror की anti-dazzle सेटिंग इस्तेमाल करो","अचानक brake लगाओ","अपनी rear fog light चालू करो"]},"pa":{"q":"ਪਿੱਛੇ ਵਾਲੇ ਵਾਹਨ ਦੀਆਂ headlights ਤੁਹਾਡੇ mirror ਵਿੱਚ ਤੁਹਾਡੀਆਂ ਅੱਖਾਂ ਚੌਂਧਿਆ ਰਹੀਆਂ ਹਨ। ਕੀ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ?","o":["speed ਵਧਾਓ","ਆਪਣੇ ਅੰਦਰਲੇ mirror ਦੀ anti-dazzle ਸੈਟਿੰਗ ਵਰਤੋ","ਅਚਾਨਕ brake ਲਾਓ","ਆਪਣੀ rear fog light ਚਾਲੂ ਕਰੋ"]},"ur":{"q":"پیچھے والی گاڑی کی ہیڈ لائٹس آپ کے آئینے میں آپ کی آنکھیں چندھیا رہی ہیں۔ کیا مدد کر سکتا ہے؟","o":["رفتار بڑھائیں","اندرونی آئینے کی اینٹی ڈیزل (anti-dazzle) سیٹنگ استعمال کریں","اچانک بریک لگائیں","اپنی پچھلی فوگ لائٹ آن کریں"]},"bn":{"q":"পেছনের যানের হেডলাইট আপনার আয়নায় আপনার চোখ ধাঁধাচ্ছে। কী সাহায্য করতে পারে?","o":["গতি বাড়ান","ভেতরের আয়নার অ্যান্টি-ডাযল সেটিং ব্যবহার করুন","হঠাৎ ব্রেক করুন","পেছনের ফগ লাইট জ্বালান"]},"te":{"q":"వెనుక వాహనం హెడ్‌లైట్లు మీ మిర్రర్‌లో మీ కళ్లను చెదరగొడుతున్నాయి. ఏది సహాయపడుతుంది?","o":["వేగం పెంచండి","మీ ఇంటీరియర్ మిర్రర్‌లోని యాంటీ-డాజిల్ సెట్టింగ్ వాడండి","అకస్మాత్తుగా బ్రేక్ వేయండి","మీ వెనుక ఫాగ్ లైట్ ఆన్ చేయండి"]},"mr":{"q":"मागच्या वाहनाचे हेडलाइट तुमच्या mirror मध्ये तुमचे डोळे दिपवत आहेत. काय मदत करू शकते?","o":["वेग वाढवा","आतील mirror ची anti-dazzle सेटिंग वापरा","अचानक ब्रेक लावा","मागचा fog light चालू करा"]},"ml":{"q":"പിന്നിലെ വാഹനത്തിന്റെ headlights നിങ്ങളുടെ mirror-ൽ കണ്ണ് മഞ്ഞളിപ്പിക്കുന്നു. എന്ത് സഹായിക്കും?","o":["വേഗത കൂട്ടുക","ഉൾവശത്തെ mirror-ലെ anti-dazzle setting ഉപയോഗിക്കുക","പെട്ടെന്ന് brake ചെയ്യുക","rear fog light ഓൺ ചെയ്യുക"]},"ta":{"q":"பின்னால் வரும் வாகனத்தின் headlights உங்கள் mirror-இல் கண்ணைக் கூசுகிறது. எது உதவும்?","o":["வேகத்தை கூட்டுங்கள்","உள் mirror-இல் உள்ள anti-dazzle அமைப்பை பயன்படுத்துங்கள்","திடீரென brake போடுங்கள்","பின் fog light-ஐ போடுங்கள்"]},"gu":{"q":"પાછળના વાહનની headlights તમારા mirror માં તમને અંજાવે છે. શું મદદ કરી શકે?","o":["ઝડપ વધારો","interior mirror ની anti-dazzle સેટિંગ વાપરો","અચાનક brake મારો","rear fog light ચાલુ કરો"]},"ne":{"q":"पछाडिको सवारीको headlights ले तपाईंको mirror मा तपाईंलाई चिलाउँछ। के मद्दत गर्न सक्छ?","o":["गति बढाउनुहोस्","interior mirror को anti-dazzle सेटिङ प्रयोग गर्नुहोस्","अचानक brake लगाउनुहोस्","rear fog light खोल्नुहोस्"]}}},
{"id":9027,"chapter":9,"q":"What does traction control help prevent?","options":["Brake fade","Engine overheating","Wheelspin when accelerating","Skidding when parked"],"answer":2,"exp":{"hi":"Traction control accelerate करते वक़्त wheels को फिसलकर घूमने (wheelspin) से रोकता है।","pa":"Traction control accelerate ਕਰਦੇ ਵੇਲੇ wheels ਨੂੰ ਤਿਲਕ ਕੇ ਘੁੰਮਣ (wheelspin) ਤੋਂ ਰੋਕਦਾ ਹੈ।","ur":"Traction control accelerate کرتے وقت wheels کو پھسل کر گھومنے (wheelspin) سے روکتا ہے۔","bn":"(not translated yet)","te":"Accelerate చేసేటప్పుడు wheels జారి తిరగడాన్ని (wheelspin) traction control ఆపుతుంది.","mr":"Traction control accelerate करताना wheels ना घसरून फिरण्यापासून (wheelspin) रोखतो.","ml":"Traction control accelerate ചെയ്യുമ്പോൾ wheels തെന്നി കറങ്ങുന്നത് (wheelspin) തടയുന്നു.","ta":"Traction control வேகமெடுக்கும்போது சக்கரங்கள் வழுக்கிச் சுழல்வதை (wheelspin) தடுக்கும்.","gu":"Traction control accelerate કરતાં થતું wheelspin અટકાવે, ખાસ કરીને લપસણા રોડ પર.","ne":"Traction control ले accelerate गर्दा हुने wheelspin रोक्छ, विशेष गरी चिप्लो सडकमा।"},"tr":{"hi":{"q":"traction control किस चीज़ को रोकने में मदद करता है?","o":["brake fade","इंजन का ज़्यादा गर्म होना","accelerate करते समय पहियों का घूमते रहना (wheelspin)","park होने पर फिसलना"]},"pa":{"q":"traction control ਕਿਸ ਚੀਜ਼ ਨੂੰ ਰੋਕਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ?","o":["brake fade","ਇੰਜਣ ਦਾ ਵੱਧ ਗਰਮ ਹੋਣਾ","accelerate ਕਰਦੇ ਸਮੇਂ ਪਹੀਆਂ ਦਾ ਘੁੰਮਦੇ ਰਹਿਣਾ (wheelspin)","park ਹੋਣ 'ਤੇ ਤਿਲਕਣਾ"]},"ur":{"q":"ٹریکشن کنٹرول کس چیز کو روکنے میں مدد دیتا ہے؟","o":["بریک فیڈ","انجن کا زیادہ گرم ہونا","رفتار بڑھاتے وقت پہیوں کا گھومنا (وہیل اسپن)","پارک ہونے پر پھسلنا"]},"bn":{"q":"ট্র্যাকশন কন্ট্রোল কী প্রতিরোধ করতে সাহায্য করে?","o":["ব্রেক ফেড","ইঞ্জিন অতিরিক্ত গরম হওয়া","গতি বাড়ানোর সময় চাকার ঘোরা (হুইলস্পিন)","পার্ক করা অবস্থায় পিছলে যাওয়া"]},"te":{"q":"ట్రాక్షన్ కంట్రోల్ దేనిని నివారించడంలో సహాయపడుతుంది?","o":["బ్రేక్ ఫేడ్","ఇంజిన్ వేడెక్కడం","వేగం పెంచేటప్పుడు చక్రాలు తిరుగుతూ ఉండడం (వీల్‌స్పిన్)","పార్క్ చేసినప్పుడు జారడం"]},"mr":{"q":"traction control कशाला प्रतिबंध करण्यास मदत करते?","o":["brake fade","इंजिन जास्त तापणे","अ‍ॅक्सिलरेट करताना wheelspin","पार्क असताना घसरणे"]},"ml":{"q":"traction control എന്തിനെ തടയാൻ സഹായിക്കുന്നു?","o":["brake fade","എൻജിൻ അമിതമായി ചൂടാകുന്നത്","accelerate ചെയ്യുമ്പോൾ wheelspin","park ചെയ്തിരിക്കുമ്പോൾ skid ചെയ്യുന്നത്"]},"ta":{"q":"traction control எதைத் தடுக்க உதவுகிறது?","o":["brake fade","engine அதிக வெப்பமடைதல்","வேகமெடுக்கும்போது wheelspin","park செய்யும்போது skid"]},"gu":{"q":"traction control શું અટકાવવામાં મદદ કરે છે?","o":["brake fade","એંજિન વધુ ગરમ થવું","accelerate કરતાં wheelspin","park કરેલા હો ત્યારે skidding"]},"ne":{"q":"traction control ले के रोक्न मद्दत गर्छ?","o":["brake fade","इन्जिन बढी तात्नु","accelerate गर्दा wheelspin","park गरिएको बेला skidding"]}}},
{"id":9028,"chapter":9,"q":"When should you not try to drive through floodwater?","options":["When it’s shallow","When it’s raining","During the day","When it’s too deep or fast-flowing"],"answer":3,"exp":{"hi":"गहरा या तेज़ बहता पानी गाड़ी बहा सकता है या engine ख़राब कर सकता है। दूसरा रास्ता लो।","pa":"ਡੂੰਘਾ ਜਾਂ ਤੇਜ਼ ਵਹਿੰਦਾ ਪਾਣੀ ਗੱਡੀ ਰੋੜ੍ਹ ਸਕਦਾ ਹੈ ਜਾਂ engine ਖ਼ਰਾਬ ਕਰ ਸਕਦਾ ਹੈ। ਦੂਜਾ ਰਾਹ ਲਓ।","ur":"گہرا یا تیز بہتا پانی گاڑی بہا سکتا ہے یا engine خراب کر سکتا ہے۔ دوسرا راستہ لیں۔","bn":"(not translated yet)","te":"లోతైన లేదా వేగంగా ప్రవహించే నీరు వాహనాన్ని కొట్టుకుపోయేలా చేయవచ్చు లేదా engine ను పాడుచేయవచ్చు. వేరే దారి తీసుకోండి.","mr":"खोल किंवा वेगाने वाहणारे पाणी गाडी वाहून नेऊ शकते किंवा engine खराब करू शकते. दुसरा रस्ता घ्या.","ml":"ആഴമുള്ളതോ വേഗത്തിൽ ഒഴുകുന്നതോ ആയ വെള്ളം വാഹനത്തെ ഒഴുക്കിക്കൊണ്ടുപോകുകയോ എൻജിൻ കേടാക്കുകയോ ചെയ്യാം. മറ്റൊരു വഴി എടുക്കുക.","ta":"ஆழமான அல்லது வேகமாக ஓடும் நீர் காரை அடித்துச் செல்லலாம் அல்லது engine-ஐ பழுதாக்கலாம். வேறு வழியை எடுங்கள்.","gu":"પૂર ખૂબ ઊંડું કે ઝડપી વહેતું હોય તો પાર ન કરો. 10 સેમીથી વધુ ઊંડું જોખમી.","ne":"बाढी धेरै गहिरो वा तीव्र बगिरहेको छ भने पार नगर्नुहोस्। 10 सेमीभन्दा गहिरो खतरनाक।"},"tr":{"hi":{"q":"आपको बाढ़ के पानी में से गुज़रने की कोशिश कब नहीं करनी चाहिए?","o":["जब वह उथला हो","जब बारिश हो रही हो","दिन में","जब वह बहुत गहरा हो या तेज़ बह रहा हो"]},"pa":{"q":"ਤੁਹਾਨੂੰ ਹੜ੍ਹ ਦੇ ਪਾਣੀ ਵਿੱਚੋਂ ਲੰਘਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਦੋਂ ਨਹੀਂ ਕਰਨੀ ਚਾਹੀਦੀ?","o":["ਜਦੋਂ ਉਹ ਘੱਟ ਡੂੰਘਾ ਹੋਵੇ","ਜਦੋਂ ਮੀਂਹ ਪੈ ਰਿਹਾ ਹੋਵੇ","ਦਿਨ ਵਿੱਚ","ਜਦੋਂ ਉਹ ਬਹੁਤ ਡੂੰਘਾ ਹੋਵੇ ਜਾਂ ਤੇਜ਼ ਵਹਿ ਰਿਹਾ ਹੋਵੇ"]},"ur":{"q":"آپ کو سیلابی پانی سے گزرنے کی کوشش کب نہیں کرنی چاہیے؟","o":["جب وہ کم گہرا ہو","جب بارش ہو رہی ہو","دن کے وقت","جب وہ بہت گہرا ہو یا تیزی سے بہہ رہا ہو"]},"bn":{"q":"আপনি কখন বন্যার পানি দিয়ে যাওয়ার চেষ্টা করবেন না?","o":["যখন তা অগভীর","যখন বৃষ্টি হচ্ছে","দিনের বেলা","যখন তা খুব গভীর বা দ্রুত বইছে"]},"te":{"q":"వరద నీటి గుండా నడపడానికి మీరు ఎప్పుడు ప్రయత్నించకూడదు?","o":["అది లోతు తక్కువగా ఉన్నప్పుడు","వర్షం పడుతున్నప్పుడు","పగటిపూట","అది చాలా లోతుగా లేదా వేగంగా ప్రవహిస్తున్నప్పుడు"]},"mr":{"q":"पुराच्या पाण्यातून गाडी चालवण्याचा प्रयत्न तुम्ही केव्हा करू नये?","o":["ते उथळ असताना","पाऊस पडत असताना","दिवसा","ते खूप खोल किंवा वेगाने वाहणारे असताना"]},"ml":{"q":"വെള്ളപ്പൊക്കത്തിലൂടെ ഓടിക്കാൻ ശ്രമിക്കരുതാത്തത് എപ്പോൾ?","o":["ആഴം കുറവാണെങ്കിൽ","മഴ പെയ്യുമ്പോൾ","പകൽ","വളരെ ആഴമുള്ളതോ വേഗത്തിൽ ഒഴുകുന്നതോ ആണെങ്കിൽ"]},"ta":{"q":"வெள்ளநீரில் ஓட்ட முயற்சிக்கக்கூடாதது எப்போது?","o":["ஆழம் குறைவாக இருக்கும்போது","மழை பெய்யும்போது","பகலில்","மிக ஆழமாக அல்லது வேகமாக ஓடும்போது"]},"gu":{"q":"પૂરના પાણીમાંથી ચલાવવાનો પ્રયત્ન ક્યારે ન કરવો?","o":["જ્યારે તે છીછરું હોય","જ્યારે વરસાદ હોય","દિવસ દરમિયાન","જ્યારે તે ખૂબ ઊંડું કે ઝડપી વહેતું હોય"]},"ne":{"q":"बाढीको पानीबाट चलाउने प्रयास कहिले गर्नु हुँदैन?","o":["जब यो उथलो हुन्छ","जब वर्षा भइरहेको हुन्छ","दिनको समयमा","जब यो धेरै गहिरो वा तीव्र बगिरहेको हुन्छ"]}}},
{"id":9029,"chapter":9,"q":"Why is overtaking downhill risky?","options":["Your speed builds quickly and stopping takes longer","Your engine loses power","Your brakes work better","Other cars go slower"],"answer":0,"exp":{"hi":"ढलान पर speed तेज़ी से बढ़ती है और रुकने में ज़्यादा दूरी लगती है।","pa":"ਢਲਾਨ ’ਤੇ speed ਤੇਜ਼ੀ ਨਾਲ ਵਧਦੀ ਹੈ ਅਤੇ ਰੁਕਣ ਵਿੱਚ ਵੱਧ ਦੂਰੀ ਲੱਗਦੀ ਹੈ।","ur":"ڈھلان پر speed تیزی سے بڑھتی ہے اور رکنے میں زیادہ فاصلہ لگتا ہے۔","bn":"(not translated yet)","te":"వాలుపై speed వేగంగా పెరుగుతుంది, ఆగడానికి ఎక్కువ దూరం పడుతుంది.","mr":"उतारावर speed झपाट्याने वाढतो आणि थांबायला जास्त अंतर लागते.","ml":"ഇറക്കത്തിൽ speed വേഗം കൂടും, നിർത്താൻ കൂടുതൽ ദൂരം വേണം.","ta":"சரிவில் வேகம் விரைவாக கூடும், நிற்க அதிக தூரம் ஆகும்.","gu":"ઢાળ ઉતરતાં ઝડપ ઝડપથી વધે અને રોકાવામાં વધુ સમય લાગે, એટલે ઓવરટેક જોખમી.","ne":"ओरालो झर्दा गति छिटो बढ्छ र रोकिन बढी समय लाग्छ, त्यसैले overtake जोखिमपूर्ण।"},"tr":{"hi":{"q":"ढलान पर उतरते हुए overtake करना जोखिम भरा क्यों है?","o":["आपकी speed जल्दी बढ़ती है और रुकने में ज़्यादा समय लगता है","आपके इंजन की शक्ति कम हो जाती है","आपके brakes बेहतर काम करते हैं","दूसरी कारें धीमी चलती हैं"]},"pa":{"q":"ਢਲਾਣ 'ਤੇ ਉਤਰਦਿਆਂ overtake ਕਰਨਾ ਜੋਖਮ ਭਰਿਆ ਕਿਉਂ ਹੈ?","o":["ਤੁਹਾਡੀ speed ਜਲਦੀ ਵਧਦੀ ਹੈ ਅਤੇ ਰੁਕਣ ਵਿੱਚ ਵੱਧ ਸਮਾਂ ਲੱਗਦਾ ਹੈ","ਤੁਹਾਡੇ ਇੰਜਣ ਦੀ ਸ਼ਕਤੀ ਘਟ ਜਾਂਦੀ ਹੈ","ਤੁਹਾਡੇ brakes ਬਿਹਤਰ ਕੰਮ ਕਰਦੇ ਹਨ","ਦੂਜੀਆਂ ਕਾਰਾਂ ਹੌਲੀ ਚੱਲਦੀਆਂ ਹਨ"]},"ur":{"q":"ڈھلان سے نیچے اوور ٹیک کرنا خطرناک کیوں ہے؟","o":["رفتار تیزی سے بڑھ جاتی ہے اور رکنے میں زیادہ وقت لگتا ہے","آپ کا انجن طاقت کھو دیتا ہے","آپ کی بریکیں بہتر کام کرتی ہیں","دوسری کاریں آہستہ چلتی ہیں"]},"bn":{"q":"ঢালু পথে নামতে নামতে ওভারটেক করা ঝুঁকিপূর্ণ কেন?","o":["গতি দ্রুত বেড়ে যায় এবং থামতে বেশি সময় লাগে","আপনার ইঞ্জিনের শক্তি কমে যায়","আপনার ব্রেক ভালো কাজ করে","অন্য গাড়ি ধীরে চলে"]},"te":{"q":"కిందికి వెళ్తూ ఓవర్‌టేక్ చేయడం ఎందుకు ప్రమాదకరం?","o":["మీ వేగం త్వరగా పెరుగుతుంది, ఆగడానికి ఎక్కువ సమయం పడుతుంది","మీ ఇంజిన్ శక్తి కోల్పోతుంది","మీ బ్రేక్‌లు బాగా పనిచేస్తాయి","ఇతర కార్లు నెమ్మదిగా వెళ్తాయి"]},"mr":{"q":"उतारावर ओव्हरटेक करणे धोकादायक का आहे?","o":["वेग झटकन वाढतो आणि थांबायला जास्त वेळ लागतो","इंजिनची शक्ती कमी होते","ब्रेक चांगले काम करतात","इतर कार हळू जातात"]},"ml":{"q":"ഇറക്കത്തിൽ ഓവർടേക്ക് ചെയ്യുന്നത് അപകടകരമായത് എന്തുകൊണ്ട്?","o":["വേഗത പെട്ടെന്ന് കൂടും, നിൽക്കാൻ കൂടുതൽ സമയമെടുക്കും","എൻജിന് power നഷ്ടപ്പെടും","brakes കൂടുതൽ നന്നായി പ്രവർത്തിക്കും","മറ്റ് കാറുകൾ പതുക്കെ പോകും"]},"ta":{"q":"கீழ்நோக்கி முந்துவது ஏன் ஆபத்து?","o":["உங்கள் வேகம் விரைவாக கூடி நிற்க நீண்ட நேரம் ஆகும்","உங்கள் engine சக்தியை இழக்கும்","உங்கள் brakes நன்றாக வேலை செய்யும்","மற்ற கார்கள் மெதுவாக செல்லும்"]},"gu":{"q":"ઢાળ ઉતરતાં ઓવરટેક કરવું જોખમી કેમ?","o":["ઝડપ ઝડપથી વધે અને રોકાવામાં વધુ સમય લાગે","તમારા એંજિનની શક્તિ ઘટે","તમારા brakes વધુ સારા કામ કરે","બીજી કારો ધીમી ચાલે"]},"ne":{"q":"ओरालोमा overtake गर्नु किन जोखिमपूर्ण छ?","o":["गति छिटो बढ्छ र रोकिन बढी समय लाग्छ","तपाईंको इन्जिनको शक्ति घट्छ","तपाईंका brakes राम्रो काम गर्छन्","अन्य कार ढिला चल्छन्"]}}},
{"id":9030,"chapter":9,"q":"How should you hold the steering wheel in normal driving?","options":["Loosely with one finger","With both hands, except when changing gear or using controls","With one hand on top","With your knees"],"answer":1,"exp":{"hi":"दोनों हाथों से पकड़ने से control सबसे अच्छा रहता है।","pa":"ਦੋਵਾਂ ਹੱਥਾਂ ਨਾਲ ਫੜਨ ਨਾਲ control ਸਭ ਤੋਂ ਵਧੀਆ ਰਹਿੰਦਾ ਹੈ।","ur":"دونوں ہاتھوں سے پکڑنے سے control سب سے اچھا رہتا ہے۔","bn":"(not translated yet)","te":"రెండు చేతులతో పట్టుకుంటే control అత్యుత్తమంగా ఉంటుంది.","mr":"दोन्ही हातांनी धरल्याने control सर्वोत्तम राहतो.","ml":"രണ്ട് കൈകൊണ്ടും പിടിക്കുമ്പോൾ control ഏറ്റവും നല്ലതാണ്.","ta":"இரு கைகளாலும் பிடித்தால் control சிறப்பாக இருக்கும்.","gu":"સામાન્ય રીતે બંને હાથ steering wheel પર રાખો, ફક્ત gear બદલતી વખતે કે controls વાપરતી વખતે સિવાય.","ne":"सामान्यतया दुवै हात steering wheel मा राख्नुहोस्, केवल gear बदल्दा वा controls प्रयोग गर्दा बाहेक।"},"tr":{"hi":{"q":"सामान्य ड्राइविंग में आपको steering wheel कैसे पकड़ना चाहिए?","o":["एक उंगली से ढीला","दोनों हाथों से, सिवाय gear बदलते समय या controls इस्तेमाल करते समय","ऊपर एक हाथ रखकर","घुटनों से"]},"pa":{"q":"ਆਮ ਡਰਾਈਵਿੰਗ ਵਿੱਚ ਤੁਹਾਨੂੰ steering wheel ਕਿਵੇਂ ਫੜਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਇਕ ਉਂਗਲ ਨਾਲ ਢਿੱਲਾ","ਦੋਵੇਂ ਹੱਥਾਂ ਨਾਲ, ਸਿਵਾਏ gear ਬਦਲਦੇ ਸਮੇਂ ਜਾਂ controls ਵਰਤਦੇ ਸਮੇਂ","ਉੱਪਰ ਇਕ ਹੱਥ ਰੱਖ ਕੇ","ਗੋਡਿਆਂ ਨਾਲ"]},"ur":{"q":"عام ڈرائیونگ میں آپ کو اسٹیئرنگ وہیل کیسے پکڑنا چاہیے؟","o":["ڈھیلے سے ایک انگلی سے","دونوں ہاتھوں سے، سوائے گیئر بدلتے یا کنٹرول استعمال کرتے وقت کے","اوپر ایک ہاتھ سے","اپنے گھٹنوں سے"]},"bn":{"q":"স্বাভাবিক চালানোর সময় আপনি স্টিয়ারিং হুইল কীভাবে ধরবেন?","o":["এক আঙুল দিয়ে আলগাভাবে","দুই হাত দিয়ে, গিয়ার বদলানো বা কন্ট্রোল ব্যবহারের সময় ছাড়া","ওপরে এক হাত দিয়ে","হাঁটু দিয়ে"]},"te":{"q":"సాధారణ డ్రైవింగ్‌లో స్టీరింగ్ వీల్‌ను ఎలా పట్టుకోవాలి?","o":["ఒక వేలితో వదులుగా","రెండు చేతులతో, గేర్ మార్చేటప్పుడు లేదా కంట్రోల్స్ వాడేటప్పుడు తప్ప","పైన ఒక చేత్తో","మోకాళ్లతో"]},"mr":{"q":"सामान्य ड्रायव्हिंगमध्ये तुम्ही स्टीअरिंग व्हील कसे धरावे?","o":["एका बोटाने सैलपणे","गिअर बदलताना किंवा नियंत्रणे वापरताना वगळता दोन्ही हातांनी","वरच्या बाजूला एका हाताने","गुडघ्यांनी"]},"ml":{"q":"സാധാരണ ഓടിക്കുമ്പോൾ steering wheel എങ്ങനെ പിടിക്കണം?","o":["ഒരു വിരൽ കൊണ്ട് അയച്ച്","gear മാറ്റുമ്പോഴോ controls ഉപയോഗിക്കുമ്പോഴോ ഒഴികെ രണ്ട് കൈകൊണ്ടും","മുകളിൽ ഒരു കൈ കൊണ്ട്","മുട്ടുകൾ കൊണ്ട്"]},"ta":{"q":"சாதாரண ஓட்டத்தில் steering wheel-ஐ எப்படி பிடிக்க வேண்டும்?","o":["ஒரு விரலால் தளர்வாக","gear மாற்றும்போது அல்லது controls பயன்படுத்தும்போது தவிர இரு கைகளாலும்","மேலே ஒரு கையால்","முழங்கால்களால்"]},"gu":{"q":"સામાન્ય ચલાવતાં steering wheel કેવી રીતે પકડવું?","o":["એક આંગળીથી ઢીલું","બંને હાથે, gear બદલતી વખતે કે controls વાપરતી વખતે સિવાય","ઉપર એક હાથે","ઘૂંટણથી"]},"ne":{"q":"सामान्य रूपमा चलाउँदा steering wheel कसरी समात्ने?","o":["एक औँलाले खुकुलो","दुवै हातले, gear बदल्दा वा controls प्रयोग गर्दा बाहेक","माथि एक हातले","घुँडाले"]}}},
{"id":9031,"chapter":9,"q":"You’re approaching a steep uphill section. When should you change to a lower gear?","options":["At the top","Never","Before the car starts to lose speed on the hill","Halfway up"],"answer":2,"exp":{"hi":"Speed गिरने से पहले gear बदलो, ताकि गाड़ी आराम से चढ़ सके।","pa":"Speed ਡਿੱਗਣ ਤੋਂ ਪਹਿਲਾਂ gear ਬਦਲੋ, ਤਾਂ ਜੋ ਗੱਡੀ ਆਰਾਮ ਨਾਲ ਚੜ੍ਹ ਸਕੇ।","ur":"Speed گرنے سے پہلے gear بدلیں، تاکہ گاڑی آرام سے چڑھ سکے۔","bn":"(not translated yet)","te":"Speed పడిపోకముందే gear మార్చండి, వాహనం సౌకర్యంగా ఎక్కగలదు.","mr":"Speed कमी होण्याआधी gear बदला म्हणजे गाडी आरामात चढेल.","ml":"Speed കുറയുന്നതിന് മുമ്പ് gear മാറ്റുക, കാർ സുഖമായി കയറാൻ.","ta":"வேகம் குறையும் முன்பே gear மாற்றுங்கள், கார் எளிதாக ஏற.","gu":"ઊભા ચઢાણ પહેલાં જ નીચા gear માં બદલો, કાર ઝડપ ગુમાવવા માંડે તે પહેલાં.","ne":"ठाडो उकालो अघि नै होचो gear मा बदल्नुहोस्, कारले गति गुमाउन थाल्नु अघि।"},"tr":{"hi":{"q":"आप खड़ी चढ़ाई के पास पहुँच रहे हैं। आपको नीचे के gear में कब बदलना चाहिए?","o":["चोटी पर पहुँचकर","कभी नहीं","इससे पहले कि कार चढ़ाई पर speed खोने लगे","आधे रास्ते में"]},"pa":{"q":"ਤੁਸੀਂ ਖੜ੍ਹੀ ਚੜ੍ਹਾਈ ਦੇ ਨੇੜੇ ਪਹੁੰਚ ਰਹੇ ਹੋ। ਤੁਹਾਨੂੰ ਨੀਵੇਂ gear ਵਿੱਚ ਕਦੋਂ ਬਦਲਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਚੋਟੀ 'ਤੇ ਪਹੁੰਚ ਕੇ","ਕਦੇ ਨਹੀਂ","ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਕਾਰ ਚੜ੍ਹਾਈ 'ਤੇ speed ਗੁਆਉਣ ਲੱਗੇ","ਅੱਧੇ ਰਾਹ ਵਿੱਚ"]},"ur":{"q":"آپ ایک کھڑی چڑھائی کے قریب پہنچ رہے ہیں۔ آپ کو نچلے گیئر میں کب جانا چاہیے؟","o":["چوٹی پر","کبھی نہیں","اس سے پہلے کہ گاڑی ڈھلان پر رفتار کھونا شروع کرے","آدھے راستے پر"]},"bn":{"q":"আপনি একটি খাড়া চড়াই অংশের কাছে আসছেন। কখন নিচু গিয়ারে বদলাবেন?","o":["চূড়ায় পৌঁছে","কখনো নয়","ঢালে গাড়ির গতি কমতে শুরু করার আগেই","মাঝপথে"]},"te":{"q":"మీరు నిటారైన ఎత్తు భాగం దగ్గరకు వస్తున్నారు. తక్కువ గేర్‌కు ఎప్పుడు మారాలి?","o":["పైకి చేరినప్పుడు","ఎప్పుడూ కాదు","కొండపై కారు వేగం కోల్పోవడం మొదలయ్యే ముందు","సగం ఎక్కిన తర్వాత"]},"mr":{"q":"तुम्ही तीव्र चढावाच्या भागाजवळ येत आहात. तुम्ही कमी गिअरमध्ये केव्हा जावे?","o":["माथ्यावर","कधीच नाही","चढावर कारचा वेग कमी होण्यापूर्वी","अर्ध्या चढावर"]},"ml":{"q":"കുത്തനെയുള്ള കയറ്റത്തിലേക്ക് അടുക്കുകയാണ്. താഴ്ന്ന gear-ലേക്ക് എപ്പോൾ മാറണം?","o":["മുകളിൽ എത്തുമ്പോൾ","ഒരിക്കലും വേണ്ട","കയറ്റത്തിൽ കാറിന്റെ വേഗത കുറയാൻ തുടങ്ങുംമുമ്പ്","പകുതി കയറുമ്പോൾ"]},"ta":{"q":"செங்குத்தான மேல்நோக்கிய பகுதியை நெருங்குகிறீர்கள். குறைந்த gear-க்கு எப்போது மாற வேண்டும்?","o":["உச்சியில்","ஒருபோதும் இல்லை","மலையில் கார் வேகத்தை இழக்கத் தொடங்கும் முன்","பாதி தூரத்தில்"]},"gu":{"q":"તમે ઊભા ચઢાણ પાસે પહોંચો છો. નીચા gear માં ક્યારે બદલવું?","o":["ટોચ પર","ક્યારેય નહીં","ઢાળ પર કાર ઝડપ ગુમાવવા માંડે તે પહેલાં","અડધે રસ્તે"]},"ne":{"q":"तपाईं ठाडो उकालो नजिक पुग्दै हुनुहुन्छ। होचो gear मा कहिले बदल्ने?","o":["टुप्पोमा","कहिल्यै होइन","ढलानमा कारले गति गुमाउन थाल्नु अघि","आधा बाटोमा"]}}},
{"id":9032,"chapter":9,"q":"What does the tread on a tyre do on a wet road?","options":["Makes the tyre quieter","Cools the brakes","Nothing","Pushes water away so the tyre can grip"],"answer":3,"exp":{"hi":"Tread पानी को बाहर निकालता है ताकि tyre सड़क को पकड़ सके। घिसा tread = aquaplaning का ख़तरा।","pa":"Tread ਪਾਣੀ ਨੂੰ ਬਾਹਰ ਕੱਢਦਾ ਹੈ ਤਾਂ ਜੋ tyre ਸੜਕ ਨੂੰ ਫੜ ਸਕੇ। ਘਸਿਆ tread = aquaplaning ਦਾ ਖ਼ਤਰਾ।","ur":"Tread پانی کو باہر نکالتا ہے تاکہ tyre سڑک کو پکڑ سکے۔ گھسا ہوا tread = aquaplaning کا خطرہ۔","bn":"(not translated yet)","te":"Tread నీటిని బయటకు పంపుతుంది, tyre రోడ్డును పట్టుకోగలదు. అరిగిన tread = aquaplaning ప్రమాదం.","mr":"Tread पाणी बाहेर काढतो म्हणजे tyre रस्ता पकडू शकतो. झिजलेला tread = aquaplaning चा धोका.","ml":"Tread വെള്ളം പുറത്തേക്ക് തള്ളുന്നു, tyre റോഡിൽ പിടിക്കാൻ. തേഞ്ഞ tread = aquaplaning സാധ്യത.","ta":"Tread நீரை வெளியேற்றி டயர் சாலையைப் பிடிக்க உதவும். தேய்ந்த tread = aquaplaning ஆபத்து.","gu":"Tread પાણીને tyre ની નીચેથી દૂર ધકેલે, જેથી રોડ પર grip મળે. ઘસાયેલા tyres માં પાણી ભરાય.","ne":"Tread ले पानीलाई tyre मुनिबाट टाढा धकेल्छ, जसले सडकमा grip दिन्छ। खिइएका tyres मा पानी जम्छ।"},"tr":{"hi":{"q":"गीली सड़क पर टायर की tread क्या काम करती है?","o":["टायर को शांत बनाती है","brakes को ठंडा करती है","कुछ नहीं","पानी को बाहर धकेलती है ताकि टायर पकड़ बना सके"]},"pa":{"q":"ਗਿੱਲੀ ਸੜਕ 'ਤੇ ਟਾਇਰ ਦੀ tread ਕੀ ਕੰਮ ਕਰਦੀ ਹੈ?","o":["ਟਾਇਰ ਨੂੰ ਸ਼ਾਂਤ ਬਣਾਉਂਦੀ ਹੈ","brakes ਨੂੰ ਠੰਢਾ ਕਰਦੀ ਹੈ","ਕੁਝ ਨਹੀਂ","ਪਾਣੀ ਨੂੰ ਬਾਹਰ ਧੱਕਦੀ ਹੈ ਤਾਂ ਜੋ ਟਾਇਰ ਪਕੜ ਬਣਾ ਸਕੇ"]},"ur":{"q":"گیلی سڑک پر ٹائر کی ٹریڈ (چکنائی/نقش) کیا کرتی ہے؟","o":["ٹائر کو زیادہ خاموش بناتی ہے","بریکوں کو ٹھنڈا کرتی ہے","کچھ نہیں","پانی کو دھکیل کر ہٹاتی ہے تاکہ ٹائر گرفت کر سکے"]},"bn":{"q":"ভেজা রাস্তায় টায়ারের ট্রেড কী করে?","o":["টায়ারকে নিঃশব্দ করে","ব্রেক ঠান্ডা করে","কিছুই না","পানি সরিয়ে দেয় যাতে টায়ার গ্রিপ পায়"]},"te":{"q":"తడి రోడ్డుపై టైర్ ట్రెడ్ ఏమి చేస్తుంది?","o":["టైర్‌ను నిశ్శబ్దంగా చేస్తుంది","బ్రేక్‌లను చల్లబరుస్తుంది","ఏమీ చేయదు","నీటిని దూరంగా నెట్టి టైర్ పట్టు సాధించేలా చేస్తుంది"]},"mr":{"q":"ओल्या रस्त्यावर टायरवरील ट्रेड काय करतो?","o":["टायर अधिक शांत करतो","ब्रेक थंड करतो","काहीच नाही","पाणी दूर ढकलतो म्हणजे टायरला पकड मिळते"]},"ml":{"q":"നനഞ്ഞ റോഡിൽ tyre-ലെ tread എന്താണ് ചെയ്യുന്നത്?","o":["tyre-നെ കൂടുതൽ നിശ്ശബ്ദമാക്കുന്നു","brakes തണുപ്പിക്കുന്നു","ഒന്നും ചെയ്യുന്നില്ല","tyre-ന് grip കിട്ടാൻ വെള്ളം തള്ളിമാറ്റുന്നു"]},"ta":{"q":"ஈரமான சாலையில் டயரின் tread என்ன செய்கிறது?","o":["டயரை அமைதியாக்கும்","brakes-ஐ குளிர்விக்கும்","எதுவும் இல்லை","நீரை வெளியே தள்ளி டயர் பிடிக்க உதவும்"]},"gu":{"q":"ભીના રોડ પર tyre ની tread શું કરે છે?","o":["tyre ને શાંત બનાવે છે","brakes ને ઠંડા કરે છે","કંઈ નહીં","પાણીને દૂર ધકેલે છે જેથી tyre grip કરી શકે"]},"ne":{"q":"भिजेको सडकमा tyre को tread ले के गर्छ?","o":["tyre लाई शान्त बनाउँछ","brakes चिसो पार्छ","केही गर्दैन","पानीलाई टाढा धकेल्छ ताकि tyre ले grip गर्न सकोस्"]}}},
{"id":9033,"chapter":9,"q":"You come to a ford. What should you do?","options":["Check the depth, drive through slowly, then test your brakes","Drive through fast","Drive through in neutral","Stop in the middle"],"answer":0,"exp":{"hi":"गहराई देखो, धीरे पार करो, फिर brakes हल्के से test करो।","pa":"ਡੂੰਘਾਈ ਦੇਖੋ, ਹੌਲੀ ਪਾਰ ਕਰੋ, ਫਿਰ brakes ਹਲਕੇ ਜਿਹੇ test ਕਰੋ।","ur":"گہرائی دیکھیں، آہستہ پار کریں، پھر brakes ہلکے سے test کریں۔","bn":"(not translated yet)","te":"లోతు చూడండి, నెమ్మదిగా దాటండి, తర్వాత brakes తేలికగా test చేయండి.","mr":"खोली पाहा, हळू पार करा, मग brakes हलकेच test करा.","ml":"ആഴം നോക്കുക, പതുക്കെ കടക്കുക, പിന്നെ brakes ലഘുവായി പരീക്ഷിക്കുക.","ta":"ஆழத்தை பாருங்கள், மெதுவாக கடந்து, பிறகு brakes-ஐ மென்மையாக சோதியுங்கள்.","gu":"Ford પર ઊંડાઈ તપાસો, ધીમેથી પહેલા gear માં પાર કરો, પછી brakes ચકાસો.","ne":"Ford मा गहिराइ जाँच्नुहोस्, बिस्तारै पहिलो gear मा पार गर्नुहोस्, अनि brakes परीक्षण गर्नुहोस्।"},"tr":{"hi":{"q":"आप एक ford (पानी से भरा रास्ता) पर पहुँचते हैं। आपको क्या करना चाहिए?","o":["गहराई जाँचो, धीरे से निकलो, फिर अपने brakes परखो","तेज़ी से निकल जाओ","neutral में निकलो","बीच में रुक जाओ"]},"pa":{"q":"ਤੁਸੀਂ ਇਕ ford (ਪਾਣੀ ਨਾਲ ਭਰੇ ਰਾਹ) 'ਤੇ ਪਹੁੰਚਦੇ ਹੋ। ਤੁਹਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਡੂੰਘਾਈ ਜਾਂਚੋ, ਹੌਲੀ ਜਿਹੇ ਲੰਘੋ, ਫਿਰ ਆਪਣੇ brakes ਪਰਖੋ","ਤੇਜ਼ੀ ਨਾਲ ਲੰਘ ਜਾਓ","neutral ਵਿੱਚ ਲੰਘੋ","ਵਿਚਕਾਰ ਰੁਕ ਜਾਓ"]},"ur":{"q":"آپ ایک پایاب نالے/گھاٹ (فورڈ) پر پہنچتے ہیں۔ آپ کو کیا کرنا چاہیے؟","o":["گہرائی چیک کریں، آہستہ گزریں، پھر بریکیں آزمائیں","تیزی سے گزر جائیں","نیوٹرل میں گزریں","بیچ میں رک جائیں"]},"bn":{"q":"আপনি একটি অগভীর নদী পারাপার (ফোর্ড) এর কাছে এলেন। আপনার কী করা উচিত?","o":["গভীরতা পরীক্ষা করুন, ধীরে পার হন, তারপর ব্রেক পরীক্ষা করুন","জোরে পার হন","নিউট্রালে পার হন","মাঝখানে থামুন"]},"te":{"q":"మీరు ఒక ఫోర్డ్ (నీటి గుండా వెళ్లే దారి) దగ్గరకు వచ్చారు. మీరు ఏమి చేయాలి?","o":["లోతు తనిఖీ చేయండి, నెమ్మదిగా నడపండి, తర్వాత బ్రేక్‌లను పరీక్షించండి","వేగంగా దాటండి","న్యూట్రల్‌లో దాటండి","మధ్యలో ఆగండి"]},"mr":{"q":"तुम्ही ford (उथळ ओढा) जवळ येता. तुम्ही काय करावे?","o":["खोली तपासा, हळू पार करा, मग ब्रेक तपासा","वेगाने पार करा","neutral मध्ये पार करा","मध्येच थांबा"]},"ml":{"q":"നിങ്ങൾ ഒരു ford-ൽ (വെള്ളം ഒഴുകുന്ന റോഡ് ഭാഗം) എത്തുന്നു. എന്ത് ചെയ്യണം?","o":["ആഴം പരിശോധിക്കുക, പതുക്കെ ഓടിച്ച് കടക്കുക, പിന്നെ brakes പരീക്ഷിക്കുക","വേഗത്തിൽ കടക്കുക","neutral-ൽ കടക്കുക","നടുവിൽ നിർത്തുക"]},"ta":{"q":"ஒரு ford (ஆற்றுக் கடவு) வருகிறது. என்ன செய்ய வேண்டும்?","o":["ஆழத்தைச் சரிபாருங்கள், மெதுவாக கடந்து, பிறகு brakes-ஐ சோதியுங்கள்","வேகமாக கடந்து செல்லுங்கள்","neutral-இல் கடந்து செல்லுங்கள்","நடுவில் நில்லுங்கள்"]},"gu":{"q":"તમે ford (છીછરી નદી પાર) પાસે પહોંચો છો. શું કરવું?","o":["ઊંડાઈ તપાસો, ધીમે ચલાવી પાર કરો, પછી brakes ચકાસો","ઝડપથી પાર કરો","neutral માં પાર કરો","વચ્ચે ઊભા રહો"]},"ne":{"q":"तपाईं ford (उथलो खोला पार) मा पुग्नुभयो। के गर्नुपर्छ?","o":["गहिराइ जाँच्नुहोस्, बिस्तारै चलाएर पार गर्नुहोस्, अनि brakes परीक्षण गर्नुहोस्","छिटो पार गर्नुहोस्","neutral मा पार गर्नुहोस्","बीचमा रोकिनुहोस्"]}}},
{"id":9034,"chapter":9,"q":"What is ‘brake fade’?","options":["Low brake fluid","Loss of braking power when brakes overheat","Squeaky brakes","Brakes locking"],"answer":1,"exp":{"hi":"लगातार brake लगाने से brakes गर्म होकर कमज़ोर हो जाते हैं। ढलान पर low gear इसीलिए।","pa":"ਲਗਾਤਾਰ brake ਲਾਉਣ ਨਾਲ brakes ਗਰਮ ਹੋ ਕੇ ਕਮਜ਼ੋਰ ਹੋ ਜਾਂਦੇ ਹਨ। ਢਲਾਨ ’ਤੇ low gear ਇਸੇ ਲਈ।","ur":"مسلسل brake لگانے سے brakes گرم ہو کر کمزور ہو جاتے ہیں۔ ڈھلان پر low gear اسی لیے۔","bn":"(not translated yet)","te":"నిరంతరం brake వేస్తే brakes వేడెక్కి బలహీనపడతాయి. వాలుపై low gear అందుకే.","mr":"सतत brake लावल्याने brakes गरम होऊन कमकुवत होतात. उतारावर म्हणूनच low gear.","ml":"തുടർച്ചയായി brake ചെയ്താൽ brakes ചൂടായി ദുർബലമാകും. അതുകൊണ്ടാണ് ഇറക്കത്തിൽ low gear.","ta":"தொடர்ந்து brake போட்டால் brakes சூடாகி பலவீனமாகும். சரிவில் குறைந்த gear இதனால்தான்.","gu":"Brake fade = લાંબા સમય વાપરવાથી brakes ગરમ થઈ કાર્યક્ષમતા ગુમાવે. નીચા gear અને engine braking વાપરો.","ne":"Brake fade = लामो समय प्रयोगले brakes तातेर कार्यक्षमता गुमाउनु। होचो gear र engine braking प्रयोग गर्नुहोस्।"},"tr":{"hi":{"q":"'brake fade' क्या है?","o":["brake fluid का कम होना","brakes के ज़्यादा गर्म होने पर braking शक्ति का कम हो जाना","brakes का चीख़ना","brakes का जाम हो जाना"]},"pa":{"q":"'brake fade' ਕੀ ਹੈ?","o":["brake fluid ਦਾ ਘੱਟ ਹੋਣਾ","brakes ਦੇ ਵੱਧ ਗਰਮ ਹੋਣ 'ਤੇ braking ਸ਼ਕਤੀ ਦਾ ਘੱਟ ਜਾਣਾ","brakes ਦਾ ਚੀਕਣਾ","brakes ਦਾ ਜਾਮ ਹੋ ਜਾਣਾ"]},"ur":{"q":"'بریک فیڈ' کیا ہے؟","o":["بریک فلوئڈ کی کمی","بریکوں کے زیادہ گرم ہونے پر بریک لگانے کی طاقت کا کم ہو جانا","بریکوں کا چیخنا","بریکوں کا جام ہو جانا"]},"bn":{"q":"'ব্রেক ফেড' কী?","o":["কম ব্রেক ফ্লুইড","ব্রেক অতিরিক্ত গরম হলে ব্রেকিং ক্ষমতা কমে যাওয়া","ব্রেকের কিচকিচ শব্দ","ব্রেক আটকে যাওয়া"]},"te":{"q":"'బ్రేక్ ఫేడ్' అంటే ఏమిటి?","o":["బ్రేక్ ఫ్లూయిడ్ తక్కువ కావడం","బ్రేక్‌లు వేడెక్కినప్పుడు బ్రేకింగ్ శక్తి తగ్గిపోవడం","బ్రేక్‌లు కీచుమనడం","బ్రేక్‌లు లాక్ కావడం"]},"mr":{"q":"‘brake fade’ म्हणजे काय?","o":["ब्रेक फ्लुइड कमी","ब्रेक जास्त तापल्यावर ब्रेकिंग शक्ती कमी होणे","ब्रेक कर्कश आवाज करणे","ब्रेक लॉक होणे"]},"ml":{"q":"‘brake fade’ എന്നാൽ എന്താണ്?","o":["brake fluid കുറവ്","brakes അമിതമായി ചൂടാകുമ്പോൾ braking ശക്തി നഷ്ടപ്പെടുന്നത്","brakes ഞരങ്ങുന്നത്","brakes ലോക്ക് ആകുന്നത്"]},"ta":{"q":"'brake fade' என்றால் என்ன?","o":["brake fluid குறைவு","brakes அதிக வெப்பமடையும்போது braking சக்தி குறைவது","brakes சத்தம் போடுவது","brakes lock ஆவது"]},"gu":{"q":"'brake fade' એટલે શું?","o":["brake fluid ઓછું","brakes વધુ ગરમ થતાં braking શક્તિ ગુમાવવી","brakes નો ચીસ અવાજ","brakes લૉક થવા"]},"ne":{"q":"'brake fade' भनेको के हो?","o":["brake fluid कम हुनु","brakes बढी तात्दा braking शक्ति गुम्नु","brakes ले चिच्याउनु","brakes लक हुनु"]}}},
{"id":9035,"chapter":9,"q":"When can snow chains be used?","options":["On motorways in rain","All winter on any road","On roads covered with snow, to help grip","On dry roads"],"answer":2,"exp":{"hi":"Snow chains सिर्फ़ बर्फ़ से ढकी सड़क पर। साफ़ सड़क पर ये सड़क और tyres दोनों ख़राब करती हैं।","pa":"Snow chains ਸਿਰਫ਼ ਬਰਫ਼ ਨਾਲ ਢਕੀ ਸੜਕ ’ਤੇ। ਸਾਫ਼ ਸੜਕ ’ਤੇ ਇਹ ਸੜਕ ਅਤੇ tyres ਦੋਵੇਂ ਖ਼ਰਾਬ ਕਰਦੀਆਂ ਹਨ।","ur":"Snow chains صرف برف سے ڈھکی سڑک پر۔ صاف سڑک پر یہ سڑک اور tyres دونوں خراب کرتی ہیں۔","bn":"(not translated yet)","te":"మంచుతో కప్పబడిన రోడ్డుపై మాత్రమే. ఖాళీ రోడ్డుపై ఇవి రోడ్డును, tyres ను రెండింటినీ పాడుచేస్తాయి.","mr":"Snow chains फक्त बर्फाने झाकलेल्या रस्त्यावर. मोकळ्या रस्त्यावर त्या रस्ता आणि tyres दोन्ही खराब करतात.","ml":"Snow chains മഞ്ഞുമൂടിയ റോഡിൽ മാത്രം. വൃത്തിയുള്ള റോഡിൽ അവ റോഡിനെയും tyres-നെയും കേടാക്കും.","ta":"Snow chains பனி மூடிய சாலையில் மட்டும். தெளிவான சாலையில் சாலையையும் டயர்களையும் கெடுக்கும்.","gu":"Snow chains ફક્ત snow થી ઢંકાયેલા રોડ પર grip માટે વાપરો, સૂકા રોડ પર નહીં.","ne":"Snow chains केवल snow ले ढाकिएको सडकमा grip का लागि प्रयोग गर्नुहोस्, सुक्खा सडकमा होइन।"},"tr":{"hi":{"q":"snow chains का इस्तेमाल कब किया जा सकता है?","o":["बारिश में मोटरवे पर","पूरी सर्दियों में किसी भी सड़क पर","बर्फ़ से ढकी सड़कों पर, पकड़ बढ़ाने के लिए","सूखी सड़कों पर"]},"pa":{"q":"snow chains ਦੀ ਵਰਤੋਂ ਕਦੋਂ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ?","o":["ਮੀਂਹ ਵਿੱਚ ਮੋਟਰਵੇ 'ਤੇ","ਸਾਰੀ ਸਰਦੀ ਕਿਸੇ ਵੀ ਸੜਕ 'ਤੇ","ਬਰਫ਼ ਨਾਲ ਢਕੀਆਂ ਸੜਕਾਂ 'ਤੇ, ਪਕੜ ਵਧਾਉਣ ਲਈ","ਸੁੱਕੀਆਂ ਸੜਕਾਂ 'ਤੇ"]},"ur":{"q":"سنو چینز کب استعمال کی جا سکتی ہیں؟","o":["بارش میں موٹرویز پر","پورے موسمِ سرما میں ہر سڑک پر","برف سے ڈھکی سڑکوں پر، گرفت میں مدد کے لیے","خشک سڑکوں پر"]},"bn":{"q":"স্নো চেইন কখন ব্যবহার করা যায়?","o":["বৃষ্টিতে মোটরওয়েতে","পুরো শীতকাল যেকোনো রাস্তায়","তুষারে ঢাকা রাস্তায়, গ্রিপে সাহায্যের জন্য","শুকনো রাস্তায়"]},"te":{"q":"స్నో చైన్లను ఎప్పుడు వాడవచ్చు?","o":["వర్షంలో మోటార్‌వేలపై","శీతాకాలం అంతా ఏ రోడ్డుపైనా","మంచుతో కప్పబడిన రోడ్లపై, పట్టు పెంచడానికి","పొడి రోడ్లపై"]},"mr":{"q":"snow chains केव्हा वापरता येतात?","o":["पावसात मोटरवेवर","संपूर्ण हिवाळाभर कोणत्याही रस्त्यावर","पकड मिळण्यासाठी बर्फाने झाकलेल्या रस्त्यांवर","कोरड्या रस्त्यांवर"]},"ml":{"q":"snow chains എപ്പോഴാണ് ഉപയോഗിക്കാൻ കഴിയുക?","o":["മഴയത്ത് മോട്ടോർവേകളിൽ","ശൈത്യകാലത്ത് ഏത് റോഡിലും","grip കിട്ടാൻ, മഞ്ഞുമൂടിയ റോഡുകളിൽ","ഉണങ്ങിയ റോഡുകളിൽ"]},"ta":{"q":"snow chains-ஐ எப்போது பயன்படுத்தலாம்?","o":["மழையில் மோட்டார்வேயில்","குளிர்காலம் முழுவதும் எந்த சாலையிலும்","பிடிப்புக்காக பனியால் மூடப்பட்ட சாலைகளில்","உலர்ந்த சாலைகளில்"]},"gu":{"q":"snow chains ક્યારે વાપરી શકાય?","o":["વરસાદમાં motorways પર","આખા શિયાળામાં કોઈ પણ રોડ પર","grip માટે snow થી ઢંકાયેલા રોડ પર","સૂકા રોડ પર"]},"ne":{"q":"snow chains कहिले प्रयोग गर्न सकिन्छ?","o":["वर्षामा मोटरवेमा","जाडोभर कुनै पनि सडकमा","grip का लागि snow ले ढाकिएको सडकमा","सुक्खा सडकमा"]}}},
{"id":9036,"chapter":9,"q":"Why should you switch on your lights at dusk?","options":["To save the battery","To see road signs only","It’s not needed","So others can see you"],"answer":3,"exp":{"hi":"शाम को रोशनी कम होती है। Lights से दूसरे आपको जल्दी देख पाते हैं।","pa":"ਸ਼ਾਮ ਨੂੰ ਰੋਸ਼ਨੀ ਘੱਟ ਹੁੰਦੀ ਹੈ। Lights ਨਾਲ ਦੂਜੇ ਤੁਹਾਨੂੰ ਜਲਦੀ ਦੇਖ ਲੈਂਦੇ ਹਨ।","ur":"شام کو روشنی کم ہوتی ہے۔ Lights سے دوسرے آپ کو جلدی دیکھ لیتے ہیں۔","bn":"(not translated yet)","te":"సాయంత్రం వెలుతురు తక్కువ. Lights తో ఇతరులు మిమ్మల్ని త్వరగా చూస్తారు.","mr":"संध्याकाळी प्रकाश कमी असतो. Lights मुळे इतरांना तुम्ही लवकर दिसता.","ml":"സന്ധ്യയ്ക്ക് വെളിച്ചം കുറവാണ്. Lights ഉണ്ടെങ്കിൽ മറ്റുള്ളവർക്ക് നിങ്ങളെ നേരത്തെ കാണാം.","ta":"மாலையில் வெளிச்சம் குறையும். Lights போட்டால் மற்றவர்கள் உங்களை சீக்கிரம் பார்ப்பார்கள்.","gu":"સાંજે લાઈટો ચાલુ કરો જેથી બીજા ડ્રાઇવરો તમને જોઈ શકે. ફક્ત તમારા જોવા માટે નહીં.","ne":"साँझमा बत्ती बाल्नुहोस् ताकि अन्य चालकले तपाईंलाई देखून्। तपाईंले देख्न मात्र होइन।"},"tr":{"hi":{"q":"आपको शाम के झुटपुटे (dusk) में अपनी lights क्यों जलानी चाहिए?","o":["battery बचाने के लिए","सिर्फ़ सड़क के signs देखने के लिए","ज़रूरत नहीं है","ताकि दूसरे आपको देख सकें"]},"pa":{"q":"ਤੁਹਾਨੂੰ ਸ਼ਾਮ ਦੇ ਝੁਟਪੁਟੇ (dusk) ਵਿੱਚ ਆਪਣੀਆਂ lights ਕਿਉਂ ਜਗਾਉਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?","o":["battery ਬਚਾਉਣ ਲਈ","ਸਿਰਫ਼ ਸੜਕ ਦੇ signs ਦੇਖਣ ਲਈ","ਲੋੜ ਨਹੀਂ ਹੈ","ਤਾਂ ਜੋ ਦੂਜੇ ਤੁਹਾਨੂੰ ਦੇਖ ਸਕਣ"]},"ur":{"q":"شام کے وقت آپ کو اپنی بتیاں کیوں آن کرنی چاہئیں؟","o":["بیٹری بچانے کے لیے","صرف سڑک کے نشان دیکھنے کے لیے","اس کی ضرورت نہیں","تاکہ دوسرے آپ کو دیکھ سکیں"]},"bn":{"q":"গোধূলিতে আপনার আলো জ্বালানো উচিত কেন?","o":["ব্যাটারি বাঁচাতে","শুধু রাস্তার চিহ্ন দেখতে","এর দরকার নেই","যাতে অন্যরা আপনাকে দেখতে পায়"]},"te":{"q":"సంధ్యా సమయంలో మీ లైట్లను ఎందుకు ఆన్ చేయాలి?","o":["బ్యాటరీ ఆదా చేయడానికి","రోడ్డు సైన్లు చూడడానికి మాత్రమే","అవసరం లేదు","ఇతరులకు మీరు కనిపించడానికి"]},"mr":{"q":"संध्याकाळच्या वेळी तुम्ही दिवे का लावावेत?","o":["बॅटरी वाचवण्यासाठी","फक्त रस्त्यावरील फलक पाहण्यासाठी","गरज नाही","म्हणजे इतरांना तुम्ही दिसाल"]},"ml":{"q":"സന്ധ്യയ്ക്ക് lights ഓൺ ചെയ്യേണ്ടത് എന്തുകൊണ്ട്?","o":["ബാറ്ററി ലാഭിക്കാൻ","road signs കാണാൻ മാത്രം","ആവശ്യമില്ല","മറ്റുള്ളവർക്ക് നിങ്ങളെ കാണാൻ കഴിയാൻ"]},"ta":{"q":"அந்தி நேரத்தில் ஏன் விளக்குகளை போட வேண்டும்?","o":["battery சேமிக்க","சாலை signs-ஐ பார்க்க மட்டும்","தேவையில்லை","மற்றவர்கள் உங்களைப் பார்க்க"]},"gu":{"q":"સાંજના સમયે લાઈટો કેમ ચાલુ કરવી?","o":["બેટરી બચાવવા","ફક્ત road signs જોવા","જરૂર નથી","જેથી બીજા તમને જોઈ શકે"]},"ne":{"q":"साँझमा बत्ती किन बाल्ने?","o":["ब्याट्री बचाउन","road signs हेर्न मात्र","आवश्यक छैन","ताकि अरूले तपाईंलाई देखून्"]}}},
{"id":9037,"chapter":9,"q":"How should you drive in strong crosswinds?","options":["Slow down and hold the steering wheel firmly","Speed up to get through","Drive in the middle of the road","Use cruise control"],"answer":0,"exp":{"hi":"धीमे चलो और steering कसकर पकड़ो, ख़ासकर पुलों और खुली जगहों पर।","pa":"ਹੌਲੀ ਚੱਲੋ ਅਤੇ steering ਘੁੱਟ ਕੇ ਫੜੋ, ਖ਼ਾਸ ਕਰਕੇ ਪੁਲਾਂ ਅਤੇ ਖੁੱਲ੍ਹੀਆਂ ਥਾਵਾਂ ’ਤੇ।","ur":"آہستہ چلیں اور steering مضبوطی سے پکڑیں، خاص طور پر پلوں اور کھلی جگہوں پر۔","bn":"(not translated yet)","te":"నెమ్మదిగా వెళ్ళి steering గట్టిగా పట్టుకోండి, ముఖ్యంగా వంతెనలు, బహిరంగ ప్రదేశాల్లో.","mr":"हळू चला आणि steering घट्ट धरा, विशेषतः पूल आणि मोकळ्या जागांवर.","ml":"വേഗത കുറച്ച് steering ഉറപ്പായി പിടിക്കുക, പ്രത്യേകിച്ച് പാലങ്ങളിലും തുറന്ന സ്ഥലങ്ങളിലും.","ta":"மெதுவாக ஓட்டி steering-ஐ உறுதியாகப் பிடியுங்கள், குறிப்பாக பாலங்களிலும் திறந்த இடங்களிலும்.","gu":"Crosswind માં ધીમા પડો અને steering મજબૂત પકડો. ખાસ કરીને પુલ અને ખુલ્લા વિસ્તારમાં.","ne":"Crosswind मा ढिलो हुनुहोस् र steering दह्रोसँग समात्नुहोस्। विशेष गरी पुल र खुला क्षेत्रमा।"},"tr":{"hi":{"q":"तेज़ आड़ी हवा (crosswinds) में आपको कैसे चलाना चाहिए?","o":["धीमे हो जाओ और steering wheel मज़बूती से पकड़ो","निकलने के लिए speed बढ़ाओ","सड़क के बीच में चलाओ","cruise control इस्तेमाल करो"]},"pa":{"q":"ਤੇਜ਼ ਆਡੀ ਹਵਾ (crosswinds) ਵਿੱਚ ਤੁਹਾਨੂੰ ਕਿਵੇਂ ਚਲਾਉਣਾ ਚਾਹੀਦਾ ਹੈ?","o":["ਹੌਲੀ ਹੋ ਜਾਓ ਅਤੇ steering wheel ਮਜ਼ਬੂਤੀ ਨਾਲ ਫੜੋ","ਨਿਕਲਣ ਲਈ speed ਵਧਾਓ","ਸੜਕ ਦੇ ਵਿਚਕਾਰ ਚਲਾਓ","cruise control ਵਰਤੋ"]},"ur":{"q":"تیز پہلو کی ہواؤں میں آپ کو گاڑی کیسے چلانی چاہیے؟","o":["رفتار کم کریں اور اسٹیئرنگ وہیل کو مضبوطی سے پکڑیں","نکلنے کے لیے رفتار بڑھائیں","سڑک کے بیچ میں چلائیں","کروز کنٹرول استعمال کریں"]},"bn":{"q":"তীব্র পাশের হাওয়ায় আপনি কীভাবে চালাবেন?","o":["গতি কমান এবং স্টিয়ারিং হুইল শক্ত করে ধরুন","পার হতে গতি বাড়ান","রাস্তার মাঝখান দিয়ে চালান","ক্রুজ কন্ট্রোল ব্যবহার করুন"]},"te":{"q":"బలమైన పక్క గాలుల్లో మీరు ఎలా నడపాలి?","o":["వేగం తగ్గించి స్టీరింగ్ వీల్‌ను గట్టిగా పట్టుకోండి","దాటడానికి వేగం పెంచండి","రోడ్డు మధ్యలో నడపండి","క్రూయిజ్ కంట్రోల్ వాడండి"]},"mr":{"q":"जोरदार आडव्या वाऱ्यात तुम्ही कसे चालवावे?","o":["वेग कमी करा आणि स्टीअरिंग व्हील घट्ट धरा","पार जाण्यासाठी वेग वाढवा","रस्त्याच्या मधून चालवा","cruise control वापरा"]},"ml":{"q":"ശക്തമായ crosswinds-ൽ എങ്ങനെ ഓടിക്കണം?","o":["വേഗത കുറച്ച് steering wheel ഉറപ്പായി പിടിക്കുക","കടക്കാൻ വേഗത കൂട്ടുക","റോഡിന്റെ നടുവിലൂടെ ഓടിക്കുക","cruise control ഉപയോഗിക്കുക"]},"ta":{"q":"வலுவான பக்கவாட்டு காற்றில் எப்படி ஓட்ட வேண்டும்?","o":["வேகத்தை குறைத்து steering wheel-ஐ உறுதியாகப் பிடியுங்கள்","கடக்க வேகத்தை கூட்டுங்கள்","சாலையின் நடுவில் ஓட்டுங்கள்","cruise control பயன்படுத்துங்கள்"]},"gu":{"q":"મજબૂત crosswinds માં કેવી રીતે ચલાવવું?","o":["ધીમા પડો અને steering મજબૂત પકડો","પસાર થવા ઝડપ વધારો","રોડની વચ્ચે ચલાવો","cruise control વાપરો"]},"ne":{"q":"बलियो crosswind मा कसरी चलाउने?","o":["ढिलो हुनुहोस् र steering दह्रोसँग समात्नुहोस्","नाघ्न गति बढाउनुहोस्","सडकको बीचमा चलाउनुहोस्","cruise control प्रयोग गर्नुहोस्"]}}},
{"id":9038,"chapter":9,"q":"Why should you brake gently and progressively in normal driving?","options":["It saves the battery","It’s smoother, warns others and reduces the risk of skidding","It wears the brakes faster","It’s quicker"],"answer":1,"exp":{"hi":"धीरे brake से पीछे वाले को समय मिलता है और skid का ख़तरा कम होता है।","pa":"ਹੌਲੀ brake ਨਾਲ ਪਿੱਛੇ ਵਾਲੇ ਨੂੰ ਸਮਾਂ ਮਿਲਦਾ ਹੈ ਅਤੇ skid ਦਾ ਖ਼ਤਰਾ ਘਟਦਾ ਹੈ।","ur":"آہستہ brake سے پیچھے والے کو وقت ملتا ہے اور skid کا خطرہ کم ہوتا ہے۔","bn":"(not translated yet)","te":"నెమ్మదిగా brake వేస్తే వెనుకవారికి సమయం దొరుకుతుంది, skid ప్రమాదం తగ్గుతుంది.","mr":"हळू brake केल्याने मागच्याला वेळ मिळतो आणि skid चा धोका कमी होतो.","ml":"പതുക്കെ brake ചെയ്താൽ പിന്നിലുള്ളയാൾക്ക് സമയം കിട്ടും, skid സാധ്യത കുറയും.","ta":"மெதுவான brake பின்னால் உள்ளவருக்கு நேரம் தரும், skid ஆபத்தை குறைக்கும்.","gu":"Brake ધીમે અને ક્રમશઃ મારવાથી સરળતા રહે, પાછળવાળાને ચેતવણી મળે અને skid ઘટે.","ne":"Brake बिस्तारै र क्रमशः लगाउँदा सहज हुन्छ, पछाडिकालाई चेतावनी मिल्छ र skid घट्छ।"},"tr":{"hi":{"q":"सामान्य ड्राइविंग में आपको धीरे और क्रमिक रूप से brake क्यों लगाना चाहिए?","o":["इससे battery बचती है","यह ज़्यादा सहज है, दूसरों को चेताता है और फिसलने का जोखिम कम करता है","इससे brakes जल्दी घिसते हैं","यह ज़्यादा तेज़ है"]},"pa":{"q":"ਆਮ ਡਰਾਈਵਿੰਗ ਵਿੱਚ ਤੁਹਾਨੂੰ ਹੌਲੀ ਅਤੇ ਕ੍ਰਮਵਾਰ ਢੰਗ ਨਾਲ brake ਕਿਉਂ ਲਾਉਣੀ ਚਾਹੀਦੀ ਹੈ?","o":["ਇਸ ਨਾਲ battery ਬਚਦੀ ਹੈ","ਇਹ ਵੱਧ ਸੁਚੱਜਾ ਹੈ, ਦੂਜਿਆਂ ਨੂੰ ਚੇਤਾਉਂਦਾ ਹੈ ਅਤੇ ਤਿਲਕਣ ਦਾ ਜੋਖਮ ਘਟਾਉਂਦਾ ਹੈ","ਇਸ ਨਾਲ brakes ਜਲਦੀ ਘਿਸਦੇ ਹਨ","ਇਹ ਵੱਧ ਤੇਜ਼ ਹੈ"]},"ur":{"q":"عام ڈرائیونگ میں آپ کو آہستگی اور بتدریج بریک کیوں لگانی چاہیے؟","o":["اس سے بیٹری بچتی ہے","یہ زیادہ ہموار ہے، دوسروں کو خبردار کرتی ہے اور پھسلنے کا خطرہ کم کرتی ہے","اس سے بریکیں جلد گھستی ہیں","یہ زیادہ تیز ہے"]},"bn":{"q":"স্বাভাবিক চালানোয় আপনার ধীরে ও ক্রমান্বয়ে ব্রেক করা উচিত কেন?","o":["এতে ব্যাটারি বাঁচে","এটি মসৃণ, অন্যদের সতর্ক করে এবং পিছলে যাওয়ার ঝুঁকি কমায়","এতে ব্রেক দ্রুত ক্ষয় হয়","এটি দ্রুততর"]},"te":{"q":"సాధారణ డ్రైవింగ్‌లో మెల్లగా, క్రమంగా బ్రేక్ ఎందుకు వేయాలి?","o":["ఇది బ్యాటరీ ఆదా చేస్తుంది","ఇది మరింత సాఫీగా ఉంటుంది, ఇతరులను హెచ్చరిస్తుంది, జారే ప్రమాదాన్ని తగ్గిస్తుంది","ఇది బ్రేక్‌లను త్వరగా అరిగిస్తుంది","ఇది వేగవంతమైనది"]},"mr":{"q":"सामान्य ड्रायव्हिंगमध्ये तुम्ही हळुवारपणे आणि हळूहळू ब्रेक का लावावा?","o":["ते बॅटरी वाचवते","ते अधिक सुरळीत असते, इतरांना इशारा देते आणि घसरण्याचा धोका कमी करते","ते ब्रेक लवकर झिजवते","ते जलद असते"]},"ml":{"q":"സാധാരണ ഓടിക്കുമ്പോൾ പതുക്കെയും ക്രമേണയും brake ചെയ്യേണ്ടത് എന്തുകൊണ്ട്?","o":["ബാറ്ററി ലാഭിക്കും","അത് സുഗമമാണ്, മറ്റുള്ളവർക്ക് മുന്നറിയിപ്പ് നൽകുന്നു, skid സാധ്യത കുറയ്ക്കുന്നു","brakes വേഗം തേയും","അത് വേഗത്തിലാണ്"]},"ta":{"q":"சாதாரண ஓட்டத்தில் ஏன் மென்மையாகவும் படிப்படியாகவும் brake போட வேண்டும்?","o":["battery சேமிக்கும்","சீராக இருக்கும், மற்றவர்களை எச்சரிக்கும், skid ஆபத்தை குறைக்கும்","brakes வேகமாக தேயும்","விரைவானது"]},"gu":{"q":"સામાન્ય ચલાવતાં brake ધીમે અને ક્રમશઃ કેમ મારવો?","o":["બેટરી બચાવે","તે સરળ છે, બીજાને ચેતવે છે અને skid નું જોખમ ઘટાડે","તે brakes ને ઝડપથી ઘસે","તે ઝડપી છે"]},"ne":{"q":"सामान्य चलाइमा brake बिस्तारै र क्रमशः किन लगाउने?","o":["ब्याट्री बचाउँछ","यो सहज हुन्छ, अरूलाई चेतावनी दिन्छ र skid को जोखिम घटाउँछ","यसले brakes छिटो खियाउँछ","यो छिटो छ"]}}},
{"id":9039,"chapter":9,"q":"In a car with automatic transmission, what is ‘creep’?","options":["The handbrake slipping","A fault with the gears","The car moves slowly in Drive without pressing the accelerator","The engine stalling"],"answer":2,"exp":{"hi":"Drive में पैर हटाते ही गाड़ी धीरे खिसकती है। खड़े होने पर brake दबाए रखो।","pa":"Drive ਵਿੱਚ ਪੈਰ ਹਟਾਉਂਦੇ ਹੀ ਗੱਡੀ ਹੌਲੀ ਖਿਸਕਦੀ ਹੈ। ਖੜ੍ਹੇ ਹੋਣ ’ਤੇ brake ਦਬਾਈ ਰੱਖੋ।","ur":"Drive میں پاؤں ہٹاتے ہی گاڑی آہستہ کھسکتی ہے۔ کھڑے ہونے پر brake دبائے رکھیں۔","bn":"(not translated yet)","te":"Drive లో కాలు తీయగానే వాహనం నెమ్మదిగా జరుగుతుంది. ఆగి ఉన్నప్పుడు brake నొక్కి ఉంచండి.","mr":"Drive मध्ये पाय काढताच गाडी हळू सरकते. थांबलेले असताना brake दाबून ठेवा.","ml":"Drive-ൽ ഇട്ടിരിക്കെ കാലെടുത്താൽ കാർ പതുക്കെ നീങ്ങും. നിർത്തിയിരിക്കുമ്പോൾ brake അമർത്തിപ്പിടിക്കുക.","ta":"Drive-இல் பாதத்தை எடுத்ததும் கார் மெதுவாக நகரும். நிற்கும்போது brake-ஐ அழுத்தி வையுங்கள்.","gu":"Automatic માં creep = accelerator દબાવ્યા વગર Drive માં કાર ધીમે સરકે. Brake દબાવી રાખો.","ne":"Automatic मा creep = accelerator नथिची Drive मा कार बिस्तारै सर्नु। Brake थिचिराख्नुहोस्।"},"tr":{"hi":{"q":"automatic transmission वाली कार में 'creep' क्या है?","o":["handbrake का खिसकना","gears में ख़राबी","accelerator दबाए बिना Drive में कार का धीरे-धीरे चलना","इंजन का बंद हो जाना (stalling)"]},"pa":{"q":"automatic transmission ਵਾਲੀ ਕਾਰ ਵਿੱਚ 'creep' ਕੀ ਹੈ?","o":["handbrake ਦਾ ਖਿਸਕਣਾ","gears ਵਿੱਚ ਖ਼ਰਾਬੀ","accelerator ਦਬਾਏ ਬਿਨਾਂ Drive ਵਿੱਚ ਕਾਰ ਦਾ ਹੌਲੀ-ਹੌਲੀ ਚੱਲਣਾ","ਇੰਜਣ ਦਾ ਬੰਦ ਹੋ ਜਾਣਾ (stalling)"]},"ur":{"q":"خودکار ٹرانسمیشن والی کار میں 'کریپ' کیا ہے؟","o":["ہینڈ بریک کا پھسلنا","گیئرز میں خرابی","ایکسیلریٹر دبائے بغیر ڈرائیو میں کار کا آہستہ آہستہ حرکت کرنا","انجن کا بند ہو جانا"]},"bn":{"q":"অটোমেটিক ট্রান্সমিশনের গাড়িতে 'ক্রিপ' কী?","o":["হ্যান্ডব্রেক পিছলে যাওয়া","গিয়ারে ত্রুটি","অ্যাক্সিলারেটর না চেপেও ড্রাইভ মোডে গাড়ির ধীরে চলা","ইঞ্জিন বন্ধ হয়ে যাওয়া"]},"te":{"q":"ఆటోమేటిక్ ట్రాన్స్‌మిషన్ ఉన్న కారులో 'క్రీప్' అంటే ఏమిటి?","o":["హ్యాండ్‌బ్రేక్ జారడం","గేర్లలో లోపం","యాక్సిలరేటర్ నొక్కకుండానే డ్రైవ్‌లో కారు నెమ్మదిగా కదలడం","ఇంజిన్ ఆగిపోవడం (stalling)"]},"mr":{"q":"ऑटोमॅटिक ट्रान्समिशन असलेल्या कारमध्ये ‘creep’ म्हणजे काय?","o":["हँडब्रेक सरकणे","गिअरमधील बिघाड","अ‍ॅक्सिलरेटर न दाबता Drive मध्ये कार हळू सरकणे","इंजिन बंद पडणे"]},"ml":{"q":"automatic transmission ഉള്ള കാറിൽ ‘creep’ എന്നാൽ എന്താണ്?","o":["handbrake തെന്നുന്നത്","gears-ലെ തകരാർ","accelerator അമർത്താതെ Drive-ൽ കാർ പതുക്കെ നീങ്ങുന്നത്","എൻജിൻ നിന്നുപോകുന്നത്"]},"ta":{"q":"automatic transmission கார்களில் 'creep' என்றால் என்ன?","o":["handbrake நழுவுவது","gears-இல் கோளாறு","Drive-இல் accelerator அழுத்தாமல் கார் மெதுவாக நகர்வது","engine நின்றுவிடுவது"]},"gu":{"q":"automatic ટ્રાન્સમિશન વાળી કારમાં 'creep' એટલે શું?","o":["handbrake સરકવી","gears માં ખામી","accelerator દબાવ્યા વગર Drive માં કાર ધીમે ચાલે","એંજિન stall થવું"]},"ne":{"q":"automatic transmission भएको कारमा 'creep' भनेको के हो?","o":["handbrake चिप्लनु","gears मा खराबी","accelerator नथिची Drive मा कार बिस्तारै सर्नु","इन्जिन stall हुनु"]}}},
{"id":9040,"chapter":9,"q":"In an automatic car, what does pressing the accelerator fully down (kickdown) do?","options":["Turns the engine off","Changes to a higher gear","Applies the brakes","Changes to a lower gear for quick acceleration"],"answer":3,"exp":{"hi":"Kickdown से gear नीचे आता है और गाड़ी तेज़ी से speed पकड़ती है, जैसे overtake के लिए।","pa":"Kickdown ਨਾਲ gear ਹੇਠਾਂ ਆਉਂਦਾ ਹੈ ਅਤੇ ਗੱਡੀ ਤੇਜ਼ੀ ਨਾਲ speed ਫੜਦੀ ਹੈ, ਜਿਵੇਂ overtake ਲਈ।","ur":"Kickdown سے gear نیچے آتا ہے اور گاڑی تیزی سے speed پکڑتی ہے، جیسے overtake کے لیے۔","bn":"(not translated yet)","te":"Kickdown తో gear కిందికి వస్తుంది, వాహనం వేగంగా speed అందుకుంటుంది, ఉదా. overtake కోసం.","mr":"Kickdown ने gear खाली येतो आणि गाडी वेगाने speed पकडते, जसे overtake साठी.","ml":"Kickdown gear താഴ്ത്തുന്നു, കാർ വേഗം speed പിടിക്കുന്നു, ഉദാ. ഓവർടേക്ക് ചെയ്യാൻ.","ta":"Kickdown gear-ஐ குறைத்து கார் வேகமாக வேகம் பிடிக்கும், உதாரணம் முந்துவதற்கு.","gu":"Kickdown = accelerator પૂરેપૂરું દબાવો ત્યારે નીચા gear માં બદલાઈ ઝડપી acceleration આપે (ઓવરટેક માટે).","ne":"Kickdown = accelerator पूरै थिच्दा होचो gear मा बदलिएर छिटो acceleration दिन्छ (overtake का लागि)।"},"tr":{"hi":{"q":"automatic कार में accelerator को पूरा दबाने (kickdown) से क्या होता है?","o":["इंजन बंद हो जाता है","ऊँचे gear में बदल जाता है","brakes लग जाते हैं","तेज़ acceleration के लिए नीचे के gear में बदल जाता है"]},"pa":{"q":"automatic ਕਾਰ ਵਿੱਚ accelerator ਨੂੰ ਪੂਰਾ ਦਬਾਉਣ (kickdown) ਨਾਲ ਕੀ ਹੁੰਦਾ ਹੈ?","o":["ਇੰਜਣ ਬੰਦ ਹੋ ਜਾਂਦਾ ਹੈ","ਉੱਚੇ gear ਵਿੱਚ ਬਦਲ ਜਾਂਦਾ ਹੈ","brakes ਲੱਗ ਜਾਂਦੇ ਹਨ","ਤੇਜ਼ acceleration ਲਈ ਨੀਵੇਂ gear ਵਿੱਚ ਬਦਲ ਜਾਂਦਾ ਹੈ"]},"ur":{"q":"خودکار کار میں ایکسیلریٹر کو پورا دبانے (کک ڈاؤن) سے کیا ہوتا ہے؟","o":["انجن بند ہو جاتا ہے","اونچے گیئر میں تبدیل ہو جاتا ہے","بریکیں لگ جاتی ہیں","تیز رفتار بڑھانے کے لیے نچلے گیئر میں تبدیل ہو جاتا ہے"]},"bn":{"q":"অটোমেটিক গাড়িতে অ্যাক্সিলারেটর পুরোপুরি চেপে ধরলে (কিকডাউন) কী হয়?","o":["ইঞ্জিন বন্ধ হয়ে যায়","উঁচু গিয়ারে বদলে যায়","ব্রেক লেগে যায়","দ্রুত গতি বাড়াতে নিচু গিয়ারে বদলে যায়"]},"te":{"q":"ఆటోమేటిక్ కారులో యాక్సిలరేటర్‌ను పూర్తిగా నొక్కితే (kickdown) ఏమి జరుగుతుంది?","o":["ఇంజిన్ ఆగిపోతుంది","ఎత్తైన గేర్‌కు మారుతుంది","బ్రేక్‌లు పడతాయి","వేగవంతమైన వేగవృద్ధి కోసం తక్కువ గేర్‌కు మారుతుంది"]},"mr":{"q":"ऑटोमॅटिक कारमध्ये अ‍ॅक्सिलरेटर पूर्ण दाबल्यास (kickdown) काय होते?","o":["इंजिन बंद होते","वरच्या गिअरमध्ये बदलते","ब्रेक लागतात","जलद अ‍ॅक्सिलरेशनसाठी कमी गिअरमध्ये बदलते"]},"ml":{"q":"automatic കാറിൽ accelerator പൂർണ്ണമായി അമർത്തുന്നത് (kickdown) എന്താണ് ചെയ്യുന്നത്?","o":["എൻജിൻ ഓഫ് ചെയ്യുന്നു","ഉയർന്ന gear-ലേക്ക് മാറ്റുന്നു","brakes ഇടുന്നു","വേഗത്തിൽ accelerate ചെയ്യാൻ താഴ്ന്ന gear-ലേക്ക് മാറ്റുന്നു"]},"ta":{"q":"automatic காரில் accelerator-ஐ முழுமையாக அழுத்துவது (kickdown) என்ன செய்கிறது?","o":["engine-ஐ அணைக்கும்","உயர்ந்த gear-க்கு மாற்றும்","brakes-ஐ பயன்படுத்தும்","விரைவான வேகமெடுப்புக்காக குறைந்த gear-க்கு மாற்றும்"]},"gu":{"q":"automatic કારમાં accelerator પૂરેપૂરું દબાવવાથી (kickdown) શું થાય?","o":["એંજિન બંધ થાય","ઊંચા gear માં બદલાય","brakes લાગે","ઝડપી acceleration માટે નીચા gear માં બદલાય"]},"ne":{"q":"automatic कारमा accelerator पूरै थिच्दा (kickdown) के हुन्छ?","o":["इन्जिन बन्द हुन्छ","माथिल्लो gear मा बदलिन्छ","brakes लाग्छन्","छिटो acceleration का लागि होचो gear मा बदलिन्छ"]}}},
{"id":9041,"chapter":9,"q":"Why shouldn't you drive with your foot resting on the clutch pedal?","options":["It wears the clutch","It saves fuel","It improves control","It's required"],"answer":0,"exp":{"hi":"Clutch पर पैर रखने से वह घिसता है। Gear बदलने के सिवा पैर हटाकर रखें।","pa":"Clutch 'ਤੇ ਪੈਰ ਰੱਖਣ ਨਾਲ ਉਹ ਘਸਦਾ ਹੈ। Gear ਬਦਲਣ ਤੋਂ ਇਲਾਵਾ ਪੈਰ ਹਟਾ ਕੇ ਰੱਖੋ।","ur":"clutch پر پاؤں رکھنے سے وہ گھستا ہے۔ gear بدلنے کے علاوہ پاؤں ہٹا کر رکھیں۔","bn":"clutch-এ পা রাখলে ক্ষয় হয়। gear বদলানো ছাড়া পা সরিয়ে রাখুন।","te":"clutch పై కాలు ఉంచితే అది అరుగుతుంది. gear మార్చేటప్పుడు తప్ప కాలు తీసేయండి.","mr":"clutch वर पाय ठेवल्याने तो झिजतो. gear बदलताना वगळता पाय काढून ठेवा.","ml":"clutch-ൽ കാൽ വച്ചാൽ അത് തേയും. gear മാറ്റുമ്പോൾ ഒഴികെ കാൽ എടുത്തുമാറ്റുക.","ta":"clutch மீது கால் வைத்தால் அது தேயும். gear மாற்றும்போது தவிர காலை எடுத்துவிடுங்கள்.","gu":"clutch પર પગ રાખવાથી તે ઘસાય છે. gear બદલતી વખતે સિવાય પગ હટાવી રાખો.","ne":"clutch मा खुट्टा राख्दा त्यो घिसिन्छ। gear बदल्ने बेलाबाहेक खुट्टा हटाइराख्नुहोस्।"},"tr":{"hi":{"q":"Clutch pedal पर पैर रखकर गाड़ी क्यों नहीं चलानी चाहिए?","o":["Clutch घिसता है","ईंधन बचता है","नियंत्रण बेहतर होता है","यह ज़रूरी है"]},"pa":{"q":"Clutch pedal 'ਤੇ ਪੈਰ ਰੱਖ ਕੇ ਗੱਡੀ ਕਿਉਂ ਨਹੀਂ ਚਲਾਉਣੀ ਚਾਹੀਦੀ?","o":["Clutch ਘਸਦਾ ਹੈ","ਤੇਲ ਬਚਦਾ ਹੈ","ਕਾਬੂ ਬਿਹਤਰ ਹੁੰਦਾ ਹੈ","ਇਹ ਜ਼ਰੂਰੀ ਹੈ"]},"ur":{"q":"clutch pedal پر پاؤں رکھ کر گاڑی کیوں نہیں چلانی چاہیے؟","o":["clutch گھس جاتا ہے","ایندھن بچتا ہے","کنٹرول بہتر ہوتا ہے","یہ ضروری ہے"]},"bn":{"q":"clutch pedal-এ পা রেখে গাড়ি চালানো উচিত নয় কেন?","o":["clutch ক্ষয় হয়","জ্বালানি বাঁচে","নিয়ন্ত্রণ ভালো হয়","এটি আবশ্যক"]},"te":{"q":"clutch pedal పై కాలు ఉంచి ఎందుకు నడపకూడదు?","o":["clutch అరిగిపోతుంది","ఇంధనం ఆదా అవుతుంది","నియంత్రణ మెరుగవుతుంది","ఇది తప్పనిసరి"]},"mr":{"q":"clutch pedal वर पाय ठेवून गाडी का चालवू नये?","o":["clutch झिजतो","इंधन वाचते","नियंत्रण चांगले राहते","हे आवश्यक आहे"]},"ml":{"q":"clutch pedal-ൽ കാൽ വച്ച് ഓടിക്കരുത് എന്തുകൊണ്ട്?","o":["clutch തേയുന്നു","ഇന്ധനം ലാഭിക്കുന്നു","നിയന്ത്രണം മെച്ചപ്പെടുന്നു","ഇത് നിർബന്ധമാണ്"]},"ta":{"q":"clutch pedal மீது காலை வைத்து ஏன் ஓட்டக் கூடாது?","o":["clutch தேயும்","எரிபொருள் சேமிக்கும்","கட்டுப்பாடு மேம்படும்","இது கட்டாயம்"]},"gu":{"q":"clutch pedal પર પગ રાખીને ગાડી કેમ ન ચલાવવી?","o":["clutch ઘસાય છે","બળતણ બચે છે","કાબૂ સારો રહે છે","તે જરૂરી છે"]},"ne":{"q":"clutch pedal मा खुट्टा राखेर किन चलाउनु हुँदैन?","o":["clutch घिसिन्छ","इन्धन बचत हुन्छ","नियन्त्रण राम्रो हुन्छ","यो आवश्यक छ"]}}},
{"id":9042,"chapter":9,"q":"You're driving a manual car downhill. Which gear helps control your speed?","options":["Neutral","A lower gear","The highest gear","Reverse"],"answer":1,"exp":{"hi":"कम gear से engine braking मिलती है और brakes ठंडे रहते हैं।","pa":"ਘੱਟ gear ਨਾਲ engine braking ਮਿਲਦੀ ਹੈ ਅਤੇ brakes ਠੰਢੇ ਰਹਿੰਦੇ ਹਨ।","ur":"نچلا gear engine braking دیتا ہے اور brakes کو ٹھنڈا رکھتا ہے۔","bn":"নিচের gear engine braking দেয় এবং brakes ঠান্ডা রাখে।","te":"తక్కువ gear engine braking ఇస్తుంది, brakes ను చల్లగా ఉంచుతుంది.","mr":"खालचा gear engine braking देतो आणि brakes थंड ठेवतो.","ml":"താഴ്ന്ന gear engine braking നൽകുകയും brakes-നെ തണുപ്പിച്ച് നിർത്തുകയും ചെയ്യുന്നു.","ta":"குறைந்த gear engine braking தந்து brakes-ஐக் குளிர்ச்சியாக வைக்கிறது.","gu":"નીચો gear engine braking આપે છે અને brakes ને ઠંડા રાખે છે.","ne":"तल्लो gear ले engine braking दिन्छ र brake हरूलाई चिसो राख्छ।"},"tr":{"hi":{"q":"आप manual car से ढलान उतर रहे हैं। Speed क़ाबू में रखने में कौन-सा gear मदद करता है?","o":["Neutral","कम gear","सबसे ऊँचा gear","Reverse"]},"pa":{"q":"ਤੁਸੀਂ manual car ਨਾਲ ਢਲਾਣ ਉਤਰ ਰਹੇ ਹੋ। Speed ਕਾਬੂ ਵਿੱਚ ਰੱਖਣ ਲਈ ਕਿਹੜਾ gear ਮਦਦ ਕਰਦਾ ਹੈ?","o":["Neutral","ਘੱਟ gear","ਸਭ ਤੋਂ ਉੱਚਾ gear","Reverse"]},"ur":{"q":"آپ manual car میں ڈھلان سے اتر رہے ہیں۔ رفتار قابو میں رکھنے کے لیے کون سا gear مدد کرتا ہے؟","o":["neutral","نچلا gear","سب سے اونچا gear","reverse"]},"bn":{"q":"আপনি manual car নিয়ে ঢাল বেয়ে নামছেন। গতি নিয়ন্ত্রণে কোন gear সাহায্য করে?","o":["neutral","নিচের gear","সবচেয়ে ওপরের gear","reverse"]},"te":{"q":"మీరు manual car తో వాలు దిగుతున్నారు. వేగాన్ని నియంత్రించడానికి ఏ gear సహాయపడుతుంది?","o":["neutral","తక్కువ gear","అత్యధిక gear","reverse"]},"mr":{"q":"तुम्ही manual car ने उतारावरून उतरत आहात. वेग नियंत्रणात ठेवण्यासाठी कोणता gear मदत करतो?","o":["neutral","खालचा gear","सर्वात वरचा gear","reverse"]},"ml":{"q":"നിങ്ങൾ manual car ഉപയോഗിച്ച് ഇറക്കമിറങ്ങുന്നു. വേഗം നിയന്ത്രിക്കാൻ ഏത് gear സഹായിക്കും?","o":["neutral","താഴ്ന്ന gear","ഏറ്റവും ഉയർന്ന gear","reverse"]},"ta":{"q":"நீங்கள் manual car-ல் மலையிறக்கத்தில் செல்கிறீர்கள். வேகத்தைக் கட்டுப்படுத்த எந்த gear உதவும்?","o":["neutral","குறைந்த gear","மிக உயர்ந்த gear","reverse"]},"gu":{"q":"તમે manual car સાથે ઢાળ ઉતરો છો. ઝડપ કાબૂમાં રાખવા કયો gear મદદ કરે?","o":["neutral","નીચો gear","સૌથી ઊંચો gear","reverse"]},"ne":{"q":"तपाईं manual car लिएर ओरालो झर्दै हुनुहुन्छ। गति नियन्त्रण गर्न कुन gear ले मद्दत गर्छ?","o":["neutral","तल्लो gear","सबैभन्दा माथिल्लो gear","reverse"]}}},
{"id":9043,"chapter":9,"q":"When is the best time to change gear on a bend?","options":["On the bend","Before the bend","Halfway","After the bend"],"answer":1,"exp":{"hi":"मोड़ से पहले gear बदलें ताकि दोनों हाथ steering पर रहें।","pa":"ਮੋੜ ਤੋਂ ਪਹਿਲਾਂ gear ਬਦਲੋ ਤਾਂ ਜੋ ਦੋਵੇਂ ਹੱਥ steering 'ਤੇ ਰਹਿਣ।","ur":"موڑ سے پہلے gear بدلیں تاکہ دونوں ہاتھ steering پر رہیں۔","bn":"বাঁকের আগে gear বদলান যাতে দুই হাত steering-এ থাকে।","te":"మలుపుకు ముందు gear మార్చండి, అప్పుడు రెండు చేతులు steering పై ఉంటాయి.","mr":"वळणाआधी gear बदला म्हणजे दोन्ही हात steering वर राहतील.","ml":"വളവിന് മുമ്പ് gear മാറ്റുക, അപ്പോൾ രണ്ട് കൈകളും steering-ൽ വയ്ക്കാം.","ta":"வளைவுக்கு முன் gear மாற்றுங்கள், அப்போது இரு கைகளும் steering-ல் இருக்கும்.","gu":"વળાંક પહેલાં gear બદલો જેથી બંને હાથ steering પર રહે.","ne":"मोडअघि gear बदल्नुहोस् ताकि दुवै हात steering मा रहून्।"},"tr":{"hi":{"q":"मोड़ पर gear बदलने का सबसे अच्छा समय कौन-सा है?","o":["मोड़ पर","मोड़ से पहले","बीच में","मोड़ के बाद"]},"pa":{"q":"ਮੋੜ 'ਤੇ gear ਬਦਲਣ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਸਮਾਂ ਕਿਹੜਾ ਹੈ?","o":["ਮੋੜ 'ਤੇ","ਮੋੜ ਤੋਂ ਪਹਿਲਾਂ","ਵਿਚਕਾਰ","ਮੋੜ ਤੋਂ ਬਾਅਦ"]},"ur":{"q":"موڑ پر gear بدلنے کا بہترین وقت کون سا ہے؟","o":["موڑ پر","موڑ سے پہلے","بیچ میں","موڑ کے بعد"]},"bn":{"q":"বাঁকে gear বদলানোর সেরা সময় কখন?","o":["বাঁকের মধ্যে","বাঁকের আগে","মাঝামাঝি","বাঁকের পরে"]},"te":{"q":"మలుపు వద్ద gear మార్చడానికి ఉత్తమ సమయం ఏది?","o":["మలుపులో","మలుపుకు ముందు","మధ్యలో","మలుపు తర్వాత"]},"mr":{"q":"वळणावर gear बदलण्याची सर्वोत्तम वेळ कोणती?","o":["वळणावर","वळणाआधी","मध्येच","वळणानंतर"]},"ml":{"q":"വളവിൽ gear മാറ്റാൻ ഏറ്റവും നല്ല സമയം ഏതാണ്?","o":["വളവിൽ","വളവിന് മുമ്പ്","പാതിവഴിയിൽ","വളവിന് ശേഷം"]},"ta":{"q":"வளைவில் gear மாற்ற சிறந்த நேரம் எது?","o":["வளைவில்","வளைவுக்கு முன்","பாதியில்","வளைவுக்குப் பின்"]},"gu":{"q":"વળાંક પર gear બદલવાનો શ્રેષ્ઠ સમય કયો?","o":["વળાંક પર","વળાંક પહેલાં","અધવચ્ચે","વળાંક પછી"]},"ne":{"q":"मोडमा gear बदल्ने उत्तम समय कुन हो?","o":["मोडमा","मोडभन्दा अघि","बीचमा","मोडपछि"]}}},
{"id":9044,"chapter":9,"q":"What's the safest way to brake on a wet road?","options":["Brake early and gently","Brake hard late","Don't brake","Use the handbrake"],"answer":0,"exp":{"hi":"जल्दी और धीरे brake लगाने से grip बनी रहती है और skid नहीं होता।","pa":"ਜਲਦੀ ਅਤੇ ਹੌਲੀ brake ਲਾਉਣ ਨਾਲ grip ਬਣੀ ਰਹਿੰਦੀ ਹੈ ਅਤੇ skid ਨਹੀਂ ਹੁੰਦਾ।","ur":"جلدی اور آہستہ brake لگانے سے گرفت برقرار رہتی ہے اور skid نہیں ہوتا۔","bn":"আগে ও আস্তে brake করলে গ্রিপ থাকে এবং skid এড়ানো যায়।","te":"ముందుగా, మెల్లగా brake వేస్తే పట్టు నిలిచి skid కాకుండా ఉంటుంది.","mr":"लवकर आणि हळू brake लावल्यास पकड टिकते आणि skid टळतो.","ml":"നേരത്തേയും പതുക്കെയും brake ചെയ്താൽ പിടുത്തം നിലനിൽക്കുകയും skid ഒഴിവാകുകയും ചെയ്യും.","ta":"முன்கூட்டியே மெதுவாக brake போட்டால் பிடிப்பு நிலைக்கும், skid ஆகாது.","gu":"વહેલા અને ધીમે brake લગાવવાથી પકડ ટકે છે અને skid ટળે છે.","ne":"चाँडै र बिस्तारै brake लगाउँदा पकड टिक्छ र skid रोकिन्छ।"},"tr":{"hi":{"q":"भीगी सड़क पर brake लगाने का सबसे सुरक्षित तरीक़ा क्या है?","o":["जल्दी और धीरे brake लगाएँ","देर से ज़ोर से brake लगाएँ","brake न लगाएँ","Handbrake इस्तेमाल करें"]},"pa":{"q":"ਭਿੱਜੀ ਸੜਕ 'ਤੇ brake ਲਾਉਣ ਦਾ ਸਭ ਤੋਂ ਸੁਰੱਖਿਅਤ ਤਰੀਕਾ ਕੀ ਹੈ?","o":["ਜਲਦੀ ਅਤੇ ਹੌਲੀ brake ਲਾਓ","ਦੇਰ ਨਾਲ ਜ਼ੋਰ ਨਾਲ brake ਲਾਓ","brake ਨਾ ਲਾਓ","Handbrake ਵਰਤੋ"]},"ur":{"q":"گیلی سڑک پر brake لگانے کا سب سے محفوظ طریقہ کیا ہے؟","o":["جلدی اور آہستہ brake لگائیں","دیر سے زور سے brake لگائیں","brake نہ لگائیں","handbrake استعمال کریں"]},"bn":{"q":"ভেজা রাস্তায় brake করার সবচেয়ে নিরাপদ উপায় কী?","o":["আগে ও আস্তে brake করুন","দেরিতে জোরে brake করুন","brake করবেন না","handbrake ব্যবহার করুন"]},"te":{"q":"తడి రోడ్డుపై brake వేయడానికి అత్యంత సురక్షిత మార్గం ఏది?","o":["ముందుగా, మెల్లగా brake వేయండి","ఆలస్యంగా గట్టిగా brake వేయండి","brake వేయకండి","handbrake వాడండి"]},"mr":{"q":"ओल्या रस्त्यावर brake लावण्याची सर्वात सुरक्षित पद्धत कोणती?","o":["लवकर आणि हळू brake लावा","उशिरा जोरात brake लावा","brake लावू नका","handbrake वापरा"]},"ml":{"q":"നനഞ്ഞ റോഡിൽ brake ചെയ്യാനുള്ള ഏറ്റവും സുരക്ഷിത മാർഗ്ഗം ഏതാണ്?","o":["നേരത്തേയും പതുക്കെയും brake ചെയ്യുക","വൈകി ശക്തമായി brake ചെയ്യുക","brake ചെയ്യാതിരിക്കുക","handbrake ഉപയോഗിക്കുക"]},"ta":{"q":"ஈரச் சாலையில் brake போட மிகப் பாதுகாப்பான வழி எது?","o":["முன்கூட்டியே மெதுவாக brake போடவும்","தாமதமாக அழுத்தமாக brake போடவும்","brake போடாதீர்கள்","handbrake பயன்படுத்தவும்"]},"gu":{"q":"ભીના રસ્તા પર brake લગાવવાની સૌથી સલામત રીત કઈ?","o":["વહેલા અને ધીમે brake લગાવો","મોડા જોરથી brake લગાવો","brake ન લગાવો","handbrake વાપરો"]},"ne":{"q":"भिजेको सडकमा brake लगाउने सबैभन्दा सुरक्षित तरिका कुन हो?","o":["चाँडै र बिस्तारै brake लगाउनुहोस्","ढिलो गरी जोडले brake लगाउनुहोस्","brake नलगाउनुहोस्","handbrake प्रयोग गर्नुहोस्"]}}},
{"id":9045,"chapter":9,"q":"How should you start moving off on a slippery road?","options":["Use high revs","Use a higher gear such as second, gently","Use low gear fast","Spin the wheels"],"answer":1,"exp":{"hi":"Second gear में धीरे से शुरू करने पर फिसलन वाली सतह पर wheelspin से बचाव होता है।","pa":"Second gear ਵਿੱਚ ਹੌਲੀ ਸ਼ੁਰੂ ਕਰਨ ਨਾਲ ਤਿਲਕਣ ਵਾਲੀ ਸਤ੍ਹਾ 'ਤੇ wheelspin ਤੋਂ ਬਚਾਅ ਹੁੰਦਾ ਹੈ।","ur":"second gear میں آہستہ شروع کرنے سے پھسلن والی سطح پر wheelspin سے بچاؤ ہوتا ہے۔","bn":"second gear-এ ধীরে শুরু করলে পিচ্ছিল তলে wheelspin এড়ানো যায়।","te":"second gear లో మెల్లగా మొదలుపెడితే జారే ఉపరితలాలపై wheelspin తప్పుతుంది.","mr":"second gear मध्ये हळू सुरुवात केल्यास निसरड्या पृष्ठभागावर wheelspin टळतो.","ml":"second gear-ൽ പതുക്കെ തുടങ്ങുന്നത് വഴുക്കലുള്ള പ്രതലങ്ങളിൽ wheelspin ഒഴിവാക്കാൻ സഹായിക്കുന്നു.","ta":"second gear-ல் மெதுவாகத் தொடங்கினால் வழுக்கும் மேற்பரப்புகளில் wheelspin தவிர்க்கப்படும்.","gu":"second gear માં ધીમી શરૂઆત લપસણી સપાટી પર wheelspin ટાળવામાં મદદ કરે છે.","ne":"second gear मा बिस्तारै सुरु गर्दा चिप्लो सतहमा wheelspin रोक्न मद्दत मिल्छ।"},"tr":{"hi":{"q":"फिसलन वाली सड़क पर गाड़ी कैसे आगे बढ़ाएँ?","o":["ज़्यादा revs लें","ऊँचा gear जैसे second, धीरे से लें","कम gear में तेज़ी से","पहिए घुमाएँ"]},"pa":{"q":"ਤਿਲਕਣ ਵਾਲੀ ਸੜਕ 'ਤੇ ਗੱਡੀ ਕਿਵੇਂ ਤੋਰੋ?","o":["ਵੱਧ revs ਲਓ","ਉੱਚਾ gear ਜਿਵੇਂ second, ਹੌਲੀ ਨਾਲ ਲਓ","ਘੱਟ gear ਵਿੱਚ ਤੇਜ਼ੀ ਨਾਲ","ਪਹੀਏ ਘੁਮਾਓ"]},"ur":{"q":"پھسلن والی سڑک پر گاڑی کیسے چلانا شروع کریں؟","o":["زیادہ revs لیں","اونچا gear جیسے second، آہستہ سے لیں","نچلے gear میں تیزی سے","پہیے گھمائیں"]},"bn":{"q":"পিচ্ছিল রাস্তায় কীভাবে গাড়ি চালানো শুরু করবেন?","o":["বেশি revs নিন","ওপরের gear যেমন second, আস্তে নিন","নিচের gear-এ দ্রুত","চাকা ঘোরান"]},"te":{"q":"జారే రోడ్డుపై కదలడం ఎలా మొదలుపెట్టాలి?","o":["ఎక్కువ revs వాడండి","second వంటి పై gear లో మెల్లగా","తక్కువ gear లో వేగంగా","చక్రాలు తిప్పండి"]},"mr":{"q":"निसरड्या रस्त्यावर गाडी कशी सुरू करावी?","o":["जास्त revs वापरा","second सारखा वरचा gear, हळूवारपणे","खालच्या gear मध्ये वेगाने","चाके फिरवा"]},"ml":{"q":"വഴുക്കലുള്ള റോഡിൽ എങ്ങനെ നീങ്ങിത്തുടങ്ങണം?","o":["ഉയർന്ന revs ഉപയോഗിക്കുക","second പോലുള്ള ഉയർന്ന gear-ൽ പതുക്കെ","താഴ്ന്ന gear-ൽ വേഗത്തിൽ","ചക്രങ്ങൾ കറക്കുക"]},"ta":{"q":"வழுக்கும் சாலையில் எப்படிப் புறப்பட வேண்டும்?","o":["அதிக revs பயன்படுத்தவும்","second போன்ற உயர்ந்த gear-ல் மெதுவாக","குறைந்த gear-ல் வேகமாக","சக்கரங்களைச் சுழற்றவும்"]},"gu":{"q":"લપસણા રસ્તા પર ગાડી કેવી રીતે શરૂ કરવી?","o":["વધુ revs વાપરો","second જેવો ઊંચો gear, ધીમેથી","નીચા gear માં ઝડપથી","પૈડાં ફેરવો"]},"ne":{"q":"चिप्लो सडकमा गाडी कसरी चलाउन सुरु गर्ने?","o":["धेरै revs प्रयोग गर्नुहोस्","second जस्तो माथिल्लो gear, बिस्तारै","तल्लो gear मा छिटो","पाङ्ग्रा घुमाउनुहोस्"]}}},
{"id":10001,"chapter":10,"q":"What’s the national speed limit for cars on a motorway?","options":["70 mph","60 mph","80 mph","65 mph"],"answer":0,"exp":{"hi":"70 mph, जब तक signs कम limit न बताएँ। Caravan या trailer के साथ 60 mph।","pa":"70 mph, ਜਦ ਤੱਕ signs ਘੱਟ limit ਨਾ ਦੱਸਣ। Caravan ਜਾਂ trailer ਨਾਲ 60 mph।","ur":"70 mph، جب تک signs کم limit نہ بتائیں۔ Caravan یا trailer کے ساتھ 60 mph۔","bn":"(not translated yet)","te":"70 mph, signs తక్కువ limit చెబితే తప్ప. Caravan లేదా trailer తో 60 mph.","mr":"70 mph, जोपर्यंत signs कमी limit सांगत नाहीत. Caravan किंवा trailer सोबत 60 mph.","ml":"70 mph, signs കുറഞ്ഞ limit പറയുന്നില്ലെങ്കിൽ. Caravan അല്ലെങ്കിൽ trailer ഉള്ളപ്പോൾ 60 mph.","ta":"70 mph, signs குறைந்த வரம்பு சொல்லாத வரை. Caravan அல்லது trailer இழுக்கும்போது 60 mph.","gu":"Motorway પર કાર માટે રાષ્ટ્રીય ઝડપ મર્યાદા 70 mph છે, જ્યાં સુધી બીજી મર્યાદા દર્શાવી ન હોય.","ne":"कारका लागि motorway को राष्ट्रिय गति सीमा 70 mph हो।"},"tr":{"hi":{"q":"मोटरवे पर कारों के लिए national speed limit क्या है?","o":["70 mph","60 mph","80 mph","65 mph"]},"pa":{"q":"ਮੋਟਰਵੇ 'ਤੇ ਕਾਰਾਂ ਲਈ national speed limit ਕੀ ਹੈ?","o":["70 mph","60 mph","80 mph","65 mph"]},"ur":{"q":"موٹروے پر کاروں کے لیے قومی رفتار کی حد کیا ہے؟","o":["70 mph","60 mph","80 mph","65 mph"]},"bn":{"q":"মোটরওয়েতে গাড়ির জন্য জাতীয় গতিসীমা কত?","o":["৭০ mph","৬০ mph","৮০ mph","৬৫ mph"]},"te":{"q":"మోటార్‌వేపై కార్లకు జాతీయ వేగ పరిమితి ఎంత?","o":["70 mph","60 mph","80 mph","65 mph"]},"mr":{"q":"मोटरवेवर कारसाठी राष्ट्रीय वेगमर्यादा किती?","o":["७० mph","६० mph","८० mph","६५ mph"]},"ml":{"q":"മോട്ടോർവേയിൽ കാറുകൾക്കുള്ള national speed limit എത്രയാണ്?","o":["70 mph","60 mph","80 mph","65 mph"]},"ta":{"q":"மோட்டார்வேயில் கார்களுக்கான தேசிய வேக வரம்பு என்ன?","o":["70 mph","60 mph","80 mph","65 mph"]},"gu":{"q":"motorway પર કાર માટે રાષ્ટ્રીય ઝડપ મર્યાદા કેટલી છે?","o":["70 mph","60 mph","80 mph","65 mph"]},"ne":{"q":"motorway मा कारका लागि राष्ट्रिय गति सीमा कति हो?","o":["70 mph","60 mph","80 mph","65 mph"]}}},
{"id":10002,"chapter":10,"q":"What colour are the reflective studs between the left-hand lane and the hard shoulder?","options":["Green","Red","White","Amber"],"answer":1,"exp":{"hi":"Red = बाईं किनारी। White = lanes के बीच। Amber = central reservation। Green = slip roads।","pa":"Red = ਖੱਬਾ ਕਿਨਾਰਾ। White = lanes ਵਿਚਕਾਰ। Amber = central reservation। Green = slip roads।","ur":"Red = بایاں کنارہ۔ White = lanes کے درمیان۔ Amber = central reservation۔ Green = slip roads۔","bn":"(not translated yet)","te":"Red = ఎడమ అంచు. White = lanes మధ్య. Amber = central reservation. Green = slip roads.","mr":"Red = डावी कड. White = lanes च्या मध्ये. Amber = central reservation. Green = slip roads.","ml":"Red = ഇടത് അരിക്. White = lanes-ക്കിടയിൽ. Amber = central reservation. Green = slip roads.","ta":"சிவப்பு = இடது ஓரம். வெள்ளை = lanes இடையே. Amber = central reservation. பச்சை = slip roads.","gu":"ડાબી lane અને hard shoulder વચ્ચે લાલ studs. જમણી બાજુ (central reservation) amber. Lanes વચ્ચે સફેદ. Slip roads પર લીલા.","ne":"बायाँ lane र hard shoulder बीचका studs रातो हुन्छन्।"},"tr":{"hi":{"q":"बाईं तरफ़ की lane और hard shoulder के बीच की reflective studs किस रंग की होती हैं?","o":["हरी","लाल","सफ़ेद","amber (पीली)"]},"pa":{"q":"ਖੱਬੀ lane ਅਤੇ hard shoulder ਵਿਚਕਾਰਲੀਆਂ reflective studs ਕਿਸ ਰੰਗ ਦੀਆਂ ਹੁੰਦੀਆਂ ਹਨ?","o":["ਹਰੀਆਂ","ਲਾਲ","ਚਿੱਟੀਆਂ","amber (ਪੀਲੀਆਂ)"]},"ur":{"q":"بائیں لین اور ہارڈ شولڈر کے درمیان ریفلیکٹر اسٹڈز کس رنگ کے ہوتے ہیں؟","o":["سبز","سرخ","سفید","امبر (زرد)"]},"bn":{"q":"বাঁ দিকের লেন ও হার্ড শোল্ডারের মাঝের প্রতিফলক স্টাড কোন রঙের?","o":["সবুজ","লাল","সাদা","অ্যাম্বার (হলুদ)"]},"te":{"q":"ఎడమ లేన్‌కు, హార్డ్ షోల్డర్‌కు మధ్య ఉన్న రిఫ్లెక్టివ్ స్టడ్‌లు ఏ రంగులో ఉంటాయి?","o":["ఆకుపచ్చ","ఎరుపు","తెలుపు","అంబర్ (పసుపు)"]},"mr":{"q":"डाव्या लेन आणि hard shoulder मधील परावर्तक स्टड कोणत्या रंगाचे असतात?","o":["हिरवे","लाल","पांढरे","अंबर"]},"ml":{"q":"ഇടത് lane-നും hard shoulder-നും ഇടയിലുള്ള reflective studs ഏത് നിറമാണ്?","o":["പച്ച","ചുവപ്പ്","വെള്ള","amber"]},"ta":{"q":"இடது lane-க்கும் hard shoulder-க்கும் இடையிலான பிரதிபலிக்கும் studs என்ன நிறம்?","o":["பச்சை","சிவப்பு","வெள்ளை","amber"]},"gu":{"q":"ડાબી lane અને hard shoulder વચ્ચેના reflective studs કયા રંગના હોય છે?","o":["લીલા","લાલ","સફેદ","amber"]},"ne":{"q":"बायाँ lane र hard shoulder बीचका reflective studs कुन रङका हुन्छन्?","o":["हरियो","रातो","सेतो","amber"]}}}
);
